// Centrale helper: geeft altijd de beste beschikbare gebruikersnaam
DY._dyGetUserNaam = function() {
  var p = DY.profile;
  var u = DY.user;
  if (p) {
    // Probeer alle bekende naamvelden op volgorde
    var naam = p.naam || p.displayName || p.name || p.authorName || p.gebruikersnaam;
    if (naam && naam.length > 0) return naam;
  }
  if (u) {
    if (u.displayName && u.displayName.length > 0) return u.displayName;
    if (u.email) return u.email.split('@')[0];
  }
  return '';
};

// ══════════════════════════════════════════════════════════════════
// VIDEO TRANSCODING - converteert HEVC/MOV naar H.264 MP4
// via de Render.com server zodat alle browsers video kunnen afspelen
// ══════════════════════════════════════════════════════════════════
DY.transcodeVideo = async function(file, onProgress) {
  var TRANSCODE_URL = 'https://doubleyou-patroon-server.onrender.com/transcode';

  // Alleen transcoden als het een video is
  if (!file.type.startsWith('video/')) return file;

  // H.264 MP4 hoeft niet getranscodeerd - direct terugsturen
  if (file.type === 'video/mp4') {
    // Check of browser H.265 ondersteunt - zo ja, ook MP4 is OK
    var testVid = document.createElement('video');
    var h264ok = testVid.canPlayType('video/mp4; codecs="avc1.42E01E"') !== '';
    // Als het een MP4 is maar misschien HEVC erin, toch transcoden
    // We kunnen codec niet checken zonder demuxen, dus stuur altijd door
  }

  if (onProgress) onProgress(5, 'Video voorbereiden...');

  try {
    // Stuur naar Render.com server voor transcoding
    var formData = new FormData();
    formData.append('video', file, file.name || 'video.mov');

    if (onProgress) onProgress(10, 'Video uploaden naar converter...');

    var res = await fetch(TRANSCODE_URL, {
      method: 'POST',
      body: formData
    });

    if (!res.ok) {
      // Server niet bereikbaar of fout - origineel bestand gebruiken
      return file;
    }

    if (onProgress) onProgress(80, 'Video converteren...');

    var blob = await res.blob();
    var mp4File = new File([blob], 'video.mp4', { type: 'video/mp4' });

    if (onProgress) onProgress(100, 'Klaar');
    return mp4File;

  } catch (e) {
    // Netwerk fout of server offline - origineel bestand gebruiken als fallback
    return file;
  }
};

