// ── SEO: URL-pad lezen bij opstarten → bepaal startpagina ────────
// Vertaalt /feed, /looks etc. naar interne pagina-ID's
// Werkt ook als backwards compat voor legacy ?pagina= query params
(function() {
  var PAD_MAP = {
    'feed':              'feed',
    'looks':             'lookbook',
    'reviews':           'reviews',
    'winkel':            'winkel',
    'challenges':        'challenges',
    'post-van-de-week':  'ovdw',
    'outfit-vergelijker':'kleuren_ai',
    'voorwaarden':       'voorwaarden',
    'privacy':           'privacy',
    'community-regels':  'community_regels',
    'beta':              'beta_pagina'
  };
  try {
    var pad = window.location.pathname.replace(/^\//, '').replace(/\/$/, '');
    // Subpaden zoals /verhaal/abc123 of /look/xyz → detail pagina
    var hoofdpad = pad.split('/')[0];
    var doelPagina = PAD_MAP[hoofdpad] || null;
    // Fallback: legacy ?pagina= query param
    if (!doelPagina) {
      var qp = new URLSearchParams(window.location.search).get('pagina');
      if (qp) doelPagina = qp;
    }
    if (doelPagina) window._dy_start_pagina = doelPagina;
  } catch(e) {}
})();

