DY._updateSEOMeta = function(pagina) {
  var SEO_URL_MAP = {
    'feed':             '/feed',
    'lookbook':         '/looks',
    'reviews':          '/reviews',
    'winkel':           '/winkel',
    'challenges':       '/challenges',
    'ovdw':             '/post-van-de-week',
    'kleuren_ai':       '/outfit-vergelijker',
    'voorwaarden':      '/voorwaarden',
    'privacy':          '/privacy',
    'community_regels': '/community-regels',
    'beta_pagina':      '/beta'
  };

  var cfg = DY._seoMetaConfig[pagina] || DY._seoMetaConfig['home'];
  var pad = SEO_URL_MAP[pagina] || '/';
  var volledigeUrl = 'https://paskamerpraat.nl' + pad;

  try {
    // Title
    document.title = cfg.title;

    // Description
    var descEl = document.querySelector('meta[name="description"]');
    if (descEl) descEl.setAttribute('content', cfg.desc);

    // Canonical
    var canonEl = document.querySelector('link[rel="canonical"]');
    if (canonEl) {
      canonEl.setAttribute('href', volledigeUrl);
    } else {
      var c = document.createElement('link');
      c.rel = 'canonical'; c.href = volledigeUrl;
      document.head.appendChild(c);
    }

    // Open Graph
    var ogUrl = document.querySelector('meta[property="og:url"]');
    if (ogUrl) ogUrl.setAttribute('content', volledigeUrl);
    var ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) ogTitle.setAttribute('content', cfg.title);
    var ogDesc = document.querySelector('meta[property="og:description"]');
    if (ogDesc) ogDesc.setAttribute('content', cfg.desc);

    // Twitter
    var twTitle = document.querySelector('meta[name="twitter:title"]');
    if (twTitle) twTitle.setAttribute('content', cfg.title);
    var twDesc = document.querySelector('meta[name="twitter:description"]');
    if (twDesc) twDesc.setAttribute('content', cfg.desc);
  } catch(e) {}
};


