// ── ADMIN TRACKING ENGINE ──────────────────────────────────────────
// Stuur events naar Firestore activity_logs voor admin dashboard
DY._trackBatch = [];
DY._trackTimer = null;
DY._trackSessionId = Math.random().toString(36).slice(2, 10);

DY.trackEvent = function(type, category, metadata) {
  if (!DY.db) return;
  var event = {
    type: type,
    category: category || 'general',
    uid: (DY.user && DY.user.uid) || null,
    sessionId: DY._trackSessionId,
    metadata: metadata || {},
    ts: firebase.firestore.FieldValue.serverTimestamp(),
    pagina: DY.pagina || 'unknown',
    ua: navigator.userAgent.slice(0, 100)
  };
  DY._trackBatch.push(event);
  // Batch schrijven elke 10s of bij 10 events
  if (DY._trackBatch.length >= 10) {
    DY._flushTrackBatch();
  } else {
    if (DY._trackTimer) clearTimeout(DY._trackTimer);
    DY._trackTimer = setTimeout(DY._flushTrackBatch, 10000);
  }
};

DY._flushTrackBatch = function() {
  if (!DY._trackBatch.length || !DY.db) return;
  var batch = DY._trackBatch.splice(0);
  var fb = DY.db.batch();
  batch.forEach(function(ev) {
    fb.set(DY.db.collection('activity_logs').doc(), ev);
  });
  fb.commit().catch(function() {}); // Stille fail - tracking mag app niet breken
};

// Track kritieke acties automatisch
DY._trackPageView = function(pagina) {
  DY.trackEvent('page_view', 'navigation', { pagina: pagina });
  // Update laatste_actief voor online presence
  if (DY.user && DY.db) {
    DY.db.collection('users').doc(DY.user.uid).update({
      laatste_actief: firebase.firestore.FieldValue.serverTimestamp(),
      huidige_pagina: pagina
    }).catch(function(){});
  }
};


