DY.isVergelijkbareBouw = function(ander) {
  var mijn = DY.profile || {};
  if (!mijn.lengte || !ander) return false;
  return Math.abs((parseInt(mijn.lengte)||0) - (parseInt(ander.lengte||ander.posterLengte)||0)) <= 8;
};
DY.obChipSelect = function(btn) {
  var fieldId = btn.getAttribute('data-field');
  btn.parentNode.querySelectorAll('.dy-rv-chip').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
  var el = document.getElementById(fieldId);
  if (el) el.value = btn.textContent;
};

