DY.sluitBposOverlay = function() {
  var el = document.getElementById('dy-bpos-overlay');
  if (!el) return;
  el.classList.remove('dy-bpos-in');
  el.classList.add('dy-bpos-out');
  setTimeout(function() { if (el && el.parentNode) el.parentNode.removeChild(el); }, 320);
};

