// ── PRIVACY CENTER - volledige settings ─────────────────────────
DY.renderPrivacyCenter = function() {
  var main = document.getElementById('dy-main');
  if (!main) return;
  main.style.background = '#0a0806';
  main.style.paddingBottom = '0';
  var p = DY.profile || {};

  // Huidige waarden uit profiel
  var zicht    = p.profielZichtbaarheid || 'openbaar';
  var dmPriv   = p.dmPrivacy           || 'iedereen';

  main.innerHTML =
    '<div class="dy-vr-header">' +
    '<div class="dy-vr-header-inner" style="justify-content:flex-start;gap:12px">' +
      '<button class="dy-back-btn" onclick="DY.terug()" style="color:rgba(252,248,239,0.7)">&#8592;</button>' +
      '<div>' +
        '<div class="dy-feed-merk-label" style="color:rgba(252,248,239,0.45)">Paskamerpraat</div>' +
        '<h1 class="dy-vr-titel">Privacy & <em>Instellingen</em></h1>' +
      '</div>' +
    '</div>' +
  '</div>' +
    '<div style="padding:20px 16px 80px;max-width:680px;margin:0 auto">' +

      // ── PROFIEL ZICHTBAARHEID ───────────────────────────────
      '<div class="dy-pc-sectie">' +
        '<div class="dy-pc-titel">Profielzichtbaarheid</div>' +
        '<div class="dy-pc-rij">' +
          '<div class="dy-pc-label">' +
            '<strong>Wie kan jouw profiel zien?</strong>' +
            '<span>Bepaal wie jouw posts, maten en activiteit kan bekijken.</span>' +
          '</div>' +
          '<select class="dy-pc-select" id="pc-zicht-select">' +
            '<option value="openbaar"' + (zicht==='openbaar'?' selected':'') + '>Iedereen</option>' +
            '<option value="leden"'   + (zicht==='leden'   ?' selected':'') + '>Alleen leden</option>' +
            '<option value="prive"'   + (zicht==='prive'   ?' selected':'') + '>Privé</option>' +
          '</select>' +
        '</div>' +
        '<p id="pc-zicht-uitleg" style="font-size:0.8rem;color:var(--ink-muted);margin:8px 0 0;line-height:1.5">' +
          (zicht==='prive'  ? '🔒 Alleen jij kunt jouw profiel bekijken.' :
           zicht==='leden'  ? '👥 Alleen ingelogde leden kunnen jouw profiel zien.' :
                              '🌐 Iedereen kan jouw profiel bekijken.') +
        '</p>' +
        '<button class="dy-btn dy-btn-primary" id="pc-zicht-opslaan" style="margin-top:12px;width:auto;padding:8px 20px">Opslaan</button>' +
      '</div>' +

      // ── DM PRIVACY ─────────────────────────────────────────
      '<div class="dy-pc-sectie">' +
        '<div class="dy-pc-titel">Privéberichten (DM\'s)</div>' +
        '<div class="dy-pc-rij">' +
          '<div class="dy-pc-label">' +
            '<strong>Wie mag jou een DM sturen?</strong>' +
            '<span>Beperk wie contact met je kan opnemen via privéberichten.</span>' +
          '</div>' +
          '<select class="dy-pc-select" id="pc-dm-select">' +
            '<option value="iedereen"' + (dmPriv==='iedereen'?' selected':'') + '>Iedereen</option>' +
            '<option value="volgenden"' + (dmPriv==='volgenden'?' selected':'') + '>Alleen die ik volg</option>' +
            '<option value="niemand"'  + (dmPriv==='niemand' ?' selected':'') + '>Niemand</option>' +
          '</select>' +
        '</div>' +
        '<button class="dy-btn dy-btn-primary" id="pc-dm-opslaan" style="margin-top:12px;width:auto;padding:8px 20px">Opslaan</button>' +
      '</div>' +

      // ── FIT IDENTITY PRIVACY ────────────────────────────────
      '<div class="dy-pc-sectie">' +
        '<div class="dy-pc-titel">Fit Identity zichtbaarheid</div>' +
        '<div class="dy-pc-rij">' +
          '<div class="dy-pc-label">' +
            '<strong>Maten en lichaamskenmerken</strong>' +
            '<span>Bepaal of anderen jouw lichaamsgegevens kunnen zien.</span>' +
          '</div>' +
          '<div class="dy-priv-toggle-wrap">' +
            '<button class="dy-priv-opt' + (p.fitPrivacy!=='privé'?' actief':'') + '" id="pc-fit-open" data-val="openbaar">Openbaar</button>' +
            '<button class="dy-priv-opt' + (p.fitPrivacy==='privé'?' actief':'') + '" id="pc-fit-prive" data-val="privé">Privé</button>' +
          '</div>' +
        '</div>' +
        '<input type="hidden" id="pc-fitprivacy" value="' + (p.fitPrivacy||'openbaar') + '">' +
        '<p id="pc-fit-uitleg" style="font-size:0.8rem;color:var(--ink-muted);margin:8px 0 0;line-height:1.5">' +
          (p.fitPrivacy==='privé' ? '🔒 Alleen zichtbaar voor jou.' : '🌐 Zichtbaar voor community leden.') +
        '</p>' +
        '<button class="dy-btn dy-btn-primary" id="pc-fit-opslaan" style="margin-top:12px;width:auto;padding:8px 20px">Opslaan</button>' +
      '</div>' +

      // ── GEGEVENS DOWNLOADEN ─────────────────────────────────
      '<div class="dy-pc-sectie">' +
        '<div class="dy-pc-titel">Jouw gegevens</div>' +
        '<div class="dy-pc-actie-rij">' +
          '<div class="dy-pc-label">' +
            '<strong>Gegevens downloaden</strong>' +
            '<span>Download een overzicht van jouw profiel en activiteit als JSON-bestand.</span>' +
          '</div>' +
          '<button class="dy-btn-sm" id="pc-download-btn">Download</button>' +
        '</div>' +
      '</div>' +

      // ── ACCOUNT VERWIJDEREN ─────────────────────────────────
      '<div class="dy-pc-sectie dy-pc-danger">' +
        '<div class="dy-pc-titel">⚠️ Account verwijderen</div>' +
        '<p class="dy-pc-warning">Dit verwijdert jouw account, profiel en alle bijbehorende data permanent. Dit kan niet ongedaan worden gemaakt.</p>' +
        '<button class="dy-btn-danger" id="pc-verwijder-btn">Account permanent verwijderen</button>' +
      '</div>' +

    '</div>';

  // ── Event handlers ──────────────────────────────────────────────

  // Profielzichtbaarheid select → uitleg bijwerken
  var zichtSelect = document.getElementById('pc-zicht-select');
  if (zichtSelect) {
    zichtSelect.onchange = function() {
      var uitleg = document.getElementById('pc-zicht-uitleg');
      if (!uitleg) return;
      var v = this.value;
      uitleg.textContent = v==='prive'  ? '🔒 Alleen jij kunt jouw profiel bekijken.'
                         : v==='leden'  ? '👥 Alleen ingelogde leden kunnen jouw profiel zien.'
                                        : '🌐 Iedereen kan jouw profiel bekijken.';
    };
  }

  // Profielzichtbaarheid opslaan
  var zichtBtn = document.getElementById('pc-zicht-opslaan');
  if (zichtBtn) {
    zichtBtn.onclick = async function() {
      if (!DY.user || !DY.db) return;
      var val = document.getElementById('pc-zicht-select').value;
      zichtBtn.disabled = true; zichtBtn.textContent = '...';
      try {
        await DY.db.collection('users').doc(DY.user.uid).update({ profielZichtbaarheid: val });
        if (DY.profile) DY.profile.profielZichtbaarheid = val;
        DY.toast('Profielzichtbaarheid opgeslagen ✓', 'succes');
      } catch(e) { DY.toast('Opslaan mislukt, probeer opnieuw.', 'fout'); }
      zichtBtn.disabled = false; zichtBtn.textContent = 'Opslaan';
    };
  }

  // DM privacy opslaan
  var dmBtn = document.getElementById('pc-dm-opslaan');
  if (dmBtn) {
    dmBtn.onclick = async function() {
      if (!DY.user || !DY.db) return;
      var val = document.getElementById('pc-dm-select').value;
      dmBtn.disabled = true; dmBtn.textContent = '...';
      try {
        await DY.db.collection('users').doc(DY.user.uid).update({ dmPrivacy: val });
        if (DY.profile) DY.profile.dmPrivacy = val;
        DY.toast('DM-instelling opgeslagen ✓', 'succes');
      } catch(e) { DY.toast('Opslaan mislukt, probeer opnieuw.', 'fout'); }
      dmBtn.disabled = false; dmBtn.textContent = 'Opslaan';
    };
  }

  // Fit Identity toggle
  ['pc-fit-open','pc-fit-prive'].forEach(function(id) {
    var btn = document.getElementById(id);
    if (!btn) return;
    btn.onclick = function() {
      document.querySelectorAll('.dy-priv-opt').forEach(function(b) { b.classList.remove('actief'); });
      this.classList.add('actief');
      var val = this.dataset.val;
      var inp = document.getElementById('pc-fitprivacy');
      if (inp) inp.value = val;
      var uitleg = document.getElementById('pc-fit-uitleg');
      if (uitleg) uitleg.textContent = val==='privé' ? '🔒 Alleen zichtbaar voor jou.' : '🌐 Zichtbaar voor community leden.';
    };
  });

  // Fit privacy opslaan
  var fitBtn = document.getElementById('pc-fit-opslaan');
  if (fitBtn) {
    fitBtn.onclick = async function() {
      if (!DY.user || !DY.db) return;
      var val = (document.getElementById('pc-fitprivacy') || {}).value || 'openbaar';
      fitBtn.disabled = true; fitBtn.textContent = '...';
      try {
        await DY.db.collection('users').doc(DY.user.uid).update({ fitPrivacy: val });
        if (DY.profile) DY.profile.fitPrivacy = val;
        DY.toast('Fit Identity privacy opgeslagen ✓', 'succes');
      } catch(e) { DY.toast('Opslaan mislukt, probeer opnieuw.', 'fout'); }
      fitBtn.disabled = false; fitBtn.textContent = 'Opslaan';
    };
  }

  // Gegevens downloaden
  var dlBtn = document.getElementById('pc-download-btn');
  if (dlBtn) {
    dlBtn.onclick = function() {
      if (!DY.user) return;
      dlBtn.disabled = true; dlBtn.textContent = 'Laden...';
      var p2 = DY.profile || {};
      var exportData = {
        uid: DY.user.uid,
        email: DY.user.email || '',
        displayName: p2.displayName || '',
        lengte: p2.lengte || null,
        maat: p2.maat || null,
        fitPrivacy: p2.fitPrivacy || 'openbaar',
        profielZichtbaarheid: p2.profielZichtbaarheid || 'openbaar',
        dmPrivacy: p2.dmPrivacy || 'iedereen',
        exportDatum: new Date().toISOString()
      };
      var blob = new Blob([JSON.stringify(exportData, null, 2)], {type: 'application/json'});
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'paskamerpraat-data-' + new Date().toISOString().slice(0,10) + '.json';
      document.body.appendChild(a);
      a.click();
      setTimeout(function() { document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 1000);
      dlBtn.disabled = false; dlBtn.textContent = 'Download';
      DY.toast('Gegevens gedownload ✓', 'succes');
    };
  }

  // Account verwijderen → navigeer naar verwijder-pagina
  var verwijderBtn = document.getElementById('pc-verwijder-btn');
  if (verwijderBtn) {
    verwijderBtn.onclick = function() { DY.navigeer('account_verwijder'); };
  }
};

// ── ACCOUNT VERWIJDEREN ──────────────────────────────────────────
DY.renderAccountVerwijder = function() {
  var main = document.getElementById('dy-main');
  if (!main) return;
  if (!DY.user) { DY.navigeer('login'); return; }

  main.innerHTML =
    '<div class="dy-vr-header">' +
    '<div class="dy-vr-header-inner" style="justify-content:flex-start;gap:12px">' +
      '<button class="dy-back-btn" onclick="DY.terug()" style="color:rgba(252,248,239,0.7)">&#8592;</button>' +
      '<div>' +
        '<div class="dy-feed-merk-label" style="color:rgba(252,248,239,0.45)">Paskamerpraat</div>' +
        '<h1 class="dy-vr-titel">Account <em>Verwijderen</em></h1>' +
      '</div>' +
    '</div>' +
  '</div>' +
    '<div style="padding:20px 16px 80px;max-width:560px;margin:0 auto">' +

      '<div class="dy-pc-sectie dy-pc-danger">' +
        '<div class="dy-pc-titel">⚠️ Permanent verwijderen</div>' +
        '<p class="dy-pc-warning">Dit verwijdert jouw account en <strong>alle bijbehorende data</strong> permanent:<br>profiel, posts, reacties, DSP-punten en alle instellingen.<br>Dit kan <strong>niet</strong> ongedaan worden gemaakt.</p>' +

        '<div class="dy-pc-verif" id="pc-av-stap1">' +
          '<p style="font-size:0.85rem;color:var(--ink);margin:0 0 12px;font-weight:600">Typ ter bevestiging: <em>verwijder mijn account</em></p>' +
          '<input class="dy-inp" id="pc-av-confirm" type="text" placeholder="verwijder mijn account" autocomplete="off">' +
          '<button class="dy-btn-danger" id="pc-av-doorgaan" style="margin-top:12px">Doorgaan →</button>' +
        '</div>' +

        '<div id="pc-av-stap2" style="display:none">' +
          '<p style="font-size:0.85rem;color:rgba(229,62,62,0.9);margin:0 0 16px;font-weight:600">🔐 Laatste bevestiging</p>' +
          '<p style="font-size:0.82rem;color:rgba(253,248,240,0.45);margin:0 0 16px;line-height:1.6">Weet je het zeker? Druk op de rode knop om jouw account definitief te verwijderen.</p>' +
          '<div style="display:flex;gap:10px;flex-wrap:wrap">' +
            '<button class="dy-btn-danger" id="pc-av-definitief" style="flex:1">Ja, verwijder mijn account</button>' +
            '<button class="dy-btn-sm" id="pc-av-annuleer" style="flex:1">Annuleren</button>' +
          '</div>' +
        '</div>' +

        '<div id="pc-av-bezig" style="display:none;text-align:center;padding:20px 0">' +
          '<p style="color:var(--ink-muted);font-size:0.88rem">Account wordt verwijderd...</p>' +
        '</div>' +
      '</div>' +

    '</div>';

  // Stap 1: bevestiging invoer
  var doorgaanBtn = document.getElementById('pc-av-doorgaan');
  if (doorgaanBtn) {
    doorgaanBtn.onclick = function() {
      var inp = document.getElementById('pc-av-confirm');
      if (!inp || inp.value.trim().toLowerCase() !== 'verwijder mijn account') {
        DY.toast('Typ exact: verwijder mijn account', 'fout');
        return;
      }
      document.getElementById('pc-av-stap1').style.display = 'none';
      document.getElementById('pc-av-stap2').style.display = 'block';
    };
  }

  // Annuleer
  var annuleerBtn = document.getElementById('pc-av-annuleer');
  if (annuleerBtn) {
    annuleerBtn.onclick = function() {
      document.getElementById('pc-av-stap1').style.display = 'block';
      document.getElementById('pc-av-stap2').style.display = 'none';
      var inp = document.getElementById('pc-av-confirm');
      if (inp) inp.value = '';
    };
  }

  // Definitief verwijderen
  var definitiefBtn = document.getElementById('pc-av-definitief');
  if (definitiefBtn) {
    definitiefBtn.onclick = async function() {
      if (!DY.user || !DY.db) return;
      document.getElementById('pc-av-stap2').style.display = 'none';
      document.getElementById('pc-av-bezig').style.display = 'block';

      var uid = DY.user.uid;
      try {
        // 1. Verwijder Firestore user document
        await DY.db.collection('users').doc(uid).delete();

        // 2. Wis localStorage/sessionStorage
        try {
          ['dy_saved_looks','dy_laatste_bezoek','dy_app_version',
           '_dy_actieve_pagina','dy_overlay_gezien'].forEach(function(k) {
            localStorage.removeItem(k);
            sessionStorage.removeItem(k);
          });
        } catch(e) {}

        // 3. Wis state
        DY.user    = null;
        DY.profile = null;
        DY.pagina  = null;
        DY._history = [];

        // 4. Firebase auth delete + signOut
        var authUser = firebase.auth().currentUser;
        if (authUser) {
          try { await authUser.delete(); }
          catch(authErr) {
            // Herauth vereist - log uit en informeer gebruiker
            await firebase.auth().signOut();
            DY.toast('Account verwijderd. Log opnieuw in om auth te verwijderen.', '');
            setTimeout(function() { window.location.replace('/'); }, 2000);
            return;
          }
        } else {
          await firebase.auth().signOut();
        }

        // 5. Redirect naar home
        DY.toast('Account succesvol verwijderd.', 'succes');
        setTimeout(function() { window.location.replace('/'); }, 1500);

      } catch(e) {
        document.getElementById('pc-av-bezig').style.display = 'none';
        document.getElementById('pc-av-stap2').style.display = 'block';
        DY.toast('Verwijderen mislukt. Probeer opnieuw of neem contact op.', 'fout');
      }
    };
  }
};

