DY.kopieerLink = function(url) {
  navigator.clipboard.writeText(url).then(() => {
    DY.toast('Link gekopieerd!');
  }).catch(() => {
    DY.toast('Kopiëren mislukt');
  });
};

DY.registreerDeel = async function(verhaalId) {
  try {
  if (!DY.user) return;
  var _dModal = document.getElementById('dy-deel-modal'); if(_dModal) _dModal.remove();
  await DY.geefPunten('verhaal_delen', { verhaal_id: verhaalId });
  // toonPuntenMelding wordt automatisch door geefPunten aangeroepen
  } catch(e) {
    DY.toast && DY.toast('Er ging iets mis. Probeer het opnieuw.');
  }
}


// ── LOOK REACTIES ──────────────────────────────────────────────────
DY.laadLookReacties = async function(lookId) {
  const lijst = document.getElementById('dy-look-reacties-lijst');
  if (!lijst) return;
  try {
    const snap = await DY.db.collection('lookbook').doc(lookId).collection('comments').limit(30).get();
    if (snap.empty) {
      lijst.innerHTML = '<p style="font-size:13px;color:var(--ink-muted);padding:8px 0">Nog geen reacties.</p>';
      return;
    }
    const reacties = [];
    snap.forEach(doc => reacties.push({ _docId: doc.id, ...doc.data() }));
    reacties.sort((a, b) => {
      const ta = a.ts && a.ts.toDate ? a.ts?.toDate?.() : new Date(a.createdAt || 0);
      const tb = b.ts && b.ts.toDate ? b.ts?.toDate?.() : new Date(b.createdAt || 0);
      return ta - tb;
    });
    lijst.innerHTML = '';
    reacties.forEach(r => {
      const naam = r.authorName || r.displayName || 'Anoniem';
      const eigenReactie = DY.user && (r.userId === DY.user.uid || r.uid === DY.user.uid);
      const el = document.createElement('div');
      el.className = 'dy-reactie';
      el.innerHTML = `
        <div class="dy-reactie-avatar">${naam.slice(0,2).toUpperCase()}</div>
        <div class="dy-reactie-content">
          <div class="dy-reactie-header">
            <span class="dy-reactie-naam">${naam}</span>
            ${eigenReactie ? `<button class="dy-reactie-verwijder" onclick="DY.verwijderLookReactie('${lookId}', '${r._docId}', this)">✕</button>` : ''}
          </div>
          <p class="dy-reactie-tekst">${r.body || r.tekst || ''}</p>
          <span class="dy-reactie-tijd">${DY.tijdGeleden(r.ts && r.ts.toDate ? r.ts?.toDate?.() : new Date(r.createdAt || 0))}</span>
        </div>`;
      lijst.appendChild(el);
    });
  } catch(e) {
    lijst.innerHTML = '<p style="font-size:13px;color:var(--ink-muted)">Reacties konden niet worden geladen.</p>';
  }
};

DY.plaatsLookReactie = async function(lookId) {
  if (!DY.user) return;
  const tekstEl = document.getElementById('look-reactie-tekst');
  const tekst = (tekstEl && tekstEl.value).trim();
  if (!tekst) { DY.toast('Schrijf eerst een reactie.'); return; }

  const btn = document.querySelector('[onclick*="plaatsLookReactie"]');
  if (btn) { btn.disabled = true; btn.textContent = 'Plaatsen...'; }

  try {
    const displayName = (DY.profile && DY.profile.displayName) || ((DY.user && DY.user.email) || '').split('@')[0];
    await DY.db.collection('lookbook').doc(lookId).collection('comments').add({
      userId: DY.user.uid,
      authorName: displayName,
      body: tekst,
      createdAt: new Date().toISOString(),
      ts: firebase.firestore.FieldValue.serverTimestamp()
    });
    await DY.db.collection('lookbook').doc(lookId).set(
      { reacties: firebase.firestore.FieldValue.increment(1) },
      { merge: true }
    );
    await DY.geefPunten('reactie_plaatsen', { look_id: lookId });
    if (tekstEl) tekstEl.value = '';
    const teller = document.getElementById('look-reactie-count');
    if (teller) teller.textContent = parseInt(teller.textContent || '0') + 1;
    DY.laadLookReacties(lookId);
  } catch(e) {
    DY.toast('Plaatsen mislukt. Probeer opnieuw.');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'REACTIE PLAATSEN'; }
  }
};

DY.verwijderLookReactie = async function(lookId, reactieId, btn) {
  if (!DY.user) return;
  try {
    btn.disabled = true;
    await DY.db.collection('lookbook').doc(lookId).collection('comments').doc(reactieId).delete();
    await DY.db.collection('lookbook').doc(lookId).set(
      { reacties: firebase.firestore.FieldValue.increment(-1) },
      { merge: true }
    );
    await DY.ontneemPunten('reactie_plaatsen', { look_id: lookId });
    DY.laadLookReacties(lookId);
  } catch(e) { btn.disabled = false; }
};

// ── VERHAAL VERWIJDEREN ─────────────────────────────────────────────
DY.verwijderVerhaal = async function(verhaalId, heeftMedia, woordenAantal) {
  if (!DY.user) return;
  

  try {
    const ref = DY.db.collection('stories').doc(verhaalId);
    const snap = await ref.get();
    if (!snap.exists) return;
    const data = snap.data();

    // Alleen eigen verhalen verwijderen
    if (data.userId !== DY.user.uid && data.uid !== DY.user.uid) return;

    await ref.delete();

    // Decrement verhalen_count in user document
    DY.db.collection('users').doc(DY.user.uid).update({
      verhalen_count: firebase.firestore.FieldValue.increment(-1)
    }).then(function() {
      if (DY.profile) DY.profile.verhalen_count = Math.max(0, (DY.profile.verhalen_count || 1) - 1);
    }).catch(function() {});

    // Punten terugtrekken
    await DY.ontneemPunten('verhaal_plaatsen', { verhaal_id: verhaalId });
    if (woordenAantal >= 120) await DY.ontneemPunten('verhaal_bonus_120', { verhaal_id: verhaalId });
    if (heeftMedia) await DY.ontneemPunten('foto_verhaal', { verhaal_id: verhaalId });

    // Terug naar feed
    DY.navigeer('feed');
    setTimeout(() => DY.toast('Verhaal verwijderd'), 300);
  } catch(e) {
    DY.toast('Verwijderen mislukt');
  }
};


// ── PUSH NOTIFICATIES ──────────────────────────────────────────────
const VAPID_PUBLIC = 'BGIhf6Dkd7qlS_jyA8OMg-03eN1wva_idMvAG5bnMqBK6RJrTpbqafMyTxfU8GF5i_J7AWcqgfPSu-oyUxh-JyE';
const WORKER_URL = 'https://black-grass-c05c.doubleuurbanluxury.workers.dev';

DY.initPush = async function() {
  if (!DY.user) return;
  if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;

  try {
    const reg = await navigator.serviceWorker.ready;
    const bestaand = await reg.pushManager.getSubscription();
    if (bestaand) {
      // Al ingeschreven - sla op voor zekerheid
      await DY.slaSubscriptionOp(bestaand);
      return;
    }

    // Vraag toestemming
    const perm = await Notification.requestPermission();
    if (perm !== 'granted') return;

    // Abonneer
    const sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: DY.urlBase64ToUint8Array(VAPID_PUBLIC)
    });

    await DY.slaSubscriptionOp(sub);
    DY.toast('Notificaties ingeschakeld!');
  } catch(e) {
      }
};

DY.slaSubscriptionOp = async function(subscription) {
  if (!DY.user) return;
  try {
    await DY.db.collection('push_subscriptions').doc(DY.user.uid).set({
      userId: DY.user.uid,
      subscription: JSON.stringify(subscription),
      endpoint: subscription.endpoint,
      aangemeld: new Date().toISOString(),
      actief: true
    });
  } catch(e) { }
};

DY.uitschrijvenPush = async function() {
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    if (sub) await sub.unsubscribe();
    if (DY.user) {
      await DY.db.collection('push_subscriptions').doc(DY.user.uid).update({ actief: false });
    }
    DY.toast('Notificaties uitgeschakeld.');
  } catch(e) { }
};

DY.urlBase64ToUint8Array = function(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
};

DY.stuurPushNaarAuteur = async function(auteurUserId, titel, bericht, url) {
  if (!auteurUserId || auteurUserId === (DY.user && DY.user.uid)) return;
  try {
    await fetch(WORKER_URL + '/push', {
      method: 'POST',
      credentials: 'omit',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: auteurUserId, titel, bericht, url })
    });
  } catch(e) { }
};

DY._pushBatch = {};
DY._pushBatchTimers = {};

DY._stuurPushGedebounced = function(auteurUid, type, docId, extraLabel) {
  if (!auteurUid || auteurUid === (DY.user && DY.user.uid)) return;
  var sleutel = auteurUid + '_' + type;
  if (!DY._pushBatch[sleutel]) DY._pushBatch[sleutel] = { count: 0, docId: docId };
  DY._pushBatch[sleutel].count++;
  if (DY._pushBatchTimers[sleutel]) clearTimeout(DY._pushBatchTimers[sleutel]);
  DY._pushBatchTimers[sleutel] = setTimeout(function() {
    var batch = DY._pushBatch[sleutel];
    if (!batch) return;
    delete DY._pushBatch[sleutel];
    delete DY._pushBatchTimers[sleutel];
    var mijnNaam = (DY.profile && (DY.profile.naam || DY.profile.displayName)) || 'Iemand';
    var titel = '', bericht = '', url = '';
    if (type === 'like') {
      titel = batch.count === 1 ? mijnNaam + ' vond je post leuk' : batch.count + ' mensen vonden je post leuk';
      bericht = 'Bekijk je verhaal in Paskamerpraat';
      url = '/?docId=' + batch.docId;
    } else if (type === 'volgen') {
      titel = mijnNaam + ' volgt je nu';
      bericht = 'Bekijk zijn of haar profiel';
      url = '/?pagina=gebruiker&uid=' + (DY.user && DY.user.uid);
    } else if (type === 'challenge_stem') {
      titel = mijnNaam + ' stemde op je outfit';
      bericht = 'Bekijk je positie in de challenge';
      url = '/?pagina=challenges';
    }
    if (titel) DY.stuurPushNaarAuteur(auteurUid, titel, bericht, url);
  }, 8000);
};


DY.togglePush = async function(btn) {
  try {
    var actief = btn.classList.contains('actief');
    btn.disabled = true;
    var kaart = btn.closest('.dy-push-toggle-kaart');
    var statusEl = kaart ? kaart.querySelector('.dy-push-toggle-links span') : null;

    if (actief) {
      await DY.uitschrijvenPush();
      btn.classList.remove('actief');
      btn.setAttribute('aria-label', 'Pushmeldingen inschakelen');
      if (statusEl) statusEl.textContent = 'Meldingen uit';
    } else {
      await DY.initPush();
      btn.classList.add('actief');
      btn.setAttribute('aria-label', 'Pushmeldingen uitschakelen');
      if (statusEl) statusEl.textContent = 'Meldingen aan';
    }
    btn.disabled = false;
  } catch(e) {
    DY.toast && DY.toast('Er ging iets mis. Probeer het opnieuw.');
    var btnEl = document.querySelector('.dy-push-toggle-schakelaar');
    if (btnEl) btnEl.disabled = false;
  }
}


