DY.renderBestellingen = async function() {
  if (!DY.user) {
    var _vPag = (DY._history && DY._history.length > 0) ? DY._history[DY._history.length-1] : 'feed';
    var _vR = {feed:DY.renderFeed,home:DY.renderHome,lookbook:DY.renderLookbook,vrienden:DY.renderVrienden,winkel:DY.renderWinkel};
    DY.pagina = null;
    if (_vR[_vPag]) { DY.pagina = _vPag; _vR[_vPag](); } else { DY.pagina = 'feed'; DY.renderFeed(); }
    DY.toonLoginPrompt('Inloggen om je bestellingen te bekijken.');
    return;
  }
  const main = document.getElementById('dy-main');
  if (!main) return;
  main.innerHTML =
    '<div class="dy-feed-header"><div class="dy-feed-header-inner"><div>' +
    '<h1 class="dy-page-title">Mijn <em>Bestellingen</em></h1>' +
    '<p class="dy-page-sub">Jouw aankopen bij DoubleYou.</p>' +
    '</div></div></div>' +
    '<div class="dy-form-wrap">' +
    '<button class="dy-back-btn" onclick="DY.terug()" style="margin-bottom:16px">\u2190 Terug</button>' +
    '<div id="dy-dsp-bestellingen"><div class="dy-loader"><div class="dy-spinner"></div></div></div>' +
    '<div class="dy-best-shopify-blok">' +
    '<div style="font-size:48px;text-align:center;margin-bottom:12px">&#128722;</div>' +
    '<h3 class="dy-best-shopify-titel">Jouw bestellingen</h3>' +
    '<p class="dy-best-shopify-tekst">Bekijk bestellingen, volg leveringen en download facturen via jouw DoubleYou account.</p>' +
    '<a href="https://doubleyoufashion.nl/account/orders?utm_source=pwa" target="_blank" rel="noopener noreferrer" class="dy-btn dy-btn-primary" style="display:block;text-align:center;margin-top:16px;text-decoration:none">' +
    'Bekijk mijn bestellingen \u2192' +
    '</a>' +
    '<p style="font-size:11px;color:var(--ink-muted);text-align:center;margin-top:10px">Opent in jouw DoubleYou account</p>' +
    '</div>' +
    '</div>';
  try {
    const dspSnap = await DY.db.collection('dsp_log')
      .where('uid', '==', DY.user.uid)
      .where('actie', 'in', ['eerste_aankoop', 'aankoop_volgend'])
      .limit(20).get();
    const dspEl = document.getElementById('dy-dsp-bestellingen');
    if (!dspEl) return;
    if (dspSnap.empty) {
      dspEl.innerHTML = '<div class="dy-dsp-tip" style="margin-bottom:16px"><span class="dy-dsp-tip-icon">\u2736</span><span>Eerste aankoop levert <strong>+100 DSP</strong>. Volgende bestellingen <strong>+75 DSP</strong>.</span></div>';
      return;
    }
    const logs = [];
    dspSnap.forEach(function(doc) { logs.push(doc.data()); });
    logs.sort(function(a,b) { return new Date(b.ts||0) - new Date(a.ts||0); });
    const totaal = logs.reduce(function(s,l) { return s + (parseInt(l.pts)||0); }, 0);
    dspEl.innerHTML =
      '<div class="dy-best-dsp-overzicht" style="margin-bottom:16px">' +
      '<div class="dy-best-dsp-totaal"><span class="dy-best-dsp-getal">+' + totaal + '</span><span class="dy-best-dsp-label">DSP verdiend met bestellingen</span></div>' +
      logs.map(function(l) {
        var datum = '';
        try { datum = l.ts ? new Date(l.ts).toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric'}) : ''; } catch(e2){}
        return '<div class="dy-best-dsp-rij"><span class="dy-best-dsp-rij-label">' + (l.label||'Bestelling') + '</span>' +
          '<div style="display:flex;align-items:center;gap:8px"><span style="font-size:11px;color:var(--ink-muted)">' + datum + '</span>' +
          '<span class="dy-best-dsp">+' + (l.pts||0) + ' DSP</span></div></div>';
      }).join('') +
      '</div>';
  } catch(e) {
    var d = document.getElementById('dy-dsp-bestellingen');
    if (d) d.innerHTML = '';
  }
};

