// ── GEBRUIKERSPROFIEL ──────────────────────────────────────────────
DY.openGebruiker = function(uid, naam) {
  if (!uid) return;
  // Eigen profiel → eigen profielpagina
  if (DY.user && uid === DY.user.uid) { DY.navigeer('profiel'); return; }
  DY.huidigGebruiker = { uid: uid, naam: naam };
  // Sla huidige pagina expliciet op als terugkeer-punt
  if (!DY._history) DY._history = [];
  if (DY.pagina && DY.pagina !== 'gebruiker') {
    DY._history.push(DY.pagina);
    if (DY._history.length > 20) DY._history.shift();
  }
  DY.toonPagina('gebruiker');
};

DY.renderGebruikersProfiel = async function() {
  if (!DY.huidigGebruiker || !DY.huidigGebruiker.uid) { DY.navigeer('feed'); return; }
  const uid = DY.huidigGebruiker.uid;
  const naam = DY.huidigGebruiker.naam || 'Profiel';
  const main = document.getElementById('dy-main');
  if (!main) return;
  const initials = naam.slice(0, 2).toUpperCase();

  main.innerHTML =
    '<div class="dy-gp-wrap">' +

      // ── Hero
      '<div class="dy-gp-hero">' +
        '<button class="dy-gp-terug" onclick="DY.terug()">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="18" height="18"><path d="M19 12H5"/><path d="M12 5l-7 7 7 7"/></svg>' +
          'Terug' +
        '</button>' +
        '<div class="dy-gp-avatar-ring" id="gu-avatar-wrap">' +
          '<div class="dy-gp-avatar-initials" id="gu-avatar">' + initials + '</div>' +
        '</div>' +
        '<h2 class="dy-gp-naam" id="gu-naam">' + naam + '</h2>' +
        '<div class="dy-gp-niveau" id="gu-niveau"></div>' +
        '<div id="gu-volg-wrap"></div>' +
      '</div>' +

      // ── Stats
      '<div class="dy-gp-stats" id="gu-stats">' +
        '<div class="dy-loading-wrap"><div class="dy-dot-loader"><span></span><span></span><span></span></div></div>' +
      '</div>' +

      // ── Verhalen
      '<div class="dy-gp-sectie">' +
        '<h3 class="dy-gp-sectie-titel">Verhalen</h3>' +
        '<div id="gu-verhalen" class="dy-verhalen-grid" style="padding:0 10px 32px"></div>' +
      '</div>' +

    '</div>';

  try {
    const doc = await DY.db.collection('users').doc(uid).get();
    const p = doc.exists ? doc.data() : {};
    // Profielzichtbaarheid check
    const _zicht = p.profielZichtbaarheid || 'openbaar';
    const _isEigen = DY.user && DY.user.uid === uid;
    if (!_isEigen) {
      if (_zicht === 'prive') {
        var _sts = document.getElementById('gu-stats');
        if (_sts) _sts.innerHTML = '<div style="padding:40px;text-align:center;color:var(--ink-muted);font-size:0.85rem">🔒 Dit profiel is privé</div>';
        return;
      }
      if (_zicht === 'leden' && !DY.user) {
        var _sts2 = document.getElementById('gu-stats');
        if (_sts2) _sts2.innerHTML = '<div style="padding:40px;text-align:center"><p style="color:var(--ink-muted);font-size:0.85rem;margin-bottom:16px">🔒 Alleen zichtbaar voor leden</p><button onclick="DY.navigeer(\x27register\x27)" style="background:var(--clay);color:var(--cream);border:none;padding:10px 20px;border-radius:8px;cursor:pointer;font-family:inherit;font-weight:600;font-size:0.85rem">Aanmelden</button></div>';
        return;
      }
    }
    const displayNaam = p.displayName || naam;
    const niveau = DY.getNiveau(p.dsp_lifetime || p.punten || 0);
    const seizoentier = DY.getSeizoenTier(p.dsp_seizoen || 0);
    const volgers = Object.keys(p.volgers || {}).length;
    const volgend = Object.keys(p.volgend || {}).length;

    // Naam
    var naamEl = document.getElementById('gu-naam');
    if (naamEl) naamEl.textContent = displayNaam;

    // Niveau pill
    var niveauEl = document.getElementById('gu-niveau');
    if (niveauEl) niveauEl.innerHTML =
      '<span class="dy-gp-niveau-pill">' + niveau.emoji + ' ' + niveau.naam + '</span>' +
      (seizoentier ? ' <span class="dy-gp-seizoen-pill">' + seizoentier.emoji + ' ' + seizoentier.naam + '</span>' : '');

    // Avatar
    var avatarWrap = document.getElementById('gu-avatar-wrap');
    if (avatarWrap && p.avatar) {
      avatarWrap.innerHTML =
        '<img loading="lazy" decoding="async" src="' + p.avatar + '" class="dy-gp-avatar-img" alt="' + displayNaam + '"' +
        ' onerror="this.style.display=\x27none\x27">';
    }

    // Volgknop - alleen voor anderen
    await DY.laadVolgStatus();
    var volgWrap = document.getElementById('gu-volg-wrap');
    if (volgWrap && DY.user && uid !== DY.user.uid) {
      var volgend2 = DY.volgtIk(uid);
      // DM knop tonen op basis van dmInstellingen van de ontvanger
      var _dmInst = p.dmInstellingen || 'iedereen';
      var _isDmVriend = DY.volgtIk && DY.volgtIk(uid);
      var _dmToegestaan = _dmInst === 'iedereen' || (_dmInst === 'vrienden' && _isDmVriend);
      volgWrap.innerHTML =
        '<button class="dy-gp-volg-btn ' + (volgend2 ? 'volgend' : '') + '" data-uid="' + uid + '" onclick="DY.toggleVolgen(this)">' +
          (volgend2
            ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="16" height="16"><path d="M20 6L9 17l-5-5"/></svg> Gevolgd'
            : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="16" height="16"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><line x1="19" y1="8" x2="19" y2="14"/><line x1="22" y1="11" x2="16" y2="11"/></svg> Volgen') +
        '</button>' +
        (_dmToegestaan
          ? '<button class="dy-gp-dm-btn" onclick="DY.stuurBericht(\'' + uid + '\', \'' + (p.displayName || naam) + '\')">' +
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="14" height="14"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg> Bericht' +
            '</button>'
          : '');
    }

    // Stats
    var statsEl = document.getElementById('gu-stats');
    if (statsEl) statsEl.innerHTML =
      '<div class="dy-gp-stat"><span class="dy-gp-stat-val">' + (p.dsp_lifetime || p.punten || 0).toLocaleString('nl') + '</span><span class="dy-gp-stat-lbl">Lifetime DSP</span></div>' +
      '<div class="dy-gp-stat"><span class="dy-gp-stat-val">' + (p.dsp_seizoen || 0).toLocaleString('nl') + '</span><span class="dy-gp-stat-lbl">Dit seizoen</span></div>' +
      '<div class="dy-gp-stat"><span class="dy-gp-stat-val">' + (p.streak || 0) + '</span><span class="dy-gp-stat-lbl">Streak</span></div>' +
      '<div class="dy-gp-stat"><span class="dy-gp-stat-val">' + volgers + '</span><span class="dy-gp-stat-lbl">Volgers</span></div>' +
      '<div class="dy-gp-stat"><span class="dy-gp-stat-val">' + volgend + '</span><span class="dy-gp-stat-lbl">Volgend</span></div>';

    // Badges
    var badgesArr = p.badges || [];

    // Verhalen laden
    // Haal verhalen op - probeer meerdere methoden zodat ontbrekende indexes geen probleem zijn
    var verhalen = [];
    var gezieneIds = {};

    // Methode 1: orderBy ts (vereist index) - meest recent
    try {
      var snap1 = await DY.db.collection('stories')
        .where('userId', '==', uid)
        .orderBy('ts', 'desc')
        .limit(20)
        .get();
      snap1.docs.forEach(function(d) {
        if (!gezieneIds[d.id]) { gezieneIds[d.id] = true; var v = d.data(); v._id = d.id; v._docId = d.id; verhalen.push(v); }
      });
    } catch(e) {
      // Index ontbreekt - haal alle recente stories op en filter client-side
      try {
        var snap2 = await DY.db.collection('stories')
          .orderBy('ts', 'desc')
          .limit(100)
          .get();
        snap2.docs.forEach(function(d) {
          var v = d.data();
          var vUid = v.userId || v.uid || v.authorId || '';
          if (vUid === uid && !gezieneIds[d.id]) {
            gezieneIds[d.id] = true; v._id = d.id; v._docId = d.id; verhalen.push(v);
          }
        });
      } catch(e2) { }
    }

    // Methode 2: ook op authorId zoeken (oudere stories)
    if (verhalen.length === 0) {
      try {
        var snap3 = await DY.db.collection('stories')
          .where('authorId', '==', uid)
          .limit(20)
          .get();
        snap3.docs.forEach(function(d) {
          if (!gezieneIds[d.id]) { gezieneIds[d.id] = true; var v = d.data(); v._id = d.id; v._docId = d.id; verhalen.push(v); }
        });
      } catch(e) {}
    }

    // Sorteer op datum
    verhalen.sort(function(a, b) {
      var da = a.ts && a.ts.toDate ? a.ts?.toDate?.() : new Date(a.createdAt || 0);
      var db2 = b.ts && b.ts.toDate ? b.ts?.toDate?.() : new Date(b.createdAt || 0);
      return db2 - da;
    });

    var verhalenEl = document.getElementById('gu-verhalen');
    if (verhalenEl) {
      if (verhalen.length === 0) {
        verhalenEl.innerHTML = '<div class="dy-leeg" style="grid-column:1/-1"><p style="color:var(--ink-muted);font-size:0.85rem;padding:var(--sp-4)">Nog geen verhalen gevonden.</p></div>';
      } else {
        verhalenEl.innerHTML = '';
        verhalen.slice(0, 12).forEach(function(v) {
          var k = DY.verhaalKaart(v, { compact: true });
          if (k) verhalenEl.appendChild(k);
        });
      }
    }

  } catch(e) {
    var st = document.getElementById('gu-stats');
    if (st) st.innerHTML = '<p style="padding:16px;color:var(--ink-muted);font-size:0.85rem">Profiel kon niet worden geladen.</p>';
  }
};
DY.renderMeldingen = async function() {
  if (!DY.user) {
    var _vPag = (DY._history && DY._history.length > 0) ? DY._history[DY._history.length-1] : 'feed';
    var _vR = {feed:DY.renderFeed,home:DY.renderHome,lookbook:DY.renderLookbook,vrienden:DY.renderVrienden,winkel:DY.renderWinkel};
    DY.pagina = null;
    if (_vR[_vPag]) { DY.pagina = _vPag; _vR[_vPag](); } else { DY.pagina = 'feed'; DY.renderFeed(); }
    DY.toonLoginPrompt('Inloggen om meldingen te zien.');
    return;
  }
  var main = document.getElementById('dy-main');

  main.innerHTML =
    '<div class="dy-pg-header">' +
      '<div class="dy-pg-header-inner">' +
        '<div>' +
          '<button class="dy-back-btn" onclick="DY.terug()" style="margin-bottom:var(--sp-2)" data-testid="meldingen-terug-btn">← Terug</button>' +
          '<div class="dy-feed-merk-label">Paskamerpraat</div>' +
          '<h1 class="dy-pg-titel">Activiteiten</h1>' +
        '</div>' +
      '</div>' +
    '</div>' +
    '<div id="dy-meld-lijst" style="background:var(--cream);min-height:200px">' +
      '<div class="dy-pg-skel-wrap dy-pg-skel-lijst">' +
        '<div class="dy-pg-skel-rij"></div><div class="dy-pg-skel-rij"></div>' +
        '<div class="dy-pg-skel-rij"></div><div class="dy-pg-skel-rij"></div>' +
      '</div>' +
    '</div>';

  // Markeer alle meldingen als gelezen bij openen
  DY.markeerMeldingenGelezen().catch(function(){});

  try {
    var snap = await DY.db.collection('meldingen')
      .where('userId', '==', DY.user.uid)
      .orderBy('ts', 'desc')
      .limit(50)
      .get();

    var lijst = document.getElementById('dy-meld-lijst');
    if (!lijst) return;

    if (snap.empty) {
      lijst.innerHTML =
        '<div class="dy-pg-leeg">' +
          '<div class="dy-pg-leeg-icon">🔔</div>' +
          '<h3 class="dy-pg-leeg-titel">Geen activiteiten</h3>' +
          '<p class="dy-pg-leeg-sub">Je activiteiten zoals likes, reacties en nieuwe volgers verschijnen hier.</p>' +
        '</div>';
      return;
    }

    var iconen = {
      'like': '❤️', 'volgend': '👤', 'reactie': '💬',
      'reactie_like': '❤️', 'review': '⭐', 'verhaal_reactie': '💬',
    };

    var teksten = {
      'like':          function(m) { return '<strong>' + DY.escapeHtml(m.vanNaam||'Iemand') + '</strong> heeft je verhaal geliked'; },
      'volgend':       function(m) { return '<strong>' + DY.escapeHtml(m.vanNaam||'Iemand') + '</strong> volgt jou nu'; },
      'reactie':       function(m) { return '<strong>' + DY.escapeHtml(m.vanNaam||'Iemand') + '</strong> reageerde: <em>' + DY.escapeHtml((m.preview||'').slice(0,40)) + '</em>'; },
      'verhaal_reactie': function(m) { return '<strong>' + DY.escapeHtml(m.vanNaam||'Iemand') + '</strong> reageerde op je verhaal'; },
      'review':        function(m) { return '<strong>' + DY.escapeHtml(m.vanNaam||'Iemand') + '</strong> schreef een review'; },
    };

    var items = '';
    snap.forEach(function(doc) {
      var m = doc.data();
      var type = m.type || 'like';
      var icon = iconen[type] || '🔔';
      var tekst = teksten[type] ? teksten[type](m) : ('Nieuwe activiteit van <strong>' + DY.escapeHtml(m.vanNaam||'Iemand') + '</strong>');
      var ts = m.ts && m.ts.toDate ? DY.tijdGeleden(m.ts?.toDate?.()) : '';
      var init = (m.vanNaam||'?').slice(0,2).toUpperCase();
      var ongelezen = m.gelezen === false ? ' ongelezen' : '';

      items +=
        '<div class="dy-meld-item' + ongelezen + '">' +
          '<div class="dy-meld-avatar">' +
            (m.vanAvatar ? '<img src="' + m.vanAvatar + '" loading="lazy" decoding="async">' : init) +
          '</div>' +
          '<div class="dy-meld-content">' +
            '<p class="dy-meld-tekst">' + tekst + '</p>' +
            (ts ? '<span class="dy-meld-tijd">' + ts + '</span>' : '') +
          '</div>' +
          '<span class="dy-meld-icon">' + icon + '</span>' +
        '</div>';
    });

    lijst.innerHTML = '<div style="display:flex;flex-direction:column;gap:1px;background:var(--border)">' + items + '</div>';

    // Markeer als gelezen
    var batch = DY.db.batch();
    snap.docs.filter(function(d) { return d.data().gelezen === false; }).slice(0,20).forEach(function(d) {
      batch.update(d.ref, { gelezen: true });
    });
    batch.commit().catch(function(){});

  } catch(e) {
    var lijst = document.getElementById('dy-meld-lijst');
    if (lijst) lijst.innerHTML = '<div class="dy-pg-leeg"><p>Meldingen konden niet worden geladen.</p></div>';
  }
};

DY.maakMelding = async function(userId, tekst, icon, link) {
  if (!userId || userId === (DY.user && DY.user.uid)) return;
  try {
    await DY.db.collection('meldingen').add({ userId: userId, tekst: tekst, icon: icon||'🔔', link: link||'', gelezen: false, ts: firebase.firestore.FieldValue.serverTimestamp(), createdAt: new Date().toISOString() });
  } catch(e) {}
};

// ══════════════════════════════════════════════════════════════════
// MELDINGEN BADGE
// ══════════════════════════════════════════════════════════════════
DY.controleerMeldingen = function() {
  if (!DY.user || !DY.db) return;
  // Stop eventuele bestaande listener
  if (window._meldingenUnsub) {
    try { window._meldingenUnsub(); } catch(e) {}
    window._meldingenUnsub = null;
  }
  try {
    // Realtime onSnapshot - badge update direct bij wijziging
    window._meldingenUnsub = DY.db.collection('meldingen')
      .where('userId', '==', DY.user.uid)
      .where('gelezen', '==', false)
      .onSnapshot(function(snap) {
        var badge = document.getElementById('dy-notif-badge');
        if (!badge || !snap) return;
        var aantal = snap.size || 0;
        if (aantal > 0) {
          badge.textContent = aantal > 9 ? '9+' : String(aantal);
          badge.style.display = 'flex';
        } else {
          badge.style.display = 'none';
        }
      }, function(e) {
        // Fallback als onSnapshot faalt (bijv. geen composite index)
        // Gebruik .get() met client-side filter
        if (!DY.user || !DY.user.uid) return; // v60.1.52: null-guard voor uitlog-race
        DY.db.collection('meldingen')
          .where('userId', '==', DY.user.uid)
          .limit(30).get()
          .then(function(snap) {
            var badge = document.getElementById('dy-notif-badge');
            if (!badge) return;
            var aantal = (snap && snap.docs ? snap.docs : []).filter(function(d){ return d.data().gelezen !== true; }).length;
            if (aantal > 0) {
              badge.textContent = aantal > 9 ? '9+' : String(aantal);
              badge.style.display = 'flex';
            } else {
              badge.style.display = 'none';
            }
          }).catch(function(){
            var badge = document.getElementById('dy-notif-badge');
            if (badge) badge.style.display = 'none';
          });
      });
  } catch(e) {
    var badge = document.getElementById('dy-notif-badge');
    if (badge) badge.style.display = 'none';
  }
};

// ══════════════════════════════════════════════════════════════════
DY.markeerMeldingenGelezen = async function() {
  if (!DY.user || !DY.db) return;
  try {
    var snap = await DY.db.collection('meldingen')
      .where('userId', '==', DY.user.uid)
      .where('gelezen', '==', false)
      .limit(30).get();
    if (snap.empty) return;
    var batch = DY.db.batch();
    (snap && snap.docs ? snap.docs : []).forEach(function(doc) { batch.update(doc.ref, { gelezen: true }); });
    await batch.commit();
    var badge = document.getElementById('dy-notif-badge');
    if (badge) badge.style.display = 'none';
  } catch(e) {
  }
};


