// NIEUW INDICATOR
// ══════════════════════════════════════════════════════════════════
DY.controleerNieuw = async function() {
  try {
    const laatste = localStorage.getItem('dy_laatste_bezoek');
    if (!laatste) { localStorage.setItem('dy_laatste_bezoek', new Date().toISOString()); return; }
    const snap = await DY.db.collection('stories').limit(50).get();
    const nieuweTs = new Date(laatste);
    let aantalNieuw = 0;
    snap.forEach(function(doc) {
      const d = doc.data();
      const ts = d.ts && d.ts.toDate ? d.ts?.toDate?.() : new Date(d.createdAt||0);
      if (ts > nieuweTs) aantalNieuw++;
    });
    if (aantalNieuw > 0) {
      const badge = document.getElementById('dy-nieuw-badge');
      const btn = document.getElementById('dy-topbar-nieuw');
      if (badge && btn) {
        badge.textContent = aantalNieuw > 9 ? '9+' : String(aantalNieuw);
        badge.style.display = 'flex';
        btn.style.display = 'flex';
      }
    }
    localStorage.setItem('dy_laatste_bezoek', new Date().toISOString());
  } catch(e) {}
};

DY.toonNieuw = function() {
  const badge = document.getElementById('dy-nieuw-badge');
  if (badge) badge.style.display = 'none';
  DY.navigeer('feed');
};

