DY._laadOutfitStems = async function(challengeId) {
  var grid = document.getElementById('dy-stem-grid-' + challengeId);
  if (!grid) return;
  try {
    var snap = await DY.db.collection('looks')
      .where('challengeId', '==', challengeId)
      .orderBy('stems', 'desc').limit(3).get();
    if (snap.empty) {
      grid.innerHTML = '<p style="font-size:0.82rem;color:rgba(252,248,239,0.4);text-align:center;padding:12px 0">Nog geen inzendingen - wees de eerste.</p>';
      return;
    }
    var mijnStem = false;
    if (DY.user) {
      var stemDoc = await DY.db.collection('challenge_stemmen').doc(DY.user.uid + '_' + challengeId).get();
      mijnStem = stemDoc.exists;
    }
    grid.innerHTML = snap.docs.map(function(doc) {
      var d = doc.data();
      var foto = (d.fotos && d.fotos[0]) || d.foto || '';
      var naam = DY.escapeHtml(d.authorName || 'Anoniem');
      var stems = d.stems || 0;
      var stemBtn = (!mijnStem && DY.user)
        ? '<button class="dy-stem-btn" data-lid="' + doc.id + '" data-cid="' + challengeId + '" onclick="DY._stemOpOutfit(this)">Stem</button>'
        : '<span class="dy-stem-gestemd">' + (mijnStem ? '\u2713' : '') + '</span>';
      return '<div class="dy-stem-kaart">' +
        (foto ? '<img src="' + foto + '" alt="Outfit" class="dy-stem-foto" loading="lazy" decoding="async">' : '<div class="dy-stem-foto dy-stem-foto-leeg"></div>') +
        '<div class="dy-stem-info"><span class="dy-stem-naam">' + naam + '</span><span class="dy-stem-count">' + stems + ' stemmen</span></div>' +
        stemBtn + '</div>';
    }).join('');
  } catch(e) {
    if (grid) grid.innerHTML = '<p style="font-size:0.82rem;color:rgba(252,248,239,0.4);padding:8px 0">Inzendingen konden niet worden geladen.</p>';
  }
};

DY._stemOpOutfit = async function(btn) {
  if (!DY.user) { DY.toonLoginPrompt('Log in om te stemmen.'); return; }
  var lookId = btn.getAttribute('data-lid');
  var challengeId = btn.getAttribute('data-cid');
  var stemDocId = DY.user.uid + '_' + challengeId;
  btn.disabled = true; btn.textContent = '...';
  try {
    await DY.db.runTransaction(async function(tx) {
      var stemRef = DY.db.collection('challenge_stemmen').doc(stemDocId);
      var bestaand = await tx.get(stemRef);
      if (bestaand.exists) throw new Error('al_gestemd');
      tx.set(stemRef, { uid: DY.user.uid, lookId: lookId, challengeId: challengeId, ts: firebase.firestore.FieldValue.serverTimestamp() });
      tx.update(DY.db.collection('looks').doc(lookId), { stems: firebase.firestore.FieldValue.increment(1) });
    });
    btn.textContent = '\u2713'; btn.style.background = '#1D9E75';
    var lookSnap = await DY.db.collection('looks').doc(lookId).get();
    if (lookSnap.exists) {
      var auteurUid = lookSnap.data().userId;
      if (auteurUid) {
        DY.geefPuntenAanGebruiker(auteurUid, 5, 'challenge_stem', lookId);
        DY._stuurPushGedebounced(auteurUid, 'challenge_stem', lookId, '');
      }
    }
    DY._toonToastBericht('Stem uitgebracht \u2713');
    setTimeout(function() { DY._laadOutfitStems(challengeId); }, 500);
  } catch(e) {
    if (e.message === 'al_gestemd') { btn.textContent = '\u2713'; }
    else { btn.disabled = false; btn.textContent = 'Stem'; }
  }
};


DY.challengeKaartHTML = function(c, toonDetailLink) {
  var deadline = new Date(c.deadline || Date.now() + 604800000);
  var dagenOver = Math.ceil((deadline - new Date()) / (1000 * 60 * 60 * 24));
  var isOvdW = c.type === 'outfit_week';
  var countdown = dagenOver > 0
    ? (dagenOver === 1 ? 'Nog 1 dag' : 'Nog ' + dagenOver + ' dagen')
    : 'Verlopen';
  var isVerlopen = dagenOver <= 0;

  if (isOvdW) {
    return '<div class="dy-ch-kaart dy-ch-kaart--featured">' +
      '<div class="dy-ch-kaart__top">' +
        '<span class="dy-ch-kaart__eyebrow">Uitgelicht · Wekelijks</span>' +
        '<span class="dy-ch-kaart__bonus">+' + c.bonus + ' <span class="dy-dsp-label">DSP</span></span>' +
      '</div>' +
      '<div class="dy-ch-kaart__icon">👑</div>' +
      '<h2 class="dy-ch-kaart__titel">' + c.titel + '</h2>' +
      '<p class="dy-ch-kaart__omschrijving">Elke week wordt de meest geliefde post automatisch gekozen als Post van de Week. Alleen posts met 25+ likes maken kans.</p>' +
      '<div class="dy-ch-kaart__footer">' +
        '<span class="dy-ch-kaart__countdown' + (isVerlopen ? ' dy-ch-verlopen' : '') + '">' + countdown + '</span>' +
        '<button class="dy-ch-kaart__cta" onclick="DY.navigeer(\'ovdw\')">' +
          '✶ Bekijk Post van de Week' +
        '</button>' +
      '</div>' +
    '</div>';
  }

  var detailLink = (toonDetailLink)
    ? '<button class="dy-ch-kaart__detail" onclick="DY._pendingChallengeId=\'' + c._id + '\';DY.navigeer(\'challenge_detail\')">Leaderboard & details →</button>'
    : '';

  return '<div class="dy-ch-kaart">' +
    '<div class="dy-ch-kaart__top">' +
      '<div class="dy-ch-kaart__top-left">' +
        '<span class="dy-ch-kaart__icon-sm">' + (c.icon || '🎯') + '</span>' +
        '<span class="dy-ch-kaart__countdown' + (isVerlopen ? ' dy-ch-verlopen' : '') + '">' + countdown + '</span>' +
      '</div>' +
      '<span class="dy-ch-kaart__bonus">+' + c.bonus + ' <span class="dy-dsp-label">DSP</span></span>' +
    '</div>' +
    '<h3 class="dy-ch-kaart__titel">' + c.titel + '</h3>' +
    '<p class="dy-ch-kaart__omschrijving">' + c.omschrijving + '</p>' +
    '<div class="dy-ch-kaart__acties">' +
      '<button class="dy-ch-kaart__cta" onclick="DY.doeChallenge(\'' + c.actie + '\', \'' + c._id + '\')">' +
        'Deelnemen →' +
      '</button>' +
      detailLink +
    '</div>' +
  '</div>';
};

DY.doeChallenge = function(actie, challengeId) {
  if (!DY.user) { DY.toonLoginPrompt('Log in om deel te nemen.'); return; }
  if (actie === 'verhaal_plaatsen') DY.navigeer('nieuw');
  else if (actie === 'look_plaatsen') {
    // Sla challenge context op zodat plaatsLook weet voor welke challenge dit is
    DY._pendingChallenge = { id: challengeId, type: 'outfit_week' };
    DY.navigeer('lookbook_nieuw');
  }
  else if (actie === 'reactie_plaatsen') DY.navigeer('feed');
};


