DY._ovdwSetSort = function(sort, btn) {
  // Bewaard voor backwards compat - sort toolbar is verwijderd
  DY._ovdwSort = sort;
  DY._ovdwLaad();
};

DY._ovdwLaad = async function() {
  var _myId = (DY._ovdwLaadId = (DY._ovdwLaadId || 0) + 1);
  var grid = document.getElementById('dy-ovdw-grid');
  if (!grid || !DY.db) return;

  try {
    var query = DY.db.collection('stories').orderBy('ts', 'desc').limit(40);
    var snap = await query.get().catch(async function() {
      return await DY.db.collection('stories').limit(40).get();
    });

    if (DY._ovdwLaadId !== _myId || !document.getElementById('dy-ovdw-grid')) return;

    if (snap.empty) {
      grid.innerHTML =
        '<div class="dy-ovdw-leeg">' +
          '<div class="dy-ovdw-leeg-icon">\u2736</div>' +
          '<p>Nog geen posts deze week.</p>' +
          '<p class="dy-ovdw-leeg-sub">Deel jouw look en maak kans op Post van de Week!</p>' +
        '</div>';
      return;
    }

    var posts = (snap && snap.docs ? snap.docs : []).map(function(d) { return Object.assign({_id: d.id}, d.data()); });
    // Bereken likesCount voor elk post (likes = object {uid: true})
    posts.forEach(function(p) {
      p._likesCount = p.likes && typeof p.likes === 'object'
        ? Object.keys(p.likes).length
        : (Number(p.likes) || 0);
    });
    // Sorteer op nieuwste
    posts.sort(function(a, b) {
      var ta = a.tsMs || (a.ts && a.ts.toMillis ? a.ts.toMillis() : 0);
      var tb = b.tsMs || (b.ts && b.ts.toMillis ? b.ts.toMillis() : 0);
      return tb - ta;
    });

    // Bouw kaarten via DOM zodat event delegation correct werkt
    grid.innerHTML = '';
    posts.forEach(function(post) {
      var foto  = post.photo || post.foto || post.image || post.imageUrl || '';
      var naam  = post.authorName || post.displayName || post.naam || 'Anoniem';
      var likes = post._likesCount;
      var ts    = post.tsMs
        ? new Date(post.tsMs).toLocaleDateString('nl-NL', {day:'2-digit', month:'short'})
        : post.createdAt ? new Date(post.createdAt).toLocaleDateString('nl-NL', {day:'2-digit', month:'short'}) : '';
      var eligibel = likes >= 25;
      var heeftGelikt = !!(DY.user && post.likes && post.likes[DY.user.uid] === true);

      var kaart = document.createElement('div');
      kaart.className = 'dy-ovdw-kaart';
      kaart.dataset.postId = post._id;
      if (post.userId || post.authorId) kaart.dataset.uid = post.userId || post.authorId || '';
      if (naam) kaart.dataset.naam = naam;

      kaart.innerHTML =
        (foto
          ? '<div class="dy-ovdw-foto-wrap"><img src="' + DY._esc(foto) + '" alt="Post" class="dy-ovdw-foto" loading="lazy" decoding="async"></div>'
          : '<div class="dy-ovdw-foto-wrap dy-ovdw-foto--leeg"></div>') +
        '<div class="dy-ovdw-kaart-info">' +
          '<span class="dy-ovdw-naam" style="cursor:pointer">' + DY._esc(naam) + '</span>' +
          '<div class="dy-ovdw-meta">' +
            '<button class="dy-ovdw-like-btn' + (heeftGelikt ? ' liked' : '') + '" data-doc="' + post._id + '" aria-label="Like" type="button">' +
              '<svg class="dy-ovdw-heart" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>' +
              '<span class="dy-ovdw-like-count">' + (likes || 0) + '</span>' +
              (eligibel ? '<span class="dy-ovdw-eligible-mark">✓</span>' : '') +
            '</button>' +
            '<span class="dy-ovdw-ts">' + DY._esc(ts) + '</span>' +
          '</div>' +
        '</div>';

      kaart.addEventListener('click', function(e) {
        var likeBtn = e.target.closest('.dy-ovdw-like-btn');
        var naamEl  = e.target.closest('.dy-ovdw-naam');
        if (naamEl && kaart.dataset.uid) {
          e.stopPropagation();
          DY.openGebruiker(kaart.dataset.uid, naam);
          return;
        }
        if (likeBtn) {
          e.stopPropagation();
          DY._ovdwToggleLike(likeBtn.dataset.doc, likeBtn);
          return;
        }
        DY._ovdwOpenLook(post._id, naam);
      });

      grid.appendChild(kaart);
    });

    // Ruim vorige onSnapshot listeners op
    DY._ovdwUnsubscribes = DY._ovdwUnsubscribes || [];
    DY._ovdwUnsubscribes.forEach(function(u) { try { u(); } catch(ex) {} });
    DY._ovdwUnsubscribes = [];

    // Realtime likes via onSnapshot per kaart
    posts.forEach(function(post) {
      var unsub = DY.db.collection('stories').doc(post._id)
        .onSnapshot(function(snap) {
          if (!snap.exists) return;
          var data = snap.data();
          var count = data.likes && typeof data.likes === 'object'
            ? Object.keys(data.likes).length
            : (Number(data.likes) || 0);
          var heeftGelikt = !!(DY.user && data.likes && data.likes[DY.user.uid] === true);
          var eligibel = count >= 25;
          var kaartEl = grid.querySelector('[data-post-id="' + post._id + '"]');
          if (!kaartEl) return;
          var btn = kaartEl.querySelector('.dy-ovdw-like-btn');
          if (!btn) return;
          btn.classList.toggle('liked', heeftGelikt);
          var countEl = btn.querySelector('.dy-ovdw-like-count');
          if (countEl) countEl.textContent = count;
          var markEl = btn.querySelector('.dy-ovdw-eligible-mark');
          if (eligibel && !markEl) {
            var m = document.createElement('span');
            m.className = 'dy-ovdw-eligible-mark';
            m.textContent = '✓';
            btn.appendChild(m);
          } else if (!eligibel && markEl) {
            markEl.parentNode.removeChild(markEl);
          }
        });
      DY._ovdwUnsubscribes.push(unsub);
    });

  } catch(e) {
    if (grid) grid.innerHTML = '<div style="padding:24px;text-align:center;color:rgba(253,248,240,0.5);font-size:0.84rem">Kon posts niet laden.<br><small>' + e.message + '</small></div>';
  }
};


// _ovdwStem verwijderd: OVDW is nu read-only (ranking op likes, niet stemmen)
DY._ovdwStem = function() { /* no-op */ };

// Like vanuit OVDW kaart
DY._ovdwToggleLike = async function(verhaalId, btn) {
  if (!DY.user) { DY.toonLoginPrompt('Like posts en maak kans om Post van de Week te worden.'); return; }
  if (!verhaalId || btn.disabled) return;
  btn.disabled = true;
  var countEl = btn.querySelector('.dy-ovdw-like-count');
  var currentCount = parseInt(countEl ? countEl.textContent : '0', 10) || 0;
  var wasLiked = btn.classList.contains('liked');
  var nieuweCount = Math.max(0, currentCount + (wasLiked ? -1 : 1));
  btn.classList.toggle('liked', !wasLiked);
  if (countEl) countEl.textContent = nieuweCount;
  try {
    var ref = DY.db.collection('stories').doc(verhaalId);
    var snap = await ref.get();
    if (!snap.exists) { btn.disabled = false; return; }
    var data = snap.data();
    var uid = DY.user.uid;
    var likesObj = (data.likes && typeof data.likes === 'object') ? data.likes : {};
    var liked = likesObj[uid] === true;
    var updateData = {};
    updateData['likes.' + uid] = liked ? firebase.firestore.FieldValue.delete() : true;
    await ref.update(updateData);
    window.dispatchEvent(new Event('dy_positieve_actie'));
    var finalCount = Math.max(0, Object.keys(likesObj).length + (liked ? -1 : 1));
    if (!liked) {
      if (finalCount === 5)  DY.geefPunten && await DY.geefPunten('likes_5',  { verhaal_id: verhaalId });
      if (finalCount === 20) DY.geefPunten && await DY.geefPunten('likes_20', { verhaal_id: verhaalId });
      DY.geefPunten && DY.geefPunten('like_ontvangen_story', verhaalId).catch(function(){});
    } else {
      if (finalCount === 4)  DY.ontneemPunten && await DY.ontneemPunten('likes_5',  { verhaal_id: verhaalId });
      if (finalCount === 19) DY.ontneemPunten && await DY.ontneemPunten('likes_20', { verhaal_id: verhaalId });
      DY.ontneemPunten && DY.ontneemPunten('like_ontvangen_story', verhaalId).catch(function(){});
    }
  } catch(err) {
    btn.classList.toggle('liked', wasLiked);
    if (countEl) countEl.textContent = currentCount;
  }
  btn.disabled = false;
};

DY._ovdwOpenLook = function(lookId, naam) {
  if (DY._openDetailOverlay) DY._openDetailOverlay(lookId);
};

DY._esc = DY._esc || function(s) {
  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
};



