// Bereken ISO weeknummer (ma=dag 1)
DY._pvdwWeekNummer = function(datum) {
  var d = new Date(Date.UTC(datum.getFullYear(), datum.getMonth(), datum.getDate()));
  var dag = d.getUTCDay() || 7; // maandag = 1
  d.setUTCDate(d.getUTCDate() + 4 - dag);
  var jaarStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return d.getUTCFullYear() + '-W' + String(Math.ceil((((d - jaarStart) / 86400000) + 1) / 7)).padStart(2, '0');
};

// Bepaal weekStart (maandag 00:00 Amsterdam) en weekEnd (zondag 23:59:59) voor een datum
DY._pvdwWeekBereik = function(datum) {
  // Werk altijd in locale tijdzone - Cloudflare Worker doet dit TZ=Europe/Amsterdam
  var d = new Date(datum);
  var dag = d.getDay(); // 0=zondag
  var dagNaMa = (dag === 0) ? 6 : dag - 1; // dagen na maandag
  var maandag = new Date(d);
  maandag.setHours(0, 0, 0, 0);
  maandag.setDate(d.getDate() - dagNaMa);
  var zondag = new Date(maandag);
  zondag.setDate(maandag.getDate() + 6);
  zondag.setHours(23, 59, 59, 999);
  return { start: maandag, end: zondag };
};

// Client-side: haal winnaar op uit weekly_rankings collectie
DY._pvdwLaadWinnaar = async function() {
  var banner = document.getElementById('dy-ovdw-winnaar-banner');
  if (!banner || !DY.db) return;

  try {
    // Zoek meest recente winnaar
    var snap = await DY.db.collection('weekly_rankings')
      .where('status', '==', 'selected')
      .orderBy('weekId', 'desc')
      .limit(1)
      .get()
      .catch(async function() {
        // Fallback zonder orderBy als index nog niet bestaat
        return await DY.db.collection('weekly_rankings')
          .where('status', '==', 'selected')
          .limit(5)
          .get()
          .catch(function() { return { empty: true, docs: [] }; });
      });

    if (snap.empty) {
      // Geen winnaar: toon "geen winnaar" state
      banner.innerHTML =
        '<div class="dy-ovdw-geen-winnaar">' +
          '<span class="dy-ovdw-geen-icon">👑</span>' +
          '<div>' +
            '<div class="dy-ovdw-geen-titel">Nog geen winnaar</div>' +
            '<div class="dy-ovdw-geen-sub">Posts met 25+ likes maken kans. Winnaar wordt elke maandag gekozen.</div>' +
          '</div>' +
        '</div>';
      return;
    }

    // Bij fallback zonder orderBy: kies hoogste weekId
    var docs = snap.docs.slice().sort(function(a, b) {
      return (b.data().weekId || '').localeCompare(a.data().weekId || '');
    });
    var winnaar = Object.assign({ _id: docs[0].id }, docs[0].data());

    // Haal post data op
    var postSnap = await DY.db.collection('stories').doc(winnaar.postId).get()
      .catch(function() { return { exists: false }; });

    var post = postSnap.exists ? Object.assign({ _id: postSnap.id }, postSnap.data()) : null;
    var foto = post ? (post.photo || post.foto || post.image || '') : '';
    var naam = post ? (post.authorName || post.displayName || 'Anoniem') : (winnaar.authorName || 'Onbekend');
    var likes = winnaar.likesCount || 0;

    // Weeknummer label: YYYY-W## → "Week ##"
    var wLabel = winnaar.weekId ? 'Week ' + (winnaar.weekId.split('-W')[1] || winnaar.weekId) : '';

    // Bouw winnaar kaart via DOM zodat like-knop event correct werkt
    var postLikesObj = (post && post.likes && typeof post.likes === 'object') ? post.likes : {};
    var postLikes = Object.keys(postLikesObj).length || likes;
    var heeftGelikt = !!(DY.user && postLikesObj[DY.user && DY.user.uid]);

    var wKaart = document.createElement('div');
    wKaart.className = 'dy-ovdw-winnaar-kaart';

    wKaart.innerHTML =
      (foto ? '<div class="dy-ovdw-winnaar-foto-wrap"><img src="' + DY._esc(foto) + '" alt="Post van de week" class="dy-ovdw-winnaar-foto" loading="lazy"></div>' : '') +
      '<div class="dy-ovdw-winnaar-info">' +
        '<div class="dy-ovdw-winnaar-badge">👑 Post van de Week</div>' +
        '<div class="dy-ovdw-winnaar-naam" style="cursor:pointer">' + DY._esc(naam) + '</div>' +
        '<div class="dy-ovdw-winnaar-meta">' +
          '<button class="dy-ovdw-like-btn' + (heeftGelikt ? ' liked' : '') + '" data-doc="' + DY._esc(winnaar.postId) + '" aria-label="Like" type="button">' +
            '<svg class="dy-ovdw-heart" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>' +
            '<span class="dy-ovdw-like-count">' + postLikes + '</span>' +
          '</button>' +
          (wLabel ? '<span class="dy-ovdw-winnaar-week">' + DY._esc(wLabel) + '</span>' : '') +
        '</div>' +
      '</div>';

    var _winnaarUid = winnaar.userId || winnaar.authorId || '';
    wKaart.addEventListener('click', function(e) {
      var likeBtn = e.target.closest('.dy-ovdw-like-btn');
      var naamEl  = e.target.closest('.dy-ovdw-winnaar-naam');
      if (naamEl && _winnaarUid) {
        e.stopPropagation();
        DY.openGebruiker(_winnaarUid, naam);
        return;
      }
      if (likeBtn) {
        e.stopPropagation();
        DY._ovdwToggleLike(likeBtn.dataset.doc, likeBtn);
        return;
      }
      DY._ovdwOpenLook(winnaar.postId, naam);
    });

    banner.innerHTML = '';
    banner.appendChild(wKaart);

    // Realtime like update voor winnaar kaart
    var winnaarUnsub = DY.db.collection('stories').doc(winnaar.postId)
      .onSnapshot(function(snap) {
        if (!snap.exists) return;
        var data = snap.data();
        var count = data.likes && typeof data.likes === 'object'
          ? Object.keys(data.likes).length : (Number(data.likes) || 0);
        var gelikt = !!(DY.user && data.likes && data.likes[DY.user.uid] === true);
        var btn = wKaart.querySelector('.dy-ovdw-like-btn');
        if (!btn) return;
        btn.classList.toggle('liked', gelikt);
        var cEl = btn.querySelector('.dy-ovdw-like-count');
        if (cEl) cEl.textContent = count;
      });
    DY._ovdwUnsubscribes = DY._ovdwUnsubscribes || [];
    DY._ovdwUnsubscribes.push(winnaarUnsub);

  } catch(e) {
    banner.innerHTML =
      '<div class="dy-ovdw-geen-winnaar">' +
        '<span class="dy-ovdw-geen-icon">👑</span>' +
        '<div><div class="dy-ovdw-geen-sub">Winnaar kon niet worden geladen.</div></div>' +
      '</div>';
  }
};

