DY.renderLeaderboard = async function() {
  // Auth-gate: alleen voor ingelogde gebruikers
  if (!DY.user) {
    // Zorg dat main content heeft voordat de modal verschijnt
    var _lbMain = document.getElementById('dy-main');
    if (_lbMain && (!_lbMain.innerHTML || _lbMain.innerHTML.trim().length < 50)) {
      DY.pagina = 'feed'; DY.renderFeed();
    }
    DY.toonLoginPrompt('Je moet ingelogd zijn om Top leden te bekijken.');
    return;
  }
  const main = document.getElementById('dy-main');
  if (!main) return;
  main.style.background = '#0a0806';
  main.style.paddingBottom = '0';
  main.innerHTML =
    '<div class="dy-vr-header">' +
      '<div class="dy-vr-header-inner">' +
        '<div>' +
          '<div class="dy-feed-merk-label">Paskamerpraat</div>' +
          '<h1 class="dy-vr-titel">Top <em>leden</em></h1>' +
        '</div>' +
        '<button class="dy-pg-actie-btn" onclick="DY.navigeer(\'feed\')">← Terug</button>' +
      '</div>' +
    '</div>' +
    '<div class="dy-lb2-wrap">' +
      '<div id="dy-leaderboard-lijst" class="dy-lb2-lijst">' +
        '<div class="dy-pg-skel-wrap dy-pg-skel-lijst">' +
          '<div class="dy-pg-skel-rij"></div><div class="dy-pg-skel-rij"></div>' +
          '<div class="dy-pg-skel-rij"></div><div class="dy-pg-skel-rij"></div>' +
          '<div class="dy-pg-skel-rij"></div>' +
        '</div>' +
      '</div>' +
    '</div>';

  try {
    const snap = await DY.db.collection('users').limit(100).get();
    const lijst = document.getElementById('dy-leaderboard-lijst');
    if (!lijst) return;
    if (snap.empty) { lijst.innerHTML = '<div class="dy-pg-leeg"><div class="dy-pg-leeg-icon">&#10022;</div><p>Nog geen leden.</p></div>'; return; }

    const leden = [];
    snap.forEach(doc => {
      const d = doc.data();
      const pts = d.dsp_seizoen || d.dsp_lifetime || 0;
      if (pts > 0) leden.push({ uid: doc.id, naam: d.displayName || 'Anoniem', avatar: d.avatar || null, dsp_seizoen: d.dsp_seizoen || 0, niveau: d.niveau || 'Binnenkomer' });
    });
    leden.sort((a, b) => b.dsp_seizoen - a.dsp_seizoen);
    const top10 = leden.slice(0, 10);
    const periodeLbl = DY.seizoenLabel ? DY.seizoenLabel(DY.huidigSeizoen ? DY.huidigSeizoen() : '') : 'Dit seizoen';
    const rangMeta = [{ icon: '&#129351;', cls: 'goud', kleur: '#c9a227' }, { icon: '&#129352;', cls: 'zilver', kleur: '#9ba7b0' }, { icon: '&#129353;', cls: 'brons', kleur: '#c07c4a' }];

    var podiumHTML = top10.slice(0, 3).map(function(lid, i) {
      var m = rangMeta[i]; var init = lid.naam.slice(0, 2).toUpperCase();
      var isJij = DY.user && lid.uid === DY.user.uid;
      return '<div class="dy-lb2-podium-item ' + m.cls + (isJij ? ' jij' : '') + '" data-uid="' + lid.uid + '" data-naam="' + DY.escapeHtml(lid.naam) + '">' +
        '<div class="dy-lb2-podium-avatar" style="border-color:' + m.kleur + '">' + (lid.avatar ? '<img src="' + lid.avatar + '" loading="lazy" decoding="async">' : init) + '<span class="dy-lb2-podium-rank">' + m.icon + '</span></div>' +
        '<span class="dy-lb2-podium-naam">' + DY.escapeHtml(lid.naam.split(' ')[0]) + (isJij ? ' &#10003;' : '') + '</span>' +
        '<span class="dy-lb2-podium-pts">' + (lid.dsp_seizoen || 0).toLocaleString('nl-NL') + ' <span class="dy-dsp-label">DSP</span></span>' +
      '</div>';
    }).join('');

    var restHTML = top10.slice(3).map(function(lid, i) {
      var rang = i + 4; var isJij = DY.user && lid.uid === DY.user.uid; var init = lid.naam.slice(0, 2).toUpperCase();
      return '<div class="dy-lb2-rij' + (isJij ? ' jij' : '') + '" data-uid="' + lid.uid + '" data-naam="' + DY.escapeHtml(lid.naam) + '">' +
        '<div class="dy-lb2-rang">' + (function(){
        var k = rang<=4?'#8B7355':rang<=5?'#7A8B8B':rang<=6?'#9E8A6B':'rgba(30,26,15,0.30)';
        return '<svg viewBox="0 0 20 24" width="20" height="24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="10" cy="15" r="7" fill="'+k+'" opacity="0.15"/><circle cx="10" cy="15" r="7" stroke="'+k+'" stroke-width="1.4"/><line x1="7.5" y1="8.5" x2="6" y2="1" stroke="'+k+'" stroke-width="1.4" stroke-linecap="round"/><line x1="12.5" y1="8.5" x2="14" y2="1" stroke="'+k+'" stroke-width="1.4" stroke-linecap="round"/><line x1="6" y1="1" x2="14" y2="1" stroke="'+k+'" stroke-width="1.4" stroke-linecap="round"/><text x="10" y="19" text-anchor="middle" font-family="DM Sans,sans-serif" font-size="6.5" font-weight="700" fill="'+k+'">'+rang+'</text></svg>';
      })() + '</div>' +
        '<div class="dy-lb2-avatar">' + (lid.avatar ? '<img src="' + lid.avatar + '" loading="lazy" decoding="async">' : init) + '</div>' +
        '<div class="dy-lb2-info"><strong>' + DY.escapeHtml(lid.naam) + (isJij ? ' <span class="dy-lb2-jij">jij</span>' : '') + '</strong><span>' + lid.niveau + '</span></div>' +
        '<span class="dy-lb2-pts">' + (lid.dsp_seizoen || 0).toLocaleString('nl-NL') + ' <span class="dy-dsp-label">DSP</span></span>' +
      '</div>';
    }).join('');

    lijst.innerHTML =
      '<div class="dy-lb2-periode">' + periodeLbl + '</div>' +
      '<div class="dy-lb2-podium">' + podiumHTML + '</div>' +
      '<div class="dy-lb2-rest">' + restHTML + '</div>' +
      '<p class="dy-lb2-disclaimer">Rangschikking op seizoenspunten · ' + periodeLbl + '</p>';

    lijst.querySelectorAll('[data-uid]').forEach(function(el) {
      el.style.cursor = 'pointer';
      el.addEventListener('click', function() { if (this.dataset.uid) DY.openGebruiker(this.dataset.uid, this.dataset.naam); });
    });
  } catch(e) {
    const lijst = document.getElementById('dy-leaderboard-lijst');
    if (lijst) lijst.innerHTML = '<div class="dy-pg-leeg"><p>Leaderboard kon niet worden geladen.</p></div>';
  }
};

DY.terug = function() {
  // Cleanup actieve Firestore listeners voor we navigeren
  if (DY._berichtListener) {
    try { DY._berichtListener(); } catch(e) {}
    DY._berichtListener = null;
  }
  // Veilige back navigatie - nooit leeg scherm
  try {
    if (!DY._history) DY._history = [];
    var vorige = DY._history[DY._history.length - 1]; // peek zonder pop
    var ongeldig = !vorige
      || vorige === DY.pagina
      || vorige === 'login'
      || vorige === 'register';

    if (!ongeldig) {
      DY._history.pop();
      // Gebruik navigeer voor correcte history + updateNav
      if (vorige !== 'feed') { try { DY.stopInfiniteScroll(); } catch(e) {} }
      try { DY.navigeer(vorige); return; } catch(e) { }
    }

    // Fallback: bepaal veilige landing op auth status
    var landing = DY.user ? 'feed' : 'home';

    // Probeer navigeer eerst - reset DY.pagina om dedup guard te omzeilen
    try {
      DY.pagina = null; // reset zodat guard niet blokkeert
      DY.navigeer(landing); return;
    } catch(e) { }

    // Laatste redmiddel: toonPagina direct
    try {
      DY.pagina = landing;
      DY.toonPagina(landing);
      if (DY.updateNav) DY.updateNav();
    } catch(e) {
      // Absolute fallback: herlaad naar root
      window.location.replace('/');
    }
  } catch(err) {
    window.location.replace('/');
  }
};


// ── Browser back/forward → nooit witte pagina ─────────────────
(function() {
  // URL-pad → interne pagina-ID mapping (spiegelt _redirects)
  var _SEO_PAD_MAP = {
    'feed':              'feed',
    'looks':             'lookbook',
    'reviews':           'reviews',
    'winkel':            'winkel',
    'challenges':        'challenges',
    'post-van-de-week':  'ovdw',
    'outfit-vergelijker':'kleuren_ai',
    'voorwaarden':       'voorwaarden',
    'privacy':           'privacy',
    'community-regels':  'community_regels',
    'beta':              'beta_pagina'
  };
  // Interne pagina-ID → URL-pad mapping
  var _SEO_URL_MAP = {
    'feed':             '/feed',
    'lookbook':         '/looks',
    'reviews':          '/reviews',
    'winkel':           '/winkel',
    'challenges':       '/challenges',
    'ovdw':             '/post-van-de-week',
    'kleuren_ai':       '/outfit-vergelijker',
    'voorwaarden':      '/voorwaarden',
    'privacy':          '/privacy',
    'community_regels': '/community-regels',
    'beta_pagina':      '/beta'
  };

  // Pagina's waarvoor we GEEN URL-pad zetten (blijven op /)
  var _NO_URL_PAGINAS = {
    'login':1,'register':1,'profiel':1,'profiel_bewerken':1,'body_profile':1,
    'berichten':1,'bericht_detail':1,'meldingen':1,'dsp':1,'configurator':1,
    'privacy_center':1,'account_verwijder':1,'onboarding':1,'deel':1,'nieuw':1,
    'story_poster':1,'vrienden':1,'vind_mensen':1,'gebruiker':1,'detail':1,
    'lookbook_nieuw':1,'lookbook_detail':1,'bestellingen':1,'leaderboard':1,
    'paskamer':1,'admin':1,'ovdw':0 // ovdw heeft wel URL
  };

  // Zet initiële history state met correcte URL
  // Root-URL (/) → home (met hero), niet feed. Legacy: /feed, /looks etc. blijven werken.
  try {
    var _initPad = window.location.pathname.replace(/^\//, '').replace(/\/$/, '');
    var _initPagina = _SEO_PAD_MAP[_initPad.split('/')[0]] || 'home';
    var _initUrl = _SEO_URL_MAP[_initPagina] || '/';
    if (!window.history.state || !window.history.state._dy) {
      window.history.replaceState({ _dy: true, pagina: _initPagina }, '', _initUrl);
    }
  } catch(e) {}

  window.addEventListener('popstate', function(e) {
    DY._popstateActive = true;
    var veiligePagina = (e.state && e.state.pagina) || (DY && DY.pagina) || 'home';
    var veiligUrl = _SEO_URL_MAP[veiligePagina] || '/';
    try { window.history.replaceState({ _dy: true, pagina: veiligePagina }, '', veiligUrl); } catch(ex) {}
    try {
      if (DY && DY.terug) DY.terug();
      else if (DY && DY.navigeer) DY.navigeer(DY && DY.user ? 'feed' : 'home');
    } finally {
      DY._popstateActive = false;
    }
  });

  // Elke navigatie: update browser URL + meta-tags
  var _origNavigeer = DY.navigeer;
  DY.navigeer = function(pagina) {
    if (!DY._popstateActive) {
      var useReplace = (pagina === 'login' || pagina === 'register');
      // Bepaal doel-URL: auth/persoonlijke pagina's blijven op /
      var doelUrl = (!_NO_URL_PAGINAS[pagina] || _NO_URL_PAGINAS[pagina] === 0)
        ? (_SEO_URL_MAP[pagina] || '/')
        : '/';
      try {
        if (useReplace) {
          window.history.replaceState({ _dy: true, pagina: pagina }, '', doelUrl);
        } else {
          window.history.pushState({ _dy: true, pagina: pagina }, '', doelUrl);
        }
      } catch(ex) {}
    }
    // Update meta-tags voor indexeerbare pagina's
    try {
      if (typeof DY._updateSEOMeta === 'function') DY._updateSEOMeta(pagina);
    } catch(ex) {}
    return _origNavigeer.apply(this, arguments);
  };
})();

// ── Sub-pagina navigatiebalk ─────────────────────────────────────
// Voegt automatisch terug+home toe op detailpagina's
DY._subNavTabs = ['feed','vrienden','kleuren_ai','winkel','reviews','profiel','home','login','register','deel','challenges','leaderboard','dsp','meldingen'];

DY.toonSubNav = function() {
  // Subnav verwijderd - alle pagina's hebben eigen navigatie in hun header
  var bestaand = document.getElementById('dy-subnav');
  if (bestaand) bestaand.remove();
};


DY.toggleLeaderboardOptin = async function(btn) {
  try {
  if (!DY.user) return;
  const huidig = (DY.profile && DY.profile.leaderboard_opt_in) || false;
  await DY.db.collection('users').doc(DY.user.uid).update({ leaderboard_opt_in: !huidig });
  DY.profile.leaderboard_opt_in = !huidig;
  btn.textContent = !huidig ? 'Uitschrijven' : 'Meedoen';
  DY.toast(!huidig ? 'Je staat nu op het leaderboard!' : 'Je bent van het leaderboard verwijderd.');
  } catch(e) {
    DY.toast && DY.toast('Er ging iets mis. Probeer het opnieuw.');
  }
}

