// ── PREMIUM REVIEW MODULE ──────────────────────────────────────────────────
DY.REVIEW_BADGES = {
  tallApproved:     { label: 'Tall Approved',          icon: '✓', kleur: '#1a6b3a' },
  plusApproved:     { label: 'Plus Size Approved',      icon: '✓', kleur: '#1a6b3a' },
  perfectSleeve:    { label: 'Perfect mouwlengte',      icon: '✓', kleur: '#1a6b3a' },
  perfectLeg:       { label: 'Perfect broeklengte',     icon: '✓', kleur: '#1a6b3a' },
  widethighFit:     { label: 'Ruim bij bovenbenen',     icon: '✓', kleur: '#1a6b3a' },
  shoulderFit:      { label: 'Schouders perfect',       icon: '✓', kleur: '#1a6b3a' },
  longTorsoFit:     { label: 'Lang bovenlichaam OK',    icon: '✓', kleur: '#1a6b3a' },
  trueToSize:       { label: 'Valt op maat',            icon: '=', kleur: '#c67d06' },
  runsBig:          { label: 'Valt groot',              icon: '↑', kleur: '#8b5e00' },
  runsSmall:        { label: 'Valt klein',              icon: '↓', kleur: '#8b5e00' },
};

DY.LICHAAMSTYPEN = [
  'XL', '2XL', '3XL', '4XL', '5XL', 'Breed bovenlichaam', 'Brede schouders',
  'Buikje', 'Grote bovenbenen', 'Lang bovenlichaam', 'Lange benen',
  'Peer-vormig', 'Rechthoekig'
];

DY.PASVORM_PROBLEMEN = [
  'Mouwen vaak te kort', 'Broeken te strak bij bovenbenen',
  'Shirts te kort', 'Schouders te smal', 'Te strak bij buik',
  'Kraag te groot', 'Taille te wijde bij grote maat',
  'Kruis te kort', 'Rug te kort', 'Mouwopening te nauw'
];

DY.PASVORM_ONDERDELEN = [
  { id: 'mouwlengte',   label: 'Mouwlengte' },
  { id: 'broeklengte',  label: 'Broeklengte' },
  { id: 'buikruimte',   label: 'Ruimte buik' },
  { id: 'beenruimte',   label: 'Ruimte benen' },
  { id: 'schouders',    label: 'Schouders' },
  { id: 'torsomaat',    label: 'Torsolengte' },
];

DY.berekenBadges = function(r) {
  var badges = [];
  if (!r) return badges;
  // Lengte badges
  if (r.lengte >= 185 && r.pasvorm === 'goed') badges.push('tallApproved');
  if (r.mouwlengte === 'perfect') badges.push('perfectSleeve');
  if (r.broeklengte === 'perfect') badges.push('perfectLeg');
  if (r.beenruimte === 'ruim' || r.beenruimte === 'perfect') badges.push('widethighFit');
  if (r.schouders === 'perfect') badges.push('shoulderFit');
  if (r.torsomaat === 'perfect') badges.push('longTorsoFit');
  if (r.pasvorm === 'goed') badges.push('trueToSize');
  else if (r.pasvorm === 'groot') badges.push('runsBig');
  else if (r.pasvorm === 'klein') badges.push('runsSmall');
  return badges;
};

DY.badgesHTML = function(badges) {
  if (!badges || !badges.length) return '';
  return '<div class="dy-rv-badges">' +
    badges.slice(0,4).map(function(b) {
      var bd = DY.REVIEW_BADGES[b];
      if (!bd) return '';
      return '<span class="dy-rv-badge" style="background:' + bd.kleur + '20;color:' + bd.kleur + ';border:1px solid ' + bd.kleur + '40">' +
        bd.icon + ' ' + bd.label +
      '</span>';
    }).join('') +
  '</div>';
};

// ── OVERZICHT PAGINA ────────────────────────────────────────────────────────


// ══════════════════════════════════════════════════════════════════
// REVIEW POPUP - volledige review tekst in bottom sheet
// ══════════════════════════════════════════════════════════════════
DY.toonReviewPopup = function(reviewId) {
  var bestaand = document.getElementById('dy-rv-popup');
  if (bestaand) bestaand.parentNode.removeChild(bestaand);

  var r = (DY._alleReviews || []).find(function(rv) {
    return (rv.id || rv._docId) === reviewId;
  });
  if (!r) return;

  var naam = r.authorName || 'Anoniem';
  var initialen = naam.slice(0, 2).toUpperCase();
  var datum = r.createdAt ? new Date(r.createdAt).toLocaleDateString('nl-NL', { day: 'numeric', month: 'long', year: 'numeric' }) : '';
  var sterHTML = [1,2,3,4,5].map(function(s) {
    return '<span style="color:' + (s <= (r.ster||0) ? 'var(--clay)' : 'rgba(253,248,240,0.18)') + ';font-size:16px">&#9733;</span>';
  }).join('');

  var matenPills = [
    r.lengte ? r.lengte + 'cm' : '',
    r.gewicht ? r.gewicht + 'kg' : '',
    r.maat || ''
  ].filter(Boolean).map(function(m) {
    return '<span style="display:inline-block;font-size:10px;font-weight:700;color:var(--clay);background:rgba(198,125,6,0.10);border:1px solid rgba(198,125,6,0.25);padding:3px 8px;border-radius:20px">' + m + '</span>';
  }).join('');

  var badges = DY.berekenBadges ? DY.berekenBadges(r) : [];
  var badgesHTML = badges.length ? DY.badgesHTML(badges) : '';

  var onderdelen = (DY.PASVORM_ONDERDELEN || []).filter(function(o) { return r[o.id]; });
  var onderdelenHTML = onderdelen.length
    ? '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:10px">' +
      onderdelen.map(function(o) {
        var val = r[o.id];
        var kleuren = { perfect:'#1a6b3a', ruim:'#1a6b3a', kort:'var(--clay)', lang:'var(--clay)', nauw:'var(--clay)' };
        var labels  = { perfect:'\u2713', ruim:'\u2191', kort:'\u2193', lang:'\u2191', nauw:'\u2193', normaal:'=' };
        var kleur = kleuren[val] || 'rgba(253,248,240,0.45)';
        return '<span style="font-size:10px;color:' + kleur + ';background:' + kleur + '15;border:1px solid ' + kleur + '35;padding:3px 8px;border-radius:4px">' + (labels[val] || '') + ' ' + o.label + '</span>';
      }).join('') + '</div>'
    : '';

  var communityHTML = '';
  if (r.twijfel || r.aanraden !== undefined) {
    communityHTML = '<div style="margin-top:14px;padding:10px 12px;background:rgba(198,125,6,0.05);border-radius:var(--r-md);border-left:3px solid var(--clay)">';
    if (r.twijfel) communityHTML += '<p style="font-size:12px;color:rgba(253,248,240,0.70);margin:0 0 4px;font-style:italic">\u201e' + DY.escapeHtml(r.twijfel) + '\u201d</p>';
    if (r.twijfelOpgelost !== undefined) communityHTML += '<p style="font-size:11px;color:' + (r.twijfelOpgelost ? '#1a6b3a' : 'var(--clay)') + ';margin:0">' + (r.twijfelOpgelost ? '\u2713 Twijfel opgelost' : '\u2717 Niet opgelost') + '</p>';
    if (r.aanraden !== undefined) communityHTML += '<p style="font-size:11px;color:' + (r.aanraden ? '#1a6b3a' : 'var(--clay)') + ';margin:4px 0 0">' + (r.aanraden ? '\u2713 Zou het aanraden' : '\u2717 Zou het niet aanraden') + '</p>';
    communityHTML += '</div>';
  }

  var extraBadges = [r.stretch, r.stofgevoel, r.gebruik].filter(Boolean);
  var extraHTML = extraBadges.length
    ? '<div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:10px">' +
      extraBadges.map(function(b) {
        return '<span style="font-size:10px;background:rgba(198,125,6,0.08);color:rgba(253,248,240,0.70);border:1px solid rgba(198,125,6,0.20);padding:3px 8px;border-radius:20px">' + DY.escapeHtml(b) + '</span>';
      }).join('') + '</div>'
    : '';

  // Foto HTML - onclick via dataset om quote-escaping te vermijden
  var fotoHTML = '';
  if (r.foto) {
    fotoHTML = '<div style="margin-bottom:14px;border-radius:var(--r-md);overflow:hidden">' +
      '<img loading="lazy" decoding="async" src="' + r.foto + '" alt="Review foto" class="dy-rv-popup-foto" data-foto="' + r.foto + '">' +
      '</div>';
  }

  var popup = document.createElement('div');
  popup.id = 'dy-rv-popup';
  popup.className = 'dy-rv-popup-backdrop';
  popup.setAttribute('role', 'dialog');
  popup.setAttribute('aria-modal', 'true');
  popup.setAttribute('aria-label', 'Review lezen');

  popup.innerHTML =
    '<div class="dy-rv-popup-sheet" id="dy-rv-popup-sheet">' +
      '<div class="dy-rv-popup-drag"></div>' +
      '<button class="dy-rv-popup-sluit" id="dy-rv-popup-sluit-btn" aria-label="Sluiten">' +
        '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
      '</button>' +
      '<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">' +
        '<div style="width:40px;height:40px;border-radius:50%;background:var(--clay);display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:13px;flex-shrink:0">' + DY.escapeHtml(initialen) + '</div>' +
        '<div style="flex:1;min-width:0">' +
          '<div style="font-weight:700;font-size:13px;color:rgba(253,248,240,0.95)">' + DY.escapeHtml(naam) + '</div>' +
          '<div style="display:flex;align-items:center;gap:6px;margin-top:2px">' +
            sterHTML +
            (datum ? '<span style="font-size:10px;color:rgba(253,248,240,0.45)">' + datum + '</span>' : '') +
          '</div>' +
        '</div>' +
        (matenPills ? '<div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end">' + matenPills + '</div>' : '') +
      '</div>' +
      fotoHTML +
      (badgesHTML ? '<div style="margin-bottom:12px">' + badgesHTML + '</div>' : '') +
      (r.tekst ? '<p style="font-size:14px;line-height:1.72;color:rgba(253,248,240,0.82);margin:0">' + DY.escapeHtml(r.tekst) + '</p>' : '') +
      onderdelenHTML +
      communityHTML +
      extraHTML +
    (r.userId && (!DY.user || r.userId !== DY.user.uid)
      ? '<div style="padding:12px 20px 0;border-top:1px solid rgba(198,125,6,0.12);margin-top:16px">' +
          '<button class="dy-rv-footer-report dy-meld-trigger" data-id="' + (r.id || r._docId || '') + '" data-naam="' + DY.escapeHtml(naam) + '" data-foto="' + (r.foto || '') + '" data-uid="' + (r.userId || '') + '" onclick="DY._toonMeldModalFromEl(this)" aria-label="Rapporteren">' +
            '<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg> Rapporteren' +
          '</button>' +
        '</div>' : '') +
    '</div>';

  document.body.appendChild(popup);
  document.body.style.overflowY = 'hidden';

  // Sluit knop
  document.getElementById('dy-rv-popup-sluit-btn').addEventListener('click', DY.sluitReviewPopup);

  // Avatar klik in review popup - event delegatie
  popup.addEventListener('click', function(e) {
    var avatarEl = e.target.closest('.dy-rv-avatar[data-uid]');
    if (avatarEl && avatarEl.dataset.uid) {
      DY.sluitReviewPopup();
      DY.openGebruiker(avatarEl.dataset.uid, avatarEl.dataset.naam || '');
    }
  });

  // Foto lightbox via dataset
  var fotoEl = popup.querySelector('.dy-rv-popup-foto');
  if (fotoEl) {
    fotoEl.addEventListener('click', function() {
      DY.openLightbox(this.dataset.foto, false);
    });
  }

  // Keyboard + backdrop
  DY._rvPopupKeyHandler = function(e) { if (e.key === 'Escape') DY.sluitReviewPopup(); };
  document.addEventListener('keydown', DY._rvPopupKeyHandler);
  popup.addEventListener('click', function(e) { if (e.target === popup) DY.sluitReviewPopup(); });

  // Animatie
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { popup.classList.add('dy-rv-popup-in'); });
  });
};

DY.sluitReviewPopup = function() {
  var popup = document.getElementById('dy-rv-popup');
  if (!popup) return;
  if (DY._rvPopupKeyHandler) {
    document.removeEventListener('keydown', DY._rvPopupKeyHandler);
    DY._rvPopupKeyHandler = null;
  }
  popup.classList.remove('dy-rv-popup-in');
  popup.classList.add('dy-rv-popup-out');
  document.body.style.overflowY = '';
  setTimeout(function() { if (popup.parentNode) popup.parentNode.removeChild(popup); }, 280);
};

DY.renderReviewsOverzicht = async function() {
  var main = document.getElementById('dy-main');
  if (main) main.style.background = '#0a0806';
  var mijLen = (DY.profile && DY.profile.lengte) ? parseInt(DY.profile.lengte) : null;
  var mijGew = (DY.profile && DY.profile.gewicht) ? parseInt(DY.profile.gewicht) : null;

  main.innerHTML =
    '<div class="dy-vr-header">' +
      '<div class="dy-vr-header-inner">' +
        '<div>' +
          '<div class="dy-feed-merk-label">Paskamerpraat</div>' +
          '<h1 class="dy-vr-titel">DoubleYou Tailored for Tall &amp; Plus Size: <em>Webshop Reviews</em></h1>' +
        '</div>' +
        '<button class="dy-pg-actie-btn" id="dy-rev-nieuw-btn">\u2605 Plaatsen</button>' +
      '</div>' +
    '</div>' +
    '<div class="dy-rv-filters-balk" id="dy-rv-filters">' +
      '<button class="dy-rv-filter active" id="dy-rv-alle" onclick="DY.rvFilter(\'alle\', this)">Alle</button>' +
      (mijLen ? '<button class="dy-rv-filter" id="dy-rv-vergelijk" onclick="DY.rvFilter(\'vergelijk\', this)">\u2248 ' + mijLen + 'cm</button>' : '') +
      '<button class="dy-rv-filter" id="dy-rv-foto" onclick="DY.rvFilter(\'foto\', this)">Met foto</button>' +
      '<button class="dy-rv-filter" id="dy-rv-top" onclick="DY.rvFilter(\'top\', this)">\u2605 Top</button>' +
    '</div>' +
    '<div id="dy-reviews-samenvatting" style="padding:10px 14px 0"></div>' +
    '<div id="dy-reviews-lijst" class="dy-verhalen-grid">' +
      '<div class="dy-pg-skel-wrap dy-pg-skel-grid" style="grid-column:1/-1">' +
        '<div class="dy-pg-skel-kaart"></div><div class="dy-pg-skel-kaart"></div>' +
        '<div class="dy-pg-skel-kaart"></div><div class="dy-pg-skel-kaart"></div>' +
      '</div>' +
    '</div>';

  var nieuwBtn = document.getElementById('dy-rev-nieuw-btn');
  if (nieuwBtn) nieuwBtn.onclick = function() { DY.navigeer('reviews_nieuw'); };

  DY._alleReviews = [];
  DY._mijLengte = mijLen;
  DY._mijGewicht = mijGew;

  try {
    var snap = await DY.db.collection('reviews').orderBy('ts', 'desc').limit(100).get();
    // v60.1.268: STRIKTE isolatie. "Eerlijke Reviews" pagina toont ALLEEN
    // tall/plus-size pasvorm-reviews van de DoubleYou webshop-items. Merk-
    // reviews (reviewType='brand' of brandId aanwezig) worden expliciet
    // uitgesloten zodat ze alleen in het merkenportaal opduiken.
    var _filteredDocs = (snap.docs || []).filter(function (d) {
      try {
        var data = d.data() || {};
        if (data.reviewType === 'brand') return false;
        if (data.brandId) return false;
        return data.reviewType === 'tall_fit' || !data.reviewType;
      } catch (_) { return true; }
    });
    snap = { empty: _filteredDocs.length === 0, docs: _filteredDocs, size: _filteredDocs.length };
    var lijst = document.getElementById('dy-reviews-lijst');
    if (!lijst) return;
    if (snap.empty) {
      lijst.innerHTML =
        '<div style="grid-column:1/-1" class="dy-pg-leeg">' +
          '<div class="dy-pg-leeg-icon">&#9733;</div>' +
          '<h3 class="dy-pg-leeg-titel">Nog geen reviews</h3>' +
          '<p class="dy-pg-leeg-sub">Wees de eerste die een eerlijke review plaatst.</p>' +
          '<button class="dy-pg-actie-btn" id="dy-rv-eerste">Review plaatsen</button>' +
        '</div>';
      var eb = document.getElementById('dy-rv-eerste');
      if (eb) eb.onclick = function() { DY.navigeer('reviews_nieuw'); };
      return;
    }
    DY._alleReviews = snap.docs.map(function(d) { return Object.assign({ id: d.id }, d.data()); });
    if (DY.verrijkMetMaten) DY._alleReviews = await DY.verrijkMetMaten(DY._alleReviews, 'userId');
    DY.rvToonSamenvatting(DY._alleReviews);
    DY.rvToonLijst(DY._alleReviews);
  } catch(e) {
    var el = document.getElementById('dy-reviews-lijst');
    if (el) el.innerHTML = '<p style="grid-column:1/-1;padding:20px;color:var(--ink-muted)">Reviews konden niet worden geladen.</p>';
  }
};

DY.rvFilter = function(type, btn) {
  document.querySelectorAll('.dy-filter').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
  var docs = DY._alleReviews || [];
  if (type === 'vergelijk') {
    // Maat Matcher: sorteer op relevantie i.p.v. filteren
    if (DY.sorteerOpMatch && DY.profile) {
      docs = DY.sorteerOpMatch(docs, function(r) { return r; });
      // Toon ook reviews zonder maatdata maar sorteer ze achteraan
    } else if (DY._mijLengte) {
      var ml = DY._mijLengte;
      docs = docs.slice().sort(function(a, b) {
        var dA = a.lengte ? Math.abs(a.lengte - ml) : 999;
        var dB = b.lengte ? Math.abs(b.lengte - ml) : 999;
        return dA - dB;
      });
    }
  } else if (type === 'foto') {
    docs = docs.filter(function(r) { return r.foto; });
  } else if (type === 'top') {
    docs = docs.slice().sort(function(a,b) { return (b.ster||0) - (a.ster||0); });
  }
  DY.rvToonLijst(docs);
};

DY.rvToonSamenvatting = function(docs) {
  var el = document.getElementById('dy-reviews-samenvatting');
  if (!el || !docs.length) return;

  var totaal = docs.reduce(function(a,r) { return a + (r.ster||0); }, 0);
  var gem = Math.round((totaal / docs.length) * 10) / 10;

  var verdelingHTML = [5,4,3,2,1].map(function(s) {
    var n = docs.filter(function(r) { return r.ster === s; }).length;
    var pct = Math.round(n / docs.length * 100);
    return '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">' +
      '<span style="font-size:10px;color:rgba(253,248,240,0.45);width:10px">' + s + '</span>' +
      '<span style="font-size:10px;color:var(--clay)">\u2605</span>' +
      '<div style="flex:1;height:5px;background:rgba(198,125,6,0.12);border-radius:3px;overflow:hidden">' +
      '<div style="height:100%;width:' + pct + '%;background:var(--clay)"></div></div>' +
      '<span style="font-size:10px;color:rgba(253,248,240,0.45);width:16px;text-align:right">' + n + '</span>' +
    '</div>';
  }).join('');

  var sterHoofd = [1,2,3,4,5].map(function(s) {
    return '<span style="color:' + (s <= Math.round(gem) ? '#c67d06' : 'rgba(253,248,240,0.15)') + ';font-size:16px">\u2605</span>';
  }).join('');

  // Top badges tellen
  var badgeTelling = {};
  docs.forEach(function(r) {
    DY.berekenBadges(r).forEach(function(b) {
      badgeTelling[b] = (badgeTelling[b] || 0) + 1;
    });
  });
  var topBadges = Object.keys(badgeTelling)
    .sort(function(a,b) { return badgeTelling[b] - badgeTelling[a]; })
    .slice(0,3);

  var badgeBar = topBadges.length ? '<div style="margin-top:12px;display:flex;flex-wrap:wrap;gap:6px">' +
    topBadges.map(function(b) {
      var bd = DY.REVIEW_BADGES[b];
      if (!bd) return '';
      return '<span style="font-size:10px;background:' + bd.kleur + '15;color:' + bd.kleur + ';border:1px solid ' + bd.kleur + '30;padding:3px 8px;border-radius:20px">' +
        bd.icon + ' ' + bd.label + ' (' + badgeTelling[b] + 'x)</span>';
    }).join('') + '</div>' : '';

  el.innerHTML =
    '<div style="background:rgba(20,16,6,0.97);border:1px solid rgba(198,125,6,0.14);border-radius:var(--radius);padding:14px;margin-bottom:4px">' +
    '<div style="display:flex;gap:16px;align-items:center">' +
    '<div style="text-align:center;flex-shrink:0">' +
    '<div style="font-family:Cormorant Garamond,serif;font-size:44px;color:var(--clay);line-height:1">' + gem + '</div>' +
    '<div>' + sterHoofd + '</div>' +
    '<div style="font-size:10px;color:rgba(253,248,240,0.40);margin-top:2px">' + docs.length + ' reviews</div>' +
    '</div>' +
    '<div style="flex:1">' + verdelingHTML + '</div>' +
    '</div>' + badgeBar + '</div>';
};

DY.rvToonLijst = function(docs) {
  var lijst = document.getElementById('dy-reviews-lijst');
  if (!lijst) return;

  if (!docs.length) {
    lijst.innerHTML = '<p style="grid-column:1/-1;padding:20px;text-align:center;color:var(--ink-muted)">Geen reviews gevonden voor dit filter.</p>';
    return;
  }

  lijst.innerHTML = docs.map(function(r) {
    var naam = r.authorName || 'Anoniem';
    var initialen = naam.slice(0,2).toUpperCase();
    var datum = r.createdAt ? new Date(r.createdAt).toLocaleDateString('nl-NL', {day:'numeric',month:'short'}) : '';
    var sterHTML = [1,2,3,4,5].map(function(s) {
      return '<span style="color:' + (s <= (r.ster||0) ? '#c67d06' : 'rgba(30,26,15,0.15)') + ';font-size:11px">\u2605</span>';
    }).join('');

    var matenStr = [
      r.lengte ? r.lengte + 'cm' : '',
      r.gewicht ? r.gewicht + 'kg' : '',
      r.maat || ''
    ].filter(Boolean).join(' \u00b7 ');

    var badges = DY.berekenBadges(r);

    // Vergelijkbaar badge
    var vergelijkbaar = DY._mijLengte && r.lengte && Math.abs(r.lengte - DY._mijLengte) <= 8;
    var vergelijkHTML = vergelijkbaar ?
      '<div style="font-size:9px;background:#1a6b3a15;color:#1a6b3a;border:1px solid #1a6b3a30;padding:2px 6px;border-radius:10px;display:inline-block;margin-bottom:4px">\u2248 Vergelijkbare bouw als jij</div>' : '';

    // Pasvorm per onderdeel
    var onderdelen = DY.PASVORM_ONDERDELEN.filter(function(o) { return r[o.id]; });
    var onderdelenHTML = onderdelen.length ?
      '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">' +
      onderdelen.map(function(o) {
        var val = r[o.id];
        var kleuren = {perfect:'#1a6b3a', ruim:'#1a6b3a', kort:'#c67d06', lang:'#c67d06', nauw:'#c67d06'};
        var kleur = kleuren[val] || 'var(--ink-muted)';
        var labels = {perfect:'v', ruim:'\u2191', kort:'\u2193', lang:'\u2191', nauw:'\u2193', normaal:'='};
        return '<span style="font-size:9px;color:' + kleur + ';background:' + kleur + '12;border:1px solid ' + kleur + '30;padding:1px 5px;border-radius:3px">' +
          (labels[val] || '') + ' ' + o.label + '</span>';
      }).join('') +
      '</div>' : '';

    // Community vragen
    var communityHTML = '';
    if (r.twijfel || r.aanraden !== undefined) {
      communityHTML = '<div style="margin-top:8px;padding:8px;background:var(--bg);border-radius:4px;border-left:2px solid var(--clay)">';
      if (r.twijfel) communityHTML += '<p style="font-size:11px;color:var(--ink-muted);margin-bottom:2px">\u201e' + r.twijfel + '\u201d</p>';
      if (r.twijfelOpgelost !== undefined) communityHTML += '<p style="font-size:10px;color:' + (r.twijfelOpgelost ? '#1a6b3a' : '#c67d06') + '">' + (r.twijfelOpgelost ? '\u2713 Twijfel opgelost' : '\u2717 Twijfel niet volledig opgelost') + '</p>';
      if (r.aanraden !== undefined) communityHTML += '<p style="font-size:10px;color:' + (r.aanraden ? '#1a6b3a' : '#c67d06') + ';margin-top:2px">' + (r.aanraden ? '\u2713 Zou het aanraden' : '\u2717 Zou het niet aanraden') + ' aan mensen met vergelijkbare bouw</p>';
      communityHTML += '</div>';
    }

    // Stof & gebruik badges
    var extraBadges = [];
    if (r.stretch) extraBadges.push({label: r.stretch, kleur:'#555'});
    if (r.stofgevoel) extraBadges.push({label: r.stofgevoel, kleur:'#555'});
    if (r.gebruik) extraBadges.push({label: r.gebruik, kleur:'#555'});
    var extraHTML = extraBadges.length ?
      '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">' +
      extraBadges.map(function(b) {
        return '<span style="font-size:9px;background:rgba(30,26,15,0.06);color:var(--ink-muted);border:1px solid var(--border);padding:2px 6px;border-radius:10px">' + b.label + '</span>';
      }).join('') + '</div>' : '';

    // Premium review header: avatar + naam/sterren/datum, maten als pill badges
    var matenPills = [
      r.lengte ? r.lengte + 'cm' : '',
      r.gewicht ? r.gewicht + 'kg' : '',
      r.maat || ''
    ].filter(Boolean).map(function(m) {
      return '<span class="dy-rv-maat-pill">' + m + '</span>';
    }).join('');

    // ── Primaire pasvorm badge (max 1 tonen in grid voor uniformiteit)
    var eersteBadge = badges && badges.length > 0 ? DY.badgesHTML([badges[0]]) : '';

    // ── Maat Matcher score voor deze review
    var _rvMatchScore = (DY.maatMatchScore && DY.profile && (DY.profile.lengte || DY.profile.maat))
      ? DY.maatMatchScore(DY.profile, r) : 0;
    var _rvMatchLabel = _rvMatchScore >= 35 ? DY.maatMatchLabel(_rvMatchScore) : null;
    var rvMatchRij = _rvMatchLabel
      ? '<div class="dy-rv-match-rij">' +
          '<div class="dy-rv-match-score" style="color:' + _rvMatchLabel.kleur + '">' +
            '<svg viewBox="0 0 12 12" width="10" height="10" fill="currentColor"><path d="M6 11s-5-3.2-5-6.7A3.8 3.8 0 0 1 6 .8 3.8 3.8 0 0 1 11 4.3C11 7.8 6 11 6 11z"/></svg>' +
            _rvMatchLabel.tekst +
          '</div>' +
          '<div class="dy-rv-match-bar-wrap">' +
            '<div class="dy-rv-match-bar-fill" style="width:' + _rvMatchLabel.pct + '%;background:' + _rvMatchLabel.kleur + '"></div>' +
          '</div>' +
        '</div>'
      : '';

    var _rvId = r.id || r._docId || '';
    return '<div class="dy-kaart dy-rv-kaart-grid" data-rv-id="' + _rvId + '" style="cursor:pointer" onclick="if(this.dataset.rvId)DY.toonReviewPopup(this.dataset.rvId)">' +
      // ── Foto bovenin met vaste aspect ratio ──
      '<div class="dy-rv-foto-zone">' +
        (r.foto
          ? '<div class="dy-img-wrap dy-rv-foto-wrap"><img class="dy-kaart-foto" src="' + r.foto + '" alt="Review foto" loading="lazy" decoding="async" onclick="event.stopPropagation();DY.openLightbox(\'' + r.foto + '\', false)" style="cursor:zoom-in"></div>'
          : '<div class="dy-rv-foto-placeholder"><span>' + (r.product || 'DoubleYou') + '</span></div>') +
        // Maatpills als overlay op de foto
        (matenPills ? '<div class="dy-rv-maten-overlay">' + matenPills + '</div>' : '') +
      '</div>' +
      rvMatchRij +
      // ── Header: vaste hoogte, altijd identiek ──
      '<div class="dy-rv-kaart-header">' +
        '<div class="dy-avatar dy-rv-avatar" style="cursor:' + (r.userId ? 'pointer' : 'default') + '" data-uid="' + (r.userId || '') + '" data-naam="' + naam + '">' + initialen + '</div>' +
        '<div class="dy-rv-header-midden">' +
          '<div class="dy-rv-naam-rij">' +
            '<span class="dy-rv-naam">' + naam + '</span>' +
            (r.geverifieerd ? '<span class="dy-rv-verified">\u2713</span>' : '') +
          '</div>' +
          '<div class="dy-rv-sterren">' + sterHTML + '</div>' +
          '<span class="dy-rv-datum">' + datum + '</span>' +
        '</div>' +
      '</div>' +
      // ── Body: strikt beperkt - max 2 regels tekst + 1 badge ──
      '<div class="dy-rv-kaart-body">' +
        eersteBadge +
        '<p class="dy-rv-kaart-tekst">' + (r.tekst || '') + '</p>' +
        (r.userId && (!DY.user || r.userId !== DY.user.uid)
          ? '<button class="dy-rv-report-btn dy-meld-trigger" data-id="' + (r.id || r._docId || '') + '" data-naam="' + naam + '" data-foto="' + (r.foto || '') + '" data-uid="' + (r.userId || '') + '" onclick="event.stopPropagation();DY._toonMeldModalFromEl(this)" aria-label="Rapporteren" title="Rapporteren">' +
            '<svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>' +
          '</button>' : '') +
      '</div>' +
    '</div>';
  }).join('');

  // Event delegatie: avatar klik → openGebruiker
  lijst.addEventListener('click', function(e) {
    var avatarEl = e.target.closest('.dy-rv-avatar[data-uid]');
    if (avatarEl && avatarEl.dataset.uid) {
      e.stopPropagation();
      DY.openGebruiker(avatarEl.dataset.uid, avatarEl.dataset.naam || '');
    }
  });
};

// ── NIEUW REVIEW FORMULIER ──────────────────────────────────────────────────

DY.renderReviews = function() {
  var main = document.getElementById('dy-main');
  var p = DY.profile || {};

  if (!DY.profile) {
    main.innerHTML =
      '<div style="padding:40px 20px;text-align:center">' +
      '<p style="margin-bottom:16px;color:var(--ink-muted)">Log in om een review te plaatsen.</p>' +
      '<button class="dy-btn dy-btn-primary" onclick="DY.navigeer(\'login\')">Inloggen</button>' +
      '</div>';
    return;
  }

  var avatarUrl = DY.profile && DY.profile.avatar;
  var naam = (DY.profile && DY.profile.displayName) || DY.user.displayName || 'Jij';
  var initialen = naam.slice(0,2).toUpperCase();

  main.innerHTML =
    '<div class="dy-composer-wrap dy-rv-composer-wrap">' +

    // ── Topbar ──
    '<div class="dy-composer-topbar">' +
    '<button class="dy-composer-annuleer" id="dy-rv-terug-btn">Annuleren</button>' +
    '<span class="dy-composer-titel">Review <em style="font-style:italic">plaatsen</em></span>' +
    '<button class="dy-btn dy-composer-plaatsen-top" id="rv-submit-btn">Plaatsen</button>' +
    '</div>' +

    // ── Auteur rij ──
    '<div class="dy-composer-auteur" style="border-bottom:1px solid var(--border)">' +
    '<div class="dy-composer-avatar">' +
    (avatarUrl ? '<img loading="lazy" decoding="async" src="' + avatarUrl + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%">' : initialen) +
    '</div>' +
    '<div class="dy-composer-auteur-info">' +
    '<span class="dy-composer-naam">' + naam + '</span>' +
    '<div class="dy-composer-zichtbaar">' +
    '<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>' +
    '<span>Zichtbaar voor iedereen</span>' +
    '</div></div>' +
    '<div style="margin-left:auto;text-align:right">' +
    '<span class="dy-composer-dsp-badge">✦ +20 DSP</span>' +
    '<span class="dy-composer-dsp-sub" style="display:block">+40 met foto</span>' +
    '</div></div>' +

    '<div class="dy-rv-composer-body">' +

    // ── STAP 1: Product + sterren ──
    '<div class="dy-rv-stap">' +
    '<div class="dy-rv-stap-header"><span class="dy-rv-stap-num">1</span><span class="dy-rv-stap-titel">Het product</span></div>' +
    '<div class="dy-rv-stap-body">' +
    '<div class="dy-fc-maat-item" style="margin-bottom:12px">' +
    '<label class="dy-fc-maat-label">Productnaam <span style="color:var(--clay)">*</span></label>' +
    '<input class="dy-fc-maat-input" style="padding:10px 12px;font-size:0.88rem;border-radius:var(--r-md)" id="rv-product" type="text" placeholder="bijv. DoubleYou Classic Hoodie Tall">' +
    '</div>' +
    '<label class="dy-fc-maat-label">Beoordeling <span style="color:var(--clay)">*</span></label>' +
    '<div class="dy-rv-sterren-groot" id="dy-sterren">' +
    [1,2,3,4,5].map(function(i) { return '<button class="dy-ster" data-ster="' + i + '" onclick="DY.setSter(' + i + ')">&#9733;</button>'; }).join('') +
    '</div><input type="hidden" id="rv-ster" value="0">' +
    '</div></div>' +

    // ── STAP 2: Jouw bouw ──
    '<div class="dy-rv-stap">' +
    '<div class="dy-rv-stap-header"><span class="dy-rv-stap-num">2</span><span class="dy-rv-stap-titel">Jouw bouw</span></div>' +
    '<div class="dy-rv-stap-body">' +
    '<div class="dy-fc-maten-grid" style="margin-bottom:12px">' +
    '<div class="dy-fc-maat-item"><label class="dy-fc-maat-label">Lengte</label><div class="dy-fc-maat-input-wrap"><input class="dy-fc-maat-input" id="rv-lengte" type="number" placeholder="185" value="' + (p.lengte || '') + '"><span class="dy-fc-maat-unit">cm</span></div></div>' +
    '<div class="dy-fc-maat-item"><label class="dy-fc-maat-label">Gewicht</label><div class="dy-fc-maat-input-wrap"><input class="dy-fc-maat-input" id="rv-gewicht" type="number" placeholder="90" value="' + (p.gewicht || '') + '"><span class="dy-fc-maat-unit">kg</span></div></div>' +
    '<div class="dy-fc-maat-item"><label class="dy-fc-maat-label">Maat gekocht</label><div class="dy-fc-maat-input-wrap"><input class="dy-fc-maat-input" id="rv-maat" type="text" placeholder="XL / 52" value="' + (p.maat || '') + '"></div></div>' +
    '</div>' +
    '<label class="dy-label" style="margin-top:12px">Lichaamstype</label>' +
    '<div class="dy-rv-chips" id="rv-lichaamstype-wrap">' +
    DY.LICHAAMSTYPEN.map(function(t) {
      return '<button class="dy-rv-chip" onclick="DY.rvChipToggle(this, \'rv-lichaamstype\')">' + t + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-lichaamstype" value="">' +
    '<label class="dy-label" style="margin-top:12px">Pasvormproblemen die je normaal ervaart</label>' +
    '<div class="dy-rv-chips" id="rv-problemen-wrap">' +
    DY.PASVORM_PROBLEMEN.map(function(p) {
      return '<button class="dy-rv-chip" onclick="DY.rvChipMulti(this, \'rv-problemen\')">' + p + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-problemen" value="">' +
    '</div></div>' +

    // ── STAP 3: Pasvorm details ──
    '<div class="dy-rv-stap">' +
    '<div class="dy-rv-stap-header"><span class="dy-rv-stap-num">3</span><span class="dy-rv-stap-titel">Pasvorm</span></div>' +
    '<div class="dy-rv-stap-body">' +
    '<label class="dy-fc-maat-label" style="display:block;margin-bottom:6px">Algeheel oordeel</label>' +
    '<div class="dy-pasvorm-knoppen">' +
    '<button class="dy-pasvorm-btn" onclick="DY.setPassvorm(\'klein\', this)">Valt klein</button>' +
    '<button class="dy-pasvorm-btn" onclick="DY.setPassvorm(\'goed\', this)">Past perfect</button>' +
    '<button class="dy-pasvorm-btn" onclick="DY.setPassvorm(\'groot\', this)">Valt groot</button>' +
    '</div><input type="hidden" id="rv-pasvorm" value="">' +

    '<label class="dy-fc-maat-label" style="display:block;margin:12px 0 6px">Pasvorm per onderdeel</label>' +
    '<div class="dy-rv-onderdelen">' +
    DY.PASVORM_ONDERDELEN.map(function(o) {
      return '<div class="dy-rv-onderdeel">' +
        '<div class="dy-rv-onderdeel-lbl">' + o.label + '</div>' +
        '<div class="dy-rv-onderdeel-knoppen">' +
        ['Te kort','Perfect','Te lang'].map(function(v) {
          var val = v === 'Perfect' ? 'perfect' : v === 'Te kort' ? 'kort' : 'lang';
          return '<button class="dy-rv-chip-sm" onclick="DY.rvOnderdeel(this, \'' + o.id + '\', \'' + val + '\')">' + v + '</button>';
        }).join('') +
        '</div><input type="hidden" id="rv-' + o.id + '" value="">' +
      '</div>';
    }).join('') +

    // Speciale velden voor borst/buik/benen
    '<div class="dy-rv-onderdeel">' +
    '<div class="dy-rv-onderdeel-lbl">Ruimte buik</div>' +
    '<div class="dy-rv-onderdeel-knoppen">' +
    ['Nauw','Normaal','Ruim'].map(function(v) {
      var val = v.toLowerCase();
      return '<button class="dy-rv-chip-sm" onclick="DY.rvOnderdeel(this, \'buikruimte\', \'' + val + '\')">' + v + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-buikruimte" value=""></div>' +

    '<div class="dy-rv-onderdeel">' +
    '<div class="dy-rv-onderdeel-lbl">Ruimte benen/dijen</div>' +
    '<div class="dy-rv-onderdeel-knoppen">' +
    ['Nauw','Normaal','Ruim'].map(function(v) {
      var val = v.toLowerCase();
      return '<button class="dy-rv-chip-sm" onclick="DY.rvOnderdeel(this, \'beenruimte\', \'' + val + '\')">' + v + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-beenruimte" value=""></div>' +
    '</div>' + // .dy-rv-onderdelen

    '<label class="dy-fc-maat-label" style="display:block;margin:12px 0 6px">Stretch</label>' +
    '<div class="dy-rv-chips">' +
    ['Geen stretch','Lichte stretch','Veel stretch'].map(function(s) {
      return '<button class="dy-rv-chip" onclick="DY.rvEenKeuze(this, \'rv-stretch\')">' + s + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-stretch" value="">' +

    '<label class="dy-fc-maat-label" style="display:block;margin:10px 0 6px">Stofgevoel</label>' +
    '<div class="dy-rv-chips">' +
    ['Zacht','Stevig','Dik','Lichtgewicht','Premium'].map(function(s) {
      return '<button class="dy-rv-chip" onclick="DY.rvEenKeuze(this, \'rv-stofgevoel\')">' + s + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-stofgevoel" value="">' +

    '<label class="dy-fc-maat-label" style="display:block;margin:10px 0 6px">Gebruiksmoment</label>' +
    '<div class="dy-rv-chips">' +
    ['Casual','Werk','Streetwear','Sportief','Uitgaan'].map(function(s) {
      return '<button class="dy-rv-chip" onclick="DY.rvEenKeuze(this, \'rv-gebruik\')">' + s + '</button>';
    }).join('') +
    '</div><input type="hidden" id="rv-gebruik" value="">' +
    '</div></div>' +

    // ── STAP 4: Jouw verhaal ──
    '<div class="dy-rv-stap">' +
    '<div class="dy-rv-stap-header"><span class="dy-rv-stap-num">4</span><span class="dy-rv-stap-titel">Jouw ervaring</span></div>' +
    '<div class="dy-rv-stap-body">' +
    '<label class="dy-fc-maat-label" style="display:block;margin-bottom:6px">Jouw review <span style="color:var(--clay)">*</span></label>' +
    '<textarea class="dy-composer-textarea" style="border:1px solid var(--border);border-radius:var(--r-md);padding:10px 12px;min-height:100px;background:var(--white)" id="rv-tekst" placeholder="Hoe zit het? Wat vind je van de kwaliteit en pasvorm? Wat wil je andere mensen met jouw bouw meegeven?" rows="4"></textarea>' +

    '<label class="dy-fc-maat-label" style="display:block;margin:12px 0 6px">Grootste twijfel voor aankoop?</label>' +
    '<input class="dy-fc-maat-input" style="width:100%;padding:10px 12px;font-size:0.85rem;border-radius:var(--r-md);box-sizing:border-box" id="rv-twijfel" type="text" placeholder="bijv. Of de mouwen lang genoeg zouden zijn...">' +

    '<label class="dy-fc-maat-label" style="display:block;margin:12px 0 6px">Is die twijfel opgelost?</label>' +
    '<div class="dy-pasvorm-knoppen">' +
    '<button class="dy-pasvorm-btn" id="rv-opgelost-ja" onclick="DY.rvJaNee(this, \'rv-twijfelOpgelost\', true)">\u2713 Ja, volledig</button>' +
    '<button class="dy-pasvorm-btn" id="rv-opgelost-nee" onclick="DY.rvJaNee(this, \'rv-twijfelOpgelost\', false)">\u2717 Niet volledig</button>' +
    '</div><input type="hidden" id="rv-twijfelOpgelost" value="">' +

    '<label class="dy-fc-maat-label" style="display:block;margin:12px 0 6px">Aanraden aan mensen met jouw bouw?</label>' +
    '<div class="dy-pasvorm-knoppen">' +
    '<button class="dy-pasvorm-btn" onclick="DY.rvJaNee(this, \'rv-aanraden\', true)">\u2713 Ja, zeker</button>' +
    '<button class="dy-pasvorm-btn" onclick="DY.rvJaNee(this, \'rv-aanraden\', false)">\u2717 Niet perse</button>' +
    '</div><input type="hidden" id="rv-aanraden" value="">' +
    '</div></div>' +

    // ── STAP 5: Foto ──
    '<div class="dy-rv-stap">' +
    '<div class="dy-rv-stap-header"><span class="dy-rv-stap-num">5</span><span class="dy-rv-stap-titel">Foto <span class="dy-rv-stap-optioneel">optioneel · +40 DSP</span></span></div>' +
    '<div class="dy-rv-stap-body">' +
    '<div class="dy-rv-foto-zone">' +
    '<input type="file" id="rv-foto-input" accept="image/*" style="display:none">' +
    '<div class="dy-rv-foto-leeg" id="dy-rv-foto-leeg" onclick="document.getElementById(\'rv-foto-input\').click()">' +
    '<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.4" style="color:rgba(198,125,6,0.5)"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>' +
    '<span>Tik om een foto toe te voegen</span>' +
    '</div>' +
    '<div class="dy-rv-foto-preview-wrap" id="dy-rv-foto-preview-wrap" style="display:none;position:relative">' +
    '<img loading="lazy" decoding="async" id="rv-foto-preview" style="width:100%;height:auto;max-height:55vh;object-fit:contain;display:block;background:#111">' +
    '<button class="dy-fc-wijzig-btn" style="position:absolute;bottom:8px;right:8px" onclick="document.getElementById(\'rv-foto-input\').click()">Wijzigen</button>' +
    '</div>' +
    '</div>' +
    '</div></div>' +
    '</div>' + // dy-rv-composer-body
    '</div>'; // dy-composer-wrap

  // Event listeners
  var terugBtn = document.getElementById('dy-rv-terug-btn');
  if (terugBtn) terugBtn.onclick = function() { DY.navigeer('reviews'); };

  var fotoInput = document.getElementById('rv-foto-input');
  if (fotoInput) fotoInput.onchange = function() { DY.rvFotoPreview(this); };

  var submitBtn = document.getElementById('rv-submit-btn');
  if (submitBtn) submitBtn.onclick = function() { DY.plaatsReview(); };
};

// ── FORM HELPERS ────────────────────────────────────────────────────────────

DY.rvChipToggle = function(btn, fieldId) {
  // Enkelvoudige keuze
  var wrap = btn.parentNode;
  wrap.querySelectorAll('.dy-rv-chip').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
  var el = document.getElementById(fieldId);
  if (el) el.value = btn.textContent;
};

DY.rvChipMulti = function(btn, fieldId) {
  // Meervoudige keuze
  btn.classList.toggle('actief');
  var el = document.getElementById(fieldId);
  if (!el) return;
  var wrap = btn.parentNode;
  var vals = [];
  wrap.querySelectorAll('.dy-rv-chip.actief').forEach(function(b) { vals.push(b.textContent); });
  el.value = vals.join(',');
};

DY.rvEenKeuze = function(btn, fieldId) {
  var wrap = btn.parentNode;
  wrap.querySelectorAll('.dy-rv-chip').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
  var el = document.getElementById(fieldId);
  if (el) el.value = btn.textContent;
};

DY.rvOnderdeel = function(btn, onderdeel, waarde) {
  var wrap = btn.parentNode;
  wrap.querySelectorAll('.dy-rv-chip-sm').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
  var el = document.getElementById('rv-' + onderdeel);
  if (el) el.value = waarde;
};

DY.rvJaNee = function(btn, fieldId, waarde) {
  var wrap = btn.parentNode;
  wrap.querySelectorAll('.dy-pasvorm-btn').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
  var el = document.getElementById(fieldId);
  if (el) el.value = String(waarde);
};

DY.setSter = function(waarde) {
  var el = document.getElementById('rv-ster');
  if (el) el.value = waarde;
  document.querySelectorAll('.dy-ster').forEach(function(btn, i) {
    btn.classList.toggle('actief', i < waarde);
  });
};

DY.setPassvorm = function(waarde, btn) {
  var el = document.getElementById('rv-pasvorm');
  if (el) el.value = waarde;
  document.querySelectorAll('.dy-pasvorm-btn').forEach(function(b) { b.classList.remove('actief'); });
  btn.classList.add('actief');
};

DY.rvFotoPreview = function(input) {
  var file = input.files[0];
  if (!file) return;
  var preview = document.getElementById('rv-foto-preview');
  var leeg = document.getElementById('dy-rv-foto-leeg');
  var previewWrap = document.getElementById('dy-rv-foto-preview-wrap');
  var reader = new FileReader();
  reader.onload = function(e) {
    if (preview) { preview.src = e.target.result; }
    if (leeg) leeg.style.display = 'none';
    if (previewWrap) previewWrap.style.display = 'block';
  };
  reader.readAsDataURL(file);
};

// ── OPSLAAN ─────────────────────────────────────────────────────────────────

DY.plaatsReview = async function() {
  if (!DY.user) { DY.navigeer('login'); return; }

  var product = (document.getElementById('rv-product') || {}).value;
  var ster = parseInt((document.getElementById('rv-ster') || {}).value || '0');
  var tekst = (document.getElementById('rv-tekst') || {}).value;

  if (!product || !product.trim()) { DY.toast('Vul een productnaam in.'); return; }
  if (!ster) { DY.toast('Geef eerst een sterrenrating.'); return; }
  if (!tekst || !tekst.trim()) { DY.toast('Schrijf eerst een review.'); return; }

  var btn = document.getElementById('rv-submit-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Plaatsen...'; }

  try {
    // Foto upload
    var fotoInput = document.getElementById('rv-foto-input');
    var file = fotoInput && fotoInput.files[0];
    var fotoURL = null;
    if (file) {
      var ext = file.name.split('.').pop();
      var pad = 'reviews/' + DY.user.uid + '/' + Date.now() + '.' + ext;
      var ref = firebase.storage().ref(pad);
      await ref.put(file);
      fotoURL = await ref.getDownloadURL();
    }

    function gv(id) { var el = document.getElementById(id); return el ? el.value.trim() : ''; }

    var displayName = (DY.profile && (DY.profile.displayName || DY.profile.naam))
    || (DY.user && DY.user.displayName)
    || ((DY.user && DY.user.email) ? ((DY.user.email) || '').split('@')[0] : '')
    || 'Gebruiker';

    var data = {
      userId:          DY.user.uid,
      authorName:      displayName,
      // v60.1.265: label voor scheiding tussen 3 review-domeinen:
      // 'tall_fit' = deze pagina (pasvorm reviews voor tall/plus size)
      // 'webshop'  = DoubleYou Webshop bestelervaring
      // 'brand'    = merkenportaal product/merk reviews
      reviewType:      'tall_fit',
      product:         product.trim(),
      ster:            ster,
      tekst:           tekst.trim(),
      foto:            fotoURL,
      // Bouw
      lengte:          parseInt(gv('rv-lengte')) || null,
      gewicht:         parseInt(gv('rv-gewicht')) || null,
      maat:            gv('rv-maat') || null,
      lichaamstype:    gv('rv-lichaamstype') || null,
      bouw:            gv('rv-lichaamstype') || null,  // alias voor maatMatchScore
      pasvormproblemen: gv('rv-problemen') || null,
      // Pasvorm
      pasvorm:         gv('rv-pasvorm') || null,
      mouwlengte:      gv('rv-mouwlengte') || null,
      broeklengte:     gv('rv-broeklengte') || null,
      buikruimte:      gv('rv-buikruimte') || null,
      beenruimte:      gv('rv-beenruimte') || null,
      schouders:       gv('rv-schouders') || null,
      torsomaat:       gv('rv-torsomaat') || null,
      // Stof & gebruik
      stretch:         gv('rv-stretch') || null,
      stofgevoel:      gv('rv-stofgevoel') || null,
      gebruik:         gv('rv-gebruik') || null,
      // Community
      twijfel:         gv('rv-twijfel') || null,
      twijfelOpgelost: gv('rv-twijfelOpgelost') === 'true' ? true : gv('rv-twijfelOpgelost') === 'false' ? false : null,
      aanraden:        gv('rv-aanraden') === 'true' ? true : gv('rv-aanraden') === 'false' ? false : null,
      // Maat Matcher extra
      fitvoorkeur:     (DY.profile && DY.profile.fitvoorkeur) || null,
      // Meta
      geverifieerd:    false,
      ts:              firebase.firestore.FieldValue.serverTimestamp(),
      createdAt:       new Date().toISOString()
    };

    // Verwijder null waarden
    Object.keys(data).forEach(function(k) { if (data[k] === null) delete data[k]; });

    await DY.db.collection('reviews').add(data);
    await DY.geefPunten(fotoURL ? 'review_foto' : 'review_plaatsen');
    DY.navigeer('reviews');

  } catch(e) {
    if (btn) { btn.disabled = false; btn.textContent = 'REVIEW PLAATSEN'; }
    DY.toast('Er ging iets mis. Probeer opnieuw.');
  }
};

// Oud helper - keep voor backwards compat
DY.voorbeeldReviewFoto = function(input) { DY.rvFotoPreview(input); };

DY._lookFilter = 'recent';
DY._looksCache = null;  // { ts, looks[] }
DY._looksCacheTTL = 90000;


// ── Deel verhaal/look via Web Share API of clipboard ─────────────
DY.deelVerhaal = async function(id, titel) {
  try {
    var url = window.location.origin + '/?verhaal=' + (id || '');
    var tekst = titel || 'Bekijk dit verhaal op Paskamerpraat';
    if (navigator.share) {
      try {
        await navigator.share({ title: 'Paskamerpraat', text: tekst, url: url });
        DY.geefPunten && DY.geefPunten('deel_verhaal', id);
      } catch(e) {
        if (e.name !== 'AbortError') DY._deelFallback(url);
      }
    } else {
      DY._deelFallback(url);
    }

  } catch(e) { }
};


DY._deelFallback = function(url) {
  if (navigator.clipboard) {
    navigator.clipboard.writeText(url).then(function() {
      DY.toast('Link gekopieerd!');
    }).catch(function() { DY.toast('Link: ' + url); });
  } else {
    DY.toast('Link: ' + url);
  }
};

