DY.cfgLaadShopifyProducten = async function() {
  const el = document.getElementById('dy-cfg-shopify-grid');
  if (!el) return;
  // Winkel nog niet open - verberg sectie
  const sectie = el.closest('.dy-cfg-shopify-sectie');
  if (sectie) sectie.style.display = 'none';
  if (!DY.CFG_SHOPIFY_TOKEN) {
    return;
  }

  el.innerHTML = '<div class="dy-loader"><div class="dy-spinner"></div></div>';

  const s = DY.cfgState.selecties;
  const k = DY.cfgState.kledingstuk;
  const kleurNaam = (DY.CFG_KLEUREN.find(function(c){return c.hex===DY.cfgState.kleur;})||{naam:'ink'}).naam
    .toLowerCase().replace(/\s+/g, '-');

  // Bouw tag query op basis van huidige selectie
  const tagFilters = ['dy-kledingstuk-' + k];
  if (s.pasvorm) tagFilters.push('dy-pasvorm-' + s.pasvorm.toLowerCase().replace(/\s+/g,'-'));
  if (s.lengte)  tagFilters.push('dy-lengte-' + s.lengte.toLowerCase().replace(/\s+/g,'-'));

  const query = tagFilters.map(function(t) { return 'tag:' + t; }).join(' AND ');

  const gqlQuery = `{
    products(first: 6, query: "${query}") {
      edges {
        node {
          id
          title
          handle
          tags
          priceRange {
            minVariantPrice { amount currencyCode }
          }
          images(first: 3) {
            edges {
              node { url altText }
            }
          }
        }
      }
    }
  }`;

  try {
    const res = await fetch('https://' + DY.CFG_SHOPIFY_STORE + '/api/2024-01/graphql.json', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Storefront-Access-Token': DY.CFG_SHOPIFY_TOKEN,
      },
      body: JSON.stringify({ query: gqlQuery }),
    });

    const data = await res.json();
    const producten = (data.data && data.data.products && data.data.products.edges) || [];

    if (producten.length === 0) {
      el.innerHTML =
        '<div class="dy-cfg-shopify-leeg">' +
        '<p>Geen producten gevonden voor deze combinatie.</p>' +
        '<p style="font-size:12px;margin-top:4px">Voeg tags toe aan je Shopify producten om ze hier te tonen.</p>' +
        '</div>';
      return;
    }

    el.innerHTML = producten.map(function(edge) {
      const p = edge.node;
      const foto = p.images.edges[0] && p.images.edges[0].node.url || '';
      const prijs = p.priceRange.minVariantPrice.amount;
      const valuta = p.priceRange.minVariantPrice.currencyCode;
      const url = 'https://doubleyoufashion.nl/products/' + p.handle + '?utm_source=pwa&utm_medium=configurator';

      return '';
    }).filter(Boolean).join('');
    document.getElementById('dy-cfg-shopify-producten').innerHTML = productHTML || '<p style="color:var(--ink-muted);font-size:0.85rem">Geen producten gevonden.</p>';
  } catch(e) { }
};


