// Maten mapping van DoubleYou paskamer (cm) naar FreeSewing (mm)
DY.fsConvertMaten = function(profiel) {
  var lengte = parseFloat(profiel.lengte || 0);
  var borst  = parseFloat(profiel.borst  || 0);
  var taille = parseFloat(profiel.taille || 0);
  var heup   = parseFloat(profiel.heup   || 0);
  var been   = parseFloat(profiel.been   || 0);

  // Validatie: alleen tall (185cm+) en plus size (XL = borst 106cm+)
  var fouten = [];
  if (lengte < 185) fouten.push('Lengte moet minimaal 185 cm zijn (DoubleYou maakt kleding voor 1.85m+).');
  if (borst < 106)  fouten.push('Borstmaat moet minimaal 106 cm zijn (DoubleYou is XL t/m 5XL).');
  if (fouten.length) return { fout: fouten.join(' ') };

  // FreeSewing werkt in millimeters
  // Berekende schattingen voor ontbrekende maten op basis van beschikbare maten
  var schouderBreedte = borst * 0.44; // schatting op basis van borst
  var halsOmtrek      = borst * 0.38;
  var armlengte       = lengte * 0.33;
  var heupToTaille    = (lengte - 160) * 0.18 + 18; // schatting tall proportie
  var ruglengte       = lengte * 0.26;

  return {
    // Kern maten
    chest:               borst   * 10,
    waist:               taille  * 10 || borst * 8.5,
    hips:                heup    * 10 || borst * 10.5,
    inseam:              been    * 10 || (lengte - 85) * 10,
    // Berekende maten
    neck:                Math.round(halsOmtrek) * 10,
    shoulderToShoulder:  Math.round(schouderBreedte) * 10,
    hpsToWaistBack:      Math.round(ruglengte) * 10,
    waistToHips:         Math.round(heupToTaille) * 10,
    shoulderSlope:       13, // standaard waarde
    biceps:              Math.round(borst * 0.34) * 10,
    wrist:               Math.round(borst * 0.17) * 10,
    // Broek specifiek
    waistToFloor:        Math.round(lengte * 0.62) * 10,
    waistToKnee:         Math.round(lengte * 0.35) * 10,
    crossSeam:           Math.round((heup || borst * 1.05) * 0.57) * 10,
    crossSeamFront:      Math.round((heup || borst * 1.05) * 0.28) * 10,
    kneeCircumference:   Math.round(borst * 0.38) * 10,
    ankleCircumference:  Math.round(borst * 0.22) * 10,
    seat:                (heup || borst * 1.05) * 10,
    // Bovenlichaam
    hpsToBust:           Math.round(ruglengte * 0.6) * 10,
    waistToArmpit:       Math.round(ruglengte * 0.35) * 10,
  };
};

