DY.berekenPatroon = function(kledingstuk, m) {
  // Schaal: 1cm = 2.5px voor overzichtelijk patroon
  var sc = 2.5;
  var naad = 1; // 1cm naadtoeslag
  var B = m.borst; var T = m.taille; var H = m.heup;
  var L = m.lengte; var been = m.been;

  // Ease per pasvorm
  var ease = { 'Slim':4, 'Regular':8, 'Relaxed':14, 'Plus Size':18, 'Oversized':22 };
  var e = ease[m.pasvorm] || 8;

  var delen = [];
  var x = 20; // start x positie

  function label(tekst, cx, cy, size) {
    return '<text x="' + cx + '" y="' + cy + '" font-family="Arial" font-size="' + (size||8) + '" fill="#1e1a0f" text-anchor="middle">' + tekst + '</text>';
  }

  function maatlijn(x1, y1, x2, y2, tekst) {
    var mx = (x1+x2)/2; var my = (y1+y2)/2;
    return '<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="#c67d06" stroke-width="0.5" stroke-dasharray="3,2"/>' +
      '<text x="'+(mx+4)+'" y="'+(my+3)+'" font-family="Arial" font-size="6" fill="#c67d06">' + tekst + '</text>';
  }

  function deel(naam, paden, breedte, hoogte, offsetX) {
    var d = '<g transform="translate(' + offsetX + ',20)">';
    d += '<rect x="0" y="0" width="' + breedte + '" height="' + hoogte + '" fill="none" stroke="#999" stroke-width="0.3" stroke-dasharray="4,3"/>';
    d += paden;
    d += label(naam, breedte/2, -6, 9);
    d += '</g>';
    return { svg: d, breedte: breedte };
  }

  if (kledingstuk === 'hoodie' || kledingstuk === 'tracksuit') {
    // Voorpand
    var vB = ((B/2 + e) / 2 + naad) * sc;
    var vL = (L * 0.42 + naad) * sc;
    var vOksel = (L * 0.28) * sc;
    var vHals = (B * 0.09) * sc;
    var vSchouder = (B * 0.23) * sc;
    var vPath = '<path d="M' + naad*sc + ',' + vL +
      ' L' + naad*sc + ',' + vOksel +
      ' L' + (naad*sc + vB*0.15) + ',' + (naad*sc) +
      ' L' + (vSchouder + naad*sc) + ',' + (naad*sc) +
      ' L' + (vSchouder + naad*sc) + ',' + vHals +
      ' L' + (vB + naad*sc) + ',' + vHals +
      ' L' + (vB + naad*sc) + ',' + vL + ' Z"' +
      ' fill="rgba(198,125,6,0.06)" stroke="#1e1a0f" stroke-width="1.5"/>';
    vPath += maatlijn(naad*sc, 20, naad*sc, vL, Math.round(L*0.42)+'cm');
    vPath += maatlijn(naad*sc, vL-5, vB+naad*sc, vL-5, Math.round(B/4+e/2)+'cm');
    var d1 = deel('1. Voorpand', vPath, vB + naad*sc*2 + 10, vL + 20, x);
    delen.push(d1); x += d1.breedte + 20;

    // Rugpand
    var rPath = '<path d="M' + naad*sc + ',' + vL +
      ' L' + naad*sc + ',' + vOksel +
      ' L' + (naad*sc + vB*0.1) + ',' + (naad*sc) +
      ' L' + (vSchouder + naad*sc + vB*0.04) + ',' + (naad*sc) +
      ' L' + (vB + naad*sc) + ',' + vHals*1.2 +
      ' L' + (vB + naad*sc) + ',' + vL + ' Z"' +
      ' fill="rgba(198,125,6,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d2 = deel('2. Rugpand', rPath, vB + naad*sc*2 + 10, vL + 20, x);
    delen.push(d2); x += d2.breedte + 20;

    // Mouw
    var mL = (m.mouw === 'Kort' ? L*0.18 : m.mouw === '3/4' ? L*0.28 : L*0.35) * sc;
    var mBo = (B * 0.19 + e*0.3 + naad) * sc;
    var mOn = (B * 0.13 + naad) * sc;
    var mPath = '<path d="M0,' + mL +
      ' L' + (mBo*0.5) + ',0' +
      ' L' + mBo + ',' + (mL*0.08) +
      ' L' + mBo + ',' + mL +
      ' L' + (mBo-mOn)/2 + ',' + mL +
      ' L' + (mBo-mOn)/2 + ',' + (mL + 12) +
      ' L' + ((mBo+mOn)/2) + ',' + (mL+12) +
      ' L' + ((mBo+mOn)/2) + ',' + mL + ' Z"' +
      ' fill="rgba(30,26,15,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    mPath += maatlijn(0, mL+4, mBo, mL+4, Math.round(B*0.19+e*0.3)+'cm');
    var d3 = deel('3. Mouw', mPath, mBo + 20, mL + 40, x);
    delen.push(d3); x += d3.breedte + 20;

    // Hood
    var hH = (L * 0.18) * sc;
    var hB = (B * 0.24) * sc;
    var hPath = '<path d="M' + naad*sc + ',' + hH +
      ' Q' + (naad*sc) + ',0 ' + (hB/2+naad*sc) + ',0' +
      ' Q' + (hB+naad*sc) + ',0 ' + (hB+naad*sc) + ',' + hH +
      ' L' + (hB+naad*sc) + ',' + (hH*1.3) +
      ' L' + naad*sc + ',' + (hH*1.3) + ' Z"' +
      ' fill="rgba(198,125,6,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d4 = deel('4. Hood (2x)', hPath, hB + naad*sc*2 + 10, hH*1.3 + 20, x);
    delen.push(d4); x += d4.breedte + 20;

  } else if (kledingstuk === 'broek') {
    var pL = (been + naad) * sc;
    var pHB = ((H/2 + e*0.5) / 2 + naad) * sc;
    var pTB = ((T/2 + e*0.3) / 2 + naad) * sc;
    var pKruis = (H * 0.15) * sc;

    // Voorpand broek
    var vpPath = '<path d="M0,' + (pL+pKruis) +
      ' L0,' + pKruis +
      ' Q0,0 ' + pTB + ',0' +
      ' L' + pHB + ',' + (pKruis*0.4) +
      ' L' + pHB + ',' + (pL+pKruis) + ' Z"' +
      ' fill="rgba(198,125,6,0.06)" stroke="#1e1a0f" stroke-width="1.5"/>';
    vpPath += maatlijn(0, pL+pKruis+5, pHB, pL+pKruis+5, Math.round(H/4+e*0.25)+'cm');
    vpPath += maatlijn(pHB+5, pKruis, pHB+5, pL+pKruis, Math.round(been)+'cm');
    var d1 = deel('1. Voorpand (2x)', vpPath, pHB + 20, pL + pKruis + 20, x);
    delen.push(d1); x += d1.breedte + 20;

    // Rugpand broek
    var rpHB = pHB * 1.06;
    var rpPath = '<path d="M0,' + (pL+pKruis*1.2) +
      ' L0,' + (pKruis*1.2) +
      ' Q' + (rpHB*0.3) + ',0 ' + rpHB + ',' + (pKruis*0.2) +
      ' L' + rpHB + ',' + (pL+pKruis*1.2) + ' Z"' +
      ' fill="rgba(30,26,15,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d2 = deel('2. Rugpand (2x)', rpPath, rpHB + 20, pL + pKruis*1.2 + 20, x);
    delen.push(d2); x += d2.breedte + 20;

    // Taille boord
    var tbB = ((H/2 + e*0.5) + naad*2) * sc;
    var tbH = 6 * sc;
    var d3Path = '<rect x="' + naad*sc + '" y="0" width="' + tbB + '" height="' + tbH + '" fill="rgba(198,125,6,0.06)" stroke="#1e1a0f" stroke-width="1.5"/>';
    d3Path += maatlijn(naad*sc, tbH+4, naad*sc+tbB, tbH+4, Math.round(H/2+e*0.5)+'cm');
    var d3 = deel('3. Taille boord', d3Path, tbB + naad*sc*2 + 10, tbH + 20, x);
    delen.push(d3); x += d3.breedte + 20;

  } else if (kledingstuk === 'shirt' || kledingstuk === 'blouse') {
    var sB = ((B/2 + e) / 2 + naad) * sc;
    var sL = (L * 0.38 + naad) * sc;
    var sOksel = (L * 0.26) * sc;
    var sHals = (B * 0.08) * sc;
    var sSch = (B * 0.22) * sc;

    var svPath = '<path d="M' + naad*sc + ',' + sL +
      ' L' + naad*sc + ',' + sOksel +
      ' L' + (naad*sc + sB*0.12) + ',' + (naad*sc) +
      ' L' + (sSch + naad*sc) + ',' + (naad*sc) +
      ' Q' + (sB*0.7+naad*sc) + ',' + sHals*0.5 + ' ' + (sB + naad*sc) + ',' + sHals +
      ' L' + (sB + naad*sc) + ',' + sL + ' Z"' +
      ' fill="rgba(198,125,6,0.06)" stroke="#1e1a0f" stroke-width="1.5"/>';
    svPath += maatlijn(naad*sc, sL+5, sB+naad*sc, sL+5, Math.round(B/4+e/2)+'cm');
    var d1 = deel('1. Voorpand', svPath, sB + naad*sc*2 + 10, sL + 20, x);
    delen.push(d1); x += d1.breedte + 20;

    var srPath = '<path d="M' + naad*sc + ',' + sL +
      ' L' + naad*sc + ',' + sOksel +
      ' L' + (naad*sc + sB*0.08) + ',' + (naad*sc) +
      ' L' + (sSch*1.04 + naad*sc) + ',' + (naad*sc) +
      ' L' + (sB + naad*sc) + ',' + sHals*1.3 +
      ' L' + (sB + naad*sc) + ',' + sL + ' Z"' +
      ' fill="rgba(30,26,15,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d2 = deel('2. Rugpand', srPath, sB + naad*sc*2 + 10, sL + 20, x);
    delen.push(d2); x += d2.breedte + 20;

    var smL = (m.mouw === 'Kort' ? L*0.14 : m.mouw === '3/4' ? L*0.24 : L*0.32) * sc;
    var smB = (B * 0.17 + e*0.25 + naad) * sc;
    var smPath = '<path d="M0,' + smL + ' L' + (smB*0.4) + ',0 L' + smB + ',' + (smL*0.1) + ' L' + smB + ',' + smL + ' Z"' +
      ' fill="rgba(30,26,15,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d3 = deel('3. Mouw (2x)', smPath, smB + 20, smL + 20, x);
    delen.push(d3); x += d3.breedte + 20;

  } else if (kledingstuk === 'jasje') {
    var jB = ((B/2 + e*1.2) / 2 + naad) * sc;
    var jL = (L * 0.44 + naad) * sc;
    var jOksel = (L * 0.3) * sc;
    var jHals = (B * 0.1) * sc;
    var jSch = (B * 0.24) * sc;

    var jvPath = '<path d="M' + naad*sc + ',' + jL +
      ' L' + naad*sc + ',' + jOksel +
      ' L' + (naad*sc + jB*0.1) + ',' + (naad*sc) +
      ' L' + (jSch + naad*sc) + ',' + (naad*sc) +
      ' L' + (jSch + naad*sc) + ',' + jHals +
      ' Q' + (jB*0.75+naad*sc) + ',' + (jHals*3) + ' ' + (jB + naad*sc) + ',' + (jHals*4) +
      ' L' + (jB + naad*sc) + ',' + jL + ' Z"' +
      ' fill="rgba(198,125,6,0.06)" stroke="#1e1a0f" stroke-width="1.5"/>';
    jvPath += maatlijn(naad*sc, jL+5, jB+naad*sc, jL+5, Math.round(B/4+e*0.6)+'cm');
    var d1 = deel('1. Voorpand', jvPath, jB + naad*sc*2 + 10, jL + 20, x);
    delen.push(d1); x += d1.breedte + 20;

    var jrPath = '<path d="M' + naad*sc + ',' + jL +
      ' L' + naad*sc + ',' + jOksel +
      ' L' + (naad*sc + jB*0.08) + ',' + (naad*sc) +
      ' L' + (jSch*1.06 + naad*sc) + ',' + (naad*sc) +
      ' L' + (jB + naad*sc) + ',' + jHals*1.5 +
      ' L' + (jB + naad*sc) + ',' + jL + ' Z"' +
      ' fill="rgba(30,26,15,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d2 = deel('2. Rugpand', jrPath, jB + naad*sc*2 + 10, jL + 20, x);
    delen.push(d2); x += d2.breedte + 20;

    var jmL = (L * 0.36 + naad) * sc;
    var jmB = (B * 0.2 + e*0.3 + naad) * sc;
    var jmPath = '<path d="M0,' + jmL + ' L' + (jmB*0.45) + ',0 L' + jmB + ',' + (jmL*0.1) + ' L' + jmB + ',' + jmL + ' Z"' +
      ' fill="rgba(30,26,15,0.04)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d3 = deel('3. Mouw (2x)', jmPath, jmB + 20, jmL + 20, x);
    delen.push(d3); x += d3.breedte + 20;

  } else {
    // Badmode - eenvoudig
    var bdB = ((B/2 + 4) / 2 + naad) * sc;
    var bdL = (L * 0.28) * sc;
    var bdPath = '<path d="M0,' + bdL + ' Q0,0 ' + bdB + ',0 L' + bdB + ',' + bdL + ' Z"' +
      ' fill="rgba(198,125,6,0.06)" stroke="#1e1a0f" stroke-width="1.5"/>';
    var d1 = deel('1. Top voor', bdPath, bdB + 20, bdL + 20, x);
    delen.push(d1); x += d1.breedte + 20;
  }

  // SVG samenstellen
  var totalW = x + 20;
  var maxH = 0;
  var deelSVG = '';
  for (var i = 0; i < delen.length; i++) {
    deelSVG += delen[i].svg;
    var dH = parseInt(delen[i].svg.match(/height="(\d+)"/)?.[1] || 300);
    if (dH > maxH) maxH = dH;
  }

  var kLabel = { hoodie:'Hoodie', shirt:'Shirt/Top', broek:'Broek', jasje:'Jasje', tracksuit:'Tracksuit', blouse:'Blouse', badmode:'Badmode' }[kledingstuk] || kledingstuk;

  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + totalW + ' ' + (maxH + 80) + '" style="width:100%;background:white">' +
    '<style>text{font-family:Arial,sans-serif}</style>' +
    // Titel
    '<text x="' + totalW/2 + '" y="28" font-size="14" font-weight="bold" text-anchor="middle" fill="#1e1a0f">DoubleYou \u2014 ' + kLabel + ' Patroon op maat</text>' +
    '<text x="' + totalW/2 + '" y="44" font-size="9" text-anchor="middle" fill="#888">Lengte ' + m.lengte + 'cm \u00b7 Borst ' + m.borst + 'cm \u00b7 Taille ' + Math.round(m.taille) + 'cm \u00b7 Heup ' + Math.round(m.heup) + 'cm \u00b7 Naadtoeslag 1cm inbegrepen</text>' +
    '<line x1="20" y1="52" x2="' + (totalW-20) + '" y2="52" stroke="#c67d06" stroke-width="0.5"/>' +
    '<g transform="translate(0,60)">' + deelSVG + '</g>' +
    // Legenda
    '<line x1="20" y1="' + (maxH+65) + '" x2="' + (totalW-20) + '" y2="' + (maxH+65) + '" stroke="#ddd" stroke-width="0.5"/>' +
    '<text x="20" y="' + (maxH+76) + '" font-size="7" fill="#888">Schaal 1:4 \u00b7 Naadtoeslag 1cm inbegrepen \u00b7 Pasvorm: ' + (m.pasvorm||'Regular') + ' \u00b7 Afdrukken op A0 of bij copyshop</text>' +
    '</svg>';
};

DY.cfgAIBericht = function(rol, tekst) {
  const chat = document.getElementById('dy-cfg-ai-chat');
  if (!chat) return;
  const el = document.createElement('div');
  el.className = 'dy-cfg-ai-msg dy-cfg-ai-msg-' + rol;
  el.textContent = tekst;
  chat.appendChild(el);
  chat.scrollTop = chat.scrollHeight;
};

DY.cfgAIPasAan = function(tekst) {
  // Detecteer pasvorm suggesties in het antwoord
  const lower = tekst.toLowerCase();
  var gewijzigd = false;

  var paasvormMap = { 'slim': 'Slim', 'regular': 'Regular', 'relaxed': 'Relaxed', 'plus size': 'Plus Size', 'oversized': 'Oversized', 'straight': 'Straight', 'wide': 'Wide' };
  var lengteMap = { 'short': 'Short', 'tall': 'Tall', 'lang': 'Lang', 'kort': 'Kort', 'extra lang': 'Extra lang', '7/8': '7/8' };

  Object.keys(paasvormMap).forEach(function(sleutel) {
    if (lower.includes(sleutel + ' pasvorm') || lower.includes('kies ' + sleutel) || lower.includes(sleutel + ' snit')) {
      DY.cfgState.selecties.pasvorm = paasvormMap[sleutel];
      gewijzigd = true;
    }
  });

  Object.keys(lengteMap).forEach(function(sleutel) {
    if (lower.includes(sleutel + ' lengte') || lower.includes('lengte ' + sleutel)) {
      DY.cfgState.selecties.lengte = lengteMap[sleutel];
      gewijzigd = true;
    }
  });

  if (gewijzigd) {
    DY.cfgTekenPanel();
    DY.cfgTekenSVG();
    DY.cfgTekenKleuren();
  }
};

DY.cfgAITyping = function(aan) {
  const chat = document.getElementById('dy-cfg-ai-chat');
  if (!chat) return;
  const bestaand = document.getElementById('dy-cfg-ai-typing');
  if (aan && !bestaand) {
    const el = document.createElement('div');
    el.className = 'dy-cfg-ai-msg dy-cfg-ai-msg-assistent dy-cfg-ai-typing';
    el.id = 'dy-cfg-ai-typing';
    el.innerHTML = '<span></span><span></span><span></span>';
    chat.appendChild(el);
    chat.scrollTop = chat.scrollHeight;
  } else if (!aan && bestaand) {
    bestaand.remove();
  }
};

DY.cfgAdminDownload = function() {
  var svg = window.__dy_admin_svg;
  if (!svg) return;
  var k = DY.cfgState.kledingstuk;
  var profiel = DY.profile || {};
  var lengte = document.getElementById('cfg-lengte')?.value || profiel.lengte || '';
  var blob = new Blob([svg], { type: 'image/svg+xml' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'paskamerpraat-atelier-' + k + '-' + lengte + 'cm-' + new Date().toISOString().slice(0,10) + '.svg';
  a.click();
  URL.revokeObjectURL(url);
  DY.toast('Atelier patroon gedownload!');
};

DY.cfgAdminGenereerPatroon = async function() {
  if (!DY.isAdmin()) return;
  var wrap = document.getElementById('dy-cfg-admin-patroon-wrap');
  var btn = event && event.target;
  if (!wrap) return;

  wrap.innerHTML = '<div class="dy-cfg-patroon-loading"><div class="dy-cfg-model-dots"><span></span><span></span><span></span></div><p>Patroon wordt gegenereerd\u2026</p></div>';

  var s = DY.cfgState.selecties;
  var k = DY.cfgState.kledingstuk;
  var profiel = DY.profile || {};

  // Haal maten op uit formulier of profiel
  var lengte = parseFloat(document.getElementById('cfg-lengte')?.value || profiel.lengte || 0);
  var borst  = parseFloat(document.getElementById('cfg-borst')?.value  || profiel.borst  || 0);
  var taille = parseFloat(document.getElementById('cfg-taille')?.value || profiel.taille || borst * 0.85);
  var heup   = parseFloat(document.getElementById('cfg-heup')?.value   || profiel.heup   || borst * 1.05);
  var been   = parseFloat(document.getElementById('cfg-been')?.value   || profiel.been   || (lengte - 85));

  if (!lengte || !borst) {
    wrap.innerHTML = '<p class="dy-cfg-patroon-fout">\u26a0 Vul eerst maten in.</p>';
    return;
  }

  try {
    var svg = DY.cfgGenereerProfessioneelPatroon(k, lengte, borst, taille, heup, been, s.pasvorm);

    wrap.innerHTML =
      '<div class="dy-cfg-admin-patroon-preview">' +
      svg +
      '</div>' +
      '<div class="dy-cfg-patroon-acties" style="margin-top:8px">' +
      '<button class="dy-btn dy-btn-primary" onclick="DY.cfgAdminDownload()" style="flex:1">\u2913 Download SVG</button>' +
      '<button class="dy-btn dy-btn-ghost" onclick="DY.cfgAdminGenereerPatroon()" style="flex:1">\u21ba Opnieuw</button>' +
      '</div>';

    window.__dy_admin_svg = svg;
  } catch(e) {
    wrap.innerHTML = '<p class="dy-cfg-patroon-fout">Fout: ' + e.message + '</p>';
  }
};

DY.cfgDownloadSVG = function() {
  if (!DY._svgPatroon) return;
  var blob = new Blob([DY._svgPatroon], { type: 'image/svg+xml' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'paskamerpraat-' + (DY._svgNaam || 'patroon') + '.svg';
  a.click();
  URL.revokeObjectURL(url);
  DY.toast('Patroon gedownload!');
};

DY.cfgGenereerModel = async function() {
  const btn = document.getElementById('dy-cfg-genereer-btn');
  const wrap = document.getElementById('dy-cfg-model-wrap');
  if (!btn || !wrap) return;

  btn.disabled = true;
  btn.textContent = '\u23f3 Wordt gegenereerd...';
  wrap.innerHTML =
    '<div class="dy-cfg-model-loading">' +
    '<div class="dy-cfg-model-dots"><span></span><span></span><span></span></div>' +
    '<p>AI genereert jouw model\u2026 even geduld</p>' +
    '</div>';

  const s = DY.cfgState.selecties;
  const k = DY.cfgState.kledingstuk;
  const kleurNaam = (DY.CFG_KLEUREN.find(function(c) { return c.hex === DY.cfgState.kleur; }) || { naam: 'zwart' }).naam;

  const lichaamstype = s.pasvorm === 'Plus Size' ? 'plus size curvy woman' :
                       s.pasvorm === 'Slim' ? 'slim woman' : 'woman';

  const modelLengte = s.lengte === 'Tall' || s.lengte === 'Extra lang' ? 'very tall 190cm' :
                      s.lengte === 'Short' || s.lengte === '7/8' ? 'petite 165cm' : '175cm';

  const kledingstukEN = {
    hoodie: 'hoodie', shirt: 't-shirt', broek: 'pants', jasje: 'jacket',
    tracksuit: 'tracksuit', blouse: 'blouse', badmode: 'swimsuit'
  }[k] || k;

  const prompt = encodeURIComponent(
    'fashion editorial photo, ' + modelLengte + ' ' + lichaamstype +
    ', wearing ' + kledingstukEN + ' in ' + kleurNaam +
    ' color, ' + (s.pasvorm || 'regular') + ' fit' +
    ', white studio background, full body, professional photography, photorealistic'
  );

  // Gebruik Pollinations.ai - gratis, geen token, werkt direct in browser
  const seed = Math.floor(Math.random() * 999999);
  const url = 'https://image.pollinations.ai/prompt/' + prompt +
    '?width=512&height=768&seed=' + seed + '&model=flux&nologo=true';

  var img = new Image();

  var timeout = setTimeout(function() {
    img.src = '';
    wrap.innerHTML =
      '<div class="dy-cfg-model-fout">' +
      '<p>Duurt te lang. Probeer opnieuw.</p>' +
      '<button class="dy-cfg-model-opnieuw" onclick="DY.cfgGenereerModel()" style="margin-top:8px">\u21ba Opnieuw</button>' +
      '</div>';
    btn.disabled = false;
    btn.textContent = '\u2736 Genereer model';
  }, 45000);

  img.onload = function() {
    clearTimeout(timeout);
    wrap.innerHTML =
      '<div class="dy-cfg-model-resultaat">' +
      '<img loading="lazy" decoding="async" src="' + url + '" class="dy-cfg-model-foto" alt="AI model">' +
      '<div class="dy-cfg-model-acties">' +
      '<button class="dy-cfg-model-opnieuw" onclick="DY.cfgGenereerModel()">\u21ba Opnieuw</button>' +
      '<a class="dy-cfg-model-download" href="' + url + '" target="_blank" rel="noopener noreferrer">\u2913 Openen</a>' +
      '</div>' +
      '</div>';
    btn.disabled = false;
    btn.textContent = '\u2736 Genereer model';
  };

  img.onerror = function() {
    clearTimeout(timeout);
    wrap.innerHTML =
      '<div class="dy-cfg-model-fout">' +
      '<p>Kon geen model genereren.</p>' +
      '<p style="font-size:11px;opacity:0.6;margin-top:4px">Probeer een andere kleur of pasvorm.</p>' +
      '<button class="dy-cfg-model-opnieuw" onclick="DY.cfgGenereerModel()" style="margin-top:8px">\u21ba Opnieuw</button>' +
      '</div>';
    btn.disabled = false;
    btn.textContent = '\u2736 Genereer model';
  };

  img.src = url;
};
// ── CONFIGURATOR AI STIJLASSISTENT ────────────────────────────────
DY.cfgGenereerPatroon = async function() {
  var btn = document.getElementById('dy-cfg-patroon-btn');
  var wrap = document.getElementById('dy-cfg-patroon-wrap');
  if (!btn || !wrap) return;

  var profiel = DY.profile || {};
  var k = DY.cfgState.kledingstuk;
  var s = DY.cfgState.selecties;
  var lengte = parseFloat(profiel.lengte || 0);
  var borst  = parseFloat(profiel.borst  || 0);
  var taille = parseFloat(profiel.taille || borst * 0.85);
  var heup   = parseFloat(profiel.heup   || borst * 1.05);
  var been   = parseFloat(profiel.been   || (lengte - 85));

  if (lengte < 185) {
    wrap.innerHTML = '<div class="dy-cfg-patroon-fout"><p>\u26a0 Vul eerst je lengte in (minimaal 185 cm)</p><button class="dy-btn dy-btn-ghost" onclick="DY.navigeer(\'paskamer\')" style="margin-top:8px;font-size:12px">\u2192 Mijn Maten</button></div>';
    return;
  }
  if (borst < 106) {
    wrap.innerHTML = '<div class="dy-cfg-patroon-fout"><p>\u26a0 Vul eerst je borstmaat in (minimaal 106 cm)</p><button class="dy-btn dy-btn-ghost" onclick="DY.navigeer(\'paskamer\')" style="margin-top:8px;font-size:12px">\u2192 Mijn Maten</button></div>';
    return;
  }

  btn.disabled = true;
  btn.textContent = '\u23f3 Berekenen...';
  wrap.innerHTML = '<div class="dy-cfg-patroon-loading"><div class="dy-cfg-model-dots"><span></span><span></span><span></span></div><p>Patroon wordt gegenereerd\u2026 Bij de eerste keer kan dit tot 60 seconden duren.</p></div>';

  // Wacht even zodat UI update zichtbaar is
  await new Promise(function(r) { setTimeout(r, 100); });

  try {
    // Haal patroon op van de DoubleYou Patroon Server
    var fetchPromise = fetch('https://doubleyou-patroon-server.onrender.com/patroon', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        kledingstuk: k,
        lengte: lengte,
        borst: borst,
        taille: taille,
        heup: heup,
        been: been,
        pasvorm: s.pasvorm || 'Regular'
      })
    });

    var timeoutPromise = new Promise(function(_, reject) {
      setTimeout(function() { reject(new Error('TIMEOUT')); }, 55000);
    });

    var svg;
    try {
      var res = await Promise.race([fetchPromise, timeoutPromise]);
      if (!res.ok) {
        var errData = await res.json().catch(function() { return {}; });
        throw new Error(errData.error || 'Server fout ' + res.status);
      }
      svg = await res.text();
    } catch(serverErr) {
      // Fallback: lokale patroon generator
      svg = DY.berekenPatroon(k, { lengte:lengte, borst:borst, taille:taille, heup:heup, been:been, pasvorm:s.pasvorm, mouw:s.mouw });
    }
    window.__dy_patroon_svg = svg;

    var labels = { hoodie:'Hoodie', shirt:'Shirt', broek:'Broek', jasje:'Jasje', tracksuit:'Tracksuit', blouse:'Blouse', badmode:'Badmode' };
    wrap.innerHTML =
      '<div class="dy-cfg-patroon-resultaat">' +
      '<div class="dy-cfg-patroon-info">' +
      '<span class="dy-cfg-patroon-naam">' + (labels[k]||k) + ' \u2014 op maat</span>' +
      '<span class="dy-cfg-patroon-maten">Borst ' + borst + 'cm \u00b7 Lengte ' + lengte + 'cm \u00b7 Naadtoeslag 1cm</span>' +
      '</div>' +
      '<div class="dy-cfg-patroon-svg" id="dy-cfg-patroon-svg">' + svg + '</div>' +
      '<div class="dy-cfg-patroon-acties">' +
      '<button class="dy-btn dy-btn-primary" onclick="DY.cfgDownloadPatroon()" style="flex:1">\u2913 Download SVG</button>' +
      '<button class="dy-btn dy-btn-ghost" onclick="DY.cfgGenereerPatroon()" style="flex:1">\u21ba Opnieuw</button>' +
      '</div>' +
      '<p class="dy-cfg-patroon-disclaimer">Technisch patroon op basis van jouw maten. Maak altijd een testexemplaar (toile) voor het definitieve stuk.</p>' +
      '</div>';

    btn.disabled = false;
    btn.textContent = '\u2702 Genereer naaipatroon';
  } catch(e) {
    wrap.innerHTML = '<div class="dy-cfg-patroon-fout"><p>Patroon kon niet worden gegenereerd.</p><p style="font-size:10px;opacity:0.5;margin-top:4px">' + e.message + '</p>' +
      '<button class="dy-btn dy-btn-ghost" onclick="DY.cfgGenereerPatroon()" style="margin-top:8px;font-size:12px">\u21ba Probeer opnieuw</button>' +
      '</div>';
    btn.disabled = false;
    btn.textContent = '\u2702 Genereer naaipatroon';
  }
};

// ── PATROON BEREKENING ─────────────────────────────────────────────
DY.cfgGenereerProfessioneelPatroon = function(kledingstuk, lengte, borst, taille, heup, been, pasvorm) {
  // Hoge-kwaliteit parametrisch patroon
  var sc = 3.5; // schaal: 1cm = 3.5px
  var naad = 1; // 1cm naadtoeslag
  var ease = { 'Slim':3, 'Regular':6, 'Relaxed':12, 'Plus Size':16, 'Oversized':20 }[pasvorm] || 6;
  var B = borst, T = taille, H = heup, L = lengte;

  function pt(x, y) { return x.toFixed(2) + ',' + y.toFixed(2); }

  function lijn(x1, y1, x2, y2, kleur, dikte, dash) {
    return '<line x1="'+x1.toFixed(2)+'" y1="'+y1.toFixed(2)+'" x2="'+x2.toFixed(2)+'" y2="'+y2.toFixed(2)+'" stroke="'+(kleur||'#1a1a2e')+'" stroke-width="'+(dikte||0.8)+'"'+(dash?' stroke-dasharray="'+dash+'"':'')+'/>';
  }

  function tekst(x, y, inhoud, midden, kleur, grootte) {
    return '<text x="'+x.toFixed(2)+'" y="'+y.toFixed(2)+'" font-family="Arial,sans-serif" font-size="'+(grootte||7)+'" fill="'+(kleur||'#1a1a2e')+'"'+(midden?' text-anchor="middle"':'')+'>'+inhoud+'</text>';
  }

  function inkeping(x, y, hoek) {
    var r = 4;
    var rad = (hoek || 0) * Math.PI / 180;
    return '<line x1="'+x+'" y1="'+y+'" x2="'+(x + r * Math.cos(rad)).toFixed(1)+'" y2="'+(y + r * Math.sin(rad)).toFixed(1)+'" stroke="#e74c3c" stroke-width="1.5"/>';
  }

  function grainline(x, y1, y2) {
    return '<line x1="'+x+'" y1="'+y1+'" x2="'+x+'" y2="'+y2+'" stroke="#1a1a2e" stroke-width="0.7" marker-start="url(#arrow-s)" marker-end="url(#arrow-e)"/>';
  }

  var delen = [];
  var offsetX = 40;

  if (kledingstuk === 'broek' || kledingstuk === 'tracksuit') {
    // ── VOORPAND BROEK ──────────────────────────────────
    var pL  = (been + naad) * sc;
    var pHB = ((H / 2 + ease * 0.5) / 2 + naad) * sc;
    var pTB = ((T / 2 + ease * 0.3) / 2 + naad) * sc;
    var pKr = (H * 0.15) * sc;
    var pKn = ((B * 0.38 + ease * 0.2) / 2) * sc;

    var vpPath = 'M0,'+(pL+pKr)+
      ' L0,'+pKr+
      ' Q0,0 '+pTB.toFixed(1)+',0'+
      ' L'+pHB.toFixed(1)+','+(pKr*0.4).toFixed(1)+
      ' L'+pHB.toFixed(1)+','+(pL*0.65).toFixed(1)+
      ' L'+pKn.toFixed(1)+','+(pL+pKr)+
      ' Z';
    var vpNaad = 'M'+(-naad*sc)+','+(pL+pKr+naad*sc)+
      ' L'+(-naad*sc)+','+pKr+
      ' Q'+(-naad*sc)+','+(-naad*sc)+' '+(pTB+naad*sc).toFixed(1)+','+(-naad*sc)+
      ' L'+(pHB+naad*sc).toFixed(1)+','+(pKr*0.4).toFixed(1)+
      ' L'+(pHB+naad*sc).toFixed(1)+','+(pL*0.65).toFixed(1)+
      ' L'+(pKn+naad*sc).toFixed(1)+','+(pL+pKr+naad*sc)+
      ' Z';

    var vp = '<g transform="translate('+offsetX+',40)">' +
      '<path d="'+vpNaad+'" fill="rgba(198,125,6,0.06)" stroke="#c67d06" stroke-width="0.8" stroke-dasharray="5,3"/>' +
      '<path d="'+vpPath+'" fill="rgba(41,98,255,0.06)" stroke="#1a1a2e" stroke-width="2"/>' +
      lijn(0, pL+pKr+15, pHB, pL+pKr+15, '#666', 0.6) +
      tekst(pHB/2, pL+pKr+22, Math.round(H/4+ease/4)+'cm', true, '#666', 6.5) +
      lijn(pHB+15, 0, pHB+15, pL, '#666', 0.6) +
      tekst(pHB+20, pL/2, Math.round(been)+'cm', false, '#666', 6.5) +
      grainline(pHB/2, pL*0.15, pL*0.75) +
      tekst(pHB/2, -14, '1. Voorpand (2x knippen)', true, '#1a1a2e', 8.5) +
      tekst(pHB/2, -4, 'Draadrichting: vertikaal', true, '#555', 6) +
      inkeping(0, pKr, 90) +
      inkeping(pHB, pL*0.4, 0) +
      '</g>';
    delen.push({ svg: vp, breedte: pHB + 50, hoogte: pL + pKr + 40 });
    offsetX += pHB + 50;

    // ── RUGPAND BROEK ────────────────────────────────────
    var rpHB = pHB * 1.06;
    var rpKr = pKr * 1.22;
    var rpPath = 'M0,'+(pL+rpKr)+
      ' L0,'+rpKr+
      ' Q'+(rpHB*0.3).toFixed(1)+',0 '+rpHB.toFixed(1)+','+(rpKr*0.18).toFixed(1)+
      ' L'+rpHB.toFixed(1)+','+(pL*0.65).toFixed(1)+
      ' L'+(pKn*1.05).toFixed(1)+','+(pL+rpKr)+
      ' Z';
    var rpNaad = 'M'+(-naad*sc)+','+(pL+rpKr+naad*sc)+
      ' L'+(-naad*sc)+','+rpKr+
      ' Q'+(rpHB*0.3).toFixed(1)+','+(-naad*sc)+' '+(rpHB+naad*sc).toFixed(1)+','+(rpKr*0.18).toFixed(1)+
      ' L'+(rpHB+naad*sc).toFixed(1)+','+(pL*0.65).toFixed(1)+
      ' L'+(pKn*1.05+naad*sc).toFixed(1)+','+(pL+rpKr+naad*sc)+
      ' Z';

    var rp = '<g transform="translate('+offsetX+',40)">' +
      '<path d="'+rpNaad+'" fill="rgba(198,125,6,0.06)" stroke="#c67d06" stroke-width="0.8" stroke-dasharray="5,3"/>' +
      '<path d="'+rpPath+'" fill="rgba(41,98,255,0.04)" stroke="#1a1a2e" stroke-width="2"/>' +
      grainline(rpHB/2, pL*0.15, pL*0.75) +
      inkeping(0, rpKr, 90) +
      tekst(rpHB/2, -14, '2. Rugpand (2x knippen)', true, '#1a1a2e', 8.5) +
      tekst(rpHB/2, -4, 'Draadrichting: vertikaal', true, '#555', 6) +
      '</g>';
    delen.push({ svg: rp, breedte: rpHB + 50, hoogte: pL + rpKr + 40 });
    offsetX += rpHB + 50;

    // ── TAILLE BOORD ─────────────────────────────────────
    var tbB = ((H / 2 + ease * 0.5) + naad * 2) * sc;
    var tbH = 6 * sc;
    var tb = '<g transform="translate('+offsetX+',40)">' +
      '<rect x="'+(naad*sc)+'" y="0" width="'+tbB.toFixed(1)+'" height="'+tbH.toFixed(1)+'" fill="rgba(198,125,6,0.06)" stroke="#c67d06" stroke-width="0.8" stroke-dasharray="5,3"/>' +
      '<rect x="0" y="'+(naad*sc)+'" width="'+tbB.toFixed(1)+'" height="'+(tbH-naad*sc*2).toFixed(1)+'" fill="rgba(41,98,255,0.04)" stroke="#1a1a2e" stroke-width="2"/>' +
      lijn(0, tbH+12, tbB, tbH+12, '#666', 0.6) +
      tekst(tbB/2, tbH+20, Math.round(H/2+ease*0.5)+'cm', true, '#666', 6.5) +
      tekst(tbB/2, -10, '3. Taille boord (1x knippen)', true, '#1a1a2e', 8.5) +
      '</g>';
    delen.push({ svg: tb, breedte: tbB + 50, hoogte: tbH + 50 });
    offsetX += tbB + 50;

  } else if (kledingstuk === 'hoodie' || kledingstuk === 'shirt' || kledingstuk === 'blouse' || kledingstuk === 'jasje' || kledingstuk === 'badmode') {
    // Gebruik de bestaande eigen generator voor bovenlichaam
    var basisSvg = DY.berekenPatroon(kledingstuk, { lengte:L, borst:B, taille:T, heup:H, been:been, pasvorm:pasvorm, mouw:'Lang' });
    // Geef de basis SVG terug ingepakt
    return basisSvg;
  }

  // ── SVG SAMENSTELLEN ─────────────────────────────────
  var maxH = Math.max(...delen.map(d => d.hoogte));
  var totalW = offsetX + 20;
  var totalH = maxH + 160;

  var svgInhoud = delen.map(d => d.svg).join('');

  return '<?xml version="1.0" encoding="UTF-8"?>' +
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+totalW+' '+totalH+'" style="background:#ffffff">' +
    '<defs>' +
    '<marker id="arrow-s" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto"><path d="M6,0 L0,3 L6,6" fill="none" stroke="#1a1a2e" stroke-width="0.8"/></marker>' +
    '<marker id="arrow-e" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="none" stroke="#1a1a2e" stroke-width="0.8"/></marker>' +
    '<pattern id="fijngrid" width="17.5" height="17.5" patternUnits="userSpaceOnUse"><path d="M 17.5 0 L 0 0 0 17.5" fill="none" stroke="#f0f0f0" stroke-width="0.4"/></pattern>' +
    '</defs>' +
    // Achtergrond
    '<rect width="'+totalW+'" height="'+totalH+'" fill="#ffffff"/>' +
    '<rect width="'+totalW+'" height="'+totalH+'" fill="url(#fijngrid)"/>' +
    // Header
    '<rect x="0" y="0" width="'+totalW+'" height="85" fill="#1a1a2e"/>' +
    '<text x="'+(totalW/2)+'" y="28" font-family="Georgia,serif" font-size="18" fill="#fcf8ef" text-anchor="middle" letter-spacing="4">DOUBLEYOU \u2014 ATELIER PATROON</text>' +
    '<line x1="30" y1="36" x2="'+(totalW-30)+'" y2="36" stroke="#c67d06" stroke-width="0.6"/>' +
    '<text x="'+(totalW/2)+'" y="52" font-family="Arial,sans-serif" font-size="8" fill="#c67d06" text-anchor="middle" letter-spacing="2">TAILORED FOR TALL &amp; PLUS SIZE</text>' +
    '<text x="'+(totalW/2)+'" y="66" font-family="Arial,sans-serif" font-size="7" fill="rgba(252,248,239,0.65)" text-anchor="middle">'+
    (kledingstuk.charAt(0).toUpperCase()+kledingstuk.slice(1))+' \u00b7 Lengte '+L+'cm \u00b7 Borst '+B+'cm \u00b7 Taille '+T+'cm \u00b7 Heup '+H+'cm \u00b7 Pasvorm: '+(pasvorm||'Regular')+
    '</text>' +
    '<text x="'+(totalW/2)+'" y="78" font-family="Arial,sans-serif" font-size="6" fill="rgba(252,248,239,0.35)" text-anchor="middle">Naadtoeslag 1cm inbegrepen \u00b7 Intern document \u00b7 ADMIN ONLY</text>' +
    // Legenda
    '<g transform="translate(20,'+(maxH+100)+'">' +
    '<text x="0" y="0" font-family="Arial,sans-serif" font-size="7" fill="#1a1a2e" font-weight="bold">Legenda:</text>' +
    '<line x1="0" y1="12" x2="30" y2="12" stroke="#1a1a2e" stroke-width="2"/><text x="35" y="16" font-family="Arial,sans-serif" font-size="6.5" fill="#555">Stofpatroon</text>' +
    '<line x1="120" y1="12" x2="150" y2="12" stroke="#c67d06" stroke-width="0.8" stroke-dasharray="5,3"/><text x="155" y="16" font-family="Arial,sans-serif" font-size="6.5" fill="#555">Naadtoeslag 1cm</text>' +
    '<line x1="280" y1="12" x2="310" y2="12" stroke="#e74c3c" stroke-width="1.5"/><text x="315" y="16" font-family="Arial,sans-serif" font-size="6.5" fill="#555">Inkeping</text>' +
    '<line x1="0" y1="28" x2="30" y2="28" stroke="#1a1a2e" stroke-width="0.7" marker-end="url(#arrow-e)"/><text x="35" y="32" font-family="Arial,sans-serif" font-size="6.5" fill="#555">Draadrichting</text>' +
    '</g>' +
    // Border
    '<rect x="8" y="92" width="'+(totalW-16)+'" height="'+(maxH+55)+'" fill="none" stroke="rgba(198,125,6,0.3)" stroke-width="0.8"/>' +
    // Content
    '<g transform="translate(0,92)">' + svgInhoud + '</g>' +
    // Voetnoot
    '<line x1="0" y1="'+(totalH-18)+'" x2="'+totalW+'" y2="'+(totalH-18)+'" stroke="#eee" stroke-width="0.5"/>' +
    '<text x="15" y="'+(totalH-6)+'" font-family="Arial,sans-serif" font-size="6" fill="#aaa">Schaal 1:3.5 \u00b7 Afdrukken op A0 of breed formaat \u00b7 Alleen voor intern ateliergebruik</text>' +
    '<text x="'+(totalW-15)+'" y="'+(totalH-6)+'" font-family="Arial,sans-serif" font-size="6" fill="#c67d06" text-anchor="end">paskamer-praat.pages.dev</text>' +
    '</svg>';
};

DY.cfgGetMaten = function(maatSleutel) {
  return DY.FS_MAATTABEL[maatSleutel] || DY.FS_MAATTABEL['2XL-190'];
};


DY.cfgLaadCommunity = async function() {
  const s = DY.cfgState.selecties;
  const el = document.getElementById('dy-cfg-community-grid');
  if (!el) return;

  el.innerHTML = '<div class="dy-loader"><div class="dy-spinner"></div></div>';

  try {
    // Haal lookbook op en filter op lengte type + maat
    const snap = await DY.db.collection('lookbook').limit(100).get();
    const looks = [];
    snap.forEach(function(doc) {
      const d = doc.data();
      if (!d.foto && !d.video) return;

      // Match op lengte type
      const lengte = d.lengte || 0;
      const maatMatch = !s.pasvorm || s.pasvorm === 'Regular' ||
        (s.pasvorm === 'Plus Size' && d.maat && ['2XL','3XL','4XL','5XL'].includes(d.maat)) ||
        (s.pasvorm === 'Slim' && d.maat && ['XS','S','M'].includes(d.maat)) ||
        true; // Altijd tonen als geen specifieke filter

      const lengteMatch =
        (s.lengte === 'Tall' && lengte >= 185) ||
        (s.lengte === 'Short' && lengte < 170 && lengte > 0) ||
        (s.lengte === 'Regular' && lengte >= 170 && lengte < 185) ||
        (s.lengte === '7/8' && lengte < 170 && lengte > 0) ||
        (s.lengte === 'Lang' && lengte >= 183) ||
        lengte === 0; // Geen lengte → altijd tonen

      if (lengteMatch || maatMatch) {
        looks.push({ _id: doc.id, ...d });
      }
    });

    if (looks.length === 0) {
      el.innerHTML =
        '<div class="dy-cfg-community-leeg">' +
        '<p>Nog geen community leden met deze maten.</p>' +
        '<p style="font-size:12px;margin-top:4px">Wees de eerste, plaats een fitcheck!</p>' +
        '<button class="dy-btn dy-btn-ghost" onclick="DY.navigeer(\'lookbook_nieuw\')" style="margin-top:10px;font-size:12px">Fitcheck plaatsen</button>' +
        '</div>';
      return;
    }

    // Sorteer: met lengte info eerst
    looks.sort(function(a,b) { return (b.lengte||0) - (a.lengte||0); });

    el.innerHTML = looks.slice(0,12).map(function(d) {
      const _dspFitOk = DY.fitLabelZichtbaar ? DY.fitLabelZichtbaar(d.userId || d.uid || '') : (d.fitPrivacy !== 'privé');
      const lengte = (_dspFitOk && d.lengte) ? d.lengte + ' cm' : '';
      const maat = (_dspFitOk && d.maat) ? d.maat : '';
      const naam = d.authorName || 'Community lid';
      const media = d.video
        ? '<video src="' + d.video + '" class="dy-cfg-community-foto" muted playsinline preload="metadata"></video>'
        : '<img src="' + d.foto + '" class="dy-cfg-community-foto" loading="lazy" decoding="async" alt="' + naam + '">';

      return '<div class="dy-cfg-community-kaart" onclick="DY.openLookDetail(\'' + d._id + '\')">' +
        '<div class="dy-cfg-community-foto-wrap">' +
        media +
        '<div class="dy-cfg-community-info">' +
        '<span class="dy-cfg-community-naam">' + naam + '</span>' +
        (lengte || maat ? '<span class="dy-cfg-community-maten">' + [lengte, maat].filter(Boolean).join(' \u00b7 ') + '</span>' : '') +
        '</div>' +
        '</div>' +
        '</div>';
    }).join('');

  } catch(e) {
    el.innerHTML = '<div class="dy-cfg-community-leeg"><p>Kon community looks niet laden.</p></div>';
  }
};


