DY.cfgMaatSleutel = function(maat, lengte) {
  // Vind de dichtstbijzijnde lengte in de tabel (185, 190, 195, 200)
  var stappen = [185, 190, 195, 200];
  var lengteGetal = parseInt(lengte) || 190;
  var dichtstbij = stappen.reduce(function(a, b) {
    return Math.abs(b - lengteGetal) < Math.abs(a - lengteGetal) ? b : a;
  });
  return maat + '-' + dichtstbij;
};

