DY.cfgSlaInlineMatenOp = function() {
  var velden = ['lengte','borst','taille','heup','been'];
  var updates = {};
  var geldig = true;

  velden.forEach(function(k) {
    var el = document.getElementById('cfg-' + k);
    if (!el) return;
    var val = parseFloat(el.value);
    if (val > 0) {
      updates[k] = val;
      el.style.borderColor = '';
    } else if (el.value !== '') {
      el.style.borderColor = 'var(--clay)';
      geldig = false;
    }
  });

  if (!geldig) return;

  // Update lokaal profiel
  if (DY.profile) {
    Object.assign(DY.profile, updates);
  } else {
    if (updates && updates.bouw) updates.bouw = DY._normBouw(updates.bouw);
    DY.profile = updates;
  }

  // Sla op in Firebase als ingelogd
  if (DY.user && DY.db && Object.keys(updates).length > 0) {
    DY.db.collection('users').doc(DY.user.uid).update(updates)
      .catch(function(e) { });
  }
};


DY.cfgStuurAI = async function() {
  const input = document.getElementById('dy-cfg-ai-input');
  if (!input) return;
  const vraag = input.value.trim();
  if (!vraag) return;
  input.value = '';

  DY.cfgAIBericht('gebruiker', vraag);
  DY.cfgAITyping(true);

  // Bouw context op basis van huidige configuratie
  const s = DY.cfgState.selecties;
  const k = DY.cfgState.kledingstuk;
  const kleurNaam = (DY.CFG_KLEUREN.find(function(c){return c.hex===DY.cfgState.kleur;})||{naam:DY.cfgState.kleur}).naam;
  const profiel = DY.profile || {};

  const systeemPrompt = `Je bent de stijlassistent van DoubleYou, een Nederlands fashion merk voor tall (1.85m+) en plus size (XL-5XL) klanten. 
Je helpt klanten bij het configureren van hun perfecte kledingstuk.

Huidige configuratie:
- Kledingstuk: ${k}
- Pasvorm: ${s.pasvorm}
- Lengte: ${s.lengte}
- Mouw: ${s.mouw}
- Kraag/hals: ${s.kraag}
- Kleur: ${kleurNaam}
- Details: ${s.details.length ? s.details.join(', ') : 'geen'}
${profiel.lengte ? '- Klantlengte: ' + profiel.lengte + ' cm' : ''}
${profiel.maat ? '- Klantvoorkeursgrootte: ' + profiel.maat : ''}

Geef praktisch, persoonlijk advies in het Nederlands. Maximaal 3 zinnen. Doe concrete suggesties voor aanpassingen in de configurator als dat relevant is. Schrijf altijd in commas, nooit em-dashes.`;

  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 300,
        system: systeemPrompt,
        messages: [{ role: 'user', content: vraag }]
      })
    });

    const data = await res.json();
    DY.cfgAITyping(false);

    if (data.content && data.content[0] && data.content[0].text) {
      const antwoord = data.content[0].text;
      DY.cfgAIBericht('assistent', antwoord);

      // Detecteer of AI een configuratie aanpassing suggereert
      DY.cfgAIPasAan(antwoord);
    } else {
      DY.cfgAIBericht('assistent', 'Even geen verbinding. Probeer het opnieuw.');
    }
  } catch(e) {
    DY.cfgAITyping(false);
    DY.cfgAIBericht('assistent', 'Even geen verbinding. Probeer het opnieuw.');
  }
};

DY.cfgVraagAI = function() {
  const sectie = document.getElementById('dy-cfg-ai-sectie');
  if (!sectie) return;
  sectie.style.display = 'block';
  sectie.scrollIntoView({ behavior: 'smooth', block: 'start' });

  // Stel automatisch een openingsvraag als chat leeg is
  const chat = document.getElementById('dy-cfg-ai-chat');
  if (chat && chat.children.length === 0) {
    const s = DY.cfgState.selecties;
    const k = DY.cfgState.kledingstuk;
    const kleurNaam = (DY.CFG_KLEUREN.find(function(c){return c.hex===DY.cfgState.kleur;})||{naam:DY.cfgState.kleur}).naam;
    const context = 'Ik configureer een ' + k + ' in ' + kleurNaam + ', ' + s.pasvorm + ' pasvorm, ' + s.lengte + ' lengte.';
    DY.cfgAIBericht('assistent', 'Hoi! Ik help je het perfecte DoubleYou ontwerp samen te stellen. ' + context + ' Wat voor gelegenheid is het, of wil je dat ik suggesties doe op basis van jouw maten?');
  }
};

DY.laadBerichten = async function(gesprekId) {
  const chat = document.getElementById('dy-bericht-chat');
  if (!chat) return;
  try {
    const snap = await DY.db.collection('berichten').doc(gesprekId)
      .collection('messages').orderBy('ts', 'asc').limit(100).get();
    DY.renderBerichtenUitSnap(snap, gesprekId);
  } catch(e) {
    try {
      const snap2 = await DY.db.collection('berichten').doc(gesprekId)
        .collection('messages').limit(100).get();
      const msgs = [];
      snap2.forEach(function(doc) { msgs.push({ _snap: doc, ...doc.data() }); });
      msgs.sort(function(a,b) { return ((a.ts && a.ts.seconds)||0) - ((b.ts && b.ts.seconds)||0); });
      // Zet terug als snapshot-achtig object
      DY.renderBerichtenUitSnap({ empty: msgs.length===0, forEach: function(cb) { msgs.forEach(function(m){ cb({id:m._id||'', data:function(){return m;}, ref:{update:function(){return Promise.resolve();}}}); }); } }, gesprekId);
    } catch(e2) {
      const chat2 = document.getElementById('dy-bericht-chat');
      if (chat2) chat2.innerHTML = '<div style="text-align:center;padding:40px;color:var(--ink-muted);font-size:13px">Berichten konden niet worden geladen.</div>';
    }
  }
};

DY.openGesprek = function(gesprekId, andereUid, anderNaam) {
  DY.huidigGesprek = { id: gesprekId, andereUid, anderNaam };
  DY.navigeer('bericht_detail');
};

DY.pkBepaalLichaamstype = function(borst,taille,heup,gender) {
  var tbl=DY_MATEN_TBL[gender]||DY_MATEN_TBL.heren;
  var gevonden='5XL';
  var keys=Object.keys(tbl);
  for (var mi=0;mi<keys.length;mi++) {
    var r=tbl[keys[mi]];
    if (borst>=r.borst[0]&&borst<=r.borst[1]){gevonden=keys[mi];break;}
    if (borst<r.borst[0]&&mi===0){gevonden=keys[0];break;}
  }
  var bh=borst/heup;
  var plussize=['2XL','3XL','4XL','5XL'].indexOf(gevonden)>-1;
  if (plussize) {
    if (bh<0.93) return {naam:'Plus Size, voller heup',sub:'Maat '+gevonden,tekst:'Heupen voller dan borst. Selecteer broeken op heupomtrek.',tips:['Broeken op heupomtrek','Bovenkleding op borst','DoubleYou '+gevonden+' proportioneel gepatroneerd']};
    if (bh>1.07) return {naam:'Plus Size, voller borst',sub:'Maat '+gevonden,tekst:'Borst breder dan heup. Kies op borstmaat.',tips:['Altijd op borstomtrek','Broeken op taille/heup','Tot 5XL, niet opgeschaald']};
    return {naam:'Plus Size',sub:'Maat '+gevonden,tekst:'Proporties in balans. DoubleYou tot 5XL, proportioneel gepatroneerd.',tips:['Borst als primaire maat','Let op taillewijdte','Getest op proportie']};
  }
  var bhDiff=Math.abs(borst-heup)/((borst+heup)/2);
  var bt=(borst-taille)/taille, ht=(heup-taille)/taille;
  if (bh>(gender==='heren'?1.05:1.06)) return {naam:'Omgekeerde driehoek',sub:'Breed bovenlichaam',tekst:'Bovenlichaam breder dan heupen. DoubleYou snit voor dit silhouet ontworpen.',tips:['Broeken op taillemaat','Rechte snit shirts','Vermijd raglan mouwen']};
  if (bh<(gender==='heren'?0.94:0.93)) return {naam:'Peer',sub:'Vollere heup',tekst:'Heupen breder dan schouders. Selecteer broeken op heupomtrek.',tips:['Broeken op heupomtrek','Shirts met bredere schouder','Regular snit beste match']};
  if (bhDiff<0.04&&bt>(gender==='heren'?0.22:0.18)&&ht>(gender==='heren'?0.20:0.16)) return {naam:'Zandloper',sub:'Uitgesproken taille',tekst:'Borst en heup in balans, smal middel. Bijna elke snit past goed.',tips:['Let op taillebreedte shirts','Slim-fit is flatterend','Bij hoodies taillebreedte checken']};
  if (taille>=borst*0.92&&taille>=heup*0.90) return {naam:'Ovaal',sub:'Voller torso',tekst:'Taille relatief breed. Kwalitatieve patroonvoering geeft beste pasvorm.',tips:['Borst als eerste maat','Let op taillewijdte','Regular met ruimere taille']};
  return {naam:'Rechthoek',sub:'Gelijkmatige proporties',tekst:'Borst, taille en heup gelijkmatig. Vrijwel elke DoubleYou snit past goed.',tips:['Regular snit beste match','Slim-fit voor meer definitie','Vermijd te wijde snits']};
};


// ── RENDER SERVER KEEP-ALIVE ─────────────────────────────────────────
// Ping de patroon server elke 10 minuten zodat hij niet in slaap valt
(function() {
  var PING_URL = 'https://doubleyou-patroon-server.onrender.com/';
  var INTERVAL = 10 * 60 * 1000; // 10 minuten

  function ping() {
    fetch(PING_URL, { method: 'GET', mode: 'no-cors' })
      .catch(function() {}); // stil falen
  }

  // Eerste ping na 30 seconden (pagina is dan geladen)
  setTimeout(ping, 30000);

  // Daarna elke 10 minuten - gecaptured voor cleanup
  DY._pingInterval = setInterval(ping, INTERVAL);
})();

DY.pkBerekenMaat = function() {
  var lengte  = parseFloat(document.getElementById('pk-lengte').value);
  var borst   = parseFloat(document.getElementById('pk-borst').value);
  var taille  = parseFloat(document.getElementById('pk-taille').value);
  var heup    = parseFloat(document.getElementById('pk-heup').value);
  var been    = parseFloat(document.getElementById('pk-been').value);
  var gewicht = parseFloat(document.getElementById('pk-gewicht').value) || 0;
  var err     = document.getElementById('pk-form-err');

  if (!lengte || !borst || !taille || !heup || !been) {
    err.textContent = 'Vul lengte, borst, taille, heup en beenlengte in.';
    err.style.display = 'block';
    return;
  }
  err.style.display = 'none';
  Object.assign(DY.pkState, {lengte,borst,taille,heup,been,gewicht});

  if (DY.user && DY.db) {
    DY.db.collection('users').doc(DY.user.uid).update({lengte,borst,taille,heup,been,gewicht}).catch(function(){});
    if (DY.profile) Object.assign(DY.profile, {lengte,borst,taille,heup,been,gewicht});
  }

  document.querySelectorAll('.dy-pk-panel').forEach(function(p) { p.classList.remove('actief'); });
  document.getElementById('pk-panel-loading').classList.add('actief');

  var msgs = ['Maten worden geanalyseerd...','Verhoudingen berekenen...','Beste pasvorm bepalen...','Aanbeveling klaar maken...'];
  var mi = 0;
  if (window._pkLoadingTimer) clearInterval(window._pkLoadingTimer);
  var lt = setInterval(function() {
    mi = (mi+1) % msgs.length;
    var el = document.getElementById('pk-loading-tekst');
    if (el) el.textContent = msgs[mi];
  }, 800);
  window._pkLoadingTimer = lt;

  setTimeout(function() { clearInterval(lt); DY.pkToonResultaat(); }, 2200);
};

