DY.pkNaarStap = function(stap) {
  DY.pkState.stap = stap;
  [1,2,3].forEach(function(n) {
    var el = document.getElementById('pk-stap-' + n);
    if (!el) return;
    el.classList.remove('active','done');
    if (n < stap) el.classList.add('actief');
    if (n === stap) el.classList.add('actief');
  });
  [1,2].forEach(function(n) {
    var lijn = document.getElementById('pk-lijn-' + n);
    if (lijn) lijn.classList.toggle('actief', n < stap);
  });
  document.querySelectorAll('.dy-pk-panel').forEach(function(p) { p.classList.remove('actief'); });
  var panel = document.getElementById('pk-panel-' + stap);
  if (panel) panel.classList.add('actief');
  document.querySelector('.dy-pk-wrap') && document.querySelector('.dy-pk-wrap').scrollIntoView({behavior:'smooth',block:'start'});
};

DY.pkSelectGender = function(gender) {
  DY.pkState.gender = gender;
  ['heren','dames','unisex'].forEach(function(g) {
    var el = document.getElementById('pk-gender-' + g);
    if (el) el.classList.toggle('geselecteerd', g === gender);
  });
  var btn = document.getElementById('pk-btn-stap2');
  if (btn) btn.disabled = false;
};

DY.pkToonResultaat = function() {
  var lengte = DY.pkState.lengte, borst = DY.pkState.borst;
  var taille = DY.pkState.taille, heup = DY.pkState.heup, been = DY.pkState.been;
  var g = DY.pkState.gender || 'heren';
  var maten = DY_MATEN_TBL[g];
  var ltypes = DY_LENGTE_TBL[g];

  var gevondenMaat = '2XL', matchScore = 999;
  Object.keys(maten).forEach(function(key) {
    var m = maten[key];
    var mid = (m.borst[0]+m.borst[1])/2;
    var score = Math.abs(borst-mid);
    if (score < matchScore) { gevondenMaat = key; matchScore = score; }
  });
  DY.pkState.maat = gevondenMaat;

  var ltype = ltypes[ltypes.length-1];
  for (var i=0; i<ltypes.length; i++) { if (lengte <= ltypes[i].max) { ltype = ltypes[i]; break; } }
  DY.pkState.maatType = ltype;

  var volleMaat = gevondenMaat + (ltype.type !== 'Regular' ? ' '+ltype.type : '');
  var m = maten[gevondenMaat];

  function fitPct(val,lo,hi) {
    var mid=(lo+hi)/2;
    return Math.max(60, Math.min(100, Math.round(100-(Math.abs(val-mid)/((hi-lo)/2))*35)));
  }

  var fitBars = [
    {label:'Borstomtrek', pct:fitPct(borst,m.borst[0],m.borst[1])},
    {label:'Taillomtrek', pct:fitPct(taille,m.taille[0],m.taille[1])},
    {label:'Heupomtrek',  pct:fitPct(heup,m.heup[0],m.heup[1])},
    {label:'Beenlengte',  pct:(ltype.type==='Tall'&&been>=86)||(ltype.type==='Regular'&&been>=76&&been<=92)||(ltype.type==='Small'&&been<=82)?94:72}
  ];

  var adviezen = [];
  if (ltype.type==='Tall') adviezen.push({goed:true,tekst:'De Tall snit geeft de extra lengte die standaard merken niet bieden.'});
  else if (ltype.type==='Small') adviezen.push({goed:true,tekst:'De Small snit zorgt dat alles in proportie blijft zonder inkorten.'});
  else adviezen.push({goed:true,tekst:'Je valt in de Regular snit, ontworpen voor verhoudingen zoals die van jou.'});
  var borstMid=(m.borst[0]+m.borst[1])/2;
  if (borst>borstMid+3) adviezen.push({goed:false,tekst:'Je borst zit aan de bovenkant van de range. Overweeg een maat groter.'});
  else if (Math.abs(borst-borstMid)<=3) adviezen.push({goed:true,tekst:'Je borstomtrek valt precies in het midden. Uitstekende pasvorm verwacht.'});
  if (['3XL','4XL','5XL'].indexOf(gevondenMaat)>-1) adviezen.push({goed:true,tekst:'DoubleYou gaat tot 5XL, gepatroneerd op echte lichaamsmaten.'});
  adviezen.push({goed:true,tekst:'DoubleYou kleding is getest op krimpvastheid.'});

  var profiel = DY.pkBepaalLichaamstype(borst,taille,heup,g);

  var panel3 = document.getElementById('pk-panel-3');
  panel3.innerHTML =
    '<div class="dy-pk-resultaat-hero">' +
    '<div class="dy-pk-maat-badge">' + volleMaat + '</div>' +
    '<p class="dy-pk-maat-uitleg">' + ltype.desc + '   aanbevolen op basis van jouw maten.</p>' +
    '</div>' +
    '<div class="dy-form-wrap" style="padding-top:16px">' +

    '<div class="dy-pk-sectie-titel">Pasvorm per maatveld</div>' +
    '<div class="dy-pk-fit-bars" style="margin-bottom:16px">' +
    fitBars.map(function(bar) {
      var cls=bar.pct>=90?'goed':bar.pct>=75?'ok':'check';
      var status=bar.pct>=90?'Uitstekend':bar.pct>=75?'Goed':'Controleer';
      return '<div class="dy-pk-fit-rij"><div class="dy-pk-fit-label"><span>'+bar.label+'</span><span class="dy-pk-fit-status '+cls+'">'+status+'</span></div><div class="dy-pk-fit-track"><div class="dy-pk-fit-fill '+cls+'" data-pct="'+bar.pct+'" style="width:0%"></div></div></div>';
    }).join('') +
    '</div>' +

    '<div class="dy-pk-sectie-titel">Lichaamstype</div>' +
    '<div class="dy-pk-profiel-blok" style="margin-bottom:16px">' +
    '<div class="dy-pk-profiel-naam">'+profiel.naam+'</div>' +
    '<div class="dy-pk-profiel-sub">'+profiel.sub+'</div>' +
    '<p class="dy-pk-profiel-tekst">'+profiel.tekst+'</p>' +
    '<div class="dy-pk-profiel-tips">'+profiel.tips.map(function(t){return '<div class="dy-pk-tip">&rarr; '+t+'</div>';}).join('')+'</div>' +
    '</div>' +

    '<div class="dy-pk-sectie-titel">Persoonlijk advies</div>' +
    '<div class="dy-pk-advies-blok" style="margin-bottom:16px">' +
    adviezen.map(function(a) {
      return '<div class="dy-pk-advies-item"><div class="dy-pk-advies-dot '+(a.goed?'goed':'warn')+'"></div><span>'+a.tekst+'</span></div>';
    }).join('') +
    '</div>' +

    '<div class="dy-pk-sectie-titel">Jouw maten</div>' +
    '<div class="dy-pk-maten-samenvatting" style="margin-bottom:20px">' +
    [['Lengte',lengte,'cm'],['Borst',borst,'cm'],['Taille',taille,'cm'],['Heup',heup,'cm'],['Been',been,'cm']].map(function(v) {
      return '<div class="dy-pk-maat-item"><span class="dy-pk-maat-val">'+v[1]+'</span><span class="dy-pk-maat-lbl">'+v[0]+' <small>'+v[2]+'</small></span></div>';
    }).join('') +
    '</div>' +

    '<div style="display:flex;gap:10px">' +
    '<button class="dy-btn dy-btn-ghost" onclick="DY.pkNaarStap(1)" style="flex:1">Opnieuw</button>' +
    '<button class="dy-btn dy-btn-primary" onclick="DY.navigeer(\'winkel\')" style="flex:2">Naar de winkel &rarr;</button>' +
    '</div></div>';

  DY.pkNaarStap(3);
  setTimeout(function() {
    document.querySelectorAll('.dy-pk-fit-fill').forEach(function(el) { el.style.width = el.dataset.pct+'%'; });
  }, 150);

  if (DY.db) {
    DY.db.collection('maatadviezen').add({gender:g,maat:gevondenMaat,snit:ltype.type,lengte:lengte,borst:borst,taille:taille,heup:heup,been:been,userId:DY.user?DY.user.uid:null,ts:firebase.firestore.FieldValue.serverTimestamp()}).catch(function(){});
  }
};

DY.renderBerichtDetail = async function() {
  if (!DY.user || !DY.huidigGesprek) { DY.navigeer('berichten'); return; }
  const { id: gesprekId, anderNaam: _anderNaam, andereUid } = DY.huidigGesprek;
  var anderNaam = _anderNaam || 'Onbekend';
  const main = document.getElementById('dy-main');
  if (!main) return;

  const initials4 = anderNaam.slice(0, 2).toUpperCase();
  main.innerHTML =
    '<div class="dy-chat-header">' +
      '<button class="dy-chat-terug" onclick="DY.terug()" aria-label="Terug">' +
        '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M15 18l-6-6 6-6"/></svg>' +
      '</button>' +
      '<div class="dy-chat-header-info">' +
        '<div class="dy-chat-header-avatar">' + initials4 + '</div>' +
        '<div class="dy-chat-header-naam">' + DY.escapeHtml(anderNaam || 'Onbekend') + '</div>' +
      '</div>' +
      '<div style="width:40px"></div>' +
    '</div>' +
    '<div id="dy-bericht-chat" class="dy-chat-berichten">' +
      '<div class="dy-loader" style="padding:40px 0"><div class="dy-spinner"></div></div>' +
    '</div>' +
    '<div class="dy-chat-input-balk">' +
      '<input type="file" id="bericht-media-input" accept="image/*,video/*" style="display:none" onchange="DY.verstuurMedia(this)">' +
      '<button class="dy-chat-media-btn" onclick="document.getElementById(\x27bericht-media-input\x27).click()" aria-label="Media toevoegen">' +
        '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/></svg>' +
      '</button>' +
      '<textarea class="dy-chat-input" id="bericht-input" placeholder="Schrijf een bericht..." rows="1" ' +
        'onkeydown="if(event.key===\x27Enter\x27&&!event.shiftKey){event.preventDefault();DY.verstuurBericht()}" ' +
        'oninput="this.style.height=\x27auto\x27;this.style.height=Math.min(this.scrollHeight,120)+\x27px\x27"></textarea>' +
      '<button class="dy-chat-send-btn" onclick="DY.verstuurBericht()" aria-label="Versturen">' +
        '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>' +
      '</button>' +
    '</div>';

  await DY.laadBerichten(gesprekId);

  // Realtime listener voor nieuwe berichten
  try {
    if (DY._berichtListener) DY._berichtListener();
    DY._berichtListener = DY.db.collection('berichten').doc(gesprekId)
      .collection('messages').orderBy('ts', 'asc').limit(100)
      .onSnapshot(function(snap) {
        DY.renderBerichtenUitSnap(snap, gesprekId);
      });
  } catch(e) {}

  // Markeer als gelezen
  try {
    const update = {};
    update['ongelezen.' + DY.user.uid] = 0;
    await DY.db.collection('berichten').doc(gesprekId).set(update, { merge: true });
  } catch(e) {}
};

DY.renderBerichten = async function() {
  // Cleanup actieve chat-listener bij terugkeer naar berichtenlijst
  if (DY._berichtListener) {
    try { DY._berichtListener(); } catch(e) {}
    DY._berichtListener = null;
  }
  if (!DY.user) {
    var _vPag = (DY._history && DY._history.length > 0) ? DY._history[DY._history.length-1] : 'feed';
    var _vR = {feed:DY.renderFeed,home:DY.renderHome,lookbook:DY.renderLookbook,vrienden:DY.renderVrienden,winkel:DY.renderWinkel};
    DY.pagina = null;
    if (_vR[_vPag]) { DY.pagina = _vPag; _vR[_vPag](); } else { DY.pagina = 'feed'; DY.renderFeed(); }
    DY.toonLoginPrompt('Inloggen om berichten te sturen.');
    return;
  }
  const main = document.getElementById('dy-main');
  if (!main) return;
  main.style.background = '#0a0806';
  main.innerHTML = `
    <div class="dy-vr-header">
      <div class="dy-vr-header-inner">
        <div>
          <div class="dy-feed-merk-label">Paskamerpraat</div>
          <h1 class="dy-vr-titel">Mijn <em>berichten</em></h1>
          <p class="dy-kai-sub" style="color:rgba(252,248,239,0.55);font-size:var(--t-sm);margin:2px 0 0">Gesprekken die ertoe doen.</p>
        </div>
        <button class="dy-pg-actie-btn" onclick="DY.navigeer('feed')">← Terug</button>
      </div>
    </div>
    <div class="dy-berichten-wrap">
      <div id="dy-berichten-lijst" class="dy-berichten-lijst">
        <div class="dy-loader"><div class="dy-spinner"></div></div>
      </div>
    </div>`;

  try {
    const snap = await DY.db.collection('berichten')
      .where('deelnemers', 'array-contains', DY.user.uid)
      .limit(20).get();

    const lijst = document.getElementById('dy-berichten-lijst');
    if (!lijst) return;

    if (snap.empty) {
      lijst.innerHTML = `
        <div class="dy-leeg" style="padding:40px 24px;text-align:center">
          <p style="margin-bottom:12px">Nog geen berichten.</p>
          <p style="font-size:13px;color:var(--ink-muted)">Klik op een profiel in de feed om een bericht te sturen.</p>
        </div>`;
      return;
    }

    const gesprekken = [];
    snap.forEach(doc => gesprekken.push({ _id: doc.id, ...doc.data() }));
    gesprekken.sort((a, b) => {
      const ta = a.laatste_ts && a.laatste_ts.toDate ? a.laatste_ts.toDate() : new Date(0);
      const tb = b.laatste_ts && b.laatste_ts.toDate ? b.laatste_ts.toDate() : new Date(0);
      return tb - ta;
    });

    // Haal namen op uit users collectie voor alle gesprekspartners
    const partnerIds = gesprekken.map(g => {
      const deelnemers = g.deelnemers || [];
      return deelnemers.find(u => u !== DY.user.uid);
    }).filter(Boolean);

    const namenMap = {};
    await Promise.allSettled(partnerIds.map(async uid => {
      try {
        const userDoc = await DY.db.collection('users').doc(uid).get();
        if (userDoc.exists) {
          const d = userDoc.data();
          namenMap[uid] = d.displayName || d.naam || null;
        }
      } catch(e) {}
    }));

    lijst.innerHTML = gesprekken.map(g => {
      const andereUid = (g.deelnemers || []).find(u => u !== DY.user.uid);
      const anderNaam = namenMap[andereUid] || (g.namen && g.namen[andereUid]) || 'Onbekend';
      const initials = anderNaam.slice(0, 2).toUpperCase();
      const ongelezen = (g.ongelezen && g.ongelezen[DY.user.uid]) || 0;
      const laatsTs = g.laatste_ts && g.laatste_ts.toDate ? g.laatste_ts.toDate() : null;
      const tijdLabel = laatsTs ? laatsTs.toLocaleTimeString('nl-NL', {hour:'2-digit',minute:'2-digit'}) : '';
      const preview = (g.laatste_bericht || '').substring(0, 45);
      const ongeleden = ongelezen > 0;
      return '<div class="dy-bericht-rij' + (ongeleden ? ' ongelezen' : '') + '" data-gid="' + g._id + '" data-uid="' + (andereUid || '') + '" data-naam="' + DY.escapeHtml(anderNaam || '').replace(/"/g, '&quot;') + '" style="cursor:pointer">' +
        '<div class="dy-conv-avatar">' + initials + '</div>' +
        '<div class="dy-conv-info">' +
          '<div class="dy-conv-top">' +
            '<span class="dy-conv-naam' + (ongeleden ? ' dy-conv-naam--bold' : '') + '">' + DY.escapeHtml(anderNaam || 'Onbekend') + '</span>' +
            '<span class="dy-conv-tijd">' + tijdLabel + '</span>' +
          '</div>' +
          '<div class="dy-conv-preview' + (ongeleden ? ' dy-conv-preview--ongelezen' : '') + '">' +
            (preview || '<em style="color:var(--ink-muted)">Geen berichten</em>') +
          '</div>' +
        '</div>' +
        (ongeleden ? '<div class="dy-conv-dot"></div>' : '') +
      '</div>';
    }).join('');

    // Event delegation voor gesprek klikken (veiliger dan inline onclick)
    if (lijst) {
      lijst.addEventListener('click', function(e) {
        var rij = e.target.closest('.dy-bericht-rij');
        if (!rij) return;
        var gid = rij.getAttribute('data-gid');
        var uid = rij.getAttribute('data-uid');
        var naam = rij.getAttribute('data-naam') || 'Onbekend';
        if (gid) DY.openGesprek(gid, uid, naam);
      });
    }
  } catch(e) {
  }
};

DY.renderBerichtenUitSnap = function(snap, gesprekId) {
  const chat = document.getElementById('dy-bericht-chat');
  if (!chat) return;
  const wasOnderaan = chat.scrollHeight - chat.scrollTop - chat.clientHeight < 60;

  chat.innerHTML = '';
  if (snap.empty) {
    chat.innerHTML = '<div style="text-align:center;padding:40px;color:var(--ink-muted);font-size:13px">Begin het gesprek!</div>';
    return;
  }

  let vorigeDatum = null;
  snap.forEach(function(doc) {
    const m = { _id: doc.id, ...doc.data() };
    const isJij = m.userId === DY.user.uid;
    const ts = m.ts && m.ts.toDate ? m.ts?.toDate?.() : new Date(m.createdAt || 0);

    // Datumlabel tonen bij nieuwe dag
    const datumStr = ts.toLocaleDateString('nl-NL', {day:'numeric',month:'long'});
    if (datumStr !== vorigeDatum) {
      const datum = document.createElement('div');
      datum.className = 'dy-bericht-datum';
      datum.textContent = datumStr;
      chat.appendChild(datum);
      vorigeDatum = datumStr;
    }

    const wrap = document.createElement('div');
    wrap.className = 'dy-chat-rij ' + (isJij ? 'eigen' : 'ander');

    const tijdStr = ts.toLocaleTimeString('nl-NL', {hour:'2-digit',minute:'2-digit'});

    // Foto-like state
    var fotoLikes = (m.fotoLikes && typeof m.fotoLikes === 'object') ? m.fotoLikes : {};
    var fotoLikeCount = Object.keys(fotoLikes).length;
    var isJijFotoLike = DY.user && fotoLikes[DY.user.uid] === true;
    var heeftMedia = !!m.mediaUrl;

    let inhoud = '';
    if (m.mediaUrl) {
      if (m.mediaType === 'video') {
        inhoud = '<div class="dy-chat-media-wrap" data-msgid="' + m._id + '">' +
          '<video src="' + m.mediaUrl + '" controls playsinline class="dy-chat-media"></video>' +
          '</div>';
      } else {
        // Foto: double-tap om te liken, tap om te openen
        inhoud = '<div class="dy-chat-media-wrap" data-msgid="' + m._id + '" data-gesprek="' + gesprekId + '">' +
          '<img loading="lazy" decoding="async" src="' + m.mediaUrl + '" class="dy-chat-media dy-chat-foto" ' +
            'onclick="DY.chatFotoTik(this, event)" ' +
            'ondblclick="DY.chatFotoLike(this)" ' +
            'data-msgid="' + m._id + '" data-gesprek="' + gesprekId + '" ' +
            'style="cursor:pointer">' +
          (fotoLikeCount > 0
            ? '<div class="dy-chat-foto-like-badge' + (isJijFotoLike ? ' eigen' : '') + '" data-msgid="' + m._id + '">' +
                '❤️ ' + (fotoLikeCount > 1 ? fotoLikeCount : '') +
              '</div>'
            : '') +
          '</div>';
      }
    }
    if (m.tekst) {
      // Story-reactie: voeg context-chip toe boven de tekst
      if (m.storyReactie && m.storyId) {
        inhoud += '<div class="dy-chat-story-chip" data-story-id="' + m.storyId + '" data-story-uid="' + (m.storyAuteurUid || '') + '" style="cursor:pointer">' +
          '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" style="margin-right:4px;vertical-align:middle"><circle cx="12" cy="12" r="10"/><polygon points="10,8 16,12 10,16"/></svg>' +
          '<span>Reageerde op story</span>' +
        '</div>';
      }
      inhoud += m.tekst;
    }

    const gelezen = isJij && m.gelezen === true;
    const vinkje = isJij
      ? '<span class="dy-chat-vinkje' + (gelezen ? ' dy-chat-vinkje--gelezen' : '') + '">' +
          (gelezen ? '✓✓' : '✓') +
        '</span>'
      : '';

    wrap.innerHTML =
      '<div class="dy-chat-bubble ' + (isJij ? 'eigen' : 'ander') + (heeftMedia && !m.tekst ? ' dy-chat-bubble--media' : '') + '">' +
        inhoud +
        (m.tekst || !heeftMedia
          ? '<div class="dy-chat-meta">' +
              '<span class="dy-chat-tijd">' + tijdStr + '</span>' +
              vinkje +
            '</div>'
          : '<div class="dy-chat-meta dy-chat-meta--op-foto">' +
              '<span class="dy-chat-tijd">' + tijdStr + '</span>' +
              vinkje +
            '</div>') +
      '</div>';

    // Long-press handler voor foto-like op mobiel
    if (heeftMedia && m.mediaType !== 'video') {
      var imgEl = wrap.querySelector('.dy-chat-foto');
      if (imgEl) {
        var holdTimer = null;
        imgEl.addEventListener('touchstart', function(e) {
          holdTimer = setTimeout(function() {
            holdTimer = null;
            DY.chatFotoLike(imgEl);
          }, 500);
        }, { passive: true });
        imgEl.addEventListener('touchend', function() {
          if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
        });
        imgEl.addEventListener('touchmove', function() {
          if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
        }, { passive: true });
      }
    }

    chat.appendChild(wrap);

    // Story-reactie chip click handler
    var storyChip = wrap.querySelector('.dy-chat-story-chip[data-story-id]');
    if (storyChip) {
      storyChip.addEventListener('click', function(e) {
        e.stopPropagation();
        var sid  = this.dataset.storyId;
        var suid = this.dataset.storyUid;
        if (sid) DY._toonStoryContextOverlay(sid, suid);
      });
    }
  });

  if (wasOnderaan || chat.scrollTop === 0) {
    chat.scrollTop = chat.scrollHeight;
  }

  // Markeer alle berichten van de ander als gelezen
  if (gesprekId) {
    snap.forEach(function(doc) {
      const m = doc.data();
      if (m.userId !== DY.user.uid && !m.gelezen) {
        doc.ref.update({ gelezen: true }).catch(function(){});
      }
    });
  }
};

// ── STORY CONTEXT OVERLAY (vanuit DM) ────────────────────────────
DY._toonStoryContextOverlay = async function(storyId, ownerUid) {
  if (!storyId) return;
  // Debounce: voorkom animatie-race bij snel achter-elkaar klikken
  if (DY._storyCtxBezig) return;
  DY._storyCtxBezig = true;
  setTimeout(function() { DY._storyCtxBezig = false; }, 600);

  // Verwijder bestaand overlay (cleanup eerste)
  var bestaand = document.getElementById('dy-story-ctx-overlay');
  if (bestaand) {
    bestaand.classList.remove('dy-story-ctx-in');
    bestaand.remove();
    document.body.style.overflowY = '';
  }

  // Bouw overlay
  var overlay = document.createElement('div');
  overlay.id = 'dy-story-ctx-overlay';
  overlay.className = 'dy-story-ctx-backdrop';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', 'Story context');

  // Loading state
  overlay.innerHTML =
    '<div class="dy-story-ctx-sheet">' +
      '<div class="dy-story-ctx-header">' +
        '<button type="button" class="dy-story-ctx-sluit" id="dy-story-ctx-sluit" aria-label="Sluiten">' +
          '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
        '</button>' +
        '<span class="dy-story-ctx-titel">Originele story</span>' +
      '</div>' +
      '<div class="dy-story-ctx-body" id="dy-story-ctx-body">' +
        '<div class="dy-story-ctx-loader"><div class="dy-spinner"></div></div>' +
      '</div>' +
    '</div>';

  document.body.appendChild(overlay);
  // Scroll-lock: voorkomt dat DM-chat door de overlay heen scrollt
  document.body.style.overflowY = 'hidden';

  // Animatie
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { overlay.classList.add('dy-story-ctx-in'); });
  });

  // Sluit handlers
  overlay.querySelector('#dy-story-ctx-sluit').addEventListener('click', function(e) {
    e.stopPropagation();
    DY._sluitStoryContextOverlay();
  });
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) DY._sluitStoryContextOverlay();
  });

  // Laad story
  var body = document.getElementById('dy-story-ctx-body');
  try {
    if (!DY.db) throw new Error('db niet beschikbaar');

    var doc = await DY.db.collection('dy_stories').doc(storyId).get();

    if (!doc || !doc.exists) {
      body.innerHTML = '<div class="dy-story-ctx-leeg"><p>Deze story is niet meer beschikbaar.</p></div>';
      return;
    }

    var data = doc.data();

    // Verlopen check (24u)
    var ts = data.ts && data.ts.toDate ? data.ts.toDate().getTime() : 0;
    var verlopen = ts && (Date.now() - ts) > 24 * 60 * 60 * 1000;

    // Auteur ophalen
    var auteurNaam = data.authorName || 'Gebruiker';
    var auteurAvatar = data.authorAvatar || null;
    if (ownerUid && (!data.authorName || !data.authorAvatar)) {
      try {
        var auteurDoc = await DY.db.collection('users').doc(ownerUid).get();
        if (auteurDoc && auteurDoc.exists) {
          var ad = auteurDoc.data();
          auteurNaam   = ad.displayName || ad.naam || auteurNaam;
          auteurAvatar = ad.avatar || auteurAvatar;
        }
      } catch(_e) {}
    }

    var init = auteurNaam.slice(0, 2).toUpperCase();
    var avatarHtml = auteurAvatar
      ? '<img src="' + DY.escapeHtml(auteurAvatar) + '" alt="' + DY.escapeHtml(auteurNaam) + '" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:50%">'
      : '<span style="font-weight:700;font-size:0.82rem;color:var(--clay)">' + init + '</span>';

    var tijdStr = ts
      ? (verlopen ? 'Verlopen' : DY.tijdGeleden ? DY.tijdGeleden(new Date(ts)) : new Date(ts).toLocaleTimeString('nl-NL', {hour:'2-digit',minute:'2-digit'}))
      : '';

    // Media
    var mediaHtml = '';
    if (data.photo) {
      mediaHtml = '<img src="' + DY.escapeHtml(data.photo) + '" alt="Story foto" loading="lazy" class="dy-story-ctx-media">';
    } else if (data.video) {
      mediaHtml = '<video src="' + DY.escapeHtml(data.video) + '" controls playsinline class="dy-story-ctx-media" style="max-height:320px"></video>';
    }

    // Tekst content
    var tekst = data.tekst || data.caption || data.body || '';

    body.innerHTML =
      '<div class="dy-story-ctx-auteur">' +
        '<div class="dy-story-ctx-avatar">' + avatarHtml + '</div>' +
        '<div class="dy-story-ctx-auteur-info">' +
          '<span class="dy-story-ctx-naam">' + DY.escapeHtml(auteurNaam) + '</span>' +
          (tijdStr ? '<span class="dy-story-ctx-tijd">' + DY.escapeHtml(tijdStr) + '</span>' : '') +
        '</div>' +
        (verlopen ? '<span class="dy-story-ctx-verlopen-badge">Verlopen</span>' : '') +
      '</div>' +
      (mediaHtml ? '<div class="dy-story-ctx-media-wrap">' + mediaHtml + '</div>' : '') +
      (tekst ? '<div class="dy-story-ctx-tekst">' + DY.escapeHtml(tekst) + '</div>' : '') +
      (!mediaHtml && !tekst ? '<div class="dy-story-ctx-leeg"><p>Story heeft geen zichtbare content.</p></div>' : '');

  } catch(e) {
    if (body) body.innerHTML = '<div class="dy-story-ctx-leeg"><p>Story kon niet worden geladen.</p></div>';
  }
};

DY._sluitStoryContextOverlay = function() {
  var overlay = document.getElementById('dy-story-ctx-overlay');
  if (!overlay) return;
  overlay.classList.remove('dy-story-ctx-in');
  setTimeout(function() {
    if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    // Herstel scroll-lock
    document.body.style.overflowY = '';
  }, 240);
};


// ── FOTO LIKEN IN DM ─────────────────────────────────────────────

// Enkeltap op foto: open groot. Double-tap: like.
DY._chatFotoLastTap = 0;
DY.chatFotoTik = function(imgEl, event) {
  var nu = Date.now();
  var delta = nu - DY._chatFotoLastTap;
  DY._chatFotoLastTap = nu;

  if (delta < 300 && delta > 0) {
    // Double-tap → like
    event.preventDefault();
    DY.chatFotoLike(imgEl);
  } else {
    // Single-tap → open groot (na 300ms delay om double-tap te onderscheiden)
    var src = imgEl.src;
    setTimeout(function() {
      if (Date.now() - DY._chatFotoLastTap >= 280) {
        window.open(src);
      }
    }, 310);
  }
};

DY.chatFotoLike = async function(imgEl) {
  if (!DY.user) return;
  var msgId = imgEl.getAttribute('data-msgid');
  var gesprekId = imgEl.getAttribute('data-gesprek') ||
    (DY.huidigGesprek && DY.huidigGesprek.id);
  if (!msgId || !gesprekId) return;

  // Heart animatie op de foto
  DY._chatFotoHeartAnimation(imgEl);

  try {
    var docRef = DY.db.collection('berichten').doc(gesprekId)
      .collection('messages').doc(msgId);
    var snap = await docRef.get();
    if (!snap.exists) return;
    var data = snap.data();
    var huidigeLikes = (data.fotoLikes && typeof data.fotoLikes === 'object') ? data.fotoLikes : {};
    var wasLiked = huidigeLikes[DY.user.uid] === true;

    var update = {};
    if (wasLiked) {
      update['fotoLikes.' + DY.user.uid] = firebase.firestore.FieldValue.delete();
    } else {
      update['fotoLikes.' + DY.user.uid] = true;
    }
    await docRef.update(update);

    // Update badge in DOM direct
    var wrap = imgEl.closest('.dy-chat-media-wrap');
    if (wrap) {
      var nieuweCount = Object.keys(huidigeLikes).length + (wasLiked ? -1 : 1);
      var bestaandBadge = wrap.querySelector('.dy-chat-foto-like-badge');
      if (nieuweCount > 0) {
        if (bestaandBadge) {
          bestaandBadge.textContent = '❤️ ' + (nieuweCount > 1 ? nieuweCount : '');
          bestaandBadge.classList.toggle('eigen', !wasLiked);
        } else {
          var badge = document.createElement('div');
          badge.className = 'dy-chat-foto-like-badge' + (!wasLiked ? ' eigen' : '');
          badge.setAttribute('data-msgid', msgId);
          badge.textContent = '❤️ ' + (nieuweCount > 1 ? nieuweCount : '');
          wrap.appendChild(badge);
        }
      } else if (bestaandBadge) {
        bestaandBadge.remove();
      }
    }
  } catch(e) {
  }
};

// Hart-animatie op de foto
DY._chatFotoHeartAnimation = function(imgEl) {
  var wrap = imgEl.closest('.dy-chat-media-wrap') || imgEl.parentNode;
  var heart = document.createElement('div');
  heart.className = 'dy-chat-foto-heart';
  heart.textContent = '❤️';
  wrap.style.position = 'relative';
  wrap.appendChild(heart);
  setTimeout(function() { if (heart.parentNode) heart.remove(); }, 800);
};

