DY.stuurBericht = async function(ontvangerUid, ontvangerNaam) {
  if (!DY.user) { DY.toonLoginPrompt('Inloggen om berichten te sturen.'); return; }
  // Check dmInstellingen van de ontvanger
  try {
    var ontvangerDoc = await DY.db.collection('users').doc(ontvangerUid).get();
    if (ontvangerDoc.exists) {
      var _dm = ontvangerDoc.data().dmInstellingen || 'iedereen';
      if (_dm === 'niemand') {
        if (typeof DY._toonToastBericht === 'function') DY._toonToastBericht('Deze gebruiker ontvangt geen berichten.');
        return;
      }
      if (_dm === 'vrienden') {
        var _isvriend = DY.volgtIk && DY.volgtIk(ontvangerUid);
        if (!_isvriend) {
          if (typeof DY._toonToastBericht === 'function') DY._toonToastBericht('Deze gebruiker ontvangt alleen berichten van vrienden.');
          return;
        }
      }
    }
  } catch(e) { /* bij fout: toestaan */ }
  const gesprekId = [DY.user.uid, ontvangerUid].sort().join('_');
  DY.huidigGesprek = { id: gesprekId, andereUid: ontvangerUid, anderNaam: ontvangerNaam };
  DY.navigeer('bericht_detail');
};

DY.verstuurBericht = async function() {
  if (!DY.user || !DY.huidigGesprek) return;
  const input = document.getElementById('bericht-input');
  const tekst = input ? input.value.trim() : '';
  if (!tekst) return;

  const { id: gesprekId, andereUid, anderNaam } = DY.huidigGesprek;
  input.value = '';
  if (input.style) input.style.height = 'auto';

  // Optimistic: voeg bericht direct toe aan UI
  DY._voegBerichtToeAanUI(tekst, null, null, 'pending');

  try {
    const displayName = (DY.profile && DY.profile.displayName) || ((DY.user && DY.user.email) || '').split('@')[0];
    const ts = firebase.firestore.FieldValue.serverTimestamp();

    // STAP 1: Zorg dat de berichten doc bestaat VOOR het eerste bericht
    // Zonder dit faalt de messages subcollectie write (parent doc bestaat niet)
    const gespreksDoc = {
      deelnemers: [DY.user.uid, andereUid],
      laatste_bericht: tekst,
      laatste_ts: ts
    };
    gespreksDoc['namen.' + DY.user.uid] = displayName;
    gespreksDoc['namen.' + andereUid] = anderNaam;
    gespreksDoc['ongelezen.' + andereUid] = firebase.firestore.FieldValue.increment(1);
    gespreksDoc['ongelezen.' + DY.user.uid] = 0;

    // set met merge: maakt doc aan als het nog niet bestaat, anders update
    await DY.db.collection('berichten').doc(gesprekId).set(gespreksDoc, { merge: true });

    // STAP 2: Nu het gesprek doc bestaat, voeg het bericht toe
    await DY.db.collection('berichten').doc(gesprekId)
      .collection('messages').add({
        userId: DY.user.uid,
        tekst: tekst,
        gelezen: false,
        createdAt: new Date().toISOString(),
        ts: ts
      });

  } catch(e) {
    DY.toast('Bericht kon niet worden verstuurd. Probeer opnieuw.');
    // Zet tekst terug in input
    if (input) input.value = tekst;
  }
};

// Voeg bericht optimistisch toe aan de chat UI
DY._voegBerichtToeAanUI = function(tekst, mediaUrl, mediaType, status) {
  const chat = document.getElementById('dy-bericht-chat');
  if (!chat || !DY.user) return;

  const nu = new Date();
  const tijdStr = nu.toLocaleTimeString('nl-NL', {hour:'2-digit', minute:'2-digit'});

  const wrap = document.createElement('div');
  wrap.className = 'dy-chat-rij eigen dy-chat-rij--optimistic';

  let inhoud = '';
  if (mediaUrl) {
    inhoud = mediaType === 'video'
      ? '<video src="' + mediaUrl + '" controls playsinline class="dy-chat-media"></video>'
      : '<img src="' + mediaUrl + '" class="dy-chat-media" style="cursor:pointer" onclick="window.open(this.src)">';
  }
  if (tekst) inhoud += tekst;

  wrap.innerHTML =
    '<div class="dy-chat-bubble eigen">' +
      inhoud +
      '<div class="dy-chat-meta">' +
        '<span class="dy-chat-tijd">' + tijdStr + '</span>' +
        '<span class="dy-chat-vinkje">✓</span>' +
      '</div>' +
    '</div>';

  chat.appendChild(wrap);
  chat.scrollTop = chat.scrollHeight;
};

DY.verstuurMedia = async function(input) {
  const file = input.files[0];
  if (!file || !DY.user || !DY.huidigGesprek) return;
  if (file.size > 20 * 1024 * 1024) { DY.toast('Bestand te groot (max 20MB).'); return; }

  const { id: gesprekId, andereUid, anderNaam } = DY.huidigGesprek;
  const isVideo = file.type.startsWith('video/');
  const ext = file.name.split('.').pop();
  const pad = 'berichten/' + DY.user.uid + '/' + Date.now() + '.' + ext;

  DY.toast('Bestand wordt verstuurd...');

  try {
    const ref = firebase.storage().ref(pad);
    await ref.put(file);
    const url = await ref.getDownloadURL();
    const displayName = (DY.profile && DY.profile.displayName) || ((DY.user && DY.user.email) || '').split('@')[0];
    const ts = firebase.firestore.FieldValue.serverTimestamp();

    await DY.db.collection('berichten').doc(gesprekId)
      .collection('messages').add({
        userId: DY.user.uid,
        tekst: '',
        mediaUrl: url,
        mediaType: isVideo ? 'video' : 'foto',
        gelezen: false,
        createdAt: new Date().toISOString(),
        ts: ts
      });

    const update = {
      deelnemers: [DY.user.uid, andereUid],
      laatste_bericht: isVideo ? '📹 Video' : '📷 Foto',
      laatste_ts: ts
    };
    update['namen.' + DY.user.uid] = displayName;
    update['namen.' + andereUid] = anderNaam;
    update['ongelezen.' + andereUid] = firebase.firestore.FieldValue.increment(1);
    update['ongelezen.' + DY.user.uid] = 0;

    await DY.db.collection('berichten').doc(gesprekId).set(update, { merge: true });
    input.value = '';
    DY.toast('Verstuurd!');
  } catch(e) {
    DY.toast('Versturen mislukt.');
  }
};

// LOOKBOOK
// ══════════════════════════════════════════════════════════════════
// STORY SYSTEEM v2 - Viewer, poster, 24h expiry, bekeken tracking
// ══════════════════════════════════════════════════════════════════

// ── STATE ────────────────────────────────────────────────────────
DY._sv = {
  users: [],       // array van { uid, naam, avatar, docs[] }
  userIdx: 0,      // welke gebruiker bekijken we
  storyIdx: 0,     // welke story van die gebruiker
  timer: null,     // voortgangstimer
  duur: 9000,      // ms per story (tekst) - max 9 sec
  mediaDuur: 9000, // ms voor foto stories - max 9 sec
  videoMax: 9000,  // video altijd gekapt op 9 sec
  paused: false,
  startTs: 0,
  elapsed: 0
};

// ── OPEN VIEWER ──────────────────────────────────────────────────
DY.openStoryViewer = function(users, userIdx) {
  if (!users || users.length === 0) return;
  var sv = DY._sv;
  sv.users = users;
  sv.userIdx = userIdx || 0;
  sv.storyIdx = 0;
  sv.paused = false;

  var viewer = document.getElementById('dy-story-viewer');
  viewer.style.display = 'flex';
  viewer.style.flexDirection = 'column';
  // FIX 4: overflowY ipv overflow shorthand - bewaart overflow-x:clip
  document.body.style.overflowY = 'hidden';

  // Touch handlers + tap zone onclick (gezet in svInitTouchHandlers)
  DY.svInitTouchHandlers();

  DY.svLaadHuidige();
};

// ── SLUIT VIEWER ─────────────────────────────────────────────────
DY.sluitStoryViewer = function() {
  // Sluit ook de outfit review overlay als die open is
  DY.svSluitOutfitReview && DY.svSluitOutfitReview();
  DY.svStopTimer();
  var viewer = document.getElementById('dy-story-viewer');
  viewer.style.display = 'none';
  document.body.style.overflowY = '';
  // Verwijder keyboard listener
  if (DY._svKeyHandler) {
    document.removeEventListener('keydown', DY._svKeyHandler);
    DY._svKeyHandler = null;
  }
  // Verwijder actieve video
  var media = document.getElementById('dy-sv-media');
  media.querySelectorAll('video').forEach(function(v) { v.pause(); v.src = ''; });
  media.innerHTML = '<div class="dy-sv-loader" id="dy-sv-loader"><div class="dy-spinner" style="border-color:rgba(255,255,255,0.2);border-top-color:#fff"></div></div>';
};

// ── LAAD HUIDIGE STORY ───────────────────────────────────────────
DY.svLaadHuidige = async function() {
  var sv = DY._sv;
  DY.svStopTimer();

  var u = sv.users[sv.userIdx];
  if (!u || !u.docs || u.docs.length === 0) {
    DY.sluitStoryViewer(); return;
  }
  var s = u.docs[sv.storyIdx];
  if (!s) { DY.svVolgendeUser(); return; }

  // Progress bars bouwen
  DY.svBouwProgressBars(u.docs.length, sv.storyIdx);

  // Header updaten
  var initialen = u.naam.slice(0,2).toUpperCase();
  var avatarEl = document.getElementById('dy-sv-avatar');
  avatarEl.innerHTML = u.avatar
    ? '<img loading="lazy" decoding="async" src="' + u.avatar + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%">'
    : initialen;
  document.getElementById('dy-sv-naam').textContent = u.naam;

  // Tijd
  var ts = s.ts && s.ts.toDate ? s.ts?.toDate?.() : new Date(s.createdAt || 0);
  document.getElementById('dy-sv-tijd').textContent = DY.tijdGeleden(ts);

  // Media laden
  var mediaEl = document.getElementById('dy-sv-media');
  mediaEl.innerHTML = '<div class="dy-sv-loader" id="dy-sv-loader"><div class="dy-spinner" style="border-color:rgba(255,255,255,0.2);border-top-color:#fff"></div></div>';

  var duur = sv.duur;

  if (s.photo || s.mediaUrl && s.mediaType === 'foto') {
    var fotoUrl = s.photo || s.mediaUrl;
    duur = sv.mediaDuur;
    var img = new Image();
    img.onload = function() {
      mediaEl.innerHTML = '';
      var i = document.createElement('img');
      i.src = fotoUrl;
      i.style.cssText = 'width:100%;height:100%;object-fit:contain;background:#0a0806';
      mediaEl.appendChild(i);
      DY.svVulCaption(s);
      DY.svStartTimer(duur);
    };
    img.onerror = function() { DY.svVolgendeStory(); };
    img.src = fotoUrl;

  } else if (s.video || s.mediaUrl && s.mediaType === 'video') {
    var videoUrl = s.video || s.mediaUrl;
    duur = 0; // video bepaalt zelf duur
    var vid = document.createElement('video');
    vid.src = videoUrl;
    vid.autoplay = true;
    vid.playsInline = true;
    vid.setAttribute('playsinline', '');
    vid.setAttribute('webkit-playsinline', '');
    vid.muted = false;
    vid.style.cssText = 'width:100%;height:100%;object-fit:cover;transform:translateZ(0)';
    // Direct aan DOM toevoegen zodat browser kan preloaden
    mediaEl.innerHTML = '';
    mediaEl.appendChild(vid);
    vid.onloadeddata = function() {
      vid.play().catch(function() {
        // Autoplay geblokkeerd: probeer muted
        vid.muted = true;
        vid.play();
      });
      DY.svVulCaption(s);
      var vidDuur = Math.min((vid.duration || 9) * 1000, DY._sv.videoMax || 9000);
      DY.svStartTimer(vidDuur);
    };
    vid.oncanplay = function() {
      if (vid.paused) {
        vid.play().catch(function() { vid.muted = true; vid.play(); });
      }
    };
    vid.onended = function() { DY.svVolgendeStory(); };
    vid.onerror = function() { DY.svVolgendeStory(); };

  } else {
    // Tekst-only story
    var bg = document.createElement('div');
    bg.className = 'dy-sv-bg-tekst';
    var card = document.createElement('div');
    card.className = 'dy-sv-media-tekst';
    var inner = document.createElement('div');
    inner.className = 'dy-sv-tekst-card';
    var tekst = s.body || s.tekst || s.title || '';
    inner.innerHTML = '<p class="dy-sv-tekst-body">' + tekst + '</p>';
    card.appendChild(inner);
    mediaEl.innerHTML = '';
    mediaEl.appendChild(bg);
    mediaEl.appendChild(card);
    document.getElementById('dy-sv-caption').innerHTML = '';
    DY.svStartTimer(duur);
  }

  // Like-knop bijwerken voor huidige story
  DY.svUpdateLikeBtn(s);

  // Markeer als bekeken (bijhoudt wat JIJZELF hebt gezien)
  DY.svMarkeerBekeken(u.uid);

  // Sla owner uid op in _sv zodat svToonViewers hem altijd kan vinden
  DY._sv._currentOwnerUid = u.uid;

  // Registreer view bij story owner (wie heeft JOUW story bekeken)
  DY.svRegistreerView(u.uid, s.id || s._docId || s._id);

  // Toon/verberg viewers-knop (alleen voor story owner)
  DY.svUpdateViewersKnop(u.uid);

  // Toon/verberg outfit review knop (alleen als story een foto heeft)
  DY.svUpdateOutfitReviewKnop();
};

// ── LIKE STATE BIJWERKEN ──────────────────────────────────────────
DY.svUpdateLikeBtn = function(story) {
  var btn = document.getElementById('dy-sv-like-btn');
  var countEl = document.getElementById('dy-sv-like-count');
  if (!btn || !countEl) return;

  var likes = (story.likes && typeof story.likes === 'object') ? story.likes : {};
  var likeCount = Object.keys(likes).length;
  var isLiked = DY.user && likes[DY.user.uid] === true;

  btn.classList.toggle('dy-sv-like-btn--actief', isLiked);
  countEl.textContent = likeCount > 0 ? likeCount : '';
};

// ── LIKE TOGGLE ───────────────────────────────────────────────────
DY.svToggleLike = async function() {
  if (!DY.user) { DY.toonLoginPrompt('Inloggen om een like te geven.'); return; }

  var sv = DY._sv;
  var u = sv.users && sv.users[sv.userIdx];
  var s = u && u.docs && u.docs[sv.storyIdx];
  if (!s || !s.id) return;

  var btn = document.getElementById('dy-sv-like-btn');
  var countEl = document.getElementById('dy-sv-like-count');
  if (!btn || !countEl) return;

  var likes = (s.likes && typeof s.likes === 'object') ? s.likes : {};
  var wasLiked = likes[DY.user.uid] === true;
  var huidigCount = Object.keys(likes).length;

  // Optimistic UI update
  var nieuweCount = wasLiked ? Math.max(0, huidigCount - 1) : huidigCount + 1;
  btn.classList.toggle('dy-sv-like-btn--actief', !wasLiked);
  countEl.textContent = nieuweCount > 0 ? nieuweCount : '';

  // Animatie
  btn.classList.add('dy-sv-like-btn--pulse');
  setTimeout(function() { btn.classList.remove('dy-sv-like-btn--pulse'); }, 400);

  // Lokale state bijwerken
  if (wasLiked) {
    delete s.likes[DY.user.uid];
  } else {
    if (!s.likes) s.likes = {};
    s.likes[DY.user.uid] = true;
  }

  // Firestore update - gebruik set+merge zodat dit werkt ook als 'likes' veld nog niet bestaat
  // en ook als de update-rules nog niet gedeployed zijn
  try {
    var docId = s.id;
    if (!docId) { return; }

    // Bouw het volledige likes-object op (set+merge is betrouwbaarder dan update met dot-notation)
    var nieuwelikesObj = {};
    // Haal huidige likes op om te mixen
    var huidigeLikes = s.likes && typeof s.likes === 'object' ? Object.assign({}, s.likes) : {};
    if (wasLiked) {
      delete huidigeLikes[DY.user.uid];
    } else {
      huidigeLikes[DY.user.uid] = true;
    }
    nieuwelikesObj.likes = huidigeLikes;

    await DY.db.collection('dy_stories').doc(docId).set(nieuwelikesObj, { merge: true });

    // DSP punten voor de story-maker (alleen bij liken, niet unliken)
    if (!wasLiked && u.uid !== DY.user.uid) {
      DY.geefPuntenAanGebruiker(u.uid, 2, 'story_like', docId).catch(function() {});
    }
  } catch(e) {
    // Rollback UI bij fout
    if (wasLiked) {
      if (!s.likes) s.likes = {};
      s.likes[DY.user.uid] = true;
    } else {
      if (s.likes) delete s.likes[DY.user.uid];
    }
    btn.classList.toggle('dy-sv-like-btn--actief', wasLiked);
    countEl.textContent = huidigCount > 0 ? huidigCount : '';
  }
};

// ── STORY REACTIE - verstuurt reactie als DM naar inbox poster ──

DY.svReplyFocus = function() {
  // Pauzeer story tijdens typen
  DY.svPauze();
  var balk = document.getElementById('dy-sv-reply-balk');
  if (balk) balk.classList.add('dy-sv-reply-balk--actief');
};

DY.svReplyBlur = function() {
  var input = document.getElementById('dy-sv-reply-input');
  // Hervat alleen als input leeg is
  if (input && !input.value.trim()) {
    DY.svHervat();
    var balk = document.getElementById('dy-sv-reply-balk');
    if (balk) balk.classList.remove('dy-sv-reply-balk--actief');
  }
};

DY.svVerstuurReactie = async function() {
  if (!DY.user || DY.user.isAnonymous) {
    DY.toonLoginPrompt('Inloggen om te reageren op een story.');
    return;
  }

  // Debounce: voorkom dubbele verzending bij snelle dubbele klik/tap
  if (DY._svReplyBezig) return;
  DY._svReplyBezig = true;
  setTimeout(function() { DY._svReplyBezig = false; }, 2000);

  var input = document.getElementById('dy-sv-reply-input');
  var tekst = input ? input.value.trim() : '';
  if (!tekst) { DY._svReplyBezig = false; return; }

  // Haal huidige story poster op
  var sv = DY._sv;
  var u = sv.users && sv.users[sv.userIdx];
  var s = u && u.docs && u.docs[sv.storyIdx];
  if (!u || !u.uid) return;

  // Je kunt niet op je eigen story reageren via DM
  if (u.uid === DY.user.uid) {
    DY.toast('Dit is jouw eigen story.');
    if (input) { input.value = ''; }
    DY.svHervat();
    return;
  }

  // Blur eerst, dan reset - zo triggert svReplyBlur niet met lege waarde
  // (svReplyBlur checkt of input leeg is voor hervat, we willen dat NIET hier)
  input.blur();
  input.value = '';

  var ontvangerUid = u.uid;
  var ontvangerNaam = u.naam || 'Community lid';
  var gesprekId = [DY.user.uid, ontvangerUid].sort().join('_');
  var displayName = (DY.profile && DY.profile.displayName) || ((DY.user && DY.user.email) || '').split('@')[0];

  // Prefix reactie met story-context - gebruik correcte veldnamen
  var _storyId  = s ? (s._docId || s.id || s._id || '') : '';
  var _mediaTyp = s && (s.photo || s.video || s.mediaType);
  var _storyTxt = s ? (s.tekst || s.caption || s.body || s.title || '') : '';
  var storyPreview = _mediaTyp
    ? '📸 story'
    : (_storyTxt ? '"' + _storyTxt.slice(0, 40) + (_storyTxt.length > 40 ? '…' : '') + '"' : 'story');
  var volledigeTekst = '↩ Reageerde op jouw ' + storyPreview + ': ' + tekst;

  try {
    var ts = firebase.firestore.FieldValue.serverTimestamp();

    // Zorg dat gesprek doc bestaat
    var gespreksDoc = {
      deelnemers: [DY.user.uid, ontvangerUid],
      laatste_bericht: volledigeTekst,
      laatste_ts: ts
    };
    gespreksDoc['namen.' + DY.user.uid] = displayName;
    gespreksDoc['namen.' + ontvangerUid] = ontvangerNaam;
    gespreksDoc['ongelezen.' + ontvangerUid] = firebase.firestore.FieldValue.increment(1);
    gespreksDoc['ongelezen.' + DY.user.uid] = 0;

    // Check eerst of gesprek al bestaat - zo weten we create vs update
    var _gesprekRef = DY.db.collection('berichten').doc(gesprekId);
    await _gesprekRef.set(gespreksDoc, { merge: true });

    // Kleine vertraging zodat Firestore de write propageert (voorkomt race bij messages write)
    // Dit is nodig voor de security rule get() in de messages.create rule
    await new Promise(function(r) { setTimeout(r, 50); });

    // Voeg bericht toe aan subcollectie
    await _gesprekRef
      .collection('messages').add({
        userId: DY.user.uid,
        tekst: volledigeTekst,
        storyReactie: true,
        storyAuteurUid: ontvangerUid,
        storyId: _storyId || null,
        gelezen: false,
        createdAt: new Date().toISOString(),
        ts: ts
      });

    // Stuur push-notificatie naar story eigenaar
    try {
      await DY.stuurMelding && DY.stuurMelding(ontvangerUid, {
        type: 'story_reactie',
        vanUid: DY.user.uid,
        vanNaam: displayName,
        tekst: tekst.slice(0, 80),
        storyId: _storyId
      });
    } catch(_e) { /* Notificatie niet kritiek */ }

    // Succes feedback + hervat story
    DY._svToast('Reactie verstuurd naar ' + ontvangerNaam.split(' ')[0] + ' ✓');
    DY.svHervat();

    var balk = document.getElementById('dy-sv-reply-balk');
    if (balk) balk.classList.remove('dy-sv-reply-balk--actief');

  } catch(e) {
    // Log de specifieke fout zodat delivery failures debuggable zijn
    var foutMsg = (e && e.code === 'permission-denied')
      ? 'Geen toestemming om reactie te sturen. Ben je ingelogd?'
      : (e && e.code === 'unavailable')
        ? 'Geen verbinding. Probeer opnieuw.'
        : 'Reactie kon niet worden verstuurd. Probeer opnieuw.';
    DY.toast(foutMsg);
    DY.svHervat();
  } finally {
    DY._svReplyBezig = false;
  }
};

// Kleine toast binnen de story viewer (niet de globale toast)
DY._svToast = function(tekst) {
  var bestaand = document.querySelector('.dy-sv-toast');
  if (bestaand) bestaand.remove();

  var t = document.createElement('div');
  t.className = 'dy-sv-toast';
  t.textContent = tekst;

  var inner = document.querySelector('.dy-sv-inner');
  if (!inner) return;
  inner.appendChild(t);

  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      t.classList.add('dy-sv-toast--in');
    });
  });

  setTimeout(function() {
    t.classList.remove('dy-sv-toast--in');
    setTimeout(function() { if (t.parentNode) t.remove(); }, 350);
  }, 2500);
};

// DSP punten geven aan een andere gebruiker (voor likes ontvangen)

DY.geefPuntenAanGebruiker = async function(ontvangerUid, punten, actie, refId) {
  if (!ontvangerUid || !DY.user || ontvangerUid === DY.user.uid) return;
  try {
    // dsp_log: uid = EIGEN uid (vereist door Firestore rules)
    // ontvangerUid apart opgeslagen als referentie
    await DY.db.collection('dsp_log').add({
      uid: DY.user.uid,
      ontvangerUid: ontvangerUid,
      actie: actie,
      pts: 0, // gever krijgt 0 pts voor deze actie - het zijn punten voor de ontvanger
      label: 'Like gegeven',
      ref_id: refId || null,
      ts: firebase.firestore.FieldValue.serverTimestamp()
    });
    // Update ontvanger punten direct op het users document
    // users/{ontvangerUid} mag gelezen worden door iedereen (rules: allow read: true)
    // maar update mag alleen de eigenaar zelf.
    // Oplossing: schrijf een apart 'punten_inbox' veld dat de ontvanger zelf verwerkt bij login
    const inboxRef = DY.db.collection('users').doc(ontvangerUid);
    await inboxRef.set({
      dsp_inbox: firebase.firestore.FieldValue.increment(punten),
      dsp_lifetime: firebase.firestore.FieldValue.increment(punten),
      dsp_seizoen: firebase.firestore.FieldValue.increment(punten)
    }, { merge: true });
  } catch(e) {
    // Stille fout - like zelf werkt altijd, punten zijn bonus
  }
};

// ── CAPTION ──────────────────────────────────────────────────────
DY.svVulCaption = function(s) {
  var tekst = s.body || s.tekst || s.title || '';
  if (!tekst) { document.getElementById('dy-sv-caption').innerHTML = ''; return; }
  var kort = tekst.length > 120 ? tekst.slice(0, 120) + '…' : tekst;
  document.getElementById('dy-sv-caption').innerHTML =
    '<p class="dy-sv-caption-tekst">' + kort + '</p>' +
    (tekst.length > 120 ? '<span class="dy-sv-caption-meer" onclick="DY.svToonVolleTekst()">Lees meer</span>' : '');
  DY._sv._volleTekst = tekst;
};

DY.svToonVolleTekst = function() {
  var sv = DY._sv;
  DY.svPauze();
  // Toon volledige tekst in caption
  document.getElementById('dy-sv-caption').innerHTML =
    '<p class="dy-sv-caption-tekst" style="-webkit-line-clamp:unset">' + (sv._volleTekst || '') + '</p>' +
    '<span class="dy-sv-caption-meer" onclick="DY.svHervat()">Sluiten</span>';
};

// ── PROGRESS BARS ────────────────────────────────────────────────
DY.svBouwProgressBars = function(aantal, actief) {
  var progressEl = document.getElementById('dy-sv-progress');
  progressEl.innerHTML = '';
  for (var i = 0; i < aantal; i++) {
    var seg = document.createElement('div');
    seg.className = 'dy-sv-progress-seg';
    var fill = document.createElement('div');
    fill.className = 'dy-sv-progress-fill' + (i < actief ? ' klaar' : '');
    fill.id = 'dy-sv-fill-' + i;
    seg.appendChild(fill);
    progressEl.appendChild(seg);
  }
};

// ── TIMER ────────────────────────────────────────────────────────
DY.svStartTimer = function(duur) {
  if (duur === 0) return; // video regelt zichzelf
  var sv = DY._sv;
  sv.duurActief = duur;
  sv.startTs = Date.now();
  sv.elapsed = 0;
  // Respecteer paused state (race condition guard)
  if (sv.paused) return;
  // Stop ook als viewers backdrop open is
  var backdrop = document.getElementById('dy-sv-viewers-backdrop');
  if (backdrop && backdrop.classList.contains('dy-sv-vw-in')) return;
  DY.svTickTimer();
};

DY.svTickTimer = function() {
  var sv = DY._sv;
  sv.timer = requestAnimationFrame(function() {
    if (sv.paused) return;
    // Stop ook als viewers backdrop zichtbaar is
    var _bd = document.getElementById('dy-sv-viewers-backdrop');
    if (_bd && _bd.classList.contains('dy-sv-vw-in')) return;
    var nu = Date.now();
    sv.elapsed = nu - sv.startTs;
    var pct = Math.min((sv.elapsed / sv.duurActief) * 100, 100);

    var fill = document.getElementById('dy-sv-fill-' + sv.storyIdx);
    if (fill && !fill.classList.contains('klaar')) {
      fill.style.width = pct + '%';
    }

    if (sv.elapsed >= sv.duurActief) {
      DY.svVolgendeStory();
    } else {
      DY.svTickTimer();
    }
  });
};

DY.svStopTimer = function() {
  if (DY._sv.timer) cancelAnimationFrame(DY._sv.timer);
  DY._sv.timer = null;
};

DY.svPauze = function() {
  DY._sv.paused = true;
  DY.svStopTimer();
  // Pauzeer video als aanwezig
  var vid = document.querySelector('#dy-sv-media video');
  if (vid) vid.pause();
};

DY.svHervat = function() {
  var sv = DY._sv;
  sv.paused = false;
  sv.startTs = Date.now() - sv.elapsed;
  var vid = document.querySelector('#dy-sv-media video');
  if (vid) { vid.play(); return; }
  DY.svTickTimer();
};

// ── NAVIGATIE ────────────────────────────────────────────────────
DY.svVolgendeStory = function() {
  var sv = DY._sv;
  DY.svStopTimer();
  var u = sv.users[sv.userIdx];
  if (!u) { DY.sluitStoryViewer(); return; }
  if (sv.storyIdx < u.docs.length - 1) {
    sv.storyIdx++;
    DY.svLaadHuidige();
  } else {
    DY.svVolgendeUser();
  }
};

DY.svVorigeStory = function() {
  var sv = DY._sv;
  DY.svStopTimer();
  if (sv.storyIdx > 0) {
    sv.storyIdx--;
    DY.svLaadHuidige();
  } else if (sv.userIdx > 0) {
    sv.userIdx--;
    var prevUser = sv.users[sv.userIdx];
    sv.storyIdx = prevUser && prevUser.docs ? Math.max(prevUser.docs.length - 1, 0) : 0;
    DY.svLaadHuidige();
  }
  // Als userIdx === 0 en storyIdx === 0: begin, doe niets
};

DY.svVolgendeUser = function() {
  var sv = DY._sv;
  DY.svStopTimer();
  if (sv.userIdx < sv.users.length - 1) {
    sv.userIdx++;
    sv.storyIdx = 0;
    DY.svLaadHuidige();
  } else {
    DY.sluitStoryViewer();
  }
};

// ── TOUCH / HOLD HANDLERS ────────────────────────────────────────
DY.svInitTouchHandlers = function() {
  var viewer = document.getElementById('dy-story-viewer');
  var touchStartX = 0;
  var touchStartY = 0;
  var touchStartTime = 0;
  var holdTimer = null;
  var isHolding = false;
  var isDragging = false;

  // Verwijder eventuele oude listeners door cloneNode trick
  var prevZone = document.getElementById('dy-sv-tap-prev');
  var nextZone = document.getElementById('dy-sv-tap-next');

  // ── Tap zones: directe onclick voor maximale responsiviteit ──
  if (prevZone) {
    prevZone.onclick = function(e) {
      e.stopPropagation();
      if (!isDragging) DY.svVorigeStory();
    };
  }
  if (nextZone) {
    nextZone.onclick = function(e) {
      e.stopPropagation();
      if (!isDragging) DY.svVolgendeStory();
    };
  }

  // ── Touch hold = pauzeren, swipe = gebruiker wisselen ──
  viewer.addEventListener('touchstart', function(e) {
    // Negeer touches op interactieve elementen
    var tag = e.target.tagName;
    if (tag === 'BUTTON' || tag === 'INPUT' || tag === 'A') return;

    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    touchStartTime = Date.now();
    isHolding = false;
    isDragging = false;

    holdTimer = setTimeout(function() {
      isHolding = true;
      DY.svPauze();
    }, 200);
  }, { passive: true });

  viewer.addEventListener('touchmove', function(e) {
    var dx = Math.abs(e.touches[0].clientX - touchStartX);
    var dy = Math.abs(e.touches[0].clientY - touchStartY);
    if (dx > 8 || dy > 8) isDragging = true;
  }, { passive: true });

  viewer.addEventListener('touchend', function(e) {
    clearTimeout(holdTimer);
    var dt = Date.now() - touchStartTime;
    var dx = e.changedTouches[0].clientX - touchStartX;

    // Hervatten na hold
    if (isHolding) {
      DY.svHervat();
      isHolding = false;
      isDragging = false;
      return;
    }

    // Swipe horizontaal (> 55px) = gebruiker wisselen
    if (Math.abs(dx) > 55 && isDragging) {
      if (dx < 0) DY.svVolgendeUser();
      else {
        // Swipe rechts: ga naar eerste story van vorige user
        if (DY._sv.userIdx > 0) {
          DY._sv.userIdx--;
          DY._sv.storyIdx = 0;
          DY.svLaadHuidige();
        }
      }
      isDragging = false;
      return;
    }

    isDragging = false;
    // Korte tap zonder drag: tap-zones handelen navigatie af via onclick
  }, { passive: true });

  // ── Keyboard navigatie - bind eenmalig, verwijder bij sluiten ──
  // Verwijder eventuele eerdere listener om dubbele bindings te voorkomen
  if (DY._svKeyHandler) {
    document.removeEventListener('keydown', DY._svKeyHandler);
    DY._svKeyHandler = null;
  }
  DY._svKeyHandler = function(e) {
    var viewer = document.getElementById('dy-story-viewer');
    if (!viewer || viewer.style.display === 'none') {
      // Viewer gesloten - ruim zichzelf op
      document.removeEventListener('keydown', DY._svKeyHandler);
      DY._svKeyHandler = null;
      return;
    }
    if (e.key === 'ArrowRight' || e.key === ' ') { e.preventDefault(); DY.svVolgendeStory(); }
    if (e.key === 'ArrowLeft') { e.preventDefault(); DY.svVorigeStory(); }
    if (e.key === 'Escape') { DY.sluitStoryViewer(); }
  };
  document.addEventListener('keydown', DY._svKeyHandler);
};

// ── BEKEKEN BIJHOUDEN ────────────────────────────────────────────
DY.svMarkeerBekeken = async function(uid) {
  if (!DY.user || !uid) return;
  try {
    var update = {};
    update['gezien.' + uid] = true;
    await DY.db.collection('dy_story_views').doc(DY.user.uid).set(update, { merge: true });
    // Update ring in DOM
    var ring = document.querySelector('.dy-story[data-uid="' + uid + '"] .dy-story-ring');
    if (ring) { ring.classList.remove('actief'); ring.classList.add('actief'); }
  } catch(e) {}
};


// ══════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════════
// STORY VIEWERS - wie heeft mijn story bekeken
// ══════════════════════════════════════════════════════════════════

DY.svRegistreerView = async function(ownerUid, storyId) {
  if (!DY.user || !ownerUid || !storyId) return;
  if (DY.user.uid === ownerUid) return;
  if (!DY._svViewedStories) DY._svViewedStories = {};
  var key = ownerUid + '_' + storyId;
  if (DY._svViewedStories[key]) return;
  DY._svViewedStories[key] = true;
  try {
    var naam = (DY.profile && DY.profile.displayName) || (DY.user && DY.user.displayName) || 'Gebruiker';
    var avatar = (DY.profile && DY.profile.avatar) || null;
    await DY.db.collection('dy_story_views').doc(ownerUid)
      .collection('viewers').doc(DY.user.uid)
      .set({ uid: DY.user.uid, naam: naam, avatar: avatar || null,
             ts: firebase.firestore.FieldValue.serverTimestamp(),
             storyId: storyId }, { merge: true });
  } catch(e) {}
};

DY.svUpdateViewersKnop = async function(ownerUid) {
  var btn = document.getElementById('dy-sv-viewers-btn');
  if (!btn) return;
  var isEigen = DY.user && DY.user.uid === ownerUid;
  if (!isEigen) { btn.style.display = 'none'; return; }
  btn.style.display = 'flex';
  btn.dataset.ownerUid = ownerUid; // Sla op voor gebruik door svToonViewers
  try {
    var cacheKey = 'sv_vcount_' + ownerUid;
    var cached = DY._svViewerCountCache && DY._svViewerCountCache[cacheKey];
    if (cached && (Date.now() - cached.ts) < 30000) {
      var cEl = document.getElementById('dy-sv-viewers-count');
      if (cEl) cEl.textContent = cached.count > 0 ? cached.count : '';
      return;
    }
    var snap = await DY.db.collection('dy_story_views').doc(ownerUid)
      .collection('viewers').get();
    var count = snap ? snap.size : 0;
    if (!DY._svViewerCountCache) DY._svViewerCountCache = {};
    DY._svViewerCountCache[cacheKey] = { ts: Date.now(), count: count };
    var countEl = document.getElementById('dy-sv-viewers-count');
    if (countEl) countEl.textContent = count > 0 ? count : '';
  } catch(e) {}
};

DY.svToonViewers = function(e) {
  if (e) { e.preventDefault(); e.stopPropagation(); }
  if (!DY.user) return;

  // Lees ownerUid uit button.dataset (meest betrouwbaar - onafhankelijk van _sv timing)
  var btn = document.getElementById('dy-sv-viewers-btn');
  var ownerUid = (btn && btn.dataset.ownerUid) || null;

  // Fallback: _sv state
  if (!ownerUid) {
    var sv = DY._sv;
    var u = sv && sv.users && sv.users[sv.userIdx];
    ownerUid = (u && u.uid) || (sv && sv._currentOwnerUid) || null;
  }

  // Ownership check: alleen de eigenaar mag de viewers zien
  if (!ownerUid || DY.user.uid !== ownerUid) return;
  DY.svPauze();
  var backdrop = document.getElementById('dy-sv-viewers-backdrop');
  var lijst    = document.getElementById('dy-sv-viewers-lijst');
  var titel    = document.getElementById('dy-sv-viewers-titel');
  if (!backdrop || !lijst) return;
  lijst.innerHTML = '<div class="dy-sv-viewers-laad"><div class="dy-spinner" style="border-color:rgba(254,252,245,0.15);border-top-color:rgba(254,252,245,0.7)"></div></div>';
  if (titel) titel.textContent = 'Bekeken door';
  backdrop.style.display = 'flex';
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { backdrop.classList.add('dy-sv-vw-in'); });
  });
  DY._svViewersInitSwipe();
  if (DY._svViewersBackdropHandler) {
    backdrop.removeEventListener('click', DY._svViewersBackdropHandler);
  }
  DY._svViewersBackdropHandler = function(ev) {
    if (ev.target === backdrop) DY.svSluitViewers();
  };
  backdrop.addEventListener('click', DY._svViewersBackdropHandler);
  DY._svLaadViewersLijst(ownerUid);
};

DY.svSluitViewers = function() {
  var backdrop = document.getElementById('dy-sv-viewers-backdrop');
  if (!backdrop) return;
  if (DY._svViewersBackdropHandler) {
    backdrop.removeEventListener('click', DY._svViewersBackdropHandler);
    DY._svViewersBackdropHandler = null;
  }
  backdrop.classList.remove('dy-sv-vw-in');
  setTimeout(function() {
    backdrop.style.display = 'none';
    DY.svHervat();
  }, 260);
};

DY._svBouwViewerRij = function(v, ownerUid) {
  var naam    = v.naam || 'Gebruiker';
  var init    = naam.slice(0,2).toUpperCase();
  var isEigen = DY.user && v.uid === DY.user.uid;
  var rij = document.createElement('div');
  rij.className = 'dy-sv-viewers-rij';
  rij.setAttribute('role', 'button');
  rij.setAttribute('tabindex', '0');
  if (!isEigen) {
    rij.dataset.uid  = v.uid;
    rij.dataset.naam = naam;
    rij.style.cursor = 'pointer';
  }
  var avatarDiv = document.createElement('div');
  avatarDiv.className = 'dy-sv-viewers-avatar';
  if (v.avatar) {
    var img = document.createElement('img');
    img.src = v.avatar;
    img.alt = naam;
    img.loading = 'lazy';
    img.onerror = function() { this.parentNode.textContent = init; };
    avatarDiv.appendChild(img);
  } else {
    avatarDiv.textContent = init;
  }
  var infoDiv = document.createElement('div');
  infoDiv.className = 'dy-sv-viewers-info';
  var naamDiv = document.createElement('div');
  naamDiv.className = 'dy-sv-viewers-naam';
  naamDiv.textContent = naam;
  if (isEigen) {
    var jijSpan = document.createElement('span');
    jijSpan.style.cssText = 'color:var(--clay,#c67d06);font-size:0.65rem;margin-left:4px';
    jijSpan.textContent = '(jij)';
    naamDiv.appendChild(jijSpan);
  }
  infoDiv.appendChild(naamDiv);
  var tijd = v.ts && v.ts.toDate ? DY.tijdGeleden(v.ts.toDate()) : '';
  if (tijd) {
    var tijdDiv = document.createElement('div');
    tijdDiv.className = 'dy-sv-viewers-tijd';
    tijdDiv.textContent = tijd;
    infoDiv.appendChild(tijdDiv);
  }
  rij.appendChild(avatarDiv);
  rij.appendChild(infoDiv);
  return rij;
};

DY._svLaadViewersLijst = async function(ownerUid) {
  var lijst = document.getElementById('dy-sv-viewers-lijst');
  var titel = document.getElementById('dy-sv-viewers-titel');
  if (!lijst) return;
  try {
    var snap = await DY.db.collection('dy_story_views').doc(ownerUid)
      .collection('viewers').orderBy('ts', 'desc').limit(100).get();
    var viewers = snap ? snap.docs.map(function(d) { return d.data(); }) : [];
    if (titel) titel.textContent = 'Bekeken door (' + viewers.length + ')';
    if (!viewers.length) {
      lijst.innerHTML = '<div class="dy-sv-viewers-leeg">Nog niemand heeft deze story bekeken.</div>';
      return;
    }
    lijst.innerHTML = '';
    for (var i = 0; i < viewers.length; i++) {
      lijst.appendChild(DY._svBouwViewerRij(viewers[i], ownerUid));
    }
    // Event delegatie op de lijst - geen IIFE closures nodig
    lijst.onclick = function(ev) {
      var rij = ev.target.closest('.dy-sv-viewers-rij[data-uid]');
      if (rij && rij.dataset.uid) {
        DY.svSluitViewers();
        DY.openGebruiker(rij.dataset.uid, rij.dataset.naam || '');
      }
    };
    if (!DY._svViewerCountCache) DY._svViewerCountCache = {};
    DY._svViewerCountCache['sv_vcount_' + ownerUid] = { ts: Date.now(), count: viewers.length };
    var countEl = document.getElementById('dy-sv-viewers-count');
    if (countEl) countEl.textContent = viewers.length > 0 ? viewers.length : '';
  } catch(e) {
    // Fallback zonder orderBy
    DY._svLaadViewersLijstFallback(ownerUid, lijst, titel);
  }
};

DY._svLaadViewersLijstFallback = async function(ownerUid, lijst, titel) {
  try {
    var snap2 = await DY.db.collection('dy_story_views').doc(ownerUid)
      .collection('viewers').limit(100).get();
    var viewers2 = snap2 ? snap2.docs.map(function(d) { return d.data(); }) : [];
    if (!viewers2.length) {
      lijst.innerHTML = '<div class="dy-sv-viewers-leeg">Nog niemand heeft deze story bekeken.</div>';
      return;
    }
    if (titel) titel.textContent = 'Bekeken door (' + viewers2.length + ')';
    lijst.innerHTML = '';
    for (var j = 0; j < viewers2.length; j++) {
      lijst.appendChild(DY._svBouwViewerRij(viewers2[j], ownerUid));
    }
    lijst.onclick = function(ev) {
      var rij = ev.target.closest('.dy-sv-viewers-rij[data-uid]');
      if (rij && rij.dataset.uid) {
        DY.svSluitViewers();
        DY.openGebruiker(rij.dataset.uid, rij.dataset.naam || '');
      }
    };
  } catch(e2) {
    lijst.innerHTML = '<div class="dy-sv-viewers-leeg">Kon viewers niet laden.</div>';
  }
};

DY._svViewersInitSwipe = function() {
  var sheet = document.getElementById('dy-sv-viewers-sheet');
  if (!sheet || sheet._swipeInit) return;
  sheet._swipeInit = true;
  var startY = 0;
  sheet.addEventListener('touchstart', function(e) {
    startY = e.touches[0].clientY;
  }, { passive: true });
  sheet.addEventListener('touchmove', function(e) {
    var dy2 = e.touches[0].clientY - startY;
    if (dy2 > 0) sheet.style.transform = 'translateY(' + Math.min(dy2, 200) + 'px)';
  }, { passive: true });
  sheet.addEventListener('touchend', function(e) {
    var dy2 = e.changedTouches[0].clientY - startY;
    sheet.style.transform = '';
    if (dy2 > 80) DY.svSluitViewers();
  }, { passive: true });
};


// ── STORY POSTER (nieuwe story plaatsen) ─────────────────────────
DY.renderStoryPoster = function() {
  if (!DY.user) {
    var _vPag = (DY._history && DY._history.length > 0) ? DY._history[DY._history.length-1] : 'feed';
    var _vR = {feed:DY.renderFeed,home:DY.renderHome,lookbook:DY.renderLookbook,vrienden:DY.renderVrienden,winkel:DY.renderWinkel};
    DY.pagina = null;
    if (_vR[_vPag]) { DY.pagina = _vPag; _vR[_vPag](); } else { DY.pagina = 'feed'; DY.renderFeed(); }
    DY.toonLoginPrompt('Log in om een story te plaatsen.');
    return;
  }
  var main = document.getElementById('dy-main');
  var avatarUrl = DY.profile && DY.profile.avatar;
  var naam = (DY.profile && DY.profile.displayName) || DY.user.displayName || 'Jij';
  var initialen = naam.slice(0,2).toUpperCase();

  main.innerHTML = `
    <div class="dy-composer-wrap">

      <!-- Topbar: identiek aan verhaal/fitcheck composer -->
      <div class="dy-composer-topbar">
        <button class="dy-composer-annuleer" onclick="DY.terug()">Annuleren</button>
        <span class="dy-composer-titel">Nieuwe <em style="font-style:italic">story</em></span>
        <button class="dy-btn dy-composer-plaatsen-top" id="story-plaatsen-btn" disabled>Plaatsen</button>
      </div>

      <!-- Grote media upload zone - 9:16 portret, Instagram story formaat -->
      <div class="dy-story-composer-zone" id="story-preview-wrap" onclick="document.getElementById('story-media-input').click()">
        <input type="file" id="story-media-input" accept="image/*,video/*" style="display:none">

        <!-- Lege staat -->
        <div class="dy-story-composer-leeg" id="story-preview-leeg">
          <div class="dy-story-composer-leeg-icoon">
            <svg viewBox="0 0 24 24" width="32" height="32" fill="none" stroke="currentColor" stroke-width="1.4">
              <rect x="3" y="3" width="18" height="18" rx="2"/>
              <circle cx="8.5" cy="8.5" r="1.5"/>
              <polyline points="21 15 16 10 5 21"/>
            </svg>
          </div>
          <span class="dy-story-composer-leeg-titel">Tik om foto of video te kiezen</span>
          <span class="dy-story-composer-leeg-sub">9:16 formaat aanbevolen · max 50MB</span>
          <div class="dy-story-composer-format-hints">
            <span>📸 Foto</span>
            <span>🎥 Video</span>
          </div>
        </div>

        <!-- Wissel knop (zichtbaar na upload) -->
        <button class="dy-fc-wijzig-btn" id="story-wissel-btn" style="display:none"
          onclick="event.stopPropagation();document.getElementById('story-media-input').click()">
          <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2">
            <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/>
            <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/>
          </svg>
          Wijzigen
        </button>
      </div>

      <!-- Upload voortgang -->
      <div id="story-upload-voortgang" style="display:none;padding:0 16px 4px" class="dy-upload-voortgang">
        <div class="dy-upload-balk"><div class="dy-upload-fill" id="story-upload-fill"></div></div>
        <span id="story-upload-pct">0%</span>
      </div>

      <!-- Auteur info -->
      <div class="dy-composer-auteur">
        <div class="dy-composer-avatar">
          ${avatarUrl
            ? '<img loading="lazy" decoding="async" src="' + avatarUrl + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%">'
            : initialen}
        </div>
        <div class="dy-composer-auteur-info">
          <span class="dy-composer-naam">${naam}</span>
          <div class="dy-composer-zichtbaar">
            <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.5">
              <circle cx="12" cy="12" r="3"/>
              <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/>
            </svg>
            <span>Verdwijnt na 24 uur</span>
          </div>
        </div>
        <!-- DSP badge rechts -->
        <div style="margin-left:auto;text-align:right">
          <span class="dy-composer-dsp-badge">✦ +15 DSP</span>
          <span class="dy-composer-dsp-sub" style="display:block">story plaatsen</span>
        </div>
      </div>

      <!-- Community norm -->
      <div class="dy-community-norm">
        <svg viewBox="0 0 16 16" width="12" height="12" fill="currentColor" style="color:var(--clay);flex-shrink:0"><path d="M8 14.5s-6-3.8-6-8a4.5 4.5 0 0 1 6-4.2A4.5 4.5 0 0 1 14 6.5c0 4.2-6 8-6 8z"/></svg>
        <span>Deel jouw verhaal met respect voor anderen. Hier draait het om echte ervaringen en wederzijds begrip.</span>
      </div>

    </div>`;

  var mediaInput = document.getElementById('story-media-input');
  var previewWrap = document.getElementById('story-preview-wrap');
  var previewLeeg = document.getElementById('story-preview-leeg');
  var wisselBtn = document.getElementById('story-wissel-btn');
  var plaatsenBtn = document.getElementById('story-plaatsen-btn');
  var _mediaFile = null;

  mediaInput.addEventListener('change', function(e) {
    var file = e.target.files[0];
    if (!file) return;
    if (file.size > 50 * 1024 * 1024) { DY.toast('Bestand te groot. Max 50MB.'); return; }
    _mediaFile = file;

    // Verberg lege staat, toon wissel knop
    if (previewLeeg) previewLeeg.style.display = 'none';
    if (wisselBtn) wisselBtn.style.display = 'flex';

    // Verwijder vorige preview
    previewWrap.querySelectorAll('img,video').forEach(function(el) { el.remove(); });

    // Schakel naar media-staat (past hoogte aan)
    previewWrap.classList.add('heeft-media');

    if (file.type.startsWith('image/')) {
      var img = document.createElement('img');
      img.style.cssText = 'width:100%;height:auto;object-fit:contain;max-height:75vh;display:block';
      var reader = new FileReader();
      reader.onload = function(ev) { img.src = ev.target.result; };
      reader.readAsDataURL(file);
      previewWrap.insertBefore(img, wisselBtn);
    } else if (file.type.startsWith('video/')) {
      var vid = document.createElement('video');
      vid.src = URL.createObjectURL(file);
      vid.style.cssText = 'width:100%;height:auto;object-fit:contain;max-height:75vh;display:block';
      vid.muted = true;
      vid.playsInline = true;
      vid.autoplay = true;
      vid.loop = true;
      previewWrap.insertBefore(vid, wisselBtn);
    }

    plaatsenBtn.disabled = false;
    plaatsenBtn.textContent = 'Plaatsen';
  });

  plaatsenBtn.onclick = async function() {
    if (!_mediaFile) { DY.toast('Kies eerst een foto of video.'); return; }
    var btn = plaatsenBtn;
    btn.disabled = true; btn.textContent = 'Uploaden...';

    try {
      var mediaType = _mediaFile.type.startsWith('video/') ? 'video' : 'foto';
      var ext = _mediaFile.name.split('.').pop().toLowerCase();
      // Gebruik verhalen/ pad - dat staat in de Storage rules
      var pad = 'verhalen/' + DY.user.uid + '/story_' + Date.now() + '.' + ext;
      var storageRef = firebase.storage().ref(pad);
      var uploadTask = storageRef.put(_mediaFile);

      var mediaURL = await new Promise(function(resolve, reject) {
        uploadTask.on('state_changed',
          function(snap) {
            var pct = Math.round((snap.bytesTransferred / snap.totalBytes) * 100);
            document.getElementById('story-upload-voortgang').style.display = 'flex';
            document.getElementById('story-upload-fill').style.width = pct + '%';
            document.getElementById('story-upload-pct').textContent = pct + '%';
          },
          reject,
          async function() { resolve(await uploadTask.snapshot.ref.getDownloadURL()); }
        );
      });
      document.getElementById('story-upload-voortgang').style.display = 'none';

      btn.textContent = 'Opslaan...';
      var displayName = (DY.profile && DY.profile.displayName) || DY.user.displayName || ((DY.user && DY.user.email) || '').split('@')[0] || 'Anoniem';
      var nu = new Date();
      var expiresAtTs = firebase.firestore.Timestamp.fromMillis(nu.getTime() + 24 * 60 * 60 * 1000);

      var storyData = {
        userId: DY.user.uid,
        uid: DY.user.uid,
        authorId: DY.user.uid,
        authorName: displayName,
        authorAvatar: (DY.profile && DY.profile.avatar) || null,
        body: null,
        photo: mediaType === 'foto' ? mediaURL : null,
        video: mediaType === 'video' ? mediaURL : null,
        mediaType: mediaType,
        createdAt: nu.toISOString(),
        tsMs: nu.getTime(),
        expiresAt: expiresAtTs,
        ts: firebase.firestore.FieldValue.serverTimestamp()
      };

      var docRef = await DY.db.collection('dy_stories').add(storyData);

      await DY.geefPunten('story_plaatsen', { type: 'story' });
      await DY.geefPunten('story_met_media', { type: 'story' });

      // Optimistic: markeer eigen story-ring als actief in feed
      DY._eigenStoryOptimistic = {
        id: docRef.id,
        photo: storyData.photo,
        video: storyData.video,
        mediaType: mediaType,
        ts: nu
      };
      DY._storiesCache = null;
      DY.wisTabCache(['feed']); // forceer verse DOM bij terugkeer

      // Toon succes scherm
      DY._toonStorySucces(storyData.photo || storyData.video, mediaType);

    } catch(e) {
      var msg = 'Uploaden mislukt. Probeer opnieuw.';
      if (e && e.code === 'permission-denied') msg = 'Geen toegang. Ben je ingelogd?';
      else if (e && e.code === 'storage/unauthorized') msg = 'Bestand geweigerd door beveiliging.';
      else if (e && e.code === 'unavailable') msg = 'Geen verbinding. Probeer opnieuw.';
      DY.toast(msg);
      btn.disabled = false; btn.textContent = 'Story plaatsen';
    }
  };
};

// ══════════════════════════════════════════════════════════════════
// ZOEKFUNCTIE - zoekt in verhalen, looks, gebruikers en reviews
// ══════════════════════════════════════════════════════════════════


// ══════════════════════════════════════════════════════════════════
// HEADER ZOEK FILTERS - lengte + bouw filtering
// ══════════════════════════════════════════════════════════════════

DY._zoekFilters = { lengte: 'alle', bouw: 'alle' };
DY._zoekFilterOpen = false;

DY.toggleZoekFilters = function() {
  var panel = document.getElementById('dy-zoek-filters-panel');
  var toggle = document.getElementById('dy-zoek-filter-toggle');
  if (!panel) return;

  DY._zoekFilterOpen = !DY._zoekFilterOpen;

  if (DY._zoekFilterOpen) {
    panel.style.display = 'block';
    requestAnimationFrame(function() { panel.classList.add('dy-zf-in'); });
    if (toggle) toggle.classList.add('actief');
    // Initialiseer chip event listeners
    DY._initZoekFilterChips();
  } else {
    panel.classList.remove('dy-zf-in');
    if (toggle) toggle.classList.remove('actief');
    setTimeout(function() { if (!DY._zoekFilterOpen) panel.style.display = 'none'; }, 220);
  }
};

DY._initZoekFilterChips = function() {
  // Lengte chips
  document.querySelectorAll('#dy-zf-lengte .dy-zf-chip').forEach(function(chip) {
    chip.onclick = function() {
      document.querySelectorAll('#dy-zf-lengte .dy-zf-chip').forEach(function(c) { c.classList.remove('actief'); });
      chip.classList.add('actief');
      DY._zoekFilters.lengte = chip.dataset.lengte;
      DY._updateZoekFilterBadge();
      DY._triggerZoek();
    };
  });
  // Bouw chips
  document.querySelectorAll('#dy-zf-bouw .dy-zf-chip').forEach(function(chip) {
    chip.onclick = function() {
      document.querySelectorAll('#dy-zf-bouw .dy-zf-chip').forEach(function(c) { c.classList.remove('actief'); });
      chip.classList.add('actief');
      DY._zoekFilters.bouw = chip.dataset.bouw;
      DY._updateZoekFilterBadge();
      DY._triggerZoek();
    };
  });
};

DY._updateZoekFilterBadge = function() {
  var badge = document.getElementById('dy-zoek-filter-badge');
  var wisBtn = document.getElementById('dy-zoek-filter-wis');
  var toggle = document.getElementById('dy-zoek-filter-toggle');
  var actief = (DY._zoekFilters.lengte !== 'alle' ? 1 : 0) + (DY._zoekFilters.bouw !== 'alle' ? 1 : 0);

  if (badge) {
    badge.style.display = actief > 0 ? 'flex' : 'none';
    badge.textContent = actief;
  }
  if (wisBtn) wisBtn.style.display = actief > 0 ? 'block' : 'none';
  if (toggle) toggle.classList.toggle('heeft-filter', actief > 0);
};

DY._triggerZoek = function() {
  var input = document.getElementById('dy-zoek-input');
  var q = input ? input.value.trim() : '';
  // Altijd zoeken als er filters actief zijn, ook zonder zoekterm
  if (q.length >= 2 || DY._zoekFilters.lengte !== 'alle' || DY._zoekFilters.bouw !== 'alle') {
    DY.voerZoekUit(q);
  }
};

DY.wisZoekFilters = function() {
  DY._zoekFilters = { lengte: 'alle', bouw: 'alle' };
  document.querySelectorAll('#dy-zf-lengte .dy-zf-chip').forEach(function(c) {
    c.classList.toggle('active', c.dataset.lengte === 'alle');
  });
  document.querySelectorAll('#dy-zf-bouw .dy-zf-chip').forEach(function(c) {
    c.classList.toggle('active', c.dataset.bouw === 'alle');
  });
  DY._updateZoekFilterBadge();
  DY._triggerZoek();
};

DY._zoekTimer = null;
DY._zoekOpen = false;

DY.toggleZoekbalk = function() {
  var wrap = document.getElementById('dy-zoekbalk-wrap');
  var input = document.getElementById('dy-zoek-input');
  if (!wrap) return;
  if (DY._zoekOpen) {
    DY.sluitZoek();
  } else {
    DY._zoekOpen = true;
    wrap.style.display = 'block';
    wrap.classList.add('actief');
    setTimeout(function() { if (input) input.focus(); }, 50);
  }
};

DY.toggleZoek = function() { DY.sluitZoek(); };

DY.sluitZoek = function() {
  var wrap = document.getElementById('dy-zoekbalk-wrap');
  var input = document.getElementById('dy-zoek-input');
  var resultaten = document.getElementById('dy-zoek-resultaten');
  var panel = document.getElementById('dy-zoek-filters-panel');
  if (wrap) { wrap.style.display = 'none'; wrap.classList.remove('actief'); }
  if (input) input.value = '';
  if (resultaten) resultaten.innerHTML = '';
  // Reset filter panel
  if (panel) { panel.classList.remove('dy-zf-in'); panel.style.display = 'none'; }
  DY._zoekFilterOpen = false;
  DY._zoekOpen = false;
};

// Input listener instellen zodra DOM klaar is
document.addEventListener('DOMContentLoaded', function() {
  var input = document.getElementById('dy-zoek-input');
  if (!input) return;
  input.addEventListener('input', function() {
    var q = input.value.trim();
    clearTimeout(DY._zoekTimer);
    var heeftFilter = DY._zoekFilters && (DY._zoekFilters.lengte !== 'alle' || DY._zoekFilters.bouw !== 'alle');
    if (q.length < 2 && !heeftFilter) {
      document.getElementById('dy-zoek-resultaten').innerHTML = '';
      return;
    }
    if (q.length < 2 && !heeftFilter) return;
    DY._zoekTimer = setTimeout(function() { DY.voerZoekUit(q); }, 250);
  });
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') DY.sluitZoek();
  });
});

DY.voerZoekUit = async function(q) {
  var resultaten = document.getElementById('dy-zoek-resultaten');
  if (!resultaten) return;
  var qLower = (q || '').toLowerCase();
  var filters = DY._zoekFilters || { lengte: 'alle', bouw: 'alle' };
  var heeftFilter = filters.lengte !== 'alle' || filters.bouw !== 'alle';

  // Toon lege resultaten alleen als ook geen filters actief zijn
  if (!q && !heeftFilter) { resultaten.innerHTML = ''; return; }

  resultaten.innerHTML = '<div class="dy-zoek-laden"><div class="dy-spinner" style="width:20px;height:20px;border-width:2px"></div></div>';

  try {
    // Detecteer lengte/maat zoekopdracht voor lengte-gebaseerde zoek
    var qNum = parseInt(q);
    var isLengteZoek = qNum >= 150 && qNum <= 220;
    var isMaatZoek = q && /^(xs|s|m|l|xl|xxl|2xl|3xl|4xl|5xl|[0-9]{2,3})$/i.test(q.trim());

    // Helper: controleer lengte filter
    function checkLengteFilter(lengte) {
      if (!filters.lengte || filters.lengte === 'alle') return true;
      var l = parseInt(lengte);
      if (!l) return false;
      if (filters.lengte === '170min')  return l < 170;
      if (filters.lengte === '170-180') return l >= 170 && l < 180;
      if (filters.lengte === '180-190') return l >= 180 && l < 190;
      if (filters.lengte === '190-200') return l >= 190 && l < 200;
      if (filters.lengte === '200plus') return l >= 200;
      return true;
    }

    // Helper: controleer bouw filter
    function checkBouwFilter(bouw) {
      if (!filters.bouw || filters.bouw === 'alle') return true;
      if (!bouw) return false;
      // Normaliseer legacy waarden (slank→XL, atletisch→2XL, etc.)
      var normBouw = DY._normBouw ? DY._normBouw(bouw) : bouw;
      return normBouw.toLowerCase() === filters.bouw.toLowerCase();
    }

    // Haal alles op - client-side filteren (zelfde patroon als rest van de app)
    var [verhalenSnap, looksSnap, usersSnap, reviewsSnap] = await Promise.all([
      DY.db.collection('stories').limit(200).get().catch(function() { return { docs: [] }; }),
      DY.db.collection('lookbook').limit(100).get().catch(function() { return { docs: [] }; }),
      DY.db.collection('users').limit(100).get().catch(function() { return { docs: [] }; }),
      DY.db.collection('reviews').limit(100).get().catch(function() { return { docs: [] }; })
    ]);

    var hits = [];

    // Verhalen zoeken
    verhalenSnap.docs.forEach(function(d) {
      var v = d.data();
      var pLen = v.posterLengte || v.lengte;
      var pMaat = (v.posterMaat || v.maat || '').toString();
      var tekst = ((v.title || '') + ' ' + (v.body || '') + ' ' + (v.authorName || '') + ' ' + (pLen ? pLen + 'cm ' + pLen : '') + ' ' + pMaat).toLowerCase();
      // Filter op bouw
      if (!checkBouwFilter(v.posterBouw || v.bouw)) return;
      // Filter op lengte (via filter panel)
      if (!checkLengteFilter(pLen)) return;
      // Filter op zoekterm (alleen als zoekterm aanwezig)
      if (q) {
        if (isLengteZoek) {
          if (pLen && Math.abs(parseInt(pLen) - qNum) > 8) return;
          if (!pLen && !tekst.includes(qLower)) return;
        } else if (isMaatZoek) {
          var maatMatch = pMaat && pMaat.toUpperCase().includes(q.toUpperCase());
          if (!maatMatch && !tekst.includes(qLower)) return;
        } else if (!tekst.includes(qLower)) return;
      }
      hits.push({
        type: 'verhaal',
        id: d.id,
        titel: v.title || v.body.slice(0,60) || 'Verhaal',
        sub: 'Door ' + (v.authorName || 'Anoniem'),
        avatar: v.authorAvatar || null,
        initialen: (v.authorName || 'A').slice(0,2).toUpperCase(),
        actie: function(id) { return function() { DY.huidigVerhaalId = id; DY.navigeer('detail'); DY.sluitZoek(); }; }(d.id)
      });
    });

    // Looks zoeken
    looksSnap.docs.forEach(function(d) {
      var v = d.data();
      var vMaat = (v.maat || v.borstomvang || '').toString();
      var tekst = ((v.omschrijving || '') + ' ' + (v.authorName || '') + ' ' + vMaat + ' ' + (v.lengte ? v.lengte + 'cm ' + v.lengte : '')).toLowerCase();
      if (isLengteZoek) {
        // Lengte zoek: match op ±8cm als lengte bekend, anders doorgaan
        if (v.lengte && Math.abs(parseInt(v.lengte) - qNum) > 8) return;
        if (!v.lengte) return; // geen lengte data
      } else if (isMaatZoek) {
        // Maat zoek: match in maat veld OF in tekst
        var maatMatch = vMaat && vMaat.toUpperCase().includes(q.toUpperCase());
        var tekstMatch = tekst.includes(qLower);
        if (!maatMatch && !tekstMatch) return;
      } else if (!tekst.includes(qLower)) return;
      hits.push({
        type: 'look',
        id: d.id,
        titel: v.omschrijving ? v.omschrijving.slice(0,60) : 'Fitcheck',
        sub: 'Look · ' + (v.authorName || 'Anoniem') + ((v.fitPrivacy !== 'privé' && v.lengte) ? ' · ' + v.lengte + 'cm' : '') + ((v.fitPrivacy !== 'privé' && v.maat) ? ' · ' + v.maat : ''),
        foto: v.foto || v.photo || null,
        avatar: v.authorAvatar || null,
        initialen: (v.authorName || 'L').slice(0,2).toUpperCase(),
        _data: { lengte: v.lengte, maat: v.maat, gewicht: v.gewicht, borst: v.borstomvang, bouw: v.bouw },
        actie: function(id) { return function() { DY.openLookDetail(id); DY.sluitZoek(); }; }(d.id)
      });
    });

    // Gebruikers zoeken
    usersSnap.docs.forEach(function(d) {
      var v = d.data();
      var uLen = v.lengte;
      var uMaat = (v.maat || '').toString();
      // Matching gebruikt ALTIJD lengte/maat (ook als privé) - alleen UI output verbergt het
      var tekst = ((v.displayName || '') + ' ' + (v.email || '') + ' ' + (v.bio || '') + ' ' + (uLen ? uLen + 'cm ' + uLen : '') + ' ' + uMaat).toLowerCase();
      if (isLengteZoek) {
        if (!uLen || Math.abs(parseInt(uLen) - qNum) > 8) return;
      } else if (isMaatZoek) {
        var maatMatch = uMaat && uMaat.toUpperCase().includes(q.toUpperCase());
        if (!maatMatch && !tekst.includes(qLower)) return;
      } else if (!tekst.includes(qLower)) return;
      // Maten alleen tonen als fitPrivacy niet privé is
      var _zUidFit = DY.fitLabelZichtbaar ? DY.fitLabelZichtbaar(d.id) : (v.fitPrivacy !== 'privé');
      hits.push({
        type: 'gebruiker',
        id: d.id,
        titel: v.displayName || v.email || 'Gebruiker',
        sub: (_zUidFit && v.lengte ? v.lengte + 'cm · ' : '') + (v.dsp_lifetime || 0) + ' DSP',
        avatar: v.avatar || null,
        initialen: (v.displayName || 'G').slice(0,2).toUpperCase(),
        actie: function(id, naam) { return function() { DY.openGebruiker(id, naam); DY.sluitZoek(); }; }(d.id, v.displayName || '')
      });
    });

    // Reviews zoeken
    reviewsSnap.docs.forEach(function(d) {
      var v = d.data();
      var vMaat = (v.maat || '').toString();
      var tekst = ((v.tekst || '') + ' ' + (v.authorName || '') + ' ' + (v.product || '') + ' ' + (v.lengte ? v.lengte + 'cm ' + v.lengte : '') + ' ' + vMaat).toLowerCase();
      if (isLengteZoek) {
        if (v.lengte && Math.abs(parseInt(v.lengte) - qNum) > 8) return;
        if (!v.lengte) return;
      } else if (isMaatZoek) {
        var maatMatch = vMaat && vMaat.toUpperCase().includes(q.toUpperCase());
        var tekstMatch = tekst.includes(qLower);
        if (!maatMatch && !tekstMatch) return;
      } else if (!tekst.includes(qLower)) return;
      hits.push({
        type: 'review',
        id: d.id,
        titel: v.product || 'Review',
        sub: 'Review · ' + (v.authorName || 'Anoniem') + ((v.fitPrivacy !== 'privé' && v.lengte) ? ' · ' + v.lengte + 'cm' : '') + ((v.fitPrivacy !== 'privé' && v.maat) ? ' · ' + v.maat : ''),
        avatar: v.authorAvatar || null,
        initialen: (v.authorName || 'R').slice(0,2).toUpperCase(),
        _data: { lengte: v.lengte, maat: v.maat, gewicht: v.gewicht, borst: v.borst, bouw: v.lichaamstype },
        actie: function() { DY.navigeer('reviews'); DY.sluitZoek(); }
      });
    });

    // Voeg maat-match score toe aan hits (looks en reviews)
    var mijnProfiel = DY.profile || {};
    var heeftMaatProfiel = !!(mijnProfiel.lengte || mijnProfiel.maat);
    hits.forEach(function(hit) {
      if (heeftMaatProfiel && (hit.type === 'look' || hit.type === 'review') && hit._data) {
        var score = DY.maatMatchScore ? DY.maatMatchScore(mijnProfiel, hit._data) : 0;
        hit.matchScore = score;
        hit.matchLabel = DY.maatMatchLabel ? DY.maatMatchLabel(score) : null;
      }
      // Detecteer lengte/maat zoekterm
      if (/^[0-9]{3}(cm)?$/i.test(q) || /^[0-9]+m$/i.test(q)) {
        hit.maatZoek = true; // Lengte zoekopdracht
      }
    });

    // Sorteer: als lengte/maat zoekopdracht → match score eerst
    if (heeftMaatProfiel && /^\d{3}|^[xXsSlLmM]+l?$/i.test(q)) {
      hits.sort(function(a, b) { return (b.matchScore || 0) - (a.matchScore || 0); });
    }

    // Render resultaten
    if (hits.length === 0) {
      resultaten.innerHTML = '<div class="dy-zoek-leeg">Geen resultaten voor "<strong>' + DY.escapeHtml(q) + '</strong>"</div>';
      return;
    }

    // Verberg suggestie chips zodra er resultaten zijn
    var suggesties = document.getElementById('dy-zoek-suggesties');
    if (suggesties) suggesties.style.display = 'none';

    var html = '';
    hits.slice(0, 15).forEach(function(hit, idx) {
      var typeLabel = { verhaal: 'Verhaal', look: 'Look', gebruiker: 'Persoon', review: 'Review' }[hit.type] || '';
      var matchBadge = hit.matchLabel
        ? '<span class="dy-zoek-hit-match">' + hit.matchLabel.pct + '% match</span>'
        : '';
      var thumb = hit.foto
        ? '<img loading="lazy" decoding="async" src="' + hit.foto + '" style="width:100%;height:100%;object-fit:cover;border-radius:6px">'
        : hit.avatar
          ? '<img loading="lazy" decoding="async" src="' + hit.avatar + '" style="width:100%;height:100%;object-fit:cover;border-radius:' + (hit.type === 'gebruiker' ? '50%' : '6px') + '">'
          : '<span style="font-weight:700;font-size:11px;color:var(--clay)">' + hit.initialen + '</span>';
      html += '<div class="dy-zoek-hit" data-idx="' + idx + '">' +
        '<div class="dy-zoek-hit-thumb">' + thumb + '</div>' +
        '<div class="dy-zoek-hit-info">' +
          '<span class="dy-zoek-hit-type">' + typeLabel + '</span>' +
          '<strong class="dy-zoek-hit-titel">' + DY.escapeHtml(hit.titel) + '</strong>' +
          '<span class="dy-zoek-hit-sub">' + DY.escapeHtml(hit.sub) + '</span>' +
        '</div>' +
        matchBadge +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="14" height="14" style="color:var(--ink-muted);flex-shrink:0"><path d="M9 18l6-6-6-6"/></svg>' +
      '</div>';
    });

    resultaten.innerHTML = html;

    // Klik handlers
    resultaten.querySelectorAll('.dy-zoek-hit').forEach(function(el) {
      var idx = parseInt(el.dataset.idx);
      el.addEventListener('click', function() { hits[idx].actie(); });
    });

  } catch(e) {
    resultaten.innerHTML = '<div class="dy-zoek-leeg">Zoeken mislukt. Probeer opnieuw.</div>';
  }
};

DY.escapeHtml = function(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
};

