DY._toonVerhaalSucces = function(docId, totalPts, heeftMedia) {
  var main = document.getElementById('dy-main');
  if (!main) return;

  var niveau = DY.getNiveau((DY.profile && DY.profile.dsp_lifetime) || 0);
  var progress = DY.getNiveauProgress((DY.profile && DY.profile.dsp_lifetime) || 0);
  var niveauNaam = niveau ? niveau.naam : '';

  main.innerHTML =
    '<div class="dy-succes-wrap">' +
      '<div class="dy-succes-glow"></div>' +
      '<div class="dy-succes-icon">✦</div>' +
      '<h1 class="dy-succes-kop">Verhaal geplaatst</h1>' +
      '<p class="dy-succes-sub">Jouw verhaal is live in de community</p>' +
      '<div class="dy-succes-pts-rij">' +
        '<div class="dy-succes-pts-badge">+' + totalPts + ' DSP</div>' +
        (heeftMedia ? '<div class="dy-succes-pts-detail">inclusief foto/video bonus</div>' : '') +
      '</div>' +
      '<div class="dy-succes-niveau-blok">' +
        '<div class="dy-succes-niveau-label">' + niveauNaam + '</div>' +
        '<div class="dy-succes-bar-bg"><div class="dy-succes-bar-fill" style="width:0%" data-target="' + progress + '"></div></div>' +
      '</div>' +
      '<div class="dy-succes-acties">' +
        '<button class="dy-btn dy-btn-primary dy-succes-btn-main" onclick="DY._naarVerhaal(\'' + docId + '\')">Jouw verhaal bekijken</button>' +
        '<button class="dy-btn dy-btn-ghost dy-succes-btn-sec" onclick="DY._naarFeedVanSucces()">Terug naar feed</button>' +
      '</div>' +
    '</div>';

  // Animeer progress bar na render
  setTimeout(function() {
    var fill = main.querySelector('.dy-succes-bar-fill');
    if (fill) fill.style.width = fill.dataset.target + '%';
  }, 300);
};

DY._toonStorySucces = function(mediaUrl, mediaType) {
  var main = document.getElementById('dy-main');
  if (!main) return;

  var thumbHtml = '';
  if (mediaUrl) {
    if (mediaType === 'foto') {
      thumbHtml = '<div class="dy-succes-story-thumb"><img src="' + mediaUrl + '" alt="Story preview"></div>';
    } else {
      thumbHtml = '<div class="dy-succes-story-thumb"><video src="' + mediaUrl + '" muted playsinline autoplay loop style="width:100%;height:100%;object-fit:cover"></video></div>';
    }
  }

  main.innerHTML =
    '<div class="dy-succes-wrap dy-succes-wrap--story">' +
      '<div class="dy-succes-glow dy-succes-glow--story"></div>' +
      (thumbHtml || '<div class="dy-succes-icon">✦</div>') +
      '<h1 class="dy-succes-kop">Story live!</h1>' +
      '<p class="dy-succes-sub">Zichtbaar in de community · verdwijnt na 24 uur</p>' +
      '<div class="dy-succes-pts-rij">' +
        '<div class="dy-succes-pts-badge">+15 DSP</div>' +
      '</div>' +
      '<div class="dy-succes-acties">' +
        '<button class="dy-btn dy-btn-primary dy-succes-btn-main" onclick="DY._naarFeedVanSucces()">Bekijk in feed</button>' +
      '</div>' +
    '</div>';
};

DY._naarVerhaal = function(docId) {
  DY._optimisticVerhaal = null;
  DY.huidigVerhaalId = docId;
  DY.navigeer('detail');
};

DY._naarFeedVanSucces = function() {
  // Reset optimistic na 8 seconden (Firestore heeft het dan bijna zeker)
  setTimeout(function() {
    DY._optimisticVerhaal = null;
    DY._eigenStoryOptimistic = null;
  }, 8000);
  DY.navigeer('feed');
};

// ── GAST STORY TEASERS (fallback als Firestore blocked) ────────────
DY._toonGastStoryTeasers = function(row) {
  // Toon 3 vage skeleton-rings als uitnodiging
  var namen = ['Emma', 'Lars', 'Nora'];
  namen.forEach(function(naam) {
    var item = document.createElement('div');
    item.className = 'dy-story dy-story-teaser-skeleton';
    item.innerHTML =
      '<div class="dy-story-ring onbekeken dy-story-ring--blur">' +
        '<div class="dy-story-avatar dy-story-avatar--skeleton"></div>' +
        '<div class="dy-story-lock-badge">🔒</div>' +
      '</div>' +
      '<div class="dy-story-name dy-story-name--blur">' + naam + '</div>';
    item.onclick = function() { DY.navigeer('register'); };
    row.appendChild(item);
  });
};

// ══════════════════════════════════════════════════════════════════
// SHOPIFY KLANT SYNC
// Maakt automatisch een Shopify klantaccount aan bij app-registratie.
// Gebruikt Storefront API customerCreate - geen Admin credentials nodig.
// Vereist: Storefront Access Token in DY.CFG_SHOPIFY_TOKEN (lees-/schrijftoegang).
//
// INSTELLEN: ga in Shopify naar
//   Instellingen → Apps en verkoopkanalen → Storefront API → Toegangstokens
//   Maak een token met scope: unauthenticated_write_customers
//   Plak het token in DY.CFG_SHOPIFY_TOKEN hierboven.
// ══════════════════════════════════════════════════════════════════

DY.registreerShopifyKlant = async function(naam, email) {
  try {
    // Roep de Cloudflare Worker aan - die heeft de Admin API token als secret.
    // Directe Shopify API calls vanuit de browser werken niet (CORS + token exposure).
    try {
      var res = await fetch(WORKER_URL + '/shopify-klant', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          naam: naam,
          email: email,
          uid: DY.user ? DY.user.uid : null
        })
      });

      var data = await res.json();

      if (data.ok) {
        await DY.slaShopifySyncOp(naam, email, data.status, data.shopify_id);
      } else {
        await DY.slaShopifySyncOp(naam, email, 'worker_fout: ' + (data.error || 'onbekend'));
      }
    } catch(e) {
      // Worker niet bereikbaar - sla op voor handmatige sync
      await DY.slaShopifySyncOp(naam, email, 'worker_unreachable');
    }

  } catch(e) { }
};


DY.slaShopifySyncOp = async function(naam, email, status, shopifyId) {
  if (!DY.user) return;
  try {
    var patch = { shopify_sync: status };
    if (shopifyId) patch.shopify_id = shopifyId;
    await DY.db.collection('users').doc(DY.user.uid).update(patch);

    // Sla ook op in aparte collectie voor overzicht
    await DY.db.collection('shopify_sync_log').add({
      uid: DY.user.uid,
      naam: naam,
      email: email,
      status: status,
      shopify_id: shopifyId || null,
      ts: firebase.firestore.FieldValue.serverTimestamp()
    });
  } catch(e) {
  }
};

