// LOOK BOOKMARK / SAVE SYSTEEM
// ══════════════════════════════════════════════════════════════════

DY._lookBookmarks = null; // cache

DY._getLookBookmarks = function() {
  if (!DY._lookBookmarks) {
    try {
      DY._lookBookmarks = JSON.parse(localStorage.getItem('dy_saved_looks') || '[]');
    } catch(e) {
      DY._lookBookmarks = [];
    }
  }
  return DY._lookBookmarks;
};

DY.isLookSaved = function(id) {
  return DY._getLookBookmarks().indexOf(id) !== -1;
};

DY.toggleLookSave = function(id, btn) {
  if (!DY.user) {
    DY.toonLoginPrompt('Inloggen om looks te bewaren.');
    return;
  }

  var bookmarks = DY._getLookBookmarks();
  var idx = bookmarks.indexOf(id);
  var wordtGesaved = idx === -1;

  if (wordtGesaved) {
    bookmarks.push(id);
  } else {
    bookmarks.splice(idx, 1);
  }

  DY._lookBookmarks = bookmarks;
  localStorage.setItem('dy_saved_looks', JSON.stringify(bookmarks));

  // Update UI van alle knoppen voor dit look-id
  document.querySelectorAll('[data-save-id="' + id + '"], .dy-look-tile-save, .dy-look-save-btn').forEach(function(b) {
    if (!btn || b === btn || b.closest('[data-look-id="' + id + '"]')) {
      var svg = b.querySelector('svg');
      b.classList.toggle('saved', wordtGesaved);
      if (svg) svg.setAttribute('fill', wordtGesaved ? 'currentColor' : 'none');
    }
  });

  // Directe feedback op de geklkte knop
  if (btn) {
    btn.classList.toggle('saved', wordtGesaved);
    var svg = btn.querySelector('svg');
    if (svg) svg.setAttribute('fill', wordtGesaved ? 'currentColor' : 'none');
    // Pulse animatie
    btn.classList.add('dy-save-pulse');
    setTimeout(function() { btn.classList.remove('dy-save-pulse'); }, 350);
  }

  DY.toast(wordtGesaved ? 'Look bewaard ♡' : 'Look verwijderd uit bewaard');

  // Wis de looks-cache tab als opgeslagen-filter actief is
  if (DY._lookFilter === 'opgeslagen') {
    DY.laadLooks('opgeslagen');
  }
};

