DY._toonMeldForm = function() { DY._toonMeldModal({}); };

DY._toonMeldModalFromEl = function(el) {
  var content = {
    id:   el.getAttribute('data-id')   || '',
    naam: el.getAttribute('data-naam') || 'Onbekend',
    foto: el.getAttribute('data-foto') || null,
    uid:  el.getAttribute('data-uid')  || '',
    ts:   new Date().toLocaleString('nl-NL')
  };
  DY._toonMeldModal(content);
};

DY._toonMeldModal = function(content) {
  // Verwijder eventuele bestaande modal
  var existing = document.getElementById('dy-meld-modal');
  if (existing) existing.remove();

  content = content || {};
  var modalEl = document.createElement('div');
  modalEl.id = 'dy-meld-modal';
  modalEl.setAttribute('role', 'dialog');
  modalEl.setAttribute('aria-modal', 'true');
  modalEl.setAttribute('aria-label', 'Inhoud rapporteren');

  var previewHTML = '';
  if (content.foto) {
    previewHTML += '<img loading="lazy" decoding="async" class="dy-meld-preview-foto" src="' + content.foto + '" alt="" aria-hidden="true">';
  } else {
    previewHTML += '<div class="dy-meld-preview-placeholder" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg></div>';
  }

  // Sla content op als module variabele - geen JSON in onclick attrs
  DY._meldContent = content;

  modalEl.innerHTML =
    '<div class="dy-meld-backdrop" onclick="DY._sluitMeldModal()"></div>' +
    '<div class="dy-meld-sheet" role="document">' +

      // ── Header
      '<div class="dy-meld-header">' +
        '<h2 class="dy-meld-titel">Inhoud rapporteren</h2>' +
        '<button class="dy-meld-sluiten" onclick="DY._sluitMeldModal()" aria-label="Sluiten">&#10005;</button>' +
      '</div>' +

      // ── Content preview
      '<div class="dy-meld-preview">' +
        previewHTML +
        '<div class="dy-meld-preview-info">' +
          '<span class="dy-meld-preview-naam">' + (content.naam || 'Onbekend') + '</span>' +
          '<span class="dy-meld-preview-ts">' + (content.ts || 'Zojuist geplaatst') + '</span>' +
        '</div>' +
      '</div>' +

      // ── Redenen
      '<div class="dy-meld-redenen">' +

        '<div class="dy-meld-categorie"><span class="dy-meld-cat-label">🔴 Veiligheid / schadelijk gedrag</span>' +
          ['Haatdragende of beledigende inhoud','Intimidatie of pesten','Dreiging of geweld','Discriminatie (geslacht, lichaam, afkomst, etc.)']
            .map(function(r){ return '<label class="dy-meld-optie"><input type="checkbox" name="meld" value="'+r+'" onchange="DY._meldValideer()"><span>'+r+'</span></label>'; }).join('') +
        '</div>' +

        '<div class="dy-meld-categorie"><span class="dy-meld-cat-label">🔞 Ongepaste content</span>' +
          ['Seksueel ongepaste inhoud','Naakt of expliciete content','Ongepaste suggestieve content']
            .map(function(r){ return '<label class="dy-meld-optie"><input type="checkbox" name="meld" value="'+r+'" onchange="DY._meldValideer()"><span>'+r+'</span></label>'; }).join('') +
        '</div>' +

        '<div class="dy-meld-categorie"><span class="dy-meld-cat-label">🧍 Body / uiterlijk gerelateerd</span>' +
          ['Body shaming of negatieve opmerkingen','Ongewenste beoordeling van uiterlijk','Respectloze opmerkingen over lichaam of stijl']
            .map(function(r){ return '<label class="dy-meld-optie"><input type="checkbox" name="meld" value="'+r+'" onchange="DY._meldValideer()"><span>'+r+'</span></label>'; }).join('') +
        '</div>' +

        '<div class="dy-meld-categorie"><span class="dy-meld-cat-label">📣 Spam / misbruik</span>' +
          ['Spam of reclame','Nepaccount of misleidende content','Herhaaldelijk storend gedrag']
            .map(function(r){ return '<label class="dy-meld-optie"><input type="checkbox" name="meld" value="'+r+'" onchange="DY._meldValideer()"><span>'+r+'</span></label>'; }).join('') +
        '</div>' +

        '<div class="dy-meld-categorie"><span class="dy-meld-cat-label">⚖️ Anders</span>' +
          '<label class="dy-meld-optie"><input type="checkbox" name="meld" value="Anders" id="dy-meld-anders" onchange="DY._meldValideer()"><span>Anders (vul toelichting in)</span></label>' +
        '</div>' +

      '</div>' +

      // ── Vrij tekstveld
      '<div class="dy-meld-toelichting">' +
        '<label class="dy-meld-toelichting-label" for="dy-meld-tekst">Wil je extra toelichting geven?</label>' +
        '<textarea id="dy-meld-tekst" class="dy-meld-textarea" placeholder="Beschrijf kort wat er volgens jou niet klopt..." rows="3" oninput="DY._meldValideer()"></textarea>' +
      '</div>' +

      // ── Ernst inschatting
      '<div class="dy-meld-ernst">' +
        '<span class="dy-meld-ernst-label">Ernst (optioneel)</span>' +
        '<div class="dy-meld-ernst-opties">' +
          ['Laag (niet dringend)','Gemiddeld','Hoog (direct risico)'].map(function(e,i){
            return '<label class="dy-meld-ernst-optie"><input type="radio" name="ernst" value="'+e+'"><span>'+e+'</span></label>';
          }).join('') +
        '</div>' +
      '</div>' +

      // ── Submit
      '<div class="dy-meld-footer">' +
        '<button class="dy-meld-submit" id="dy-meld-submit-btn" onclick="DY._verstuurMelding(DY._meldContent)" disabled>' +
          'Rapporteren versturen' +
        '</button>' +
        '<div class="dy-meld-ok" id="dy-meld-bevestiging" style="display:none">' +
          '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>' +
          '<span id="dy-meld-ok-tekst">Melding ontvangen. Bedankt voor je bijdrage.</span>' +
        '</div>' +
      '</div>' +

    '</div>';

  document.body.appendChild(modalEl);
  // Focus naar modal voor toegankelijkheid
  requestAnimationFrame(function() {
    var sheet = modalEl.querySelector('.dy-meld-sheet');
    if (sheet) sheet.focus();
    modalEl.classList.add('dy-meld-open');
  });
};

DY._sluitMeldModal = function() {
  var modal = document.getElementById('dy-meld-modal');
  if (!modal) return;
  modal.classList.remove('dy-meld-open');
  setTimeout(function() { if (modal.parentNode) modal.parentNode.removeChild(modal); }, 220);
};

DY._meldValideer = function() {
  var checked = document.querySelectorAll('#dy-meld-modal input[name="meld"]:checked');
  var anders = document.getElementById('dy-meld-anders');
  var tekst = document.getElementById('dy-meld-tekst');
  var btn = document.getElementById('dy-meld-submit-btn');
  if (!btn) return;
  var andersChecked = anders && anders.checked;
  var tekstveld = tekst ? tekst.value.trim() : '';
  var geldig = checked.length > 0 && (!andersChecked || tekstveld.length > 0);
  btn.disabled = !geldig;
  // Tekstveld required indicator
  if (tekst) tekst.classList.toggle('dy-meld-textarea-verplicht', andersChecked && tekstveld.length === 0);
};

DY._verstuurMelding = function(content) {
  var checked     = Array.from(document.querySelectorAll('#dy-meld-modal input[name="meld"]:checked')).map(function(c){ return c.value; });
  var ernstEl     = document.querySelector('#dy-meld-modal input[name="ernst"]:checked');
  var tekstEl     = document.getElementById('dy-meld-tekst');
  var toelichting = tekstEl ? tekstEl.value.trim() : '';
  var ernst       = ernstEl ? ernstEl.value : '';
  var uid         = DY.user ? DY.user.uid : 'gast';
  var naam        = DY.user ? (DY.user.displayName || DY.user.email || uid) : 'gast';
  var ts          = new Date();

  // Genereer uniek ticketnummer via localStorage counter (geen Firestore rules nodig)
  var _n = parseInt(localStorage.getItem('dy_ticket_counter') || '2001', 10);
  _n = isNaN(_n) ? 2001 : Math.max(_n, 2001);
  _n += 1;
  localStorage.setItem('dy_ticket_counter', String(_n));
  var ticket = 'DY' + _n;

  // Sla op in Firestore
  var meldData = {
    ticket:       ticket,
    reporterUid:  uid,
    reporterNaam: naam,
    contentId:    content.id   || '',
    contentUid:   content.uid  || '',
    contentNaam:  content.naam || '',
    redenen:      checked,
    toelichting:  toelichting,
    ernst:        ernst,
    status:       'open',
    ts:           ts.toISOString()
  };

  if (DY.db) {
    DY.db.collection('meldingen').add(meldData).catch(function(e) {
    });
  }

  // Mail opbouwen en verzenden
  var onderwerp = encodeURIComponent('Nieuwe rapportmelding - ' + ticket);
  var mailBody  = encodeURIComponent(
    'Ticketnummer: ' + ticket + '\n' +
    'Tijdstip: ' + ts.toLocaleString('nl-NL') + '\n\n' +
    'INHOUD\n' +
    'Content ID: ' + (content.id   || '-') + '\n' +
    'Auteur:     ' + (content.naam || '-') + '\n\n' +
    'REDENEN\n' +
    checked.map(function(r){ return '  • ' + r; }).join('\n') + '\n\n' +
    'Ernst: ' + (ernst || 'Niet opgegeven') + '\n\n' +
    (toelichting ? 'Toelichting:\n' + toelichting + '\n\n' : '') +
    'Gemeld door: ' + naam + ' (UID: ' + uid + ')\n'
  );

  var mailLink = document.createElement('a');
  mailLink.href = 'mailto:info@doubleyousmallandtall.nl?subject=' + onderwerp + '&body=' + mailBody;
  mailLink.style.display = 'none';
  document.body.appendChild(mailLink);
  mailLink.click();
  setTimeout(function(){ if (mailLink.parentNode) mailLink.parentNode.removeChild(mailLink); }, 500);

  // Bevestiging tonen
  var submitBtn = document.getElementById('dy-meld-submit-btn');
  var okDiv     = document.getElementById('dy-meld-bevestiging');
  var okTekst   = document.getElementById('dy-meld-ok-tekst');
  if (submitBtn) { submitBtn.disabled = true; submitBtn.style.display = 'none'; }
  if (okTekst)   { okTekst.textContent = ticket + ' - Bedankt voor je melding.'; }
  if (okDiv)     { okDiv.style.display = 'flex'; }

  // Sluit modal na 2.5s
  setTimeout(function() {
    DY._sluitMeldModal();
  }, 2500);
};



// ══════════════════════════════════════════════════════════════════
// ADMIN PANEL - Paskamerpraat
// Toegang: alleen admin gebruikers
// ══════════════════════════════════════════════════════════════════

DY._ADMIN_EMAILS = ['williamdevriesis@gmail.com'];

DY._isAdmin = function() {
  return !!(DY.user && DY.user.email && DY._ADMIN_EMAILS.includes(DY.user.email.toLowerCase()));
};

DY._adminListeners = {}; // actieve realtime listeners

DY._stopAdminListeners = function() {
  Object.values(DY._adminListeners).forEach(function(unsub) {
    try { if (typeof unsub === 'function') unsub(); } catch(e) {}
  });
  DY._adminListeners = {};
};

// ── Admin renderer ───────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════
// KAI ACTIVITY LOGGER - async, non-blocking, fire-and-forget
// Alle outfit events worden gelogd naar Firestore kai_events collection
// Structuur: { userId, ts, eventType, payload }
// ══════════════════════════════════════════════════════════════════

DY._kaiLog = function(eventType, payload) {
  if (!DY.user || !DY.user.uid || !DY.db) return;
  try {
    var record = {
      eventId:   'ev_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
      userId:    DY.user.uid,
      userName:  DY._dyGetUserNaam(),
      sessionId: DY._kaiVergSessionId || (window._dySessionId = window._dySessionId || ('s_' + Date.now())),
      ts:        Date.now(),
      eventType: eventType,
      source:    'frontend',
      status:    'success',
      payload:   payload || {}
    };
    var _retries = 0;
    function _schrijf() {
      DY.db.collection('kai_events').add(record).catch(function(e) {
        if (_retries < 2) { _retries++; setTimeout(_schrijf, 1500 * _retries); }
      });
    }
    _schrijf();
  } catch(e) {}
};


// ── Admin Tab: Activiteit Log ─────────────────────────────────────
DY._adminTabActiviteit = function(el) {
  el.innerHTML =
    '<div class="dy-adm-act-wrap">' +
      '<h2 class="dy-adm-sectie-titel">📊 Outfit Activiteit Log</h2>' +

      // Filter balk
      '<div class="dy-adm-act-filters">' +
        '<input type="text" id="adm-act-uid" placeholder="Zoek op gebruiker ID of naam..." ' +
          'class="dy-adm-input" style="flex:1" oninput="DY._adminActZoek()">' +
        '<select id="adm-act-type" class="dy-adm-select" onchange="DY._adminActZoek()">' +
          '<option value="">Alle events</option>' +
          '<option value="analysis">Analyses</option>' +
          '<option value="compare">Vergelijkingen</option>' +
          '<option value="interaction">Interacties</option>' +
          '<option value="feedback">🤔 Bijna-feedback</option>' +
        '</select>' +
      '</div>' +

      // Resultaten
      '<div id="adm-act-resultaten" class="dy-adm-act-lijst">' +
        '<p class="dy-adm-lege-staat">Voer een gebruiker ID in om activiteit te laden.</p>' +
      '</div>' +
    '</div>';

  // Initieel: laad laatste 50 events van alle gebruikers
  DY._adminActLaad('', '');
};

DY._adminActZoek = function() {
  var uid = (document.getElementById('adm-act-uid') || {}).value || '';
  var type = (document.getElementById('adm-act-type') || {}).value || '';
  DY._adminActLaad(uid.trim(), type);
};

DY._adminActLaad = function(zoekTerm, eventType) {
  var el = document.getElementById('adm-act-resultaten');
  if (!el) return;
  el.innerHTML = '<div class="dy-adm-laden">Laden...</div>';

  // Laad beide collections: kai_events en outfit_feedback
  var collection = (document.getElementById('adm-act-type') || {}).value === 'feedback'
    ? 'outfit_feedback'
    : 'kai_events';
  var query = DY.db.collection(collection)
    .orderBy('ts', 'desc')
    .limit(100);

  if (eventType) query = query.where('eventType', '==', eventType);

  query.get().then(function(snap) {
    if (!snap.docs.length) {
      el.innerHTML = '<p class="dy-adm-lege-staat">Geen activiteit gevonden.</p>';
      return;
    }

    // Filter op zoekterm (client-side op userId)
    var docs = snap.docs;
    if (zoekTerm) {
      docs = docs.filter(function(d) {
        var _uid = d.data().userId || '';
        var _email = d.data().email || '';
        var _naam = d.data().displayName || d.data().naam || '';
        var _q = zoekTerm.toLowerCase();
        return _uid.toLowerCase().indexOf(_q) >= 0 ||
               _email.toLowerCase().indexOf(_q) >= 0 ||
               _naam.toLowerCase().indexOf(_q) >= 0;
      });
    }

    if (!docs.length) {
      el.innerHTML = '<p class="dy-adm-lege-staat">Geen resultaten voor "' + DY._esc(zoekTerm) + '".</p>';
      return;
    }

    // Groepeer per gebruiker
    var perUser = {};
    docs.forEach(function(d) {
      var data = d.data();
      var uid = data.userId || 'onbekend';
      if (!perUser[uid]) perUser[uid] = [];
      perUser[uid].push({ id: d.id, ...data });
    });

    var html = '';
    Object.keys(perUser).forEach(function(uid) {
      var events = perUser[uid];
      html +=
        '<div class="dy-adm-act-user-blok">' +
          '<div class="dy-adm-act-user-header" onclick="this.nextElementSibling.classList.toggle(\'open\')">' +
            '<span class="dy-adm-act-uid">' + DY._esc(uid.substring(0, 20)) + '...</span>' +
            '<span class="dy-adm-act-count">' + events.length + ' events</span>' +
            '<span class="dy-adm-act-chevron">▼</span>' +
          '</div>' +
          '<div class="dy-adm-act-events">' +
            events.map(function(ev) {
              var dt = new Date(ev.ts).toLocaleString('nl-NL');
              var typeKleur = {
                analysis: '#2d7a4e', compare: '#c67d06',
                interaction: '#4169e1', upload: '#888'
              }[ev.eventType] || '#888';
              var payloadStr = JSON.stringify(ev.payload || {}, null, 2);
              return '<div class="dy-adm-act-event">' +
                '<div class="dy-adm-act-event-header">' +
                  '<span class="dy-adm-act-badge" style="background:' + typeKleur + '">' + DY._esc(ev.eventType) + '</span>' +
                  '<span class="dy-adm-act-ts">' + DY._esc(dt) + '</span>' +
                '</div>' +
                '<pre class="dy-adm-act-payload">' + DY._esc(payloadStr) + '</pre>' +
              '</div>';
            }).join('') +
          '</div>' +
        '</div>';
    });

    el.innerHTML = html;
  }).catch(function(e) {
    if (el) el.innerHTML = '<p class="dy-adm-fout">Fout bij laden: ' + DY._esc(e.message) + '</p>';
  });
};


DY.renderAdmin = function() {
  if (!DY._isAdmin()) {
    DY.navigeer('feed');
    return;
  }
  var main = document.getElementById('dy-main');
  main.innerHTML =
    '<div class="dy-admin-wrap">' +
      '<div class="dy-vr-header"><div class="dy-vr-header-inner">' +
        '<div>' +
          '<button class="dy-back-btn" onclick="DY.terug()" style="margin-bottom:var(--sp-2);color:rgba(252,248,239,0.7)" data-testid="admin-terug-btn">← Terug</button>' +
          '<div class="dy-feed-merk-label">Paskamerpraat</div>' +
          '<h1 class="dy-vr-titel">Admin <em>Dashboard</em></h1>' +
        '</div>' +
      '</div></div>' +
      // Tabs
      '<div class="dy-admin-tabs">' +
        '<button class="dy-admin-tab actief" onclick="DY._adminTab(this,&quot;overzicht&quot;)">Overzicht</button>' +
        '<button class="dy-admin-tab" onclick="DY._adminTab(this,&quot;gebruikers&quot;)">Gebruikers</button>' +
        '<button class="dy-admin-tab" onclick="DY._adminTab(this,&quot;pwa&quot;)">PWA</button>' +
        '<button class="dy-admin-tab" onclick="DY._adminTab(this,&quot;mel&quot;)">💰 Monetization</button>' +
        '<button class="dy-admin-tab" onclick="DY._adminTab(this,&quot;activiteit&quot;)">📊 Activiteit</button>' +
      '</div>' +
      '<div id="dy-admin-content" class="dy-admin-content"></div>' +
    '</div>';

  DY._adminTab(document.querySelector('.dy-admin-tab.actief'), 'overzicht');
};

DY._adminTab = function(btn, tabId) {
  if (!btn) return;
  document.querySelectorAll('.dy-admin-tab').forEach(function(t) { t.classList.remove('actief'); });
  btn.classList.add('actief');
  DY._stopAdminListeners();
  var content = document.getElementById('dy-admin-content');
  if (tabId === 'overzicht') DY._adminTabOverzicht(content);
  else if (tabId === 'gebruikers') DY._adminTabGebruikers(content);
  else if (tabId === 'pwa') DY._adminTabPWA(content);
  else if (tabId === 'activiteit') DY._adminTabActiviteit(content);
};

// ── Tab: Overzicht (realtime KPI's) ─────────────────────────────
DY._adminTabOverzicht = function(el) {
  el.innerHTML =
    '<div class="dy-admin-kpi-grid">' +
      '<div class="dy-admin-kpi" id="kpi-users"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">Gebruikers</div></div>' +
      '<div class="dy-admin-kpi" id="kpi-stories"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">Verhalen</div></div>' +
      '<div class="dy-admin-kpi" id="kpi-reviews"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">Reviews</div></div>' +
      '<div class="dy-admin-kpi" id="kpi-pwa-install"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">PWA installs</div></div>' +
    '</div>' +
    '<div class="dy-admin-sectie-titel">Realtime actief</div>' +
    '<div id="dy-admin-online-list" class="dy-admin-online-list"><div class="dy-admin-laden">Laden…</div></div>';

  if (!DY.db) return;

  // Realtime: users count
  DY._adminListeners.users = DY.db.collection('users')
    .onSnapshot(function(snap) {
      var el = document.getElementById('kpi-users');
      if (el) el.querySelector('.dy-admin-kpi-val').textContent = snap.size;
    }, function() {});

  // Realtime: stories count
  DY._adminListeners.stories = DY.db.collection('stories')
    .onSnapshot(function(snap) {
      var el = document.getElementById('kpi-stories');
      if (el) el.querySelector('.dy-admin-kpi-val').textContent = snap.size;
    }, function() {});

  // Realtime: reviews count
  DY._adminListeners.reviews = DY.db.collection('reviews')
    .onSnapshot(function(snap) {
      var el = document.getElementById('kpi-reviews');
      if (el) el.querySelector('.dy-admin-kpi-val').textContent = snap.size;
    }, function() {});

  // Realtime: PWA installs count
  DY._adminListeners.pwaCount = DY.db.collection('pwa_events')
    .where('type', '==', 'installed')
    .onSnapshot(function(snap) {
      var el = document.getElementById('kpi-pwa-install');
      if (el) el.querySelector('.dy-admin-kpi-val').textContent = snap.size;
    }, function() {});

  // v60.1.37: cache voor users-collection lookups (vermijdt UID-codes in UI)
  if (!DY._adminUserCache) DY._adminUserCache = {};

  // Realtime: online users (realtime_status)
  DY._adminListeners.online = DY.db.collection('realtime_status')
    .where('online', '==', true)
    .onSnapshot(function(snap) {
      var listEl = document.getElementById('dy-admin-online-list');
      if (!listEl) return;
      if (snap.empty) {
        listEl.innerHTML = '<p class="dy-admin-leeg">Niemand online</p>';
        return;
      }
      var html = '';
      (snap && snap.docs ? snap.docs : []).forEach(function(doc) {
        var d = doc.data();
        // v60.1.37: nooit UID-codes tonen, altijd leesbare naam.
        // - displayName uit realtime_status (logged-in users)
        // - "Gast" voor anonieme users
        // - "Onbekend" als laatste fallback (cache lookup vult later in)
        var naam;
        if (d.displayName) {
          naam = d.displayName;
        } else if (d.isAnonymous) {
          naam = 'Gast';
        } else if (DY._adminUserCache[doc.id]) {
          naam = DY._adminUserCache[doc.id];
        } else {
          naam = 'Onbekend';
          // Async lookup + DOM update
          (function(uid) {
            DY.db.collection('users').doc(uid).get().then(function(u) {
              if (!u.exists) return;
              var nm = u.data().displayName || (u.data().email && u.data().email.split('@')[0]) || 'Onbekend';
              DY._adminUserCache[uid] = nm;
              var span = document.querySelector('[data-admin-naam-uid="' + uid + '"]');
              if (span) span.textContent = nm;
            }).catch(function(){});
          })(doc.id);
        }
        var route = d.route || '-';
        var device = d.device || '-';
        var ts = d.lastSeenMs ? new Date(d.lastSeenMs).toLocaleTimeString('nl-NL', {hour:'2-digit',minute:'2-digit'}) : '-';
        html += '<div class="dy-admin-online-rij">' +
          '<span class="dy-admin-online-dot"></span>' +
          '<span class="dy-admin-online-naam" data-admin-naam-uid="' + DY.escapeHtml(doc.id) + '">' + DY.escapeHtml(naam) + '</span>' +
          '<span class="dy-admin-online-tijd">' + ts + '</span>' +
          '<span class="dy-admin-online-route">/' + DY.escapeHtml(route) + '</span>' +
          '<span class="dy-admin-online-device">' + DY.escapeHtml(device) + '</span>' +
        '</div>';
      });
      listEl.innerHTML = html;
    }, function() {
      var listEl = document.getElementById('dy-admin-online-list');
      if (listEl) listEl.innerHTML = '<p class="dy-admin-leeg">Geen realtime data</p>';
    });
};

// ── Tab: Gebruikers ──────────────────────────────────────────────
DY._adminTabGebruikers = function(el) {
  el.innerHTML = '<div class="dy-admin-laden">Laden…</div>';
  if (!DY.db) return;

  DY._adminListeners.usersTable = DY.db.collection('users')
    .orderBy('createdAt', 'desc')
    .limit(50)
    .onSnapshot(function(snap) {
      var content = document.getElementById('dy-admin-content');
      if (!content) return;
      // v60.1.37: wrap tabel in horizontal-scroll container voor mobile
      var html = '<div class="dy-admin-tabel-wrap"><table class="dy-admin-tabel"><thead><tr>' +
        '<th>Naam</th><th>Email</th><th>Maat</th><th>Lengte</th><th>DSP</th><th>Aangemeld</th>' +
      '</tr></thead><tbody>';
      (snap && snap.docs ? snap.docs : []).forEach(function(doc) {
        var d = doc.data();
        // v60.1.37: fallback chain voor naam - nooit UID-code tonen
        var naamRaw = d.displayName
          || (d.email ? d.email.split('@')[0] : null)
          || (d.naam || null)
          || 'Onbekend';
        var naam = DY.escapeHtml(naamRaw);
        var email = DY.escapeHtml(d.email || '-');
        var maat = DY.escapeHtml(DY._normBouw ? DY._normBouw(d.bouw || '-') : (d.bouw || '-'));
        var lengte = d.lengte ? d.lengte + 'cm' : '-';
        var dsp = d.dsp_lifetime || 0;
        var ts = d.createdAt ? (d.createdAt.toDate ? d.createdAt.toDate().toLocaleDateString('nl-NL') : '-') : '-';
        html += '<tr><td>' + naam + '</td><td>' + email + '</td><td>' + maat + '</td>' +
          '<td>' + lengte + '</td><td>' + dsp + '</td><td>' + ts + '</td></tr>';
      });
      html += '</tbody></table></div>';
      content.innerHTML = html;
    }, function() {
      var content = document.getElementById('dy-admin-content');
      if (content) content.innerHTML = '<p class="dy-admin-leeg">Geen data beschikbaar</p>';
    });
};

// ── Tab: PWA Installaties ────────────────────────────────────────
DY._adminTabPWA = function(el) {
  el.innerHTML =
    '<div class="dy-admin-kpi-grid">' +
      '<div class="dy-admin-kpi" id="pwa-kpi-total"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">Totaal installs</div></div>' +
      '<div class="dy-admin-kpi" id="pwa-kpi-android"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">Android</div></div>' +
      '<div class="dy-admin-kpi" id="pwa-kpi-ios"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">iOS</div></div>' +
      '<div class="dy-admin-kpi" id="pwa-kpi-removed"><div class="dy-admin-kpi-val">-</div><div class="dy-admin-kpi-lbl">Verwijderd</div></div>' +
    '</div>' +
    '<div class="dy-admin-sectie-titel">Recente PWA events</div>' +
    '<div id="dy-admin-pwa-list" class="dy-admin-pwa-list"><div class="dy-admin-laden">Laden…</div></div>';

  if (!DY.db) return;

  // v60.1.37: gedeelde user-cache (zelfde als overzicht tab)
  if (!DY._adminUserCache) DY._adminUserCache = {};

  // Realtime listener op pwa_events collectie
  DY._adminListeners.pwaEvents = DY.db.collection('pwa_events')
    .orderBy('ts', 'desc')
    .limit(50)
    .onSnapshot(function(snap) {
      // Tel per type
      var totals = { installed: 0, removed: 0, android: 0, ios: 0 };
      var rows = '';
      (snap && snap.docs ? snap.docs : []).forEach(function(doc) {
        var d = doc.data();
        if (d.type === 'installed') totals.installed++;
        if (d.type === 'removed') totals.removed++;
        if (d.platform === 'android') totals.android++;
        if (d.platform === 'ios') totals.ios++;
        var ts = d.ts ? new Date(d.ts).toLocaleString('nl-NL', {day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}) : '-';
        var icon = d.type === 'installed' ? '✅' : '🗑';
        // v60.1.37: toon username i.p.v. UID-code. Async lookup + DOM patch.
        var uidLabel;
        if (!d.uid) {
          uidLabel = 'Gast';
        } else if (DY._adminUserCache[d.uid]) {
          uidLabel = DY._adminUserCache[d.uid];
        } else {
          uidLabel = 'Laden…';
          (function(uid) {
            DY.db.collection('users').doc(uid).get().then(function(u) {
              if (!u.exists) {
                DY._adminUserCache[uid] = 'Gast';
              } else {
                var nm = u.data().displayName || (u.data().email && u.data().email.split('@')[0]) || 'Onbekend';
                DY._adminUserCache[uid] = nm;
              }
              document.querySelectorAll('[data-admin-pwa-uid="' + uid + '"]').forEach(function(s){ s.textContent = DY._adminUserCache[uid]; });
            }).catch(function(){});
          })(d.uid);
        }
        rows += '<div class="dy-admin-pwa-rij">' +
          '<span>' + icon + '</span>' +
          '<span>' + DY.escapeHtml(d.type || '-') + '</span>' +
          '<span>' + DY.escapeHtml(d.platform || '-') + '</span>' +
          '<span data-admin-pwa-uid="' + DY.escapeHtml(d.uid || '') + '">' + DY.escapeHtml(uidLabel) + '</span>' +
          '<span class="dy-admin-pwa-ts">' + ts + '</span>' +
        '</div>';
      });
      // Update KPI's
      var setKpi = function(id, val) {
        var el = document.getElementById(id);
        if (el) el.querySelector('.dy-admin-kpi-val').textContent = val;
      };
      setKpi('pwa-kpi-total', totals.installed);
      setKpi('pwa-kpi-android', totals.android);
      setKpi('pwa-kpi-ios', totals.ios);
      setKpi('pwa-kpi-removed', totals.removed);
      var listEl = document.getElementById('dy-admin-pwa-list');
      if (listEl) listEl.innerHTML = rows || '<p class="dy-admin-leeg">Nog geen events</p>';
    }, function() {
      var listEl = document.getElementById('dy-admin-pwa-list');
      if (listEl) listEl.innerHTML = '<p class="dy-admin-leeg">Geen data</p>';
    });
};

