DY._melLaadStats = async function() {
  if (!DY.db) return;
  try {
    var collections = [
    ];
    for (var i = 0; i < collections.length; i++) {
      try {
        var snap = await DY.db.collection(collections[i].col).limit(500).get();
        var el = document.getElementById(collections[i].id);
        if (el) el.textContent = snap.size + (snap.size === 500 ? '+' : '');
      } catch(e) {}
    }
  } catch(e) {}
};





DY.trackPWAEvent = function(type) {
  if (!DY.db) return;
  var ua = navigator.userAgent || '';
  var platform = /iphone|ipad|ipod/i.test(ua) ? 'ios' : /android/i.test(ua) ? 'android' : 'desktop';
  DY.db.collection('pwa_events').add({
    type: type,           // 'installed' | 'removed'
    platform: platform,
    uid: (DY.user && DY.user.uid) || null,
    ts: Date.now(),
    ua: ua.slice(0, 120)
  }).catch(function() {});
};

