// Auth timeout: als na 2s geen auth response, render als gast
window._dyAuthTimeout = setTimeout(function() {
  if (!DY.authKlaar) {
    DY.authKlaar = true;
    if (!document.getElementById('dy-main').innerHTML || 
        document.getElementById('dy-main').innerHTML.trim().length < 50) {
      DY.pagina = null;
      try { DY.toonPagina('feed'); } catch(e) {}
    }
  }
}, 2000);

DY.debounce = function(fn, ms) {
  var t; return function() { var a=arguments,c=this; clearTimeout(t); t=setTimeout(function(){fn.apply(c,a);},ms||300); };
};



