DY._kaiWhyItWorksHTML = function(a) {
  if (!a) return '';

  var items = [
    {
      icoon: '🎨',
      titel: 'Kleur',
      score: a.harmonie_score || 0,
      uitleg: a.harmonie_type
        ? 'Het kleurschema is <strong>' + a.harmonie_type + '</strong>. ' +
          (a.harmonie_score >= 75
            ? 'De kleuren versterken elkaar - dat geeft de outfit samenhang.'
            : a.harmonie_score >= 55
            ? 'Er is een goed kleurritme, met ruimte voor meer contrast.'
            : 'De kleuren werken nog niet optimaal samen.')
        : 'Kleuranalyse beschikbaar na analyse.'
    },
    {
      icoon: '⚖️',
      titel: 'Balans',
      score: a.balans_score || 0,
      uitleg: a.balans_score >= 75
        ? 'De verdeling van lichte en donkere tinten is evenwichtig - geen enkel deel domineert te veel.'
        : a.balans_score >= 55
        ? 'De outfit heeft een redelijke balans. Iets meer aandacht voor proportie kan het verbeteren.'
        : 'De balans verdient aandacht - één kleur of stuk domineert nu te sterk.'
    },
    {
      icoon: '✂️',
      titel: 'Stijl',
      score: 80,
      uitleg: a.stijl
        ? 'De outfit valt in het genre <strong>' + a.stijl + '</strong>. ' +
          (a.positief && a.positief[0] ? a.positief[0] : 'Een consistente stijl maakt de look herkenbaar.')
        : 'Stijlanalyse beschikbaar na analyse.'
    },
    {
      icoon: '🌟',
      titel: 'Contrast',
      score: a.contrast_score || 0,
      uitleg: a.contrast_score >= 75
        ? 'Het contrast trekt de aandacht op de juiste manier - je outfit valt op zonder te schreeuwen.'
        : a.contrast_score >= 55
        ? 'Het contrast is subtiel. Iets meer verschil tussen donker en licht kan de outfit scherper maken.'
        : 'Weinig contrast - de outfit kan daardoor vlak overkomen. Probeer een accentkleur toe te voegen.'
    }
  ];

  return items.map(function(item) {
    var scoreKleur = item.score >= 75 ? '#2d7a4e' : item.score >= 55 ? 'var(--clay)' : '#c0392b';
    var breedte = Math.min(100, Math.max(0, item.score));
    return '<div class="dy-kai-why-item">' +
      '<div class="dy-kai-why-header">' +
        '<span class="dy-kai-why-icoon">' + item.icoon + '</span>' +
        '<span class="dy-kai-why-titel">' + item.titel + '</span>' +
        '<div class="dy-kai-why-score-bar">' +
          '<div class="dy-kai-why-score-fill" style="width:' + breedte + '%;background:' + scoreKleur + '"></div>' +
        '</div>' +
        '<span class="dy-kai-why-score-getal" style="color:' + scoreKleur + '">' + item.score + '</span>' +
      '</div>' +
      '<p class="dy-kai-why-uitleg">' + item.uitleg + '</p>' +
    '</div>';
  }).join('');
};


DY._kaiStijladviesPanel = function() {
  var a = DY._kleurenAI && DY._kleurenAI.analyseResultaat;
  var kd = (a && a.kleurenData) ||
           (DY._kleurenAI && DY._kleurenAI.kleurenDataCache) ||
           { kleuren: [] };
  var url = DY._kleurenAI && DY._kleurenAI.analyseURL;

  if (!a) {
    return '<div class="dy-kai-leeg">' +
      '<p>Analyseer eerst een outfit via de Analyse tab.</p>' +
      '<p class="dy-kai-leeg-sub">Daarna zie je hier je stijladvies.</p>' +
    '</div>';
  }

  // Uitgebreide kleurpalette (alle kleuren)
  var allKleuren = kd.kleuren.slice(0, 7);
  var paletteHTML = allKleuren.length > 0
    ? allKleuren.map(function(k) {
        return '<div class="dy-kai-sa-kleur-item">' +
          '<div class="dy-kai-sa-bol" style="background:' + k.hex + '" title="' + k.naam + '">' +
            '<span class="dy-kai-sa-bol-pct">' + (k.pct||0) + '%</span>' +
          '</div>' +
          '<span class="dy-kai-sa-kleur-naam">' + k.naam + '</span>' +
          '<span class="dy-kai-sa-kleur-hex">' + k.hex + '</span>' +
        '</div>';
      }).join('')
    : '<p class="dy-kai-geen-kleuren">Upload een outfit voor je kleurpalet</p>';

  // Stijl categorisering visueel
  var stijlIconen = {
    casual: '👕', zakelijk: '👔', sportief: '🏃', elegant: '✨',
    streetwear: '🧢', bohemian: '🌿', minimalistisch: '⬜'
  };
  var stijl = a.stijl || 'casual';
  var stijlIcoon = stijlIconen[stijl] || '👗';

  // Harmonie type toelichting
  var harmonieUitleg = {
    'sterk contrast': 'Je kleuren staan ver van elkaar - dit trekt meteen de aandacht.',
    'vergelijkbare tinten': 'Je kleuren liggen dicht bij elkaar - dat oogt rustig en samenhangend.',
    'drie kleuren': 'Drie goed verdeelde kleuren - klassiek en uitgebalanceerd.',
    'een kleur': 'Één toon doorgetrokken - strak en effectief.',
    'zachte tegenstelling': 'Subtiel contrast - chic en verfijnd.',
    'accentkleur': 'Een kleur springt eruit - geeft karakter aan je look.'
  };
  var harmonieType = a.harmonie_type || '';
  var harmonieUitlegTekst = harmonieUitleg[harmonieType] || '';

  // Styling tips op basis van stijl + seizoen
  var tipMap = {
    casual:          ['Voeg een statement accessoire toe voor meer karakter', 'Een laag extra (vest of overshirt) verhoogt de look'],
    zakelijk:        ['Zorg dat de schoenen matchen met je riem of tas', 'Een strak gestreken overhemd maakt het af'],
    sportief:        ['Kies schoenen die functioneel én stijlvol zijn', 'Monochroom sportief oogt altijd goed'],
    elegant:         ['Minder is meer - kies één statement stuk', 'Zorg voor een goede pasvorm, dat is het fundament'],
    streetwear:      ['Oversized pieces werken het best als de rest fitted is', 'Sneakers maken of breken een streetwear look'],
    bohemian:        ['Lagen en texturen geven bohemian diepte', 'Accessoires in aardetinten completeren de look'],
    minimalistisch:  ['Focus op kwaliteit van stoffen, niet op prints', 'Neutrale basiskleuren zijn je beste investering']
  };
  var tips = tipMap[stijl] || tipMap.casual;
  var tipsHTML = tips.map(function(tip) {
    return '<div class="dy-kai-sa-tip"><span class="dy-kai-sa-tip-icoon">💡</span>' + DY._esc(tip) + '</div>';
  }).join('');

  // Poll sectie - was orphaned, nu correct geïntegreerd
  var heeftPollGespeeld = DY._kleurenAI._pollGespeeld;
  var pollHTML = heeftPollGespeeld
    ? '<p class="dy-kai-sa-poll-klaar">Je hebt al gestemd. Bedankt!</p>'
    : '<div class="dy-kai-sa-poll">' +
        '<p class="dy-kai-sa-poll-vraag">Zou jij deze outfit dragen</p>' +
        '<div class="dy-kai-sa-poll-knoppen">' +
          '<button class="dy-kai-poll-knop" id="kai-poll-ja" onclick="DY._kaiStemPollSA(\'Ja\')">👍 Ja</button>' +
          '<button class="dy-kai-poll-knop" id="kai-poll-nee" onclick="DY._kaiStemPollSA(\'Nee\')">👎 Nee</button>' +
          '<button class="dy-kai-poll-knop" id="kai-poll-bijna" onclick="DY._kaiStemPollSA(\'Bijna\')">🤔 Misschien</button>' +
        '</div>' +
      '</div>';

  return '<div class="dy-kai-stijladvies">' +

    // Stijl identiteit
    '<div class="dy-kai-sa-sectie dy-kai-sa-hero">' +
      '<div class="dy-kai-sa-stijl-badge">' +
        '<span class="dy-kai-sa-stijl-icoon">' + stijlIcoon + '</span>' +
        '<div>' +
          '<span class="dy-kai-sa-stijl-naam">' + stijl.charAt(0).toUpperCase() + stijl.slice(1) + '</span>' +
          '<span class="dy-kai-sa-stijl-label">Jouw stijl</span>' +
        '</div>' +
      '</div>' +
      (harmonieUitlegTekst ? '<p class="dy-kai-sa-harmonie-uitleg">' + DY._esc(harmonieUitlegTekst) + '</p>' : '') +
    '</div>' +

    // Volledig kleurpalet
    '<div class="dy-kai-sa-sectie">' +
      '<h3 class="dy-kai-sectie-titel">Jouw kleurenpalet</h3>' +
      '<div class="dy-kai-sa-palette">' + paletteHTML + '</div>' +
    '</div>' +

    // Styling tips
    '<div class="dy-kai-sa-sectie">' +
      '<h3 class="dy-kai-sectie-titel">Zo maak je het nóg beter</h3>' +
      '<div class="dy-kai-sa-tips">' + tipsHTML + '</div>' +
    '</div>' +

    // Why It Works - gedetailleerde uitleg per dimensie
    '<div class="dy-kai-sa-sectie">' +
      '<h3 class="dy-kai-sectie-titel">Waarom dit werkt</h3>' +
      '<div class="dy-kai-why-grid">' +
        DY._kaiWhyItWorksHTML(a) +
      '</div>' +
    '</div>' +

    // Poll
    '<div class="dy-kai-sa-sectie">' +
      pollHTML +
    '</div>' +

    // Acties
    '<div class="dy-kai-acties">' +
      '<button class="dy-kai-btn dy-kai-btn--primair" onclick="DY._kaiDeel()">📤 Deel je outfit</button>' +
      '<button class="dy-kai-btn dy-kai-btn--secundair" onclick="DY._kaiTab(document.querySelector(\'[data-tab=vergelijk]\'),\'vergelijk\')">Vergelijk</button>' +
    '</div>' +

  '</div>';
};

// ── Poll stem voor stijladvies tab ───────────────────────────────
// ── Feedback formulier HTML ───────────────────────────────────────
DY._kaiFeedbackFormulier = function(keuze) {
  var a = DY._kleurenAI && DY._kleurenAI.analyseResultaat;
  var stijl = a && a.stijl || '';
  var seizoen = a && a.seizoen || '';
  var outfitId = (DY._kleurenAI && DY._kleurenAI.analyseURL || '').substring(0, 60) || ('outfit_' + Date.now());

  return '<div class="dy-kai-feedback-module" id="kai-feedback-module" data-keuze="' + keuze + '" data-outfit="' + outfitId + '">' +

    // Header
    '<div class="dy-kai-fb-mod-header">' +
      '<span class="dy-kai-fb-mod-icoon">🤔</span>' +
      '<div>' +
        '<p class="dy-kai-fb-mod-titel">Wat maakte het bijna perfect?</p>' +
        '<p class="dy-kai-fb-mod-sub">Jouw feedback helpt ons beter worden</p>' +
      '</div>' +
    '</div>' +

    // Gestructureerde vragen
    '<div class="dy-kai-fb-sectie">' +
      '<p class="dy-kai-fb-vraag-label">Wat vond je bijna goed?</p>' +
      '<div class="dy-kai-fb-chips" id="kai-fb-chips-goed">' +
        ['De kleuren', 'De stijl', 'De combinatie', 'Het patroon', 'De balans'].map(function(opt) {
          return '<button type="button" class="dy-kai-fb-chip" onclick="this.classList.toggle(\'actief\')">' + opt + '</button>';
        }).join('') +
      '</div>' +
    '</div>' +

    '<div class="dy-kai-fb-sectie">' +
      '<p class="dy-kai-fb-vraag-label">Wat zou je anders willen?</p>' +
      '<div class="dy-kai-fb-chips" id="kai-fb-chips-anders">' +
        ['Andere kleur', 'Andere pasvorm', 'Ander seizoen', 'Minder contrast', 'Meer karakter'].map(function(opt) {
          return '<button type="button" class="dy-kai-fb-chip" onclick="this.classList.toggle(\'actief\')">' + opt + '</button>';
        }).join('') +
      '</div>' +
    '</div>' +

    // Vrij tekstveld
    '<div class="dy-kai-fb-sectie">' +
      '<p class="dy-kai-fb-vraag-label">Vertel het ons in eigen woorden</p>' +
      '<textarea id="kai-fb-vrij" class="dy-kai-fb-textarea" ' +
        'placeholder="Vertel ons wat je anders zou willen zien\u2026" ' +
        'oninput="DY._kaiFeedbackTeller(this)" ' +
        'rows="4" maxlength="2000"></textarea>' +
      '<span class="dy-kai-fb-teller" id="kai-fb-teller">0 / 2000</span>' +
    '</div>' +

    // Submit
    '<div class="dy-kai-fb-acties">' +
      '<button type="button" class="dy-kai-btn dy-kai-btn--goud" onclick="DY._kaiFeedbackVerstuur()">' +
        'Feedback verzenden' +
      '</button>' +
      '<button type="button" class="dy-kai-btn dy-kai-btn--ghost" onclick="DY._kaiFeedbackSla()">' +
        'Overslaan' +
      '</button>' +
    '</div>' +

  '</div>';
};

// ── Teller update bij typen ───────────────────────────────────────
DY._kaiFeedbackTeller = function(ta) {
  var t = document.getElementById('kai-fb-teller');
  if (t) t.textContent = (ta.value.length) + ' / 2000';
};

// ── Feedback versturen (non-blocking) ────────────────────────────
DY._kaiFeedbackVerstuur = function() {
  var module = document.getElementById('kai-feedback-module');
  if (!module) return;

  var keuze    = module.dataset.keuze || 'Misschien';
  var outfitId = module.dataset.outfit || '';

  // Haal geselecteerde chips op
  var goed   = Array.from(document.querySelectorAll('#kai-fb-chips-goed .dy-kai-fb-chip.actief')).map(function(b){return b.textContent;});
  var anders = Array.from(document.querySelectorAll('#kai-fb-chips-anders .dy-kai-fb-chip.actief')).map(function(b){return b.textContent;});
  var vrij   = (document.getElementById('kai-fb-vrij') || {}).value || '';

  var a = DY._kleurenAI && DY._kleurenAI.analyseResultaat;
  var payload = {
    userId:            DY.user && DY.user.uid || '',
    outfitId:          outfitId,
    timestamp:         Date.now(),
    decisionState:     keuze.toLowerCase(),
    structuredAnswers: {
      bijna_goed:    goed,
      wil_anders:    anders
    },
    outfitContext: {
      stijl:    a && a.stijl    || '',
      seizoen:  a && a.seizoen  || '',
      harmonie: a && a.harmonie_score || 0
    },
    freeText: vrij.trim()
  };

  // Non-blocking Firestore write
  if (DY.db && payload.userId) {
    DY.db.collection('outfit_feedback').add(payload).catch(function(){});
  }

  // Log als activiteit
  DY._kaiLog('interaction', {
    type:          'feedback_bijna',
    goed:          goed,
    anders:        anders,
    heeftVrijTekst: vrij.trim().length > 0
  });

  // Toon bevestiging (geen navigatie, geen state reset)
  if (module) {
    module.innerHTML =
      '<div class="dy-kai-fb-bedankt">' +
        '<span style="font-size:2rem">🙏</span>' +
        '<p class="dy-kai-fb-bedankt-titel">Bedankt voor je feedback!</p>' +
        '<p class="dy-kai-fb-bedankt-sub">Je helpt ons de app beter maken voor iedereen.</p>' +
      '</div>';
  }
};

// ── Feedback overslaan ────────────────────────────────────────────
DY._kaiFeedbackSla = function() {
  var module = document.getElementById('kai-feedback-module');
  if (!module) return;
  module.innerHTML =
    '<p style="text-align:center;color:var(--ink-muted);font-size:var(--t-sm);padding:var(--sp-2) 0">Overgeslagen.</p>';
};


DY._kaiStemPollSA = function(keuze) {
  if (!DY._kleurenAI) DY._kleurenAI = {};
  DY._kleurenAI._pollGespeeld = true;

  // Debounce - voorkom dubbele klik
  if (DY._kaiStemPollSA._bezig) return;
  DY._kaiStemPollSA._bezig = true;
  setTimeout(function() { DY._kaiStemPollSA._bezig = false; }, 400);

  var analyse = DY._kleurenAI.analyseResultaat || {};
  var poll = document.querySelector('.dy-kai-sa-poll');

  // Log interactie
  DY._kaiLog('interaction', {
    type:  'poll_outfit',
    keuze: keuze,
    stijl: analyse.stijl || ''
  });

  // ── JA: bedankt popup + positief signal ────────────────────────
  if (keuze === 'Ja') {
    // Update style profile - positief signal
    DY._styleProfileFeedback('ja', null, analyse);
    // Toon bedankt popup
    DY._kaiDankjewelPopup();
    // Vervang poll
    if (poll) {
      poll.innerHTML = '<p class="dy-kai-poll-bevestiging dy-kai-poll-bevestiging--ja">' +
        '👍 Geweldig! We leren van jouw stijlvoorkeur.' +
      '</p>';
    }
    return;
  }

  // ── BIJNA: bestaand feedback formulier ─────────────────────────
  if (keuze === 'Bijna') {
    if (poll) poll.innerHTML = DY._kaiFeedbackFormulier(keuze);
    return;
  }

  // ── NEE: toon "Waarom niet?" inline ────────────────────────────
  if (keuze === 'Nee') {
    // Disable knoppen
    document.querySelectorAll('.dy-kai-poll-knop').forEach(function(b) {
      b.disabled = true; b.style.opacity = '0.5';
    });
    if (!poll) return;

    poll.innerHTML =
      '<div class="dy-kai-nee-wrap">' +
        '<p class="dy-kai-nee-vraag">Waarom zou je deze outfit niet dragen?</p>' +
        '<div class="dy-kai-nee-chips">' +
          '<button class="dy-kai-nee-chip" type="button" onclick="DY._kaiNeeChip(this)">Past niet bij mijn stijl</button>' +
          '<button class="dy-kai-nee-chip" type="button" onclick="DY._kaiNeeChip(this)">Kleuren spreken me niet aan</button>' +
          '<button class="dy-kai-nee-chip" type="button" onclick="DY._kaiNeeChip(this)">Te gedurfd voor mij</button>' +
          '<button class="dy-kai-nee-chip" type="button" onclick="DY._kaiNeeChip(this)">Niet praktisch genoeg</button>' +
          '<button class="dy-kai-nee-chip" type="button" onclick="DY._kaiNeeChip(this)">Past niet bij mijn maat</button>' +
        '</div>' +
        '<textarea class="dy-kai-nee-input" id="kai-nee-tekst" maxlength="400" placeholder="Of schrijf het zelf..." rows="3" oninput="DY._kaiNeeInputCheck()"></textarea>' +
        '<div class="dy-kai-nee-teller"><span id="kai-nee-teller">0</span>/400</div>' +
        '<button class="dy-kai-nee-submit dy-btn-disabled" id="kai-nee-submit" type="button" disabled onclick="DY._kaiNeeSubmit()">Verstuur feedback</button>' +
      '</div>';
  }
};

// ── Chip selectie ──────────────────────────────────────────────────
DY._kaiNeeChip = function(chip) {
  // Toggle chip
  chip.classList.toggle('dy-kai-nee-chip--actief');
  // Sync naar textarea
  var actief = Array.from(document.querySelectorAll('.dy-kai-nee-chip--actief'))
    .map(function(c) { return c.textContent; });
  var input = document.getElementById('kai-nee-tekst');
  if (input) {
    input.value = actief.join(', ');
    DY._kaiNeeInputCheck();
  }
};

// ── Input validatie - submit alleen actief als er tekst is ─────────
DY._kaiNeeInputCheck = function() {
  var input = document.getElementById('kai-nee-tekst');
  var submit = document.getElementById('kai-nee-submit');
  var teller = document.getElementById('kai-nee-teller');
  if (!input || !submit) return;
  var len = input.value.trim().length;
  if (teller) teller.textContent = input.value.length;
  if (len > 0) {
    submit.disabled = false;
    submit.classList.remove('dy-btn-disabled');
  } else {
    submit.disabled = true;
    submit.classList.add('dy-btn-disabled');
  }
};

// ── Nee submit ────────────────────────────────────────────────────
DY._kaiNeeSubmit = function() {
  var input = document.getElementById('kai-nee-tekst');
  var reden = input ? input.value.trim() : '';
  if (!reden) return;

  var analyse = (DY._kleurenAI && DY._kleurenAI.analyseResultaat) || {};

  // Sla op in Firestore
  DY._kaiLog('outfit_feedback', {
    type:   'nee',
    reden:  reden,
    stijl:  analyse.stijl || '',
    seizoen: analyse.seizoen || '',
    harmonie_type: analyse.harmonie_type || '',
    scores: {
      harmonie: analyse.harmonie_score || 0,
      contrast: analyse.contrast_score || 0,
      balans:   analyse.balans_score || 0
    }
  });

  // Update style profile - negatief signal
  DY._styleProfileFeedback('nee', reden, analyse);

  // Vervang formulier met bevestiging
  var poll = document.querySelector('.dy-kai-sa-poll');
  if (poll) {
    poll.innerHTML = '<p class="dy-kai-poll-bevestiging dy-kai-poll-bevestiging--nee">' +
      '👎 Bedankt! We houden hier rekening mee.' +
    '</p>';
  }
};

// ── Bedankt popup bij JA ──────────────────────────────────────────
DY._kaiDankjewelPopup = function() {
  // Verwijder eventueel bestaande popup
  var bestaand = document.getElementById('kai-dankje-popup');
  if (bestaand) bestaand.remove();

  var popup = document.createElement('div');
  popup.id = 'kai-dankje-popup';
  popup.className = 'dy-kai-dankje-overlay';
  popup.innerHTML =
    '<div class="dy-kai-dankje-modal">' +
      '<div class="dy-kai-dankje-icoon">🙌</div>' +
      '<h3 class="dy-kai-dankje-titel">Bedankt voor je reactie!</h3>' +
      '<p class="dy-kai-dankje-sub">We leren van jouw stijlvoorkeuren.</p>' +
      '<button class="dy-kai-dankje-sluit" type="button" onclick="document.getElementById(\'kai-dankje-popup\').remove()">Sluiten</button>' +
    '</div>';

  // Sluit ook bij klik buiten modal
  popup.addEventListener('click', function(e) {
    if (e.target === popup) popup.remove();
  });

  document.body.appendChild(popup);

  // Auto-sluit na 3 seconden
  setTimeout(function() {
    var p = document.getElementById('kai-dankje-popup');
    if (p) p.remove();
  }, 3000);
};

// ── Style profile feedback signal ─────────────────────────────────
DY._styleProfileFeedback = function(type, reden, analyse) {
  if (!DY.user || !DY.db) return;
  try {
    var update = { bijgewerkt: Date.now() };
    if (type === 'ja') {
      update['gedrag.poll_ja'] = firebase.firestore.FieldValue.increment(1);
      if (analyse && analyse.stijl) update.laatste_positieve_stijl = analyse.stijl;
      if (analyse && analyse.harmonie_type) update.laatste_positieve_harmonie = analyse.harmonie_type;
    } else if (type === 'nee' && reden) {
      update['gedrag.poll_nee'] = firebase.firestore.FieldValue.increment(1);
      // Sla afwijzing op als rejection signal
      if (analyse && analyse.stijl) update.laatste_afwijzing_stijl = analyse.stijl;
      update.laatste_afwijzing_reden = reden.substring(0, 100);
    }
    DY.db.collection('users').doc(DY.user.uid)
      .collection('ai_style_profile').doc('profiel')
      .set(update, { merge: true })
      .catch(function() {});
    // Update in-memory
    if (DY._styleProfile) Object.assign(DY._styleProfile, update);
  } catch(e) {}
};


DY._kaiVergelijkPanel = function() {
  // Reset vergelijkdata alleen als het panel opnieuw gebouwd wordt zonder bestaande data
  // Behoud data als die al ingeladen is (bijv. na verhaalselecitie op andere tab)
  if (!DY._kaiVergData) DY._kaiVergData = { a: null, b: null };
  if (!DY._kaiVergSessionId) DY._kaiVergSessionId = 'sess_' + Date.now() + '_' + Math.random().toString(36).slice(2,8);
  // Kritieke null-check: voorkomt crash + redirect naar feed
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  var _isIngelogd = !!DY.profile;
  var _lockClass = _isIngelogd ? '' : ' dy-kai-ctx-locked';
  function slot(id, label) {
    var s = id;
    var isPrimair = s === 'a';
    return '<div class="dy-kai-verg-slot-wrap">' +
      '<input type="file" id="kai-verg-input-' + s + '" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" style="display:none" onchange="DY._kaiVergFoto(\'' + s + '\',this.files[0])">' +
      '<input type="file" id="kai-verg-camera-' + s + '" accept="image/*" capture="environment" style="display:none" onchange="DY._kaiVergFoto(\'' + s + '\',this.files[0])">' +
      '<div class="dy-kai-verg-slot" id="kai-verg-' + s + '" role="region" aria-label="Outfit ' + label + '">' +
        '<div class="dy-kai-verg-leeg dy-kai-verg-leeg--cards" id="kai-verg-leeg-' + s + '">' +

          // Label bovenaan, buiten de kaarten
          '<div class="dy-kvs-label-rij">' +
            '<span class="dy-kvs-badge dy-kvs-badge--' + (isPrimair ? 'a' : 'b') + '" style="' + (isPrimair ? 'background:#c67d06;color:#fff;border-radius:9px;' : 'background:rgba(198,125,6,0.20);color:#f5d78e;border:2.5px solid #c67d06;border-radius:9px;box-shadow:0 0 0 1px rgba(198,125,6,0.40);') + '">' + label + '</span>' +
            '<span class="dy-kvs-label-tekst" style="color:#fdf8f0;opacity:1;text-shadow:0 1px 3px rgba(0,0,0,0.6);">Outfit ' + label + '</span>' +
          '</div>' +

          // Drie keuzekaarten
          '<button type="button" class="dy-kvs-knop dy-kvs-knop--primair" onclick="event.stopPropagation();DY._kaiVergSlotKlik(\'' + s + '\')">' +
            '<span class="dy-kvs-knop-icoon">' +
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8.5" cy="8.5" r="1.5" fill="currentColor" stroke="none"/><path d="M21 15l-5-5L5 21" stroke-linecap="round"/></svg>' +
            '</span>' +
            '<span class="dy-kvs-knop-tekst">' +
              '<span class="dy-kvs-knop-label">Galerij</span>' +
              '<span class="dy-kvs-knop-sub" style="color:rgba(255,255,255,0.88);">Kies een foto</span>' +
            '</span>' +
            '<svg class="dy-kvs-pijl" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="14" height="14"><path d="M9 18l6-6-6-6"/></svg>' +
          '</button>' +

          '<button type="button" class="dy-kvs-knop dy-kvs-knop--sec" onclick="event.stopPropagation();DY._kaiVergCameraKlik(\'' + s + '\')">' +
            '<span class="dy-kvs-knop-icoon">' +
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" stroke-linecap="round"/><circle cx="12" cy="13" r="4"/></svg>' +
            '</span>' +
            '<span class="dy-kvs-knop-tekst">' +
              '<span class="dy-kvs-knop-label">Camera</span>' +
              '<span class="dy-kvs-knop-sub" style="color:rgba(253,248,240,0.82);">Maak een foto</span>' +
            '</span>' +
            '<svg class="dy-kvs-pijl" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="14" height="14"><path d="M9 18l6-6-6-6"/></svg>' +
          '</button>' +

          '<button type="button" class="dy-kvs-knop dy-kvs-knop--ter" onclick="event.stopPropagation();DY._kaiKiesVerhaal(\'vergelijk_' + s + '\')">' +
            '<span class="dy-kvs-knop-icoon">' +
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" stroke-linecap="round"/></svg>' +
            '</span>' +
            '<span class="dy-kvs-knop-tekst">' +
              '<span class="dy-kvs-knop-label">Verhaal</span>' +
              '<span class="dy-kvs-knop-sub" style="color:rgba(253,248,240,0.82);">Uit jouw feed</span>' +
            '</span>' +
            '<svg class="dy-kvs-pijl" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="14" height="14"><path d="M9 18l6-6-6-6"/></svg>' +
          '</button>' +

        '</div>' +
      '</div>' +
    '</div>';
  }
  // Context helpers
  function ctxChips(id, items, multi, stateKey) {
    var cur = (DY._kaiVergContext || {})[stateKey] || (multi ? [] : '');
    return items.map(function(item) {
      var aktief = multi
        ? (Array.isArray(cur) && cur.indexOf(item) > -1)
        : (cur === item);
      var cls = 'dy-kai-ctx-chip' + (aktief ? ' dy-kai-ctx-chip--aktief' : '');
      var handler = multi
        ? 'DY._kaiCtxToggle(\'' + stateKey + '\',\'' + item + '\',this)'
        : 'DY._kaiCtxSelect(\'' + stateKey + '\',\'' + item + '\',this)';
      return '<button type="button" class="' + cls + '" onclick="' + handler + '">' + item + '</button>';
    }).join('');
  }

  function mkSelect(id, placeholder, opties, stateKey) {
    var cur = (DY._kaiVergContext || {})[stateKey] || '';
    if (!_isIngelogd) {
      return '<div class="dy-ctx-dd dy-kai-ctx-locked">' +
        '<div class="dy-ctx-dd-trigger dy-ctx-dd-trigger--leeg">' +
          '<span class="dy-ctx-dd-val">' + placeholder + '</span>' +
          '<svg class="dy-ctx-dd-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="14" height="14"><path d="M6 9l6 6 6-6"/></svg>' +
        '</div></div>';
    }
    var optsHTML = '';
    for (var _i = 0; _i < opties.length; _i++) {
      var _o = opties[_i];
      var _ak = cur === _o;
      optsHTML += '<button type="button" class="dy-ctx-dd-opt' + (_ak ? ' dy-ctx-dd-opt--aktief' : '') + '" ' +
        'data-statekey="' + stateKey + '" data-ddid="' + id + '" data-val="' + _o + '" ' +
        'onclick="DY._kaiCtxDdKies(this)">' +
        _o + (_ak ? ' <span class="dy-ctx-dd-check">\u2713</span>' : '') +
      '</button>';
    }
    return '<div class="dy-ctx-dd" id="dy-ctx-dd-' + id + '">' +
      '<button type="button" class="dy-ctx-dd-trigger' + (!cur ? ' dy-ctx-dd-trigger--leeg' : '') + '" ' +
        'id="dy-ctx-dd-btn-' + id + '" ' +
        'onclick="event.preventDefault();event.stopPropagation();DY._kaiCtxDdToggle(\'' + id + '\')" ' +
        'aria-haspopup="listbox" aria-expanded="false">' +
        '<span class="dy-ctx-dd-val">' + (cur || placeholder) + '</span>' +
        '<svg class="dy-ctx-dd-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="14" height="14"><path d="M6 9l6 6 6-6"/></svg>' +
      '</button>' +
      '<div class="dy-ctx-dd-panel" id="dy-ctx-dd-panel-' + id + '" role="listbox" aria-hidden="true">' +
        optsHTML +
      '</div>' +
    '</div>';
  }

  function mkMultiChips(focusOpties) {
    var cur = (DY._kaiVergContext || {}).focus || [];
    return focusOpties.map(function(item) {
      var aktief = Array.isArray(cur) && cur.indexOf(item) > -1;
      return '<button type="button" class="dy-kai-ctx-chip' + (aktief ? ' dy-kai-ctx-chip--aktief' : '') + '" ' +
        'onclick="DY._kaiCtxToggle(\'focus\',\'' + item + '\',this)">' + item + '</button>';
    }).join('');
  }

  var gelegenheden = ['Casual','Werk','Date','Feest','Festival','Sport','Streetwear','Formeel','Travel','Bruiloft','Vakantie'];
  var uitstralingen = ['Minimalistisch','Luxe','Street','Clean','Opvallend','Sportief','Edgy','Elegant','Casual','Professioneel'];
  var focusOpties   = ['Pasvorm','Kleurcombinatie','Comfort','Seizoen','Lichaamsverhouding','Trendfactor','Materiaal'];
  var prioriteiten  = ['Stijl','Comfort','Uitstraling','Originaliteit','Balans'];

  var noteMemo = (DY._kaiVergContext || {}).note || '';

  return '<div class="dy-kai-vergelijk-rij">' +
    slot('a', 'A') +
    '<div class="dy-kai-verg-vs">VS</div>' +
    slot('b', 'B') +
  '</div>' +
  '<div class="dy-kai-ctx-wrap" id="dy-kai-ctx-wrap">' +
    '<div class="dy-kai-ctx-grid">' +
      '<div class="dy-kai-ctx-field">' +
        '<label class="dy-kai-ctx-label">Voor welke gelegenheid? <span class="dy-kai-ctx-req">*</span></label>' +
        mkSelect('occasion', 'Kies gelegenheid…', gelegenheden, 'occasion') +
      '</div>' +
      '<div class="dy-kai-ctx-field">' +
        '<label class="dy-kai-ctx-label">Gewenste uitstraling <span class="dy-kai-ctx-req">*</span></label>' +
        mkSelect('style', 'Kies uitstraling…', uitstralingen, 'style') +
      '</div>' +
      '<div class="dy-kai-ctx-field">' +
        '<label class="dy-kai-ctx-label">Wat is het belangrijkst? <span class="dy-kai-ctx-req">*</span></label>' +
        mkSelect('priority', 'Kies prioriteit…', prioriteiten, 'priority') +
      '</div>' +
    '</div>' +
    '<div class="dy-kai-ctx-field">' +
      '<label class="dy-kai-ctx-label">Let extra op <span class="dy-kai-ctx-multi-hint">(meerdere mogelijk)</span></label>' +
      '<div class="dy-kai-ctx-chips">' + mkMultiChips(focusOpties) + '</div>' +
    '</div>' +
    '<div class="dy-kai-ctx-field">' +
      '<label class="dy-kai-ctx-label">Extra wensen of opmerkingen</label>' +
      '<textarea id="dy-kai-ctx-note" class="dy-kai-ctx-note" rows="2" ' +
        'placeholder="Bijv. ik heb een hou van gedempte kleuren en wil de schouders benadrukken…" ' +
        'oninput="DY._kaiCtxNote(this.value)">' + noteMemo + '</textarea>' +
    '</div>' +
  '</div>' +
  '<div id="kai-vergelijk-resultaat" style="padding:0 var(--sp-3) var(--sp-8)"></div>';
};

// Context interacties
DY._kaiCtxSelect = function(key, val, btn) {
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '' };
  var isAktief = DY._kaiVergContext[key] === val;
  DY._kaiVergContext[key] = isAktief ? '' : val;
  // Update chip UI
  var wrap = btn.closest('.dy-kai-ctx-chips');
  if (wrap) wrap.querySelectorAll('.dy-kai-ctx-chip').forEach(function(c) {
    c.classList.toggle('dy-kai-ctx-chip--aktief', c.textContent === DY._kaiVergContext[key]);
  });
};

DY._kaiCtxToggle = function(key, val, btn) {
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  if (!Array.isArray(DY._kaiVergContext[key])) DY._kaiVergContext[key] = [];
  var idx = DY._kaiVergContext[key].indexOf(val);
  if (idx > -1) DY._kaiVergContext[key].splice(idx, 1);
  else DY._kaiVergContext[key].push(val);
  btn.classList.toggle('dy-kai-ctx-chip--aktief', DY._kaiVergContext[key].indexOf(val) > -1);
};

DY._kaiCtxSelectChange = function(key, val) {
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  DY._kaiVergContext[key] = val;
};

DY._kaiCtxNote = function(val) {
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  DY._kaiVergContext.note = val.slice(0, 280);
};

DY._kaiOpgeslagenPanel = function() {
  return '<div id="kai-opgeslagen-lijst" style="padding:var(--sp-3) var(--sp-3) var(--sp-8)"></div>';
};

// Foto gekozen - start analyse
DY._kaiFilterTekst = function(tekst) {
  if (!tekst) return tekst;
  // Verwijder hex codes (#rrggbb of #rgb)
  tekst = tekst.replace(/#[0-9a-fA-F]{3,6}\b/g, '');
  // Verwijder em-dashes, en-dashes en streepjes permanent - vervang door komma of spatie
  tekst = tekst.replace(/\s*[\u2014\u2013\u2012\u2011]\s*/g, ', ');
  // Verwijder ook literal --- en -- constructies
  tekst = tekst.replace(/\s*---?\s*/g, ', ');
  // Verwijder dubbele spaties en dubbele komma's na verwijdering
  tekst = tekst.replace(/,\s*,/g, ',').replace(/\s{2,}/g, ' ').trim();
  // Verwijder leidende/volgende komma's of haakjes
  tekst = tekst.replace(/^\s*[,;()]+\s*/, '').replace(/\s*[,;()]+\s*$/, '');
  return tekst;
};

// ── Haal afbeelding op als blob, probeert meerdere methoden ──────
// Methode 1: fetch met Firebase ID token (lost Firebase Storage CORS op)
// Methode 2: fetch zonder token
// Methode 3: geeft null terug (caller gebruikt img.src als fallback)
// ── Analyse URL cache - voorkomt dubbele AI calls ──────────────
// Cache: url → { analyse, kleurenData, ts }
// TTL: 10 minuten
DY._kaiCache = DY._kaiCache || {};
DY._kaiCacheTTL = 10 * 60 * 1000;

DY._kaiCacheGet = function(url) {
  var entry = DY._kaiCache[url];
  if (!entry) return null;
  if (Date.now() - entry.ts > DY._kaiCacheTTL) {
    delete DY._kaiCache[url];
    return null;
  }
  return entry;
};

DY._kaiCacheSet = function(url, analyse, kleurenData) {
  DY._kaiCache[url] = {
    analyse: analyse,
    kleurenData: kleurenData,
    ts: Date.now()
  };
};


DY._kaiHaalBlobOp = async function(url) {
  var methods = [];

  // Methode 1: met Firebase ID token
  try {
    var currentUser = firebase.auth().currentUser;
    if (currentUser) {
      var idToken = await currentUser.getIdToken(false);
      if (idToken) {
        methods.push({ headers: { 'Authorization': 'Firebase ' + idToken } });
      }
    }
  } catch(e) { /* auth niet beschikbaar */ }

  // Methode 2: zonder headers
  methods.push({});

  for (var i = 0; i < methods.length; i++) {
    try {
      var ctrl = new AbortController();
      var t = setTimeout(function() { ctrl.abort(); }, 12000);
      var opts = Object.assign({ signal: ctrl.signal }, methods[i].headers ? { headers: methods[i].headers } : {});
      var resp = await fetch(url, opts);
      clearTimeout(t);
      if (!resp.ok) continue;
      var blob = await resp.blob();
      if (blob.size >= 100) return blob;
    } catch(e) {
      if (e.name === 'AbortError') break; // timeout, stop proberen
      // CORS of netwerk error: probeer volgende methode
    }
  }
  return null; // alles mislukt
};

// ── Extraheer kleuren + base64 uit een blob ───────────────────────
DY._kaiVerwerkBlob = function(blob) {
  return new Promise(function(resolve) {
    var blobUrl = URL.createObjectURL(blob);
    var kleuren = null;
    var base64  = null;
    var done = 0;

    function check() {
      if (++done === 2) {
        URL.revokeObjectURL(blobUrl);
        resolve({ kleuren: kleuren || { kleuren: [], totaal: 0 }, base64: base64 });
      }
    }

    // Kleuren
    DY._kleurenVanURL(blobUrl, function(k) {
      kleuren = k;
      check();
    });

    // Base64
    var img = new Image();
    img.onload = function() {
      try {
        var c = document.createElement('canvas');
        var MAX = 512;
        var ratio = Math.min(MAX / img.naturalWidth, MAX / img.naturalHeight, 1);
        c.width  = Math.max(1, Math.round(img.naturalWidth  * ratio));
        c.height = Math.max(1, Math.round(img.naturalHeight * ratio));
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        base64 = (c.toDataURL('image/jpeg', 0.72).split(',')[1]) || null;
      } catch(e) { base64 = null; }
      check();
    };
    img.onerror = function() { check(); };
    img.src = blobUrl;
    setTimeout(function() { if (done < 2) { done = 1; check(); } }, 7000);
  });
};


DY._kaiAnalyseerURL = async function(photoUrl) {
  if (!DY._kleurenAI) DY._kleurenAI = {};
  if (DY._kleurenAI.analyseURL && DY._kleurenAI.analyseURL.startsWith('blob:')) {
    try { URL.revokeObjectURL(DY._kleurenAI.analyseURL); } catch(e) {}
  }

  DY._kleurenAI.analyseFoto      = { name: 'verhaal.jpg', size: 99999, type: 'image/jpeg', _isURL: true };
  DY._kleurenAI.analyseURL       = photoUrl;
  DY._kleurenAI.analyseResultaat = null;

  var _selfAbort = new AbortController();
  DY._kaiAnalyseAbort = _selfAbort;

  // ── STAP A: Instant - preview + skeleton (<50ms) ─────────────
  var inner = document.getElementById('kai-upload-inner');
  if (inner) inner.innerHTML =
    '<div class="dy-kai-preview-wrap">' +
      '<img src="' + DY._esc(photoUrl) + '" class="dy-kai-preview-img" alt="Gekozen outfit">' +
      '<button class="dy-kai-preview-wis" onclick="event.stopPropagation();DY._kaiWisAnalyse()" aria-label="Verwijder foto" type="button">\xd7</button>' +
    '</div>';

  var resultaat = document.getElementById('kai-analyse-resultaat');
  if (resultaat) {
    resultaat.innerHTML = '';
    resultaat.appendChild(DY._bouwWSpinner('Foto verwerken…'));
  }

  // ── STYLE PROFILE LADEN VOOR ANALYSE ─────────────────────────
  // Wacht op profile zodat match score direct beschikbaar is
  if (DY.profile && !DY._styleProfile) {
    try { await DY._styleProfileLaad(); } catch(e) {}
  }

  // ── CACHE CHECK: zelfde URL eerder geanalyseerd? ─────────────
  var cached = DY._kaiCacheGet(photoUrl);
  if (cached) {
    // Cache hit → direct resultaat tonen (perceived: instant)
    var cAnalyse = cached.analyse;
    cAnalyse.kleurenData = cached.kleurenData;
    DY._kleurenAI.analyseResultaat = cAnalyse;
    if (DY._kleurenAI.kleurenDataCache === undefined || cached.kleurenData.kleuren.length > 0) {
      DY._kleurenAI.kleurenDataCache = cached.kleurenData;
    }
    DY._kleurenAISlaOp({ type: 'analyse', analyse: cAnalyse });
    DY._kaiToonResultaat(cAnalyse);
    return;
  }

  // ── STAP B: Parallel - blob + kleuren (~300-600ms) ───────────
  var kleurenData = null;
  var base64      = null;

  // Start blob fetch (achtergrond) en toon intussen "kleuren laden" in skeleton
  var blobPromise = DY._kaiHaalBlobOp(photoUrl);

  var blob = await blobPromise;
  if (_selfAbort.signal.aborted) return;

  if (blob) {
    var verwerkt = await DY._kaiVerwerkBlob(blob);
    kleurenData = verwerkt.kleuren;
    base64      = verwerkt.base64;
  }

  // Fallback kleuren via canvas
  if (!kleurenData || !kleurenData.kleuren || !kleurenData.kleuren.length) {
    kleurenData = await new Promise(function(res) { DY._kleurenVanURL(photoUrl, res); });
  }

  if (_selfAbort.signal.aborted) return;

  var heeftKleuren = kleurenData && kleurenData.kleuren && kleurenData.kleuren.length > 0;
  if (!heeftKleuren) kleurenData = { kleuren: [], totaal: 0 };

  // ── PROGRESSIEVE UPDATE B: toon kleuren vóór AI klaar is ─────
  // Bouw een mini-resultaat met alleen kleuren (AI sectie = skeleton)
  if (heeftKleuren && resultaat) {
    var kd = kleurenData;
    var swatchHTML = kd.kleuren.slice(0, 5).map(function(k) {
      return '<div class="dy-kai-bol-wrap">' +
        '<div class="dy-kai-bol" style="background:' + k.hex + '" title="' + k.naam + '"></div>' +
        '<span class="dy-kai-bol-naam">' + k.naam + '</span>' +
        '<span class="dy-kai-bol-pct">' + (k.pct||0) + '%</span>' +
      '</div>';
    }).join('');

    resultaat.innerHTML =
      '<div class="dy-kai-resultaat dy-kai-resultaat--partial">' +
        '<div class="dy-kai-sectie">' +
          '<h3 class="dy-kai-sectie-titel">Kleuren in jouw outfit</h3>' +
          '<div class="dy-kai-palette">' + swatchHTML + '</div>' +
        '</div>' +
        '<div class="dy-kai-ai-laden" id="dy-kai-ai-laden-wrap"></div>' +
      '</div>';

    // Sla kleurenData alvast op
    if (kleurenData.kleuren.length > 0) {
      DY._kleurenAI.kleurenDataCache = kleurenData;
    }
    // Injecteer W-spinner in de ai-laden placeholder
    var aiLadenWrap = document.getElementById('dy-kai-ai-laden-wrap');
    if (aiLadenWrap) aiLadenWrap.appendChild(DY._bouwWSpinner('Stijladvies wordt opgesteld…'));
  } else if (resultaat) {
    resultaat.innerHTML = '';
    resultaat.appendChild(DY._bouwWSpinner('Stijl analyseren…'));
  }

  // ── STAP C: AI analyse (~800-2500ms) ─────────────────────────
  if (_selfAbort.signal.aborted) return;

  var analyse = null, lastErr = null;
  for (var poging = 0; poging < 2; poging++) {
    try {
      analyse = await DY._kleurenAnalyseerMet(kleurenData, base64, photoUrl);
      break;
    } catch(e) {
      lastErr = e;
      var retry = e.name === 'AbortError' ||
        (e.message && (e.message.indexOf('tijdelijk') >= 0 || e.message.indexOf('bezet') >= 0));
      if (poging === 0 && retry) {
        if (resultaat) { var rt = resultaat.querySelector('.dy-kai-loading-tekst'); if (rt) rt.textContent = 'Analyse opnieuw starten\u2026'; }
        await new Promise(function(r) { setTimeout(r, 1500); });
      }
    }
  }

  if (_selfAbort.signal.aborted) return;

  if (!analyse) {
    var msg = (lastErr && lastErr.message) || 'Analyse mislukt. Probeer opnieuw.';
    DY._kaiResultaatFout(msg);
    return;
  }

  analyse.kleurenData = kleurenData;
  DY._kleurenAI.analyseResultaat = analyse;

  // Sla op in cache voor heranalyse
  DY._kaiCacheSet(photoUrl, analyse, kleurenData);

  DY._kleurenAISlaOp({ type: 'analyse', analyse: analyse });
  // Log opslaan voor admin
  DY._kaiLog('saved', {
    stijl:    analyse.stijl || '',
    seizoen:  analyse.seizoen || '',
    harmonie: analyse.harmonie_score || 0,
    contrast: analyse.contrast_score || 0,
    balans:   analyse.balans_score || 0,
  });
  // Update style profile (non-blocking)
  DY._styleProfileUpdate(analyse);
  // Log analyse event (non-blocking)
  DY._kaiLog('analysis', {
    url:        photoUrl ? photoUrl.substring(0, 80) : '',
    stijl:      analyse.stijl,
    seizoen:    analyse.seizoen,
    harmonie:   analyse.harmonie_score,
    contrast:   analyse.contrast_score,
    balans:     analyse.balans_score,
    kleuren:    (analyse.kleurenData && analyse.kleurenData.kleuren || []).slice(0,5).map(function(k){return k.hex;}),
    cacheHit:   false
  });
  DY._kaiToonResultaat(analyse);
};


DY._kaiVergFotoURL = async function(slot, photoUrl) {
  if (!DY._kaiVergData) DY._kaiVergData = { a: null, b: null };
  if (DY._kaiVergData['_url_' + slot] && DY._kaiVergData['_url_' + slot].startsWith('blob:')) {
    try { URL.revokeObjectURL(DY._kaiVergData['_url_' + slot]); } catch(e) {}
  }
  DY._kaiVergData[slot] = null;
  DY._kaiVergData['_url_' + slot] = photoUrl;

  // Preview in slot
  var leegEl = document.getElementById('kai-verg-leeg-' + slot);
  if (!leegEl) {
    var vergBtn = document.querySelector('[data-tab="vergelijk"]');
    if (vergBtn) DY._kaiTab(vergBtn, 'vergelijk');
    leegEl = document.getElementById('kai-verg-leeg-' + slot);
    if (!leegEl) { DY._kaiFout('Ga naar de vergelijk tab en probeer het opnieuw.'); return; }
  }
  // Zet foto in slot (niet in leegEl om layout intact te houden)
  var slotFotoEl = document.getElementById('kai-verg-' + slot);
  if (slotFotoEl) {
    slotFotoEl.style.position = 'relative';
    slotFotoEl.innerHTML =
      '<img src="' + DY._esc(photoUrl) + '" style="width:100%;height:auto;max-height:320px;object-fit:contain;object-position:center top;border-radius:12px;display:block;background:var(--warm)" alt="Outfit ' + slot.toUpperCase() + '">' +
      '<button type="button" class="dy-kvs-wis-knop" onclick="event.stopPropagation();DY._kaiVergWis(\'' + slot + '\')" aria-label="Verwijder">\xd7</button>';
  }

  var res = document.getElementById('kai-vergelijk-resultaat');
  if (res) res.innerHTML =
    '<div style="padding:var(--sp-4);text-align:center">' +
    '<div class="dy-kai-loading-dots" style="justify-content:center;margin-bottom:var(--sp-2)"><span></span><span></span><span></span></div>' +
    '<p style="font-size:var(--t-sm);color:var(--ink-muted)">Outfit ' + slot.toUpperCase() + ' verwerken\u2026</p></div>';

  // Cache check voor vergelijk
  var cachedVerg = DY._kaiCacheGet(photoUrl);
  if (cachedVerg) {
    DY._kaiVergData[slot] = { kleurenData: cachedVerg.kleurenData, base64: null };
    if (DY._kaiVergData.a && DY._kaiVergData.b) {
      DY._kaiVoerVergelijkingUit();
    } else {
      if (res) res.innerHTML =
        '<div style="padding:var(--sp-4);text-align:center;color:var(--success);font-size:var(--t-sm)">\u2713 Outfit ' + slot.toUpperCase() + ' geladen. Kies de andere outfit.</div>';
    }
    return;
  }

  // Blob ophalen met Firebase token
  var kleurenData = null;
  var base64      = null;

  var blob = await DY._kaiHaalBlobOp(photoUrl);
  if (blob) {
    var verwerkt = await DY._kaiVerwerkBlob(blob);
    kleurenData = verwerkt.kleuren;
    base64      = verwerkt.base64;
  }

  // Fallback canvas
  if (!kleurenData || !kleurenData.kleuren || !kleurenData.kleuren.length) {
    kleurenData = await new Promise(function(res2) { DY._kleurenVanURL(photoUrl, res2); });
  }

  var heeftKleuren = kleurenData && kleurenData.kleuren && kleurenData.kleuren.length > 0;
  // Altijd doorgaan - ook zonder kleurendata
  if (!heeftKleuren) kleurenData = { kleuren: [], totaal: 0 };

  DY._kaiCacheSet(photoUrl, { kleurenData: kleurenData, _vergelijkCache: true }, kleurenData);
  DY._kaiVergData[slot] = { kleurenData: kleurenData, base64: base64 };

  if (DY._kaiVergData.a && DY._kaiVergData.b) {
    var _ctx2 = DY._kaiVergContext || {};
    if (_ctx2.occasion && _ctx2.style && _ctx2.priority) {
      // Context al gevuld - direct starten
      DY._kaiVoerVergelijkingUit();
    } else {
      // Context nog niet gevuld - toon start knop
      if (res) res.innerHTML =
        '<div class="dy-kai-verg-gate">' +
          '<span class="dy-kai-verg-gate-icon">\u2713</span>' +
          '<p>Beide outfits geladen. Vul de velden in en start de vergelijking.</p>' +
          '<button type="button" class="dy-kai-btn-cta dy-kai-btn-cta--prim" ' +
            'onclick="DY._kaiVoerVergelijkingUit()" style="margin-top:var(--sp-3)">' +
            '\u2728 Vergelijking starten</button>' +
        '</div>';
    }
  } else {
    if (res) res.innerHTML =
      '<div style="padding:var(--sp-4);text-align:center;color:var(--success);font-size:var(--t-sm)">\u2713 Outfit ' + slot.toUpperCase() + ' geladen. Kies de andere outfit.</div>';
  }
};


DY._kaiStylistVergelijk = async function(analyseA, analyseB) {
  var apiKey = await DY._kleurenGetAPIKey();
  if (!apiKey) return null;

  var kA = (analyseA.kleurenData && analyseA.kleurenData.kleuren || []).slice(0,5)
    .map(function(k,i) { return (i+1)+'. '+k.naam+' ('+k.pct+'%)'; }).join(', ');
  var kB = (analyseB.kleurenData && analyseB.kleurenData.kleuren || []).slice(0,5)
    .map(function(k,i) { return (i+1)+'. '+k.naam+' ('+k.pct+'%)'; }).join(', ');

  var sA = Math.round(((analyseA.harmonie_score||0)+(analyseA.contrast_score||0)+(analyseA.balans_score||0))/3);
  var sB = Math.round(((analyseB.harmonie_score||0)+(analyseB.contrast_score||0)+(analyseB.balans_score||0))/3);
  var winner = sA >= sB ? 'A' : 'B';

  // Context ophalen met smart defaults
  var ctx = DY._kaiVergContext || {};
  var ctxOccasion  = ctx.occasion  || 'Dagelijks';
  var ctxStyle     = ctx.style     || 'Casual';
  var ctxFocus     = (Array.isArray(ctx.focus) && ctx.focus.length) ? ctx.focus.join(', ') : '';
  var ctxPriority  = ctx.priority  || 'Stijl';
  var ctxNote      = (ctx.note || '').trim();

  var prompt = 'Je bent een ervaren persoonlijke stylist. Je spreekt warm en direct, als een vriend die verstand heeft van mode. ' +
    'Je noemt uitsluitend kleuren en kledingstukken die daadwerkelijk zichtbaar zijn. ' +
    'Je gebruikt geen lichaamstypelabels, geen vakjargon, geen em-dashes. ' +
    'Je legt altijd uit WAAROM iets werkt of niet werkt. ' +
    'Gewoon Nederlands, concreet en persoonlijk.\n\n' +
    'De persoon wil weten welke outfit het best bij hem/haar past.\n\n' +
    'WAT DE PERSOON WIL:\n' +
    'Gelegenheid: ' + ctxOccasion + '\n' +
    'Gewenste uitstraling: ' + ctxStyle + '\n' +
    (ctxFocus ? 'Extra aandacht voor: ' + ctxFocus + '\n' : '') +
    'Belangrijkste criterium: ' + ctxPriority + '\n' +
    (ctxNote ? 'Extra opmerking van de persoon: ' + ctxNote + '\n' : '') +
    '\nOUTFIT A: kleuren: ' + kA + '\nStijl: ' + (analyseA.stijl||'onbekend') + '\n' +
    'OUTFIT B: kleuren: ' + kB + '\nStijl: ' + (analyseB.stijl||'onbekend') + '\n\n' +
    'Let op outfit-classificatie: beoordeel silhouet, lengte en layering samen. Een lange hoodie zonder broek = longline hoodie outfit, geen jurk.\n\n' +
    'Geef een JSON object terug met ALLEEN deze velden:\n' +
    '{"winnaar_reden":"<1 directe zin waarom die outfit beter past, schrijf alsof je het tegen iemand zegt>","swap_a":["<1 concreet menselijk verbeterpunt voor A>","<nog een tip>"],"swap_b":["<1 concreet menselijk verbeterpunt voor B>","<nog een tip>"],"verbeter_a":"<1 zin hoe A nóg beter past bij ' + ctxOccasion + ', spreektaal>","verbeter_b":"<1 zin hoe B nóg beter past bij ' + ctxOccasion + ', spreektaal>"}\n\n' +
    'Regels: gewone spreektaal, geen hex codes, geen technische termen, geen scores, ALLEEN JSON.';

  var controller = new AbortController();
  var t = setTimeout(function() { controller.abort(); }, 20000);
  var res;
  try {
    res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 400,
        messages: [{ role: 'user', content: prompt }]
      })
    });
  } finally { clearTimeout(t); }

  if (!res.ok) return null;
  var data = await res.json();
  var text = (data.content&&data.content[0]&&data.content[0].text||'').trim();
  var s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s < 0 || e <= s) return null;
  try { return JSON.parse(text.substring(s, e+1)); } catch(e) { return null; }
};

// ── Poll stem handler ─────────────────────────────────────────────
DY._kaiStemPoll = function(keuze) {
  if (DY._kaiStemPoll._bezig) return;
  DY._kaiStemPoll._bezig = true;
  setTimeout(function() { DY._kaiStemPoll._bezig = false; }, 400);
  var knoppen = document.querySelectorAll('.dy-kai-poll-knop');
  knoppen.forEach(function(b) { b.classList.remove('dy-kai-poll-knop--actief'); b.disabled = true; });
  var gekozenKnop = document.getElementById('kai-poll-' + keuze.toLowerCase());
  if (gekozenKnop) gekozenKnop.classList.add('dy-kai-poll-knop--actief');
  var poll = document.querySelector('.dy-kai-verg-poll');
  if (poll) {
    var bevestiging = document.createElement('p');
    bevestiging.style.cssText = 'text-align:center;font-size:var(--t-sm);color:var(--clay);font-weight:600;margin-top:var(--sp-2)';
    bevestiging.textContent = 'Je koos Outfit ' + keuze + '. Goede keuze!';
    poll.appendChild(bevestiging);
  }
  var vData = DY._kaiVergData || {};
  var aA = vData._analyseA || {};
  var aB = vData._analyseB || {};
  DY._kaiLog('verg_poll', {
    answer: keuze === 'A' ? 'YES_A' : 'YES_B',
    keuze:  keuze,
    stijlA: aA.stijl || '',
    stijlB: aB.stijl || '',
    scoreA: Math.round(((aA.harmonie_score||0)+(aA.contrast_score||0)+(aA.balans_score||0))/3),
    scoreB: Math.round(((aB.harmonie_score||0)+(aB.contrast_score||0)+(aB.balans_score||0))/3),
    vergTs: vData._vergTs || Date.now(),
  });
};

// ── Nieuwe vergelijking starten ───────────────────────────────────
DY._kaiNieuweVergelijking = function() {
  if (DY._kaiVergData) {
    ['a','b'].forEach(function(s) {
      if (DY._kaiVergData['_url_'+s] && DY._kaiVergData['_url_'+s].startsWith('blob:')) {
        try { URL.revokeObjectURL(DY._kaiVergData['_url_'+s]); } catch(e) {}
      }
    });
  }
  DY._kaiVergData = { a: null, b: null };
  DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '' };
  DY._kaiVergSessionId = 'sess_' + Date.now() + '_' + Math.random().toString(36).slice(2,8);
  DY._kaiVergBezig = false;
  // Herbouw het vergelijk panel
  var panel = document.getElementById('kai-panel-vergelijk');
  if (panel) panel.innerHTML = DY._kaiVergelijkPanel();
};

// ── Vergelijking opslaan ──────────────────────────────────────────
DY._kaiSlaVergelijkOp = function() {
  var res = document.querySelector('.dy-kai-verg-layer1');
  if (!res) { DY._kaiFout('Geen vergelijking om op te slaan.'); return; }
  var ctx = DY._kaiVergContext || {};
  DY._kleurenAISlaOp({
    type:        'vergelijk_snapshot',
    ts:          Date.now(),
    sessionId:    DY._kaiVergSessionId || '',
    occasion:     ctx.occasion  || '',
    desiredStyle: ctx.style     || '',
    focusAreas:   Array.isArray(ctx.focus) ? ctx.focus.slice() : [],
    mainPriority: ctx.priority  || '',
    note:         ctx.note      || '',
    userId:       (DY.user && DY.user.uid) || '',
  });
  DY._kaiFout('\u2713 Vergelijking opgeslagen onder Opgeslagen.');
};


// ── Analyse upload auth wrappers ────────────────────────────────
DY._kaiGalerijKlik = function() {
  if (!DY.profile) { DY.toonLoginPrompt('Inloggen om een outfit foto te kiezen.'); return; }
  var inp = document.getElementById('kai-foto-input');
  if (inp) inp.click();
};
DY._kaiCameraKlik = function() {
  if (!DY.profile) { DY.toonLoginPrompt('Inloggen om een outfit foto te maken.'); return; }
  var inp = document.getElementById('kai-camera-input');
  if (inp) inp.click();
};


DY._kaiFotoGekozen = async function(file) {
  if (!file) return;
  var naam = (file.name || '').toLowerCase();
  var toegestaan = ['image/jpeg','image/jpg','image/png','image/webp','image/gif','image/heic','image/heif','image/bmp'];
  var extOk = /\.(jpg|jpeg|png|webp|heic|heif|gif|bmp)$/.test(naam);
  if (file.type && !toegestaan.includes(file.type) && !extOk) {
    DY._kaiFout('Dit formaat wordt niet ondersteund. Kies een JPG, PNG of WEBP foto.'); return;
  }
  if (file.size > 25 * 1024 * 1024) { DY._kaiFout('Foto is te groot (max 25MB). Kies een kleinere foto.'); return; }
  if (file.size < 1000) { DY._kaiFout('Foto lijkt leeg of beschadigd. Probeer een andere foto.'); return; }
  ['kai-foto-input','kai-camera-input'].forEach(function(id) { var el = document.getElementById(id); if (el) el.value = ''; });
  if (DY._kleurenAI.analyseURL) { try { URL.revokeObjectURL(DY._kleurenAI.analyseURL); } catch(e) {} }
  DY._kleurenAI.analyseFoto = file;
  DY._kleurenAI.analyseResultaat = null;
  DY._kleurenAI.analyseURL = URL.createObjectURL(file);
  var inner = document.getElementById('kai-upload-inner');
  if (inner) inner.innerHTML = '<div class="dy-kai-preview-wrap"><img src="' + DY._kleurenAI.analyseURL + '" class="dy-kai-preview-img" alt="Gekozen outfit"><button class="dy-kai-preview-wis" onclick="event.stopPropagation();DY._kaiWisAnalyse()" aria-label="Verwijder foto" type="button">\xd7</button></div>';
  var resultaat = document.getElementById('kai-analyse-resultaat');
  if (resultaat) resultaat.innerHTML = DY._kaiLoadingSkeleton();
  var kleurenData;
  try { kleurenData = await DY._kleurenExtraheer(file); }
  catch(e) { DY._kaiResultaatFout('Deze foto kon niet worden geopend. Probeer een andere foto.'); return; }
  if (!kleurenData || !kleurenData.kleuren || !kleurenData.kleuren.length) {
    DY._kaiResultaatFout('We konden geen kleuren herkennen in deze foto. Probeer een foto met duidelijkere kleuren.'); return;
  }
  var base64 = null;
  try { base64 = await DY._fileNaarBase64(file); } catch(e) { }
  if (resultaat) { var lt = resultaat.querySelector('.dy-kai-loading-tekst'); if (lt) lt.textContent = 'Kleuren worden geanalyseerd\u2026'; }
  var analyse = null;
  var maxRetries = 2;
  var lastError = null;
  for (var poging = 0; poging < maxRetries; poging++) {
    try { analyse = await DY._kleurenAnalyseerMet(kleurenData, base64, DY._kleurenAI.analyseURL || null); break; }
    catch(e) {
      lastError = e;
      var isRetryable = e.name === 'AbortError' || (e.message && (e.message.indexOf('tijdelijk') >= 0 || e.message.indexOf('bezet') >= 0));
      if (poging < maxRetries - 1 && isRetryable) {
        if (resultaat) { var rt = resultaat.querySelector('.dy-kai-loading-tekst'); if (rt) rt.textContent = 'Analyse opnieuw starten\u2026'; }
        await new Promise(function(r) { setTimeout(r, 1500); });
      }
    }
  }
  if (!analyse) {
    var errorMsg = (lastError && lastError.message) ? lastError.message : 'Analyse mislukt.';
    if (errorMsg.indexOf('AbortError') >= 0 || errorMsg.indexOf('abort') >= 0) errorMsg = 'De analyse duurde te lang. Probeer het opnieuw.';
    DY._kaiResultaatFout(errorMsg); return;
  }
  analyse.kleurenData = kleurenData;
  DY._kleurenAI.analyseResultaat = analyse;
  DY._kleurenAISlaOp({ type: 'analyse', analyse: analyse });
  DY._kaiToonResultaat(analyse);
};

DY._kaiDrop = function(e) {
  e.preventDefault();
  document.getElementById('kai-upload-zone').classList.remove('dragover');
  var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
  if (file) DY._kaiFotoGekozen(file);
};

