// Override _kaiCtxSelectChange met preventDefault guard
var _orig_kaiCtxSelectChange = DY._kaiCtxSelectChange;
DY._kaiCtxSelectChange = function(key, val) {
  if (!DY.profile) {
    DY.toonLoginPrompt && DY.toonLoginPrompt('Log in om je voorkeuren te personaliseren.');
    return;
  }
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  DY._kaiVergContext[key] = val;
};

// Override _kaiCtxNote met auth guard
DY._kaiCtxNote = function(val) {
  if (!DY.profile) return;
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  DY._kaiVergContext.note = (val || '').slice(0, 280);
};

// Override _kaiCtxToggle met auth guard
var _orig_kaiCtxToggle = DY._kaiCtxToggle;
DY._kaiCtxToggle = function(key, val, btn) {
  if (!DY.profile) {
    DY.toonLoginPrompt && DY.toonLoginPrompt('Log in om je voorkeuren te personaliseren.');
    return;
  }
  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  if (!Array.isArray(DY._kaiVergContext[key])) DY._kaiVergContext[key] = [];
  var idx = DY._kaiVergContext[key].indexOf(val);
  if (idx > -1) DY._kaiVergContext[key].splice(idx, 1);
  else DY._kaiVergContext[key].push(val);
  if (btn) btn.classList.toggle('dy-kai-ctx-chip--aktief', DY._kaiVergContext[key].indexOf(val) > -1);
};

// ══════════════════════════════════════════════════════════════════
// PATCH v306-p2: Vergelijking opslaan naar Firestore + toast fix
// ══════════════════════════════════════════════════════════════════

// Fix _kaiFout: gebruik bestaande _toonToastBericht als fallback
DY._kaiFout = function(tekst) {
  if (typeof DY._toonToastBericht === 'function') {
    DY._toonToastBericht(tekst);
    return;
  }
  // Fallback: maak toast zelf aan
  var bestaand = document.getElementById('dy-kai-toast');
  if (bestaand) bestaand.parentNode.removeChild(bestaand);
  var toast = document.createElement('div');
  toast.id = 'dy-kai-toast';
  toast.textContent = tekst;
  toast.style.cssText = 'position:fixed;bottom:calc(80px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);background:rgba(30,26,15,0.95);color:rgba(252,248,239,0.95);padding:10px 20px;border-radius:100px;font-size:0.85rem;font-weight:600;font-family:\'DM Sans\',sans-serif;z-index:9999;white-space:nowrap;box-shadow:0 4px 16px rgba(0,0,0,0.3)';
  document.body.appendChild(toast);
  setTimeout(function() { if (toast.parentNode) toast.parentNode.removeChild(toast); }, 3200);
};

// Fix _kaiSlaVergelijkOp: schrijf naar Firestore vergelijkingen collectie
DY._kaiSlaVergelijkOp = function() {
  var res = document.querySelector('.dy-kai-verg-layer1');
  if (!res) { DY._kaiFout('Geen vergelijking om op te slaan.'); return; }
  if (!DY.user || !DY.profile) { DY.toonLoginPrompt && DY.toonLoginPrompt('Log in om vergelijkingen op te slaan.'); return; }

  var ctx = DY._kaiVergContext || {};
  var vData = DY._kaiVergData || {};
  var analyseA = vData._analyseA || {};
  var analyseB = vData._analyseB || {};

  var opslag = {
    userId:       DY.user.uid,
    sessionId:    DY._kaiVergSessionId || ('sess_' + Date.now()),
    ts:           Date.now(),
    createdAt:    new Date().toISOString(),
    type:         'vergelijk_snapshot',
    occasion:     ctx.occasion     || '',
    desiredStyle: ctx.style        || '',
    focusAreas:   Array.isArray(ctx.focus) ? ctx.focus.slice() : [],
    mainPriority: ctx.priority     || '',
    note:         ctx.note         || '',
    scoreA:       Math.round(((analyseA.harmonie_score||0)+(analyseA.contrast_score||0)+(analyseA.balans_score||0))/3),
    scoreB:       Math.round(((analyseB.harmonie_score||0)+(analyseB.contrast_score||0)+(analyseB.balans_score||0))/3),
    stijlA:       analyseA.stijl   || '',
    stijlB:       analyseB.stijl   || '',
    winnaar:      (vData._winnaar  || ''),
    authorName:   DY.profile.displayName || DY.profile.naam || '',
  };

  // 1. Lokaal opslaan (sessionStorage)
  try {
    var list = DY._kleurenAI.opgeslagen || [];
    list.unshift({ ts: opslag.ts, analyse: analyseA, vergelijk: opslag });
    if (list.length > 10) list = list.slice(0, 10);
    DY._kleurenAI.opgeslagen = list;
    sessionStorage.setItem('dy_kleuren_analyses', JSON.stringify(list));
  } catch(e) {}

  // 2. Firestore opslaan met retry
  if (!DY.db) { DY._kaiFout('\u2713 Vergelijking opgeslagen.'); return; }

  var _retries = 0;
  function schrijfNaarFirestore() {
    DY.db.collection('vergelijkingen').add(opslag)
      .then(function(docRef) {
        DY._kaiFout('\u2713 Vergelijking opgeslagen.');
        // Log ook naar activity_logs voor admin panel zichtbaarheid
        try {
          DY.db.collection('activity_logs').add({
            type:      'vergelijking_opgeslagen',
            userId:    DY.user.uid,
            docId:     docRef.id,
            sessionId: opslag.sessionId,
            ts:        firebase.firestore.FieldValue.serverTimestamp(),
          }).catch(function(){});
        } catch(e) {}
      })
      .catch(function(err) {
        if (_retries < 2) {
          _retries++;
          setTimeout(schrijfNaarFirestore, 1500);
        } else {
          // Lokaal al opgeslagen - toon bevestiging toch
          DY._kaiFout('\u2713 Vergelijking opgeslagen (lokaal).');
          console.error('[pvdw] Firestore write mislukt na 3 pogingen:', err.message);
        }
      });
  }
  schrijfNaarFirestore();
};

// Fix _kaiNieuweVergelijking: scroll naar boven na reset
var _orig_kaiNieuweVerg = DY._kaiNieuweVergelijking;
DY._kaiNieuweVergelijking = function() {
  if (DY._kaiVergData) {
    ['a','b'].forEach(function(s) {
      if (DY._kaiVergData['_url_'+s] && DY._kaiVergData['_url_'+s].startsWith('blob:')) {
        try { URL.revokeObjectURL(DY._kaiVergData['_url_'+s]); } catch(e) {}
      }
    });
  }
  DY._kaiVergData = { a: null, b: null };
  DY._kaiVergContext = { occasion: '', style: '', focus: [], priority: '', note: '' };
  DY._kaiVergSessionId = 'sess_' + Date.now() + '_' + Math.random().toString(36).slice(2,8);
  DY._kaiVergBezig = false;
  var panel = document.getElementById('kai-panel-vergelijk');
  if (panel) {
    panel.innerHTML = DY._kaiVergelijkPanel();
    // Scroll naar boven zodat de nieuwe lege slots zichtbaar zijn
    requestAnimationFrame(function() {
      panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }
};

