// ══════════════════════════════════════════════════════════════════
// PATCH v309-p1: Bottom sheet dropdown voor mobiel
// ══════════════════════════════════════════════════════════════════

// Overschrijf _kaiCtxDdToggle met backdrop + bottom sheet support
// ── Custom dropdown - éénduidige implementatie voor alle devices ──
DY._kaiCtxDdToggle = function(id) {
  var dd    = document.getElementById('dy-ctx-dd-' + id);
  var panel = document.getElementById('dy-ctx-dd-panel-' + id);
  var btn   = document.getElementById('dy-ctx-dd-btn-' + id);
  if (!dd || !panel) return;

  var isOpen = dd.classList.contains('dy-ctx-dd--open');

  // Sluit alle andere open dropdowns
  document.querySelectorAll('.dy-ctx-dd--open').forEach(function(el) {
    if (el !== dd) {
      el.classList.remove('dy-ctx-dd--open');
      var p = el.querySelector('.dy-ctx-dd-panel');
      var b = el.querySelector('.dy-ctx-dd-trigger');
      if (p) p.setAttribute('aria-hidden', 'true');
      if (b) b.setAttribute('aria-expanded', 'false');
    }
  });

  if (isOpen) {
    DY._kaiDdSluit(dd, panel, btn);
    return;
  }

  // Open
  dd.classList.add('dy-ctx-dd--open');
  panel.setAttribute('aria-hidden', 'false');
  if (btn) btn.setAttribute('aria-expanded', 'true');

  // Sluit bij klik buiten - bubble fase zodat optie onclick eerst vuurt
  function sluiten(e) {
    // Negeer kliks op opties zelf - die sluiten via _kaiCtxDdKies
    if (e.target && e.target.closest && e.target.closest('.dy-ctx-dd-opt')) return;
    if (!dd.contains(e.target)) {
      DY._kaiDdSluit(dd, panel, btn);
      document.removeEventListener('click', sluiten, false);
      document.removeEventListener('touchstart', sluiten, false);
    }
  }
  setTimeout(function() {
    document.addEventListener('click', sluiten, false);
    document.addEventListener('touchstart', sluiten, false);
  }, 50);
};

DY._kaiDdSluit = function(dd, panel, btn) {
  if (!dd) return;
  dd.classList.remove('dy-ctx-dd--open');
  if (panel) panel.setAttribute('aria-hidden', 'true');
  if (btn)   btn.setAttribute('aria-expanded', 'false');
};

DY._kaiDdVerwijderBackdrop = function() {};

// Overschrijf _kaiCtxDdKies met sluit-logica
DY._kaiCtxDdKies = function(el) {
  var btn = (el && el.target) ? el.target.closest('.dy-ctx-dd-opt') : el;
  if (!btn) return;
  var id       = btn.dataset.ddid;
  var stateKey = btn.dataset.statekey;
  var val      = btn.dataset.val;
  if (!id || !stateKey || !val) return;

  if (!DY._kaiVergContext) DY._kaiVergContext = { occasion:'', style:'', focus:[], priority:'', note:'' };
  DY._kaiVergContext[stateKey] = val;

  // Update trigger label
  var triggerBtn = document.getElementById('dy-ctx-dd-btn-' + id);
  if (triggerBtn) {
    var span = triggerBtn.querySelector('.dy-ctx-dd-val');
    if (span) span.textContent = val;
    triggerBtn.classList.remove('dy-ctx-dd-trigger--leeg');
  }

  // Update vinkjes
  var ddPanel = document.getElementById('dy-ctx-dd-panel-' + id);
  if (ddPanel) {
    ddPanel.querySelectorAll('.dy-ctx-dd-opt').forEach(function(o) {
      var isKeuze = o.dataset.val === val;
      o.classList.toggle('dy-ctx-dd-opt--aktief', isKeuze);
      var check = o.querySelector('.dy-ctx-dd-check');
      if (isKeuze && !check) {
        var c = document.createElement('span');
        c.className = 'dy-ctx-dd-check';
        c.textContent = ' \u2713';
        o.appendChild(c);
      } else if (!isKeuze && check) {
        check.parentNode.removeChild(check);
      }
    });
  }

  // Sluit met kleine vertraging zodat gebruiker zijn keuze ziet
  var ddEl = document.getElementById('dy-ctx-dd-' + id);
  setTimeout(function() {
    DY._kaiDdSluit(ddEl, ddPanel, triggerBtn);
  }, 120);
};

// ══════════════════════════════════════════════════════════════════
// KAI UITBREIDING - Verbeterknoppen + AI Stylist Chat + Stijlprofiel
// Build: v311-uitbreiding-1
// ══════════════════════════════════════════════════════════════════

// ─────────────────────────────────────────────────────────────────
// VERBETERKNOPPEN
// ─────────────────────────────────────────────────────────────────

DY._kaiVerbeterKnoppen = [
  { id: 'bovenkant',  label: 'Bovenkant',   icoon: '👕' },
  { id: 'onderkant',  label: 'Onderkant',   icoon: '👖' },
  { id: 'schoenen',   label: 'Schoenen',    icoon: '👟' },
  { id: 'kleuren',    label: 'Kleuren',     icoon: '🎨' },
  { id: 'accessoires',label: 'Accessoires', icoon: '⌚' },
  { id: 'volledig',   label: 'Alles',       icoon: '✦'  }
];

// HTML voor verbeterknoppen sectie
DY._kaiVerbeterKnoppenHTML = function() {
  var knoppen = DY._kaiVerbeterKnoppen.map(function(k) {
    return '<button type="button" class="dy-kai-vb-knop" data-deel="' + k.id + '" ' +
      'onclick="DY._kaiVerbeter(\'' + k.id + '\')">' +
      '<span class="dy-kai-vb-icoon">' + k.icoon + '</span>' +
      '<span class="dy-kai-vb-label">' + k.label + '</span>' +
    '</button>';
  }).join('');

  return '<div class="dy-kai-sectie dy-kai-vb-wrap" id="dy-kai-vb-wrap">' +
    '<h3 class="dy-kai-sectie-titel">Verbeter jouw outfit</h3>' +
    '<div class="dy-kai-vb-grid">' + knoppen + '</div>' +
    '<div id="dy-kai-vb-resultaat"></div>' +
  '</div>';
};

// Voer verbeteractie uit
DY._kaiVerbeter = async function(deel) {
  var resEl = document.getElementById('dy-kai-vb-resultaat');
  if (!resEl) return;

  // Markeer actieve knop
  document.querySelectorAll('.dy-kai-vb-knop').forEach(function(b) {
    b.classList.toggle('dy-kai-vb-knop--actief', b.dataset.deel === deel);
  });

  // Gebruik bestaande analysecontext - geen nieuwe beeldanalyse
  var analyse = DY._kleurenAI && DY._kleurenAI.analyseResultaat;
  if (!analyse) {
    resEl.innerHTML = '<p class="dy-kai-vb-fout">Analyseer eerst een outfit.</p>';
    return;
  }

  resEl.innerHTML = '<div class="dy-kai-vb-laden">' +
    '<div class="dy-kai-loading-dots"><span></span><span></span><span></span></div>' +
    '<p class="dy-kai-loading-tekst">Verbeteradvies laden\u2026</p>' +
  '</div>';

  var deelLabel = DY._kaiVerbeterKnoppen.find(function(k) { return k.id === deel; });
  deelLabel = deelLabel ? deelLabel.label : deel;

  var apiKey = await DY._kleurenGetAPIKey().catch(function() { return null; });
  if (!apiKey) {
    resEl.innerHTML = DY._kaiVbFallback(deel, analyse);
    DY._kaiVbLogActie(deel);
    return;
  }

  var profiel = DY._styleProfile || {};

  // Gebruik AI-gecorrigeerde analysedata als primaire bron, niet ruwe pixel-extractie
  var samenv   = analyse.samenvatting || '';
  var positief = (analyse.positief || []).join('; ');
  var verbpnt  = (analyse.verbeterpunten || []).join('; ');
  var stijl    = analyse.stijl || 'onbekend';
  var seizoen  = analyse.seizoen || '';

  var prompt = 'Je bent een ervaren persoonlijke stylist. Geef kort en concreet verbeteradvies. ' +
    'Noem ALLEEN wat daadwerkelijk visueel zichtbaar is. Geen lichaamstypelabels. Geen em-dashes. Gewoon Nederlands.\n\n' +
    'OUTFIT ANALYSE (gebruik dit als basis voor je advies):\n' +
    (samenv   ? 'Beschrijving: ' + samenv + '\n' : '') +
    (stijl    ? 'Stijl: ' + stijl + '\n' : '') +
    (seizoen  ? 'Seizoen: ' + seizoen + '\n' : '') +
    (positief ? 'Sterke punten: ' + positief + '\n' : '') +
    (verbpnt  ? 'Verbeterpunten uit analyse: ' + verbpnt + '\n' : '') +
    (profiel.laatste_stijl ? 'Gebruiker draagt vaak: ' + profiel.laatste_stijl + '\n' : '') +
    '\nGeef verbeteradvies specifiek voor: ' + deelLabel + '\n' +
    'Baseer je advies uitsluitend op de bovenstaande outfit-informatie. Verzin geen kleuren of items.\n\n' +
    'Geef een JSON object:\n' +
    '{"werkt_goed":"<1 zin wat al goed werkt, gebaseerd op de beschrijving>","kan_beter":"<1 zin concreet verbeterpunt>",' +
    '"aanpassing":"<1 concrete aanpassing in spreektaal>","effect":"<1 zin verwacht resultaat>"}\n\n' +
    'Regels: gewone spreektaal, geen jargon, geen lichaamstypelabels, ALLEEN JSON.';

  var controller = new AbortController();
  var t = setTimeout(function() { controller.abort(); }, 15000);

  try {
    var res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 300,
        messages: [{ role: 'user', content: prompt }]
      })
    });
    clearTimeout(t);

    if (res.ok) {
      var data = await res.json();
      var text = (data.content && data.content[0] && data.content[0].text || '').trim();
      var s = text.indexOf('{'), e = text.lastIndexOf('}');
      if (s >= 0 && e > s) {
        var parsed = JSON.parse(text.substring(s, e + 1));
        resEl.innerHTML = DY._kaiVbResultaatHTML(parsed, deelLabel);
        DY._kaiVbLogActie(deel, parsed);
        return;
      }
    }
  } catch(err) { clearTimeout(t); }

  // Fallback
  resEl.innerHTML = DY._kaiVbFallback(deel, analyse);
  DY._kaiVbLogActie(deel);
};

DY._kaiVbResultaatHTML = function(data, label) {
  return '<div class="dy-kai-vb-res">' +
    '<div class="dy-kai-vb-res-header">' +
      '<span class="dy-kai-vb-res-label">' + label + '</span>' +
    '</div>' +
    '<div class="dy-kai-vb-rij dy-kai-vb-rij--goed">' +
      '<span class="dy-kai-vb-rij-icoon">✓</span>' +
      '<span>' + DY._esc(DY._kaiFilterTekst(data.werkt_goed || '')) + '</span>' +
    '</div>' +
    '<div class="dy-kai-vb-rij dy-kai-vb-rij--beter">' +
      '<span class="dy-kai-vb-rij-icoon">→</span>' +
      '<span>' + DY._esc(DY._kaiFilterTekst(data.kan_beter || '')) + '</span>' +
    '</div>' +
    '<div class="dy-kai-vb-aanpassing">' +
      '<strong>Probeer dit:</strong> ' + DY._esc(DY._kaiFilterTekst(data.aanpassing || '')) +
    '</div>' +
    '<div class="dy-kai-vb-effect">' +
      '<span class="dy-kai-vb-effect-icoon">✦</span>' +
      DY._esc(DY._kaiFilterTekst(data.effect || '')) +
    '</div>' +
  '</div>';
};

DY._kaiVbFallback = function(deel, analyse) {
  var tips = {
    bovenkant:   { werkt_goed: 'Je kleurkeuze is een goede basis.', kan_beter: 'De pasvorm kan nog aandacht gebruiken.', aanpassing: 'Probeer een maat kleiner voor een strakker silhouet.', effect: 'Dit geeft een gestroomlijnder geheel.' },
    onderkant:   { werkt_goed: 'De kleurbalans met de bovenkant werkt.', kan_beter: 'De lengte bepaalt sterk de verhoudingen.', aanpassing: 'Kies een lengte die je benen optisch verlengt.', effect: 'Je ziet er direct geproportioneerder uit.' },
    schoenen:    { werkt_goed: 'Je outfit heeft een duidelijke stijlrichting.', kan_beter: 'Schoenen maken of breken een look.', aanpassing: 'Kies een schoen die aansluit op de energie van je outfit.', effect: 'Het geheel voelt completer en bewuster.' },
    kleuren:     { werkt_goed: 'Er zit een herkenbare kleurlijn in je outfit.', kan_beter: 'Een accentkleur kan de look naar een hoger niveau tillen.', aanpassing: 'Voeg één kleur toe via accessoires die complementair is.', effect: 'Je outfit krijgt meer diepte en karakter.' },
    accessoires: { werkt_goed: 'De basis van je outfit staat.', kan_beter: 'Accessoires ontbreken of sluiten niet aan.', aanpassing: 'Kies één statement stuk dat de outfit afmaakt.', effect: 'De look voelt bewuster en completer.' },
    volledig:    { werkt_goed: 'Er is een herkenbare stijlrichting.', kan_beter: 'De onderdelen versterken elkaar nog niet maximaal.', aanpassing: 'Zorg dat kleur, pasvorm en stijl in één richting wijzen.', effect: 'Je outfit oogt als een bewuste, samenhangende keuze.' }
  };
  var t = tips[deel] || tips.volledig;
  return DY._kaiVbResultaatHTML(t, deel);
};

DY._kaiVbLogActie = function(deel, resultaat) {
  if (!DY.user || !DY.db) return;
  try {
    DY.db.collection('users').doc(DY.user.uid)
      .collection('ai_style_profile').doc('profiel')
      .set({
        bijgewerkt: Date.now(),
        'gedrag.verbeter_acties': firebase.firestore.FieldValue.increment(1),
        laatste_verbeter_deel: deel
      }, { merge: true }).catch(function(){});
  } catch(e) {}
};

// ─────────────────────────────────────────────────────────────────
// AI STYLIST CHAT
// ─────────────────────────────────────────────────────────────────

DY._kaiChat = {
  actief: false,
  sessieId: null,
  berichten: [],   // { rol: 'gebruiker'|'stylist', tekst }
  analyseId: null
};

DY._kaiChatHTML = function() {
  return '<div class="dy-kai-sectie dy-kai-chat-wrap" id="dy-kai-chat-wrap">' +
    '<h3 class="dy-kai-sectie-titel">Vraag je stylist</h3>' +
    '<div class="dy-kai-chat-suggesties" id="dy-kai-chat-sug">' +
      ['Welke schoenen passen hierbij?', 'Is dit geschikt voor kantoor?', 'Hoe maak ik dit moderner?', 'Welke kleur broek werkt beter?']
        .map(function(v) {
          return '<button type="button" class="dy-kai-chat-sug-btn" onclick="DY._kaiChatStel(\'' + v.replace(/'/g, "\\'") + '\')">' + v + '</button>';
        }).join('') +
    '</div>' +
    '<div class="dy-kai-chat-berichten" id="dy-kai-chat-berichten"></div>' +
    '<div class="dy-kai-chat-invoer">' +
      '<textarea id="dy-kai-chat-input" class="dy-kai-chat-input" rows="1" ' +
        'placeholder="Stel een vraag over je outfit\u2026" ' +
        'oninput="DY._kaiChatAutoResize(this)" ' +
        'onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();DY._kaiChatVerstuur()}">' +
      '</textarea>' +
      '<button type="button" class="dy-kai-chat-send" onclick="DY._kaiChatVerstuur()" aria-label="Verstuur">' +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" width="18" height="18"><path d="M22 2L11 13"/><path d="M22 2L15 22 11 13 2 9l20-7z"/></svg>' +
      '</button>' +
    '</div>' +
  '</div>';
};

DY._kaiChatAutoResize = function(ta) {
  ta.style.height = 'auto';
  ta.style.height = Math.min(ta.scrollHeight, 120) + 'px';
};

DY._kaiChatStel = function(vraag) {
  var input = document.getElementById('dy-kai-chat-input');
  if (input) { input.value = vraag; DY._kaiChatAutoResize(input); }
  // Verberg suggesties na eerste gebruik
  var sug = document.getElementById('dy-kai-chat-sug');
  if (sug) sug.style.display = 'none';
  DY._kaiChatVerstuur();
};

DY._kaiChatVerstuur = async function() {
  var input = document.getElementById('dy-kai-chat-input');
  if (!input) return;
  var vraag = (input.value || '').trim();
  if (!vraag) return;

  input.value = '';
  input.style.height = 'auto';

  // Voeg gebruikersbericht toe
  DY._kaiChat.berichten.push({ rol: 'gebruiker', tekst: vraag });
  DY._kaiChatRenderBerichten();

  // Typing indicator
  var berichtenEl = document.getElementById('dy-kai-chat-berichten');
  var typingId = 'dy-kai-chat-typing';
  if (berichtenEl) {
    var typing = document.createElement('div');
    typing.id = typingId;
    typing.className = 'dy-kai-chat-bericht dy-kai-chat-bericht--stylist dy-kai-chat-typing';
    typing.innerHTML = '<span></span><span></span><span></span>';
    berichtenEl.appendChild(typing);
    berichtenEl.scrollTop = berichtenEl.scrollHeight;
  }

  var analyse = DY._kleurenAI && DY._kleurenAI.analyseResultaat;
  var profiel  = DY._styleProfile || {};

  // Gebruik de AI-gecorrigeerde samenvatting als primaire kleurenbron
  // De samenvatting bevat de door de AI visueel bevestigde kleuren, niet de ruwe extractie
  var samenv   = analyse ? (analyse.samenvatting || '') : '';
  var stijl    = analyse ? (analyse.stijl || '') : '';
  var seizoen  = analyse ? (analyse.seizoen || '') : '';
  var positief = analyse ? (analyse.positief || []).join('; ') : '';

  var apiKey = await DY._kleurenGetAPIKey().catch(function(){ return null; });

  // Verwijder typing indicator
  var typingEl = document.getElementById(typingId);
  if (typingEl) typingEl.parentNode.removeChild(typingEl);

  if (!apiKey) {
    DY._kaiChat.berichten.push({ rol: 'stylist', tekst: 'Even geduld, ik kan momenteel geen verbinding maken. Probeer het straks nog eens.' });
    DY._kaiChatRenderBerichten();
    return;
  }

  // Bouw chat history voor context
  var history = DY._kaiChat.berichten.slice(0, -1).slice(-6).map(function(b) {
    return { role: b.rol === 'gebruiker' ? 'user' : 'assistant', content: b.tekst };
  });

  var analyseContext = '';
  if (analyse) {
    analyseContext = 'OUTFIT ANALYSE CONTEXT:\n' +
      (samenv   ? 'Samenvatting van de outfit: ' + samenv + '\n' : '') +
      (stijl    ? 'Stijl: ' + stijl + '\n' : '') +
      (seizoen  ? 'Seizoen: ' + seizoen + '\n' : '') +
      (positief ? 'Sterke punten: ' + positief + '\n' : '') +
      '\n';
  }

  var systeemContext = 'Je bent een ervaren persoonlijke stylist. Geef directe, vriendelijke antwoorden in gewoon Nederlands. ' +
    'Geen lichaamstypelabels. Geen em-dashes. Geen streepjes als stijlelement.\n' +
    'Leg altijd uit waarom iets werkt of niet werkt. Wees concreet en specifiek.\n' +
    'KRITIEKE REGEL: Noem NOOIT kleuren of kledingstukken die je niet zeker weet. ' +
    'Als de gebruiker vraagt naar iets wat niet in de analyse staat (zoals "welke broek"), ' +
    'geef dan een concreet advies op basis van wat je WEL weet van de outfit, zonder te verzinnen.\n' +
    analyseContext +
    (profiel.laatste_stijl ? 'Gebruiker draagt vaak: ' + profiel.laatste_stijl + '\n' : '') +
    'Max 3 zinnen per antwoord. Persoonlijk en direct.';

  history.push({ role: 'user', content: vraag });

  var controller = new AbortController();
  var t = setTimeout(function() { controller.abort(); }, 18000);
  var antwoord = '';

  try {
    var res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        system: systeemContext,
        messages: history
      })
    });
    clearTimeout(t);

    if (res.ok) {
      var data = await res.json();
      antwoord = (data.content && data.content[0] && data.content[0].text || '').trim();
    }
  } catch(err) { clearTimeout(t); }

  if (!antwoord) antwoord = 'Ik kon je vraag even niet verwerken. Stel hem gerust opnieuw!';

  DY._kaiChat.berichten.push({ rol: 'stylist', tekst: antwoord });
  DY._kaiChatRenderBerichten();

  // Log naar Firestore (non-blocking)
  DY._kaiChatLog(vraag, antwoord);
};

DY._kaiChatRenderBerichten = function() {
  var el = document.getElementById('dy-kai-chat-berichten');
  if (!el) return;
  el.innerHTML = DY._kaiChat.berichten.map(function(b) {
    var cls = 'dy-kai-chat-bericht dy-kai-chat-bericht--' + (b.rol === 'gebruiker' ? 'gebruiker' : 'stylist');
    return '<div class="' + cls + '">' + DY._esc(b.tekst) + '</div>';
  }).join('');
  el.scrollTop = el.scrollHeight;
};

DY._kaiChatLog = function(vraag, antwoord) {
  if (!DY.user || !DY.db) return;
  try {
    DY.db.collection('users').doc(DY.user.uid)
      .collection('ai_style_profile').doc('profiel')
      .set({
        bijgewerkt: Date.now(),
        'gedrag.chat_vragen': firebase.firestore.FieldValue.increment(1),
        laatste_chat_vraag: vraag.slice(0, 80)
      }, { merge: true }).catch(function(){});
  } catch(e) {}
};

// ─────────────────────────────────────────────────────────────────
// INJECTIE IN BESTAANDE ANALYSE FLOW
// Overschrijf de analyse-render om nieuwe secties toe te voegen
// ─────────────────────────────────────────────────────────────────

var _origKaiAnalyseer = DY._kleurenAnalyseer;
if (typeof _origKaiAnalyseer === 'function') {
  DY._kleurenAnalyseer = async function() {
    // Reset chat bij nieuwe analyse
    DY._kaiChat = { actief: false, sessieId: 'chat_' + Date.now(), berichten: [], analyseId: null };
    return _origKaiAnalyseer.apply(this, arguments);
  };
}

// Hook in de post-render stap: injecteer verbeterknoppen + chat na improvement engine
var _origImprovementEngine = DY._kaiImprovementEngine;
DY._kaiImprovementEngine = async function(analyse) {
  var resultaat = await _origImprovementEngine.call(this, analyse);

  // Injecteer verbeterknoppen en chat na korte vertraging
  // (zodat de improvement engine HTML al in de DOM staat)
  setTimeout(function() {
    var resEl = document.getElementById('kai-analyse-resultaat');
    if (!resEl) return;

    // Verwijder eerdere instanties (bij herhaling)
    var oudeVb = document.getElementById('dy-kai-vb-wrap');
    if (oudeVb) oudeVb.parentNode.removeChild(oudeVb);
    var oudeChat = document.getElementById('dy-kai-chat-wrap');
    if (oudeChat) oudeChat.parentNode.removeChild(oudeChat);

    // Voeg verbeterknoppen toe
    var vbDiv = document.createElement('div');
    vbDiv.innerHTML = DY._kaiVerbeterKnoppenHTML();
    resEl.appendChild(vbDiv.firstChild);

    // Voeg chat toe (alleen ingelogd)
    if (DY.profile) {
      var chatDiv = document.createElement('div');
      chatDiv.innerHTML = DY._kaiChatHTML();
      resEl.appendChild(chatDiv.firstChild);
    }
  }, 400);

  return resultaat;
};

