// ══════════════════════════════════════════════════════════════════
// SPRINT 1 - FEED CARD & AI SOCIAL LAYER UPGRADE (v359)
// Features: Community Score, AI Kleuranalyse, Bookmark Systeem
// Volledig additioneel - geen bestaande functies gewijzigd
// ══════════════════════════════════════════════════════════════════

// ── CENTRALE POST STATE ─────────────────────────────────────────────
// Single source of truth voor alle nieuwe features per post
DY._postState = DY._postState || {};

DY._getPostState = function(docId) {
  if (!DY._postState[docId]) {
    DY._postState[docId] = {
      scoreData:    null,   // { avg, totaal, zou_dragen, geweldige_outfit, goede_kleuren }
      userStem:     null,   // { zou_dragen, geweldige_outfit, goede_kleuren } of false
      stemLoaded:   false,
      bookmarked:   false,
      collections:  [],
      bookmarkLoaded: false,
      analyseCache: null,   // { ts, result }
      viewSent:     false
    };
  }
  return DY._postState[docId];
};

// ══════════════════════════════════════════════════════════════════
// FEATURE 1.3 - BOOKMARK SYSTEEM (geen Firestore lees-dependency
// bij initieel laden → kan eerder gebouwd worden dan score)
// ══════════════════════════════════════════════════════════════════

DY._BOOKMARK_COLLECTIONS = [
  { id: 'casual',           label: 'Casual' },
  { id: 'werk',             label: 'Werk' },
  { id: 'date_night',       label: 'Date Night' },
  { id: 'plussize_inspo',   label: 'Plus Size Inspiratie' },
  { id: 'favorieten',       label: 'Favorieten' }
];

// Offline queue: persist in localStorage, drain bij online
DY._bookmarkQueueDrain = function() {
  if (!DY.user || !navigator.onLine) return;
  var raw = '';
  try { raw = localStorage.getItem('dy_bookmark_queue') || '[]'; } catch(e) { return; }
  var queue = [];
  try { queue = JSON.parse(raw); } catch(e) { return; }
  if (!queue.length) return;
  // Verwerk via users/{uid} document - altijd toegestaan
  var promises = queue.map(function(item) {
    var upd = {};
    if (item.action === 'add') {
      upd['savedPosts.' + item.docId] = {
        docId: item.docId,
        collections: item.collections || ['favorieten'],
        foto: item.foto || null,
        titel: item.titel || '',
        ts: Date.now()
      };
    } else if (item.action === 'remove') {
      upd['savedPosts.' + item.docId] = firebase.firestore.FieldValue.delete();
    } else if (item.action === 'update') {
      upd['savedPosts.' + item.docId + '.collections'] = item.collections || [];
    }
    return DY.db.collection('users').doc(DY.user.uid).update(upd).catch(function(){});
  });
  Promise.all(promises).then(function() {
    try { localStorage.removeItem('dy_bookmark_queue'); } catch(e) {}
  }).catch(function() {});
};
window.addEventListener('online', function() { DY._bookmarkQueueDrain(); });

DY._addToBookmarkQueue = function(item) {
  var queue = [];
  try { queue = JSON.parse(localStorage.getItem('dy_bookmark_queue') || '[]'); } catch(e) {}
  queue.push(item);
  try { localStorage.setItem('dy_bookmark_queue', JSON.stringify(queue)); } catch(e) {}
};

DY.laadBookmarkStatus = async function(docId) {
  var state = DY._getPostState(docId);
  if (state.bookmarkLoaded) return state;
  if (!DY.user) { state.bookmarkLoaded = true; return state; }
  try {
    // Lees uit users/{uid}.savedPosts.{docId} - altijd toegestaan
    // Gebruik gecacht profiel als dat al beschikbaar is (geen extra Firestore read)
    var savedPosts = null;
    if (DY.profile && DY.profile.savedPosts !== undefined) {
      savedPosts = DY.profile.savedPosts;
    } else {
      // Haal alleen het savedPosts veld op
      var userSnap = await DY.db.collection('users').doc(DY.user.uid).get();
      savedPosts = (userSnap.exists && userSnap.data().savedPosts) || {};
      // Sync naar profiel cache
      if (DY.profile) DY.profile.savedPosts = savedPosts;
    }
    var saved = savedPosts && savedPosts[docId];
    if (saved) {
      state.bookmarked = true;
      state.collections = saved.collections || [];
    } else {
      state.bookmarked = false;
      state.collections = [];
    }
    state.bookmarkLoaded = true;
  } catch(e) {
    state.bookmarkLoaded = true;
  }
  return state;
};

// Update alle bookmark-knoppen voor een post in de DOM
DY._updateBookmarkBtns = function(docId) {
  var state = DY._getPostState(docId);
  document.querySelectorAll('.dy-bookmark-btn[data-doc="' + docId + '"]').forEach(function(btn) {
    btn.classList.toggle('saved', state.bookmarked);
    var icon = btn.querySelector('.dy-bookmark-icon');
    if (icon) icon.setAttribute('fill', state.bookmarked ? 'currentColor' : 'none');
    var label = btn.querySelector('.dy-bookmark-label');
    if (label) label.textContent = state.bookmarked ? 'Bewaard' : 'Opslaan';
  });
};

// Toon collection picker als bottom sheet
DY._toonBookmarkSheet = function(docId, triggerBtn) {
  var bestaand = document.getElementById('dy-bookmark-sheet-wrap');
  if (bestaand) bestaand.parentNode.removeChild(bestaand);

  DY.laadBookmarkStatus(docId).catch(function(){ return {}; }).then(function(state) {
    var wrap = document.createElement('div');
    wrap.id = 'dy-bookmark-sheet-wrap';
    wrap.className = 'dy-bs-backdrop';

    var colsHTML = DY._BOOKMARK_COLLECTIONS.map(function(col) {
      var active = state.collections.indexOf(col.id) !== -1;
      return '<button class="dy-bs-col-btn' + (active ? ' active' : '') + '" data-col="' + col.id + '">' +
        '<span class="dy-bs-col-check">' +
          (active
            ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>'
            : '') +
        '</span>' +
        col.label +
      '</button>';
    }).join('');

    wrap.innerHTML =
      '<div class="dy-bs-sheet" id="dy-bs-sheet">' +
        '<div class="dy-bs-drag"></div>' +
        '<div class="dy-bs-header">' +
          '<span class="dy-bs-titel">📌 Opslaan in collectie</span>' +
          '<span class="dy-bs-sub">Kies één of meerdere categorieën</span>' +
        '</div>' +
        '<div class="dy-bs-cols">' + colsHTML + '</div>' +
        '<div class="dy-bs-acties">' +
          '<button class="dy-bs-opslaan-btn" id="dy-bs-opslaan">Opslaan</button>' +
          (state.bookmarked
            ? '<button class="dy-bs-verwijder-btn" id="dy-bs-verwijder">Verwijderen</button>'
            : '') +
        '</div>' +
      '</div>';

    document.body.appendChild(wrap);
    requestAnimationFrame(function() { requestAnimationFrame(function() { wrap.classList.add('dy-bs-in'); }); });

    // Toggle collectie
    wrap.querySelectorAll('.dy-bs-col-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        btn.classList.toggle('active');
        var check = btn.querySelector('.dy-bs-col-check');
        if (check) {
          check.innerHTML = btn.classList.contains('active')
            ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>'
            : '';
        }
      });
    });

    function sluitSheet(cb) {
      wrap.classList.remove('dy-bs-in');
      wrap.classList.add('dy-bs-out');
      setTimeout(function() {
        if (wrap.parentNode) wrap.parentNode.removeChild(wrap);
        if (cb) cb();
      }, 280);
    }

    // Opslaan knop
    var opslaanBtn = document.getElementById('dy-bs-opslaan');
    if (opslaanBtn) {
      opslaanBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        var activeCols = [];
        wrap.querySelectorAll('.dy-bs-col-btn.active').forEach(function(b) { activeCols.push(b.dataset.col); });
        // Minimaal één collectie vereist
        if (activeCols.length === 0) activeCols = ['favorieten'];

        var state = DY._getPostState(docId);
        state.bookmarked = true;
        state.collections = activeCols;
        state.bookmarkLoaded = true;
        DY._updateBookmarkBtns(docId);

        // Micro-animatie op trigger
        if (triggerBtn) {
          triggerBtn.style.transform = 'scale(1.35)';
          setTimeout(function() { triggerBtn.style.transform = ''; }, 220);
        }
        DY._toonToastBericht('📌 Opgeslagen in ' + activeCols.map(function(id) {
          var c = DY._BOOKMARK_COLLECTIONS.find(function(x) { return x.id === id; });
          return c ? c.label : id;
        }).join(', '));

        if (DY.user) {
          var saveUpd = {};
          saveUpd['savedPosts.' + docId] = {
            docId: docId, collections: activeCols,
            foto: null, titel: '', ts: Date.now()
          };
          DY.db.collection('users').doc(DY.user.uid).update(saveUpd)
            .then(function() {
              if (!DY.profile.savedPosts) DY.profile.savedPosts = {};
              DY.profile.savedPosts[docId] = saveUpd['savedPosts.' + docId];
            })
            .catch(function() {
              DY._addToBookmarkQueue({ action: 'add', docId: docId, collections: activeCols });
            });
        }
        sluitSheet();
      });
    }

    // Verwijder knop
    var verwijderBtn = document.getElementById('dy-bs-verwijder');
    if (verwijderBtn) {
      verwijderBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        var state = DY._getPostState(docId);
        state.bookmarked = false;
        state.collections = [];
        DY._updateBookmarkBtns(docId);
        DY._toonToastBericht('Verwijderd uit opgeslagen posts');
        if (DY.user) {
          var delUpdate = {};
          delUpdate['savedPosts.' + docId] = firebase.firestore.FieldValue.delete();
          DY.db.collection('users').doc(DY.user.uid).update(delUpdate)
            .then(function() {
              if (DY.profile && DY.profile.savedPosts) delete DY.profile.savedPosts[docId];
            })
            .catch(function() {
              DY._addToBookmarkQueue({ action: 'remove', docId: docId });
            });
        }
        sluitSheet();
      });
    }

    // Backdrop klik
    wrap.addEventListener('click', function(e) { if (e.target === wrap) sluitSheet(); });
  });
};

// HTML voor bookmark-knop (reel sidebar stijl)
DY._bookmarkBtnReelHTML = function(docId) {
  return '<button class="dy-reel-action-btn dy-bookmark-btn" data-doc="' + docId + '" onclick="event.stopPropagation();DY._toonBookmarkSheet(\'' + docId + '\',this)" aria-label="Opslaan">' +
    '<svg class="dy-reel-action-icon dy-bookmark-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>' +
    '<span class="dy-reel-action-count dy-bookmark-label">Opslaan</span>' +
  '</button>';
};

// HTML voor bookmark-knop (detail popup stijl)
DY._bookmarkBtnDetailHTML = function(docId, bookmarked) {
  return '<button class="dy-sd-actie-btn dy-bookmark-btn' + (bookmarked ? ' saved' : '') + '" data-doc="' + docId + '" onclick="event.stopPropagation();DY._toonBookmarkSheet(\'' + docId + '\',this)" aria-label="Opslaan">' +
    '<svg class="dy-sd-actie-icon dy-bookmark-icon" viewBox="0 0 24 24" fill="' + (bookmarked ? 'currentColor' : 'none') + '" stroke="currentColor" stroke-width="2"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>' +
    '<span>Opslaan</span>' +
  '</button>';
};

// ══════════════════════════════════════════════════════════════════
// FEATURE 1.1 - COMMUNITY SCORE MODULE
// ══════════════════════════════════════════════════════════════════

// Bouw score-HTML - puur functie, geen DOM side-effects
DY._bouwScoreHTML = function(docId, scoreData) {
  var avg       = (scoreData && scoreData.avg)           ? scoreData.avg           : 0;
  var totaal    = (scoreData && scoreData.totaal)        ? scoreData.totaal        : 0;
  var zou       = (scoreData && scoreData.zou_dragen)    ? scoreData.zou_dragen    : 0;
  var geweldig  = (scoreData && scoreData.geweldige_outfit) ? scoreData.geweldige_outfit : 0;
  var kleuren   = (scoreData && scoreData.goede_kleuren) ? scoreData.goede_kleuren : 0;

  var sterrenHTML = '';
  for (var i = 1; i <= 5; i++) {
    sterrenHTML += '<span class="dy-score-ster' + (i <= Math.round(avg) ? ' vol' : '') + '">★</span>';
  }

  return '<div class="dy-score-module" data-doc="' + docId + '">' +
    '<div class="dy-score-header">' +
      '<span class="dy-score-sterren">' + sterrenHTML + '</span>' +
      '<span class="dy-score-gem">' + (avg > 0 ? avg.toFixed(1) : '-') + '</span>' +
      (totaal > 0 ? '<span class="dy-score-totaal">(' + totaal + ')</span>' : '') +
    '</div>' +
    '<div class="dy-score-reacties">' +
      '<button class="dy-score-reactie-btn dy-stem-btn" data-doc="' + docId + '" data-type="zou_dragen" onclick="event.stopPropagation();DY.stemOpOutfit(\'' + docId + '\',\'zou_dragen\',this)">' +
        '👍 Zou ik dragen' + (zou > 0 ? ' <span class="dy-score-n">' + zou + '</span>' : '') +
      '</button>' +
      '<button class="dy-score-reactie-btn dy-stem-btn" data-doc="' + docId + '" data-type="geweldige_outfit" onclick="event.stopPropagation();DY.stemOpOutfit(\'' + docId + '\',\'geweldige_outfit\',this)">' +
        '🔥 Geweldige outfit' + (geweldig > 0 ? ' <span class="dy-score-n">' + geweldig + '</span>' : '') +
      '</button>' +
      '<button class="dy-score-reactie-btn dy-stem-btn" data-doc="' + docId + '" data-type="goede_kleuren" onclick="event.stopPropagation();DY.stemOpOutfit(\'' + docId + '\',\'goede_kleuren\',this)">' +
        '💡 Goede kleuren' + (kleuren > 0 ? ' <span class="dy-score-n">' + kleuren + '</span>' : '') +
      '</button>' +
    '</div>' +
  '</div>';
};

// Update alle score-modules voor een docId in de DOM
DY._updateScoreModules = function(docId) {
  var state = DY._getPostState(docId);
  document.querySelectorAll('.dy-score-module[data-doc="' + docId + '"]').forEach(function(el) {
    el.outerHTML = DY._bouwScoreHTML(docId, state.scoreData);
    // outerHTML vervangt het element - de querySelectorAll loop loopt al door dus dit is veilig
  });
  // Herlaad ook user-stem-markering
  DY._markeerUserStem(docId);
};

// Markeer welke knoppen de user al heeft ingedrukt
DY._markeerUserStem = function(docId) {
  var state = DY._getPostState(docId);
  if (!state.stemLoaded || !state.userStem) return;
  document.querySelectorAll('.dy-stem-btn[data-doc="' + docId + '"]').forEach(function(btn) {
    var type = btn.dataset.type;
    btn.classList.toggle('gestemd', !!(state.userStem && state.userStem[type]));
  });
};

// Laad score voor een post (lazy, via IntersectionObserver)
DY.laadScoreVoorPost = async function(docId) {
  var state = DY._getPostState(docId);
  if (state.scoreData !== null) {
    DY._markeerUserStem(docId);
    return;
  }
  try {
    var snap = await DY.db.collection('stories').doc(docId).get();
    if (!snap.exists) return;
    var d = snap.data();
    state.scoreData = {
      avg:             d._scoreAvg        || 0,
      totaal:          d._scoreTotaal     || 0,
      zou_dragen:      (d._ratings && d._ratings.zou_dragen)      || 0,
      geweldige_outfit:(d._ratings && d._ratings.geweldige_outfit) || 0,
      goede_kleuren:   (d._ratings && d._ratings.goede_kleuren)   || 0
    };
  } catch(e) {
    state.scoreData = { avg: 0, totaal: 0, zou_dragen: 0, geweldige_outfit: 0, goede_kleuren: 0 };
  }

  // Laad user eigen stem uit stories/{docId}._votes.{uid}
  // (zelfde document dat al opgehaald wordt voor scoreData - geen extra read)
  if (DY.user) {
    try {
      var userVotes = (snap.exists && snap.data()._votes && snap.data()._votes[DY.user.uid]) || {};
      state.userStem = {
        zou_dragen:       userVotes.zou_dragen       === true,
        geweldige_outfit: userVotes.geweldige_outfit === true,
        goede_kleuren:    userVotes.goede_kleuren    === true
      };
    } catch(e) { state.userStem = false; }
    state.stemLoaded = true;
  } else {
    state.stemLoaded = true;
  }

  // Update DOM
  DY._updateScoreModules(docId);
  DY._markeerUserStem(docId);
};

// IntersectionObserver voor lazy score loading
DY._scoreObserver = null;
DY._initScoreObserver = function() {
  if (DY._scoreObserver) return;
  DY._scoreObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        var docId = entry.target.dataset.doc;
        if (docId) DY.laadScoreVoorPost(docId).catch(function(){});
      }
    });
  }, { rootMargin: '120px 0px', threshold: 0.01 });
};

DY._observeerScoreModules = function(container) {
  DY._initScoreObserver();
  container.querySelectorAll('.dy-score-module[data-doc]').forEach(function(el) {
    DY._scoreObserver.observe(el);
  });
};

// Stemmen op outfit
DY.stemOpOutfit = async function(docId, type, btn) {
  if (!DY.user) {
    DY.toonLoginPrompt('Stem op outfits en help de community de beste looks ontdekken.');
    return;
  }

  // Debounce
  if (!DY._stemBezig) DY._stemBezig = {};
  var debounceKey = docId + '_' + type;
  if (DY._stemBezig[debounceKey]) return;
  DY._stemBezig[debounceKey] = true;
  setTimeout(function() { delete DY._stemBezig[debounceKey]; }, 600);

  var state = DY._getPostState(docId);
  var uid = DY.user.uid;

  // Schrijft naar stories/{docId} - zelfde collectie als likes (werkt gegarandeerd)
  // Veldpad: _votes.{uid}.{type} voor eigen stem
  //          _ratings.{type} voor geaggregeerde teller (atomic increment)
  var storyRef = DY.db.collection('stories').doc(docId);

  var huidigeStem = state.userStem || {};
  var wasGestemd = !!(huidigeStem[type]);
  var nieuweWaarde = !wasGestemd;
  var delta = nieuweWaarde ? 1 : -1;

  // Optimistic UI
  if (!state.userStem) state.userStem = {};
  state.userStem[type] = nieuweWaarde;
  state.stemLoaded = true;
  if (!state.scoreData) state.scoreData = { avg: 0, totaal: 0, zou_dragen: 0, geweldige_outfit: 0, goede_kleuren: 0 };
  state.scoreData[type] = Math.max(0, (state.scoreData[type] || 0) + delta);
  btn.classList.toggle('gestemd', nieuweWaarde);
  btn.style.transform = 'scale(1.18)';
  setTimeout(function() { btn.style.transform = ''; }, 180);
  DY._updateStemTellers(docId, state);

  try {
    // Bouw update object - beide velden in één write (atomisch)
    var update = {};
    // Eigen stem opslaan als nested veld op het story document
    update['_votes.' + uid + '.' + type] = nieuweWaarde
      ? true
      : firebase.firestore.FieldValue.delete();
    // Geaggregeerde teller atomisch bijwerken
    update['_ratings.' + type] = firebase.firestore.FieldValue.increment(delta);

    await storyRef.update(update);

    // Herlaad werkelijke aggregaten voor accurate weergave
    var snap = await storyRef.get();
    if (snap.exists) {
      var d = snap.data();
      var r = d._ratings || {};
      var zou = Math.max(0, r.zou_dragen || 0);
      var gew = Math.max(0, r.geweldige_outfit || 0);
      var kl  = Math.max(0, r.goede_kleuren || 0);
      var totaal = zou + gew + kl;
      var gemScore = totaal > 0
        ? Math.min(5, Math.round((totaal / Math.max(1, Object.keys(d._votes || {}).length) / 3) * 5 * 10) / 10)
        : 0;

      state.scoreData.zou_dragen       = zou;
      state.scoreData.geweldige_outfit = gew;
      state.scoreData.goede_kleuren    = kl;
      state.scoreData.totaal           = totaal;
      state.scoreData.avg              = gemScore;
      DY._updateStemTellers(docId, state);

      // Schrijf gemiddelde terug (niet blocking)
      storyRef.update({ '_scoreAvg': gemScore, '_scoreTotaal': totaal }).catch(function(){});
    }

  } catch(e) {
    // Rollback bij fout
    state.userStem[type] = wasGestemd;
    state.scoreData[type] = Math.max(0, (state.scoreData[type] || 0) - delta);
    btn.classList.toggle('gestemd', wasGestemd);
    DY._updateStemTellers(docId, state);
    // Log voor debugging (geen UI exposure)
    if (window.console && console.warn) console.warn('[stemOpOutfit error]', e && e.code, e && e.message);
    DY._toonToastBericht('Jouw stem kon niet worden opgeslagen. Probeer het opnieuw.');
  }
};


// Helper: update alle DOM-elementen voor score van een post
DY._updateStemTellers = function(docId, state) {
  document.querySelectorAll('.dy-score-module[data-doc="' + docId + '"]').forEach(function(moduleEl) {
    var headerEl = moduleEl.querySelector('.dy-score-header');
    if (headerEl) {
      var avg = state.scoreData ? (state.scoreData.avg || 0) : 0;
      var totaal = state.scoreData ? (state.scoreData.totaal || 0) : 0;
      var sterrenHTML = '';
      for (var i = 1; i <= 5; i++) {
        sterrenHTML += '<span class="dy-score-ster' + (i <= Math.round(avg) ? ' vol' : '') + '">★</span>';
      }
      headerEl.innerHTML =
        '<span class="dy-score-sterren">' + sterrenHTML + '</span>' +
        '<span class="dy-score-gem">' + (avg > 0 ? avg.toFixed(1) : '-') + '</span>' +
        (totaal > 0 ? '<span class="dy-score-totaal">(' + totaal + ')</span>' : '');
    }
    moduleEl.querySelectorAll('.dy-stem-btn').forEach(function(b) {
      var bType = b.dataset.type;
      var n = state.scoreData ? (state.scoreData[bType] || 0) : 0;
      var bestaandN = b.querySelector('.dy-score-n');
      if (n > 0) {
        if (bestaandN) { bestaandN.textContent = n; }
        else {
          var span = document.createElement('span');
          span.className = 'dy-score-n';
          span.textContent = n;
          b.appendChild(span);
        }
      } else if (bestaandN) {
        bestaandN.parentNode.removeChild(bestaandN);
      }
      b.classList.toggle('gestemd', !!(state.userStem && state.userStem[bType]));
    });
  });
};


// ══════════════════════════════════════════════════════════════════
// FEATURE 1.2 - AI KLEURANALYSE
// ══════════════════════════════════════════════════════════════════

DY._aiAnalyseCache = {};  // { [docId]: { ts, result } }
DY._AI_ANALYSE_TTL = 24 * 60 * 60 * 1000; // 24 uur

// ══════════════════════════════════════════════════════════════════
// OUTFIT REVIEW - VERBETER JOUW OUTFIT
// Uitbreiding: voegt de "Verbeter jouw outfit" sectie toe aan de
// Outfit Review analyse. Hergebruikt exact dezelfde logica als
// Vergelijk Mijn Outfit (_kaiVerbeter), aangepast op de
// Outfit Review data-bron (DY._aiAnalyseCache[docId]).
// Geen bestaande functies gewijzigd.
// ══════════════════════════════════════════════════════════════════

// ── Verbeterknoppen HTML voor Outfit Review context ────────────────
DY._orVerbeterKnoppenHTML = function(docId) {
  var knoppen = DY._kaiVerbeterKnoppen.map(function(k) {
    return '<button type="button" class="dy-kai-vb-knop" data-deel="' + k.id + '" ' +
      'onclick="DY._orVerbeter(\'' + DY.escapeHtml(docId) + '\',\'' + k.id + '\')">' +
      '<span class="dy-kai-vb-icoon">' + k.icoon + '</span>' +
      '<span class="dy-kai-vb-label">' + k.label + '</span>' +
    '</button>';
  }).join('');

  return '<div class="dy-kai-sectie dy-kai-vb-wrap dy-or-verbeter-wrap" id="dy-or-verbeter-wrap-' + DY.escapeHtml(docId) + '">' +
    '<h3 class="dy-kai-sectie-titel">Verbeter jouw outfit</h3>' +
    '<div class="dy-kai-vb-grid">' + knoppen + '</div>' +
    '<div id="dy-or-verbeter-resultaat-' + DY.escapeHtml(docId) + '"></div>' +
  '</div>';
};

// ── Verbeteractie uitvoeren voor Outfit Review ─────────────────────
// Identieke logica als DY._kaiVerbeter, maar gebruikt DY._aiAnalyseCache
// als databron in plaats van DY._kleurenAI.analyseResultaat.
DY._orVerbeter = async function(docId, deel) {
  var resEl = document.getElementById('dy-or-verbeter-resultaat-' + docId);
  if (!resEl) return;

  // Markeer actieve knop (alleen binnen de eigen wrap)
  var wrap = document.getElementById('dy-or-verbeter-wrap-' + docId);
  if (wrap) {
    wrap.querySelectorAll('.dy-kai-vb-knop').forEach(function(b) {
      b.classList.toggle('dy-kai-vb-knop--actief', b.dataset.deel === deel);
    });
  }

  // Haal analyse op uit de Outfit Review cache
  var cached = DY._aiAnalyseCache && DY._aiAnalyseCache[docId];
  var analyse = cached ? cached.result : null;

  if (!analyse) {
    resEl.innerHTML = '<p class="dy-kai-vb-fout">Voer eerst een Outfit Review analyse uit.</p>';
    return;
  }

  // Laadstatus tonen - identiek aan _kaiVerbeter
  resEl.innerHTML = '<div class="dy-kai-vb-laden">' +
    '<div class="dy-kai-loading-dots"><span></span><span></span><span></span></div>' +
    '<p class="dy-kai-loading-tekst">Verbeteradvies laden\u2026</p>' +
  '</div>';

  var deelObj  = DY._kaiVerbeterKnoppen.find(function(k) { return k.id === deel; });
  var deelLabel = deelObj ? deelObj.label : deel;

  var apiKey = await DY._kleurenGetAPIKey().catch(function() { return null; });
  if (!apiKey) {
    resEl.innerHTML = DY._kaiVbFallback(deel, analyse);
    DY._kaiVbLogActie(deel);
    return;
  }

  var profiel  = DY._styleProfile || {};
  var samenv   = analyse.samenvatting || '';
  var positief = (analyse.positief || []).join('; ');
  var verbpnt  = (analyse.verbeterpunten || []).join('; ');
  var stijl    = analyse.stijl || 'onbekend';
  var seizoen  = analyse.seizoen || '';

  // Identieke prompt als _kaiVerbeter
  var prompt = 'Je bent een ervaren persoonlijke stylist. Geef kort en concreet verbeteradvies. ' +
    'Noem ALLEEN wat daadwerkelijk visueel zichtbaar is. Geen lichaamstypelabels. Geen em-dashes. Gewoon Nederlands.\n\n' +
    'OUTFIT ANALYSE (gebruik dit als basis voor je advies):\n' +
    (samenv   ? 'Beschrijving: ' + samenv + '\n' : '') +
    (stijl    ? 'Stijl: ' + stijl + '\n' : '') +
    (seizoen  ? 'Seizoen: ' + seizoen + '\n' : '') +
    (positief ? 'Sterke punten: ' + positief + '\n' : '') +
    (verbpnt  ? 'Verbeterpunten uit analyse: ' + verbpnt + '\n' : '') +
    (profiel.laatste_stijl ? 'Gebruiker draagt vaak: ' + profiel.laatste_stijl + '\n' : '') +
    '\nGeef verbeteradvies specifiek voor: ' + deelLabel + '\n' +
    'Baseer je advies uitsluitend op de bovenstaande outfit-informatie. Verzin geen kleuren of items.\n\n' +
    'Geef een JSON object:\n' +
    '{"werkt_goed":"<1 zin wat al goed werkt, gebaseerd op de beschrijving>","kan_beter":"<1 zin concreet verbeterpunt>",' +
    '"aanpassing":"<1 concrete aanpassing in spreektaal>","effect":"<1 zin verwacht resultaat>"}\n\n' +
    'Regels: gewone spreektaal, geen jargon, geen lichaamstypelabels, ALLEEN JSON.';

  var controller = new AbortController();
  var t = setTimeout(function() { controller.abort(); }, 15000);

  try {
    var res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 300,
        messages: [{ role: 'user', content: prompt }]
      })
    });
    clearTimeout(t);

    if (res.ok) {
      var data = await res.json();
      var text = (data.content && data.content[0] && data.content[0].text || '').trim();
      var s = text.indexOf('{'), e = text.lastIndexOf('}');
      if (s >= 0 && e > s) {
        var parsed = JSON.parse(text.substring(s, e + 1));
        // Hergebruik exact dezelfde resultaat-HTML functie als _kaiVerbeter
        resEl.innerHTML = DY._kaiVbResultaatHTML(parsed, deelLabel);
        DY._kaiVbLogActie(deel, parsed);
        return;
      }
    }
  } catch(err) { clearTimeout(t); }

  // Fallback - hergebruik exact dezelfde fallback als _kaiVerbeter
  resEl.innerHTML = DY._kaiVbFallback(deel, analyse);
  DY._kaiVbLogActie(deel);
};

// Verbeter-injectie verplaatst naar directe call-sites in toonAIAnalyse

// ══════════════════════════════════════════════════════════════════
// EINDE OUTFIT REVIEW - VERBETER JOUW OUTFIT
// ══════════════════════════════════════════════════════════════════

DY.toonAIAnalyse = async function(docId, foto, panelEl) {
  if (!panelEl) return;

  // Debounce
  if (panelEl._aiBezig) return;

  // Geen foto
  if (!foto) {
    panelEl.innerHTML = '<div class="dy-ai-fallback">Voeg een foto toe om de outfit te analyseren.</div>';
    panelEl.classList.add('open');
    return;
  }

  // Toggle: open panel sluiten
  if (panelEl.classList.contains('open') && !panelEl.classList.contains('loading')) {
    panelEl.style.maxHeight = panelEl.scrollHeight + 'px';
    panelEl.style.overflow = 'hidden';
    requestAnimationFrame(function() {
      panelEl.style.maxHeight = '0';
      setTimeout(function() { panelEl.classList.remove('open'); panelEl.style.maxHeight = ''; panelEl.style.overflow = ''; }, 380);
    });
    var tb = panelEl.previousElementSibling;
    if (tb && tb.classList.contains('dy-ai-trigger')) tb.classList.remove('active');
    return;
  }

  // Cache check (24u)
  var cached = DY._aiAnalyseCache[docId];
  if (cached && (Date.now() - cached.ts) < DY._AI_ANALYSE_TTL) {
    DY._renderAIAnalyse(panelEl, cached.result);
    var tb2 = panelEl.previousElementSibling;
    if (tb2 && tb2.classList.contains('dy-ai-trigger')) tb2.classList.add('active');
    panelEl.classList.add('open');

    return;
  }

  // W-spinner via DOM (inline styles - cache-onafhankelijk, werkt op alle devices)
  (function() {
    var wrapper = document.createElement('div');
    wrapper.style.cssText = 'display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:28px 16px';

    var ring = document.createElement('div');
    ring.style.cssText = [
      'width:52px', 'height:52px', 'border-radius:50%',
      'background:rgba(198,125,6,0.10)',
      'border:2px solid rgba(198,125,6,0.40)',
      'display:flex', 'align-items:center', 'justify-content:center',
      'font-family:\'Cormorant Garamond\',Georgia,serif',
      'font-size:1.75rem', 'font-weight:700',
      'color:#c67d06',
      'box-shadow:0 0 14px rgba(198,125,6,0.22)',
      'animation:dy-ai-w-puls 1.8s ease-in-out infinite'
    ].join(';');

    var letter = document.createElement('span');
    letter.textContent = 'W';
    letter.style.cssText = 'display:block;line-height:1;font-family:\'Cormorant Garamond\',Georgia,serif;font-size:1.75rem;font-weight:700;color:#c67d06';

    var tekst = document.createElement('span');
    tekst.textContent = 'Outfit analyseren';
    tekst.style.cssText = 'font-size:0.78rem;font-weight:600;color:#7a6a3a;letter-spacing:0.03em;font-family:inherit';

    ring.appendChild(letter);
    wrapper.appendChild(ring);
    wrapper.appendChild(tekst);
    panelEl.innerHTML = '';
    panelEl.appendChild(wrapper);
  })();
  panelEl.classList.add('open', 'loading');
  panelEl._aiBezig = true;
  // Zet max-height tijdelijk hoog voor animatie, reset na transitie
  panelEl.style.maxHeight = '2000px';
  setTimeout(function() { if (panelEl.classList.contains('open')) { panelEl.style.maxHeight = 'none'; panelEl.style.overflow = 'visible'; } }, 420);
  var triggerBtn = panelEl.previousElementSibling;
  if (triggerBtn && triggerBtn.classList.contains('dy-ai-trigger')) triggerBtn.classList.add('active');

  try {
    // ── Stap 1: blob + kleuren ophalen (zelfde als _kaiAnalyseerURL)
    var kleurenData = { kleuren: [], totaal: 0 };
    var base64      = null;

    // Gebruik _kaiHaalBlobOp als beschikbaar (zelfde CORS-fix als vergelijker)
    if (typeof DY._kaiHaalBlobOp === 'function') {
      try {
        var blob = await DY._kaiHaalBlobOp(foto);
        if (blob) {
          var verwerkt = await DY._kaiVerwerkBlob(blob);
          kleurenData = verwerkt.kleuren || kleurenData;
          base64      = verwerkt.base64  || null;
        }
      } catch(e) {}
    }

    // Fallback: directe canvas kleuren extractie
    if (!kleurenData.kleuren.length && typeof DY._kleurenExtraheer === 'function') {
      try {
        kleurenData = await DY._kleurenExtraheer(foto);
      } catch(e) {}
    }

    // Fallback base64 als blob mislukte maar canvas werkte
    if (!base64 && kleurenData.kleuren.length > 0) {
      try {
        base64 = await new Promise(function(resolve) {
          var img = new Image();
          img.crossOrigin = 'anonymous';
          img.onload = function() {
            try {
              var MAX = 800;
              var r = Math.min(MAX / img.naturalWidth, MAX / img.naturalHeight, 1);
              var c = document.createElement('canvas');
              c.width  = Math.max(1, Math.round(img.naturalWidth  * r));
              c.height = Math.max(1, Math.round(img.naturalHeight * r));
              c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
              resolve((c.toDataURL('image/jpeg', 0.82).split(',')[1]) || null);
            } catch(e) { resolve(null); }
          };
          img.onerror = function() { resolve(null); };
          img.src = foto;
          setTimeout(function() { resolve(null); }, 8000);
        });
      } catch(e) {}
    }

    // ── Stap 2: AI analyse via zelfde functie als outfit vergelijker
    var analyse = null;
    var lastErr  = null;

    // Twee pogingen - zelfde retry patroon als _kaiAnalyseerURL
    for (var poging = 0; poging < 2; poging++) {
      try {
        analyse = await DY._kleurenAnalyseerMet(kleurenData, base64, foto);
        break;
      } catch(e) {
        lastErr = e;
        if (poging === 0) {
          // Wacht 1.5s voor retry (zelfde als vergelijker)
          await new Promise(function(r) { setTimeout(r, 1500); });
        }
      }
    }

    if (!analyse) {
      throw lastErr || new Error('Analyse mislukt na twee pogingen.');
    }

    // Voeg kleurenData toe aan analyse zodat _renderAIAnalyse de canvas-kleuren kan tonen
    analyse.kleurenData = kleurenData;
    // Cache opslaan
    DY._aiAnalyseCache[docId] = { ts: Date.now(), result: analyse };
    panelEl.classList.remove('loading');
    panelEl._aiBezig = false;
    DY._renderAIAnalyse(panelEl, analyse);
    // Verwijder max-height limiet zodat volledige analyse zichtbaar is
    panelEl.style.maxHeight = 'none';
    panelEl.style.overflow = 'visible';


  } catch(e) {
    panelEl.classList.remove('loading');
    panelEl._aiBezig = false;

    // Fallback: toon foutmelding met retry
    var foutTekst = 'De analyse is nu niet beschikbaar. Probeer het straks opnieuw.';
    if (e && e.message) {
      if (e.message.indexOf('niet beschikbaar') >= 0) foutTekst = e.message;
      else if (e.message.indexOf('lang') >= 0 || e.message.indexOf('abort') >= 0)
        foutTekst = 'De analyse duurde te lang. Controleer je verbinding en probeer het opnieuw.';
      else if (e.message.indexOf('verbinding') >= 0 || e.message.indexOf('fetch') >= 0)
        foutTekst = 'Geen internetverbinding. Controleer je verbinding en probeer het opnieuw.';
    }

    var _fd = document.createElement('div');
    _fd.className = 'dy-ai-fallback';
    var _fs = document.createElement('span');
    _fs.textContent = foutTekst;
    var _rb = document.createElement('button');
    _rb.className = 'dy-ai-retry-btn';
    _rb.textContent = 'Opnieuw proberen';
    _rb.addEventListener('click', function(ev) {
      ev.stopPropagation();
      panelEl.classList.remove('open');
      var _tr = panelEl.previousElementSibling;
      if (_tr && _tr.classList.contains('dy-ai-trigger')) _tr.classList.remove('active');
    });
    _fd.appendChild(_fs);
    _fd.appendChild(_rb);
    panelEl.innerHTML = '';
    panelEl.appendChild(_fd);
  }
};


// ── Verwijder hex-codes uit AI tekst, vervang door inline kleurstaal ──────────
// Zoekt naar patronen zoals "fel roze (#FF1493)" of "(#FF1493)" en vervangt
// de (#RRGGBB) door een visueel inline kleurstaal + kleur naam behouden
DY._vervangHexInTekst = function(tekst) {
  if (!tekst) return '';
  function chipVoor(hex) {
    var vollHex = '#' + hex;
    var r, g, b;
    if (hex.length === 3) {
      r = parseInt(hex[0]+hex[0],16); g = parseInt(hex[1]+hex[1],16); b = parseInt(hex[2]+hex[2],16);
    } else {
      r = parseInt(hex.slice(0,2),16); g = parseInt(hex.slice(2,4),16); b = parseInt(hex.slice(4,6),16);
    }
    var licht = (0.299*r + 0.587*g + 0.114*b) > 128;
    return '<span class="dy-ai-inline-chip" style="background:' + vollHex + ';color:' + (licht ? '#1e1a0f' : '#fdf8f0') + '" aria-label="kleurbol"></span>';
  }
  // Stap 1: (#RRGGBB) of (#RGB) met haakjes - verwijder haakjes + code, vervang door chip
  tekst = tekst.replace(/\s*\(#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{3})\)/g, function(m, hex) {
    return ' ' + chipVoor(hex);
  });
  // Stap 2: bare #RRGGBB of #RGB zonder haakjes - vervang door chip
  tekst = tekst.replace(/#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{3})\b/g, function(m, hex) {
    return chipVoor(hex);
  });
  return tekst;
};

DY._renderAIAnalyse = function(panelEl, result) {
  if (!result || typeof result !== 'object') {
    panelEl.innerHTML = '<div class="dy-ai-fallback">De analyse kon niet worden geladen. Probeer het opnieuw.</div>';
    return;
  }

  var harmonieScore  = Math.max(0, Math.min(100, result.harmonie_score  || 0));
  var contrastScore  = Math.max(0, Math.min(100, result.contrast_score  || 0));
  var balansScore    = Math.max(0, Math.min(100, result.balans_score    || 0));
  var seizoen        = result.seizoen       || '';
  var stijl          = result.stijl         || '';
  var harmonieType   = result.harmonie_type || '';
  var positief       = Array.isArray(result.positief)       ? result.positief       : [];
  var verbeterpunten = Array.isArray(result.verbeterpunten) ? result.verbeterpunten : [];
  var alternatieven  = Array.isArray(result.alternatieven)  ? result.alternatieven  : [];
  var samenvatting   = result.samenvatting  || '';

  // Kleurprioriteit: 1. AI outfit_kleuren (AI ziet de foto direct - altijd accuraat)
  //                  2. canvas-gedetecteerde kleuren (lokale extractie)
  //                  3. leeg (geen stalen tonen)
  var aiKleuren = Array.isArray(result.outfit_kleuren) && result.outfit_kleuren.length > 0
    ? result.outfit_kleuren.map(function(k, i, arr) {
        // Gebruik pct van AI als beschikbaar, anders schat op basis van positie
        var aiPct = (k.pct && k.pct > 0) ? k.pct : null;
        // Fallback: dalende verdeling (eerste kleur dominant)
        var fallbackPct = Math.max(5, Math.round(60 / Math.pow(1.6, i)));
        return { naam: k.naam || k.name || '', hex: k.hex || '#888888', pct: aiPct || fallbackPct };
      })
    : [];
  var canvasKleuren = (result.kleurenData && result.kleurenData.kleuren && result.kleurenData.kleuren.length > 0)
    ? result.kleurenData.kleuren
    : [];
  // AI kleuren zijn leidend - die zien de foto direct zonder CORS beperkingen
  var displayKleuren = aiKleuren.length > 0 ? aiKleuren : canvasKleuren;

  function scoreKleur(n) {
    return n >= 75 ? '#1a6b3a' : n >= 50 ? '#c67d06' : '#c0392b';
  }

  function scoreBalk(label, score) {
    var kleur = scoreKleur(score);
    return '<div class="dy-ai-harmonie-bar-wrap">' +
      '<span class="dy-ai-harmonie-label">' + DY.escapeHtml(label) + '</span>' +
      '<div class="dy-ai-harmonie-bar">' +
        '<div class="dy-ai-harmonie-fill" style="width:' + score + '%;background:' + kleur + '"></div>' +
      '</div>' +
      '<span class="dy-ai-harmonie-score" style="color:' + kleur + '">' + score + '/100</span>' +
    '</div>';
  }

  // Positieve punten HTML - hex codes vervangen door kleurstalen
  var positiefHTML = positief.slice(0, 4).map(function(p) {
    return '<li class="dy-ai-lijst-item">✦ ' + DY._vervangHexInTekst(DY.escapeHtml(p)) + '</li>';
  }).join('');

  // Verbeterpunten HTML - hex codes vervangen door kleurstalen
  var verbHTML = verbeterpunten.slice(0, 4).map(function(v) {
    return '<li class="dy-ai-lijst-item">→ ' + DY._vervangHexInTekst(DY.escapeHtml(v)) + '</li>';
  }).join('');

  // Alternatieven HTML - objecten met kleur+hex+reden, of strings
  var altHTML = alternatieven.slice(0, 3).map(function(a) {
    if (typeof a === 'object' && a !== null) {
      var chip = a.hex
        ? '<span class="dy-ai-kleur-chip" style="background:' + DY.escapeHtml(a.hex) + ';color:' + (isLicht(a.hex) ? '#1e1a0f' : '#fdf8f0') + '">' + DY.escapeHtml(a.kleur || a.hex) + '</span> '
        : '';
      return '<li class="dy-ai-lijst-item">' + chip + DY._vervangHexInTekst(DY.escapeHtml(a.reden || a.kleur || '')) + '</li>';
    }
    return '<li class="dy-ai-lijst-item">→ ' + DY._vervangHexInTekst(DY.escapeHtml(String(a))) + '</li>';
  }).join('');

  function isLicht(hex) {
    try {
      var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
      return (0.299*r + 0.587*g + 0.114*b) > 128;
    } catch(e) { return false; }
  }

  // Kleurstalen: canvas-kleuren van de outfit (primair, accuraat)
  var paletHTML = '';
  if (displayKleuren.length > 0) {
    paletHTML = '<div class="dy-ai-sectie">' +
      '<span class="dy-ai-sectie-label">Kleuren in de outfit</span>' +
      '<div class="dy-ai-palet">' +
      displayKleuren.slice(0, 6).map(function(k) {
        return '<div class="dy-ai-palet-item">' +
          '<div class="dy-ai-palet-bol" style="background:' + k.hex + '" title="' + DY.escapeHtml(k.naam) + '"></div>' +
          '<span class="dy-ai-palet-naam">' + DY.escapeHtml(k.naam) + '</span>' +
          (k.pct > 0 ? '<span class="dy-ai-palet-pct">' + k.pct + '%</span>' : '') +
        '</div>';
      }).join('') +
      '</div>' +
    '</div>';
  }

  var html =
    // Sectie 0: Kleurstalen (canvas-detectie)
    paletHTML +
    // Sectie 1: Kleuren & Harmonie scores
    '<div class="dy-ai-sectie">' +
      '<span class="dy-ai-sectie-label">Kleuren & Harmonie</span>' +
      (harmonieType ? '<p class="dy-ai-tekst"><em>' + DY._vervangHexInTekst(DY.escapeHtml(harmonieType)) + '</em></p>' : '') +
      scoreBalk('Harmonie', harmonieScore) +
      scoreBalk('Contrast', contrastScore) +
      scoreBalk('Balans', balansScore) +
    '</div>' +

    // Sectie 2: Stijl
    '<div class="dy-ai-sectie">' +
      '<span class="dy-ai-sectie-label">Stijl</span>' +
      (stijl    ? '<span class="dy-ai-stijl-badge">' + DY.escapeHtml(stijl)    + '</span> ' : '') +
      (seizoen  ? '<span class="dy-ai-stijl-badge dy-ai-stijl-badge--seizoen">' + DY.escapeHtml(seizoen) + '</span>' : '') +
    '</div>' +

    // Sectie 3: Wat werkt goed
    (positiefHTML
      ? '<div class="dy-ai-sectie">' +
          '<span class="dy-ai-sectie-label">Wat werkt goed</span>' +
          '<ul class="dy-ai-lijst">' + positiefHTML + '</ul>' +
        '</div>'
      : '') +

    // Sectie 4: Verbeterpunten
    (verbHTML
      ? '<div class="dy-ai-sectie">' +
          '<span class="dy-ai-sectie-label">Verbeterpunten</span>' +
          '<ul class="dy-ai-lijst">' + verbHTML + '</ul>' +
        '</div>'
      : '') +

    // Sectie 5: Alternatieve kleuren
    (altHTML
      ? '<div class="dy-ai-sectie">' +
          '<span class="dy-ai-sectie-label">Alternatieve kleuren</span>' +
          '<ul class="dy-ai-lijst">' + altHTML + '</ul>' +
        '</div>'
      : '') +

    // Sectie 6: Samenvatting stylist
    (samenvatting
      ? '<div class="dy-ai-sectie dy-ai-samenvatting">' +
          '<span class="dy-ai-sectie-label">Stylistadvies</span>' +
          '<p class="dy-ai-tekst dy-ai-tekst--samenvatting">' + DY._vervangHexInTekst(DY.escapeHtml(samenvatting)) + '</p>' +
        '</div>'
      : '');

  panelEl.innerHTML = html || '<div class="dy-ai-fallback">De analyse is klaar. Probeer de pagina te vernieuwen als je niets ziet.</div>';

  // Verbeter jouw outfit: vul de hardcoded container in de DOM
  // De container staat altijd in de sectie-wrap (display:none tot nu).
  var _orDocId = (panelEl.dataset && panelEl.dataset.docid) || '';
  if (!_orDocId && panelEl.id && panelEl.id.indexOf('dy-ai-panel-') === 0) {
    _orDocId = panelEl.id.slice('dy-ai-panel-'.length);
  }
  if (_orDocId) {
    var _orContainer = document.getElementById('dy-or-vb-' + _orDocId);
    var _orGrid = document.getElementById('dy-or-vb-grid-' + _orDocId);
    if (_orContainer && _orGrid && typeof DY._kaiVerbeterKnoppen !== 'undefined') {
      // Vul de knoppen
      _orGrid.innerHTML = DY._kaiVerbeterKnoppen.map(function(k) {
        return '<button type="button" class="dy-kai-vb-knop" data-deel="' + k.id + '" ' +
          'onclick="DY._orVerbeter(\'' + _orDocId + '\',\'' + k.id + '\')">' +
          '<span class="dy-kai-vb-icoon">' + k.icoon + '</span>' +
          '<span class="dy-kai-vb-label">' + k.label + '</span>' +
        '</button>';
      }).join('');
      // Maak zichtbaar
      _orContainer.style.display = '';
    }
  }
};


// ══════════════════════════════════════════════════════════════════
// INJECTIE IN BESTAANDE CARD BUILDERS - via monkey patching
// De originele functies worden NIET gewijzigd in de broncode.
// We wrappen _compactKaart en verhaalKaart na definitie.
// ══════════════════════════════════════════════════════════════════

// ── PATCH _compactKaart: voeg score + bookmark toe aan footer
var _orig_compactKaart = DY._compactKaart;
DY._compactKaart = function(data, el) {
  // Roep originele functie aan - bouwt innerHTML volledig op
  var result = _orig_compactKaart.call(DY, data, el);
  var docId = data._docId || data.id || '';
  if (!docId) return result;

  // Voeg score module in na de footer-wrap (vóór einde van el)
  var footerWrap = el.querySelector('.dy-kaart-footer-wrap');
  if (footerWrap) {
    // Score module
    var scoreDivK = document.createElement('div');
    scoreDivK.innerHTML = DY._bouwScoreHTML(docId, null);
    var scoreModuleK = scoreDivK.firstChild;
    el.insertBefore(scoreModuleK, footerWrap.nextSibling);

    // Bookmark knop: voeg toe naast "Lees meer" knop
    var leesBtn = footerWrap.querySelector('.dy-lees-meer-btn');
    if (leesBtn) {
      var bmarkEl = document.createElement('button');
      bmarkEl.className = 'dy-kaart-actie dy-bookmark-btn';
      bmarkEl.dataset.doc = docId;
      bmarkEl.setAttribute('aria-label', 'Opslaan');
      bmarkEl.innerHTML = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.5" class="dy-bookmark-icon"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>';
      bmarkEl.addEventListener('click', function(e) {
        e.stopPropagation();
        DY._toonBookmarkSheet(docId, bmarkEl);
      });
      var actiesRij = footerWrap.querySelector('.dy-kaart-acties-rij');
      if (actiesRij) actiesRij.appendChild(bmarkEl);
    }
  }

  // Observer voor lazy score load
  if (DY._scoreObserver) {
    var sm = el.querySelector('.dy-score-module[data-doc]');
    if (sm) DY._scoreObserver.observe(sm);
  } else {
    setTimeout(function() {
      DY._initScoreObserver();
      var sm = el.querySelector('.dy-score-module[data-doc]');
      if (sm) DY._scoreObserver.observe(sm);
    }, 0);
  }

  return result;
};

// ── PATCH verhaalKaart: voeg bookmark toe aan dy-reel-actions sidebar
// ── Feed Outfit Review handler - debounced, hergebruikt bestaande pipeline ──
DY._feedOutfitReview = function(docId, fotoUrl) {
  if (!docId) return;
  // Debounce: voorkom dubbele triggers
  if (DY._feedOutfitReview._ts && Date.now() - DY._feedOutfitReview._ts < 500) return;
  DY._feedOutfitReview._ts = Date.now();

  // FIX: wis AI-cache voor dit docId zodat elke nieuwe Outfit Review met schone sessie start
  if (DY._aiAnalyseCache) delete DY._aiAnalyseCache[docId];
  if (DY._kleurenAI) DY._kleurenAI.analyseResultaat = null;

  // Open het verhaal popup en trigger AI analyse zodra het panel beschikbaar is
  DY.toonVerhaalPopup(docId);

  // Wacht tot popup gerenderd is, zoek dan het AI panel en trigger het
  // v60.1.41: triggerBtn is verwijderd uit overlay UI, dus we wachten alleen
  // op panelEl (de container waarin het analyse-resultaat rendert).
  // v60.1.43: extra fallback - als fotoUrl null is, probeer het opnieuw te lezen
  // uit de inmiddels geladen popup-hero-media zodat we niet onterecht
  // de "Voeg een foto toe" fallback tonen.
  var pogingen = 0;
  var interval = setInterval(function() {
    pogingen++;
    var panelEl = document.getElementById('dy-ai-panel-' + docId);
    if (panelEl) {
      clearInterval(interval);
      setTimeout(function() {
        try { panelEl.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch(e) {}
        // Fallback foto-lookup uit de overlay zelf
        if (!fotoUrl) {
          var heroEl = document.querySelector('.dy-sd-hero-media, .dy-reel-bg-img-main, .dy-reel-bg-blur');
          if (heroEl) {
            fotoUrl = heroEl.currentSrc || heroEl.src || heroEl.getAttribute('src') || heroEl.getAttribute('poster') || null;
          }
        }
        DY.toonAIAnalyse(docId, fotoUrl || null, panelEl);
      }, 80);
    } else if (pogingen > 20) {
      clearInterval(interval); // stop na 2s
    }
  }, 100);
};

var _orig_verhaalKaart = DY.verhaalKaart;
DY.verhaalKaart = function(data, opties) {
  // Roep origineel aan
  var el = _orig_verhaalKaart.call(DY, data, opties);
  if (!el) return el;

  var isCompact = opties && opties.compact;
  if (isCompact) return el; // compact handled by _compactKaart patch

  var docId = data._docId || data.id || '';
  if (!docId) return el;

  // v60.1.41: Outfit Analyse + Opslaan buttons verwijderd uit feed kaart UI.
  // Outfit Analyse blijft beschikbaar via card-hub popover (extra-menu-v3.js).
  // Opslaan/Bewaar functie blijft beschikbaar via card-hub popover (Bewaar item).
  // Handler DY._feedOutfitReview en bookmark-handlers blijven actief voor menu.

  // Laad bookmark status async (na render) - voor synchronisatie met popover Bewaar-state
  if (DY.user) {
    DY.laadBookmarkStatus(docId).catch(function(){}).then(function() {
      DY._updateBookmarkBtns(docId);
    });
  }

  return el;
};

// ── PATCH toonVerhaalPopup: voeg AI analyse + bookmark toe na data geladen
// We wrappen de functie zodat na het renderen van contentHTML twee features worden toegevoegd
var _orig_toonVerhaalPopup = DY.toonVerhaalPopup;
DY.toonVerhaalPopup = async function(id) {
  // Roep origineel aan - dit bouwt de popup en laadt data
  try {
    await _orig_toonVerhaalPopup.call(DY, id);
  } catch(e) {
    // Originele popup heeft zijn eigen error handling - dit voorkomt een unhandled rejection
    return;
  }

  // Wacht één frame zodat DOM is bijgewerkt door originele functie
  await new Promise(function(r) { requestAnimationFrame(r); });

  var contentEl = document.getElementById('dy-vp-content');
  if (!contentEl) return;

  // Haal foto-url op uit het al-gerenderde hero element of via state
  var heroImg = contentEl.querySelector('.dy-sd-hero-media');
  var foto = heroImg ? (heroImg.src || heroImg.getAttribute('src') || null) : null;
  // Fallback: haal docId op en laad foto uit story data
  // (al zichtbaar in DOM via img src)

  var actiesEl = contentEl.querySelector('.dy-sd-acties');
  if (!actiesEl) return; // popup nog niet volledig geladen

  // v60.1.41: Opslaan-knop injectie in overlay verwijderd. Bewaar-functie
  // blijft beschikbaar via card-hub popover. Bookmark-state synchronisatie blijft
  // intact zodat de popover de juiste 'saved' state toont.
  if (DY.user) {
    DY.laadBookmarkStatus(id).catch(function(){}).then(function() { DY._updateBookmarkBtns(id); });
  }

  // v60.1.41: Outfit Analyse trigger BUTTON is verwijderd uit overlay (zit nu
  // alleen in card-hub popover). De onderstaande hook is no-op geworden voor
  // de overlay, maar blijft staan voor backwards-compat met andere code paden
  // die mogelijk nog een dy-ai-trigger element renderen.
  var aiTriggerBestaand = contentEl.querySelector('.dy-ai-trigger[data-docid="' + id + '"]');
  if (aiTriggerBestaand) {
    if (foto) aiTriggerBestaand.dataset.foto = foto;
    aiTriggerBestaand.addEventListener('click', function(e) {
      e.stopPropagation();
      var fotoUrl = this.dataset.foto || null;
      var panelEl = document.getElementById('dy-ai-panel-' + id);
      DY.toonAIAnalyse(id, fotoUrl, panelEl);
    });
  }

  // ── Voeg community score toe in popup (na AI sectie)
  var sdBody = contentEl ? contentEl.querySelector('.dy-sd-body') : null;
  if (sdBody && !sdBody.querySelector('.dy-score-module')) {
    var scoreWrapPopup = document.createElement('div');
    scoreWrapPopup.className = 'dy-score-popup-wrap';
    scoreWrapPopup.innerHTML = DY._bouwScoreHTML(id, DY._getPostState(id).scoreData);
    var aiSectie = sdBody.querySelector('.dy-ai-sectie-wrap');
    if (aiSectie) {
      sdBody.insertBefore(scoreWrapPopup, aiSectie);
    } else {
      var acties = sdBody.querySelector('.dy-sd-acties');
      if (acties && acties.parentNode) {
        acties.parentNode.insertBefore(scoreWrapPopup, acties.nextSibling);
      } else {
        sdBody.appendChild(scoreWrapPopup);
      }
    }
    DY.laadScoreVoorPost(id).catch(function() {}).then(function() {
      // Herrender score module in popup na laden
      var sm = sdBody ? sdBody.querySelector('.dy-score-module[data-doc="' + id + '"]') : null;
      if (sm) {
        sm.outerHTML = DY._bouwScoreHTML(id, DY._getPostState(id).scoreData);
        DY._markeerUserStem(id);
      }
    });
  }
};

// ── Drain bookmark queue na login / bij initialisatie
// Wrap onAuthReady zodat drain plaatsvindt bij elke auth state change naar ingelogd
(function() {
  var _origOnAuthReady = DY.onAuthReady;
  DY.onAuthReady = function(user) {
    var result = _origOnAuthReady.apply(DY, arguments);
    if (user && !user.isAnonymous) {
      setTimeout(function() { DY._bookmarkQueueDrain(); }, 1500);

      // v60.1.11 WELKOMST-TOAST: éénmalig tonen wanneer de gebruiker
      // expliciet inlogt via de loginform (niet bij elke sessie-restore).
      // De flag wordt gezet door de login button-handler en hier gewist.
      try {
        if (window.__dyJustLoggedIn) {
          window.__dyJustLoggedIn = false;
          // Wacht tot DY.profile geladen is voor correcte displayName
          setTimeout(function() {
            try {
              var naam = (DY.profile && (DY.profile.displayName || DY.profile.naam))
                || (user.displayName)
                || (user.email ? user.email.split('@')[0] : 'jij');
              if (typeof DY.toast === 'function') {
                DY.toast('Welkom terug, ' + naam + '!');
              }
            } catch(e) {}
          }, 600);
        }
      } catch(e) {}
    }
    return result;
  };
})();

