// ══════════════════════════════════════════════════════════════════
// v361 - SPRINT 1 FEATURES IN DETAIL PAGINA (renderDetail fix)
// Centrale injectie-functie die werkt in ALLE detail contexten:
//   - renderDetail (desktop/mobile losse pagina)
//   - toonVerhaalPopup (bottom sheet overlay) → patch al actief
//   - _laadDetailOverlayContent (fullscreen overlay) → via verhaalKaart patch
// ══════════════════════════════════════════════════════════════════

DY._injecteerSprint1InDetail = function(docId, foto, containerEl) {
  if (!docId || !containerEl) return;

  // Zoek de dy-sd-acties rij in de container
  var actiesEl = containerEl.querySelector('.dy-sd-acties');
  if (!actiesEl) return;

  // Guard: voorkom dubbele injectie
  if (actiesEl.querySelector('.dy-bookmark-btn')) return;

  // ── 1. Bookmark knop toevoegen aan actie-rij
  var state = DY._getPostState(docId);
  var bmarkBtn = document.createElement('button');
  bmarkBtn.className = 'dy-sd-actie-btn dy-bookmark-btn' + (state.bookmarked ? ' saved' : '');
  bmarkBtn.dataset.doc = docId;
  bmarkBtn.setAttribute('aria-label', 'Opslaan');
  bmarkBtn.innerHTML =
    '<svg class="dy-sd-actie-icon dy-bookmark-icon" viewBox="0 0 24 24" fill="' +
      (state.bookmarked ? 'currentColor' : 'none') +
    '" stroke="currentColor" stroke-width="2"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>' +
    '<span>Opslaan</span>';
  bmarkBtn.addEventListener('click', function(e) {
    e.stopPropagation();
    DY._toonBookmarkSheet(docId, bmarkBtn);
  });
  // Invoegen als tweede knop (na like-knop)
  var eersteActie = actiesEl.querySelector('.dy-sd-actie-btn');
  if (eersteActie && eersteActie.nextSibling) {
    actiesEl.insertBefore(bmarkBtn, eersteActie.nextSibling);
  } else {
    actiesEl.appendChild(bmarkBtn);
  }
  // Laad bookmark status asynchroon
  if (DY.user) {
    DY.laadBookmarkStatus(docId).catch(function(){}).then(function() {
      DY._updateBookmarkBtns(docId);
    });
  }

  // ── 2. Community Score + AI Analyse invoegen NA dy-sd-acties
  var sdBody = containerEl.querySelector('.dy-sd-body');
  if (!sdBody) return;

  // Guard: voorkom dubbele injectie
  if (sdBody.querySelector('.dy-score-popup-wrap') || sdBody.querySelector('.dy-score-module')) return;

  // Score module
  var scoreWrap = document.createElement('div');
  scoreWrap.className = 'dy-score-popup-wrap';
  scoreWrap.innerHTML = DY._bouwScoreHTML(docId, DY._getPostState(docId).scoreData);

  // AI analyse sectie
  var aiWrap = document.createElement('div');
  aiWrap.className = 'dy-ai-sectie-wrap';
  var aiTriggerBtn = document.createElement('button');
  aiTriggerBtn.className = 'dy-ai-trigger dy-sd-ai-btn';
  aiTriggerBtn.setAttribute('aria-label', 'Klik hier voor een outfit analyse');
  aiTriggerBtn.innerHTML =
    '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">' +
      '<path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"/>' +
    '</svg>' +
    '✨ Klik hier voor een outfit analyse';
  if (foto) aiTriggerBtn.dataset.foto = foto;

  var aiPanel = document.createElement('div');
  aiPanel.className = 'dy-ai-panel';
  aiPanel.id = 'dy-ai-panel-' + docId;
  aiPanel.dataset.docid = docId;

  aiTriggerBtn.addEventListener('click', function(e) {
    e.stopPropagation();
    DY.toonAIAnalyse(docId, aiTriggerBtn.dataset.foto || null, aiPanel);
  });

  aiWrap.appendChild(aiTriggerBtn);
  aiWrap.appendChild(aiPanel);

  // Invoegen: score → AI, allebei na dy-sd-acties
  var actiesRij = sdBody.querySelector('.dy-sd-acties');
  if (actiesRij && actiesRij.parentNode) {
    var insertNa = actiesRij.nextSibling;
    actiesRij.parentNode.insertBefore(scoreWrap, insertNa);
    actiesRij.parentNode.insertBefore(aiWrap, scoreWrap.nextSibling);
  } else {
    sdBody.appendChild(scoreWrap);
    sdBody.appendChild(aiWrap);
  }

  // ── 3. Laad score asynchroon
  DY.laadScoreVoorPost(docId).catch(function() {}).then(function() {
    // Herrender score module na laden van Firestore data
    var sm = containerEl ? containerEl.querySelector('.dy-score-module[data-doc="' + docId + '"]') : null;
    if (sm) {
      var nieuwHTML = document.createElement('div');
      nieuwHTML.innerHTML = DY._bouwScoreHTML(docId, DY._getPostState(docId).scoreData);
      if (nieuwHTML.firstChild && sm.parentNode) {
        sm.parentNode.replaceChild(nieuwHTML.firstChild, sm);
      }
      DY._markeerUserStem(docId);
    }
  });
};

