// Voeg "Opgeslagen" tab toe onderaan de profielpagina
DY._opgeslaanToggle = function() {
  var body    = document.getElementById('dy-opg-body');
  var chevron = document.getElementById('dy-opg-chevron');
  var btn     = document.getElementById('dy-opg-toggle-btn');
  if (!body) return;

  // Spam guard via dataset
  if (body.dataset.toggling === '1') return;
  body.dataset.toggling = '1';
  setTimeout(function() { if (body) body.dataset.toggling = ''; }, 350);

  var isOpen = body.style.display !== 'none';

  if (isOpen) {
    // Sluiten - exact psToggle patroon
    body.style.maxHeight = body.scrollHeight + 'px';
    requestAnimationFrame(function() {
      body.style.transition = 'max-height 0.28s ease, opacity 0.2s ease';
      body.style.maxHeight  = '0';
      body.style.opacity    = '0';
      setTimeout(function() {
        body.style.display    = 'none';
        body.style.maxHeight  = '';
        body.style.opacity    = '';
        body.style.transition = '';
      }, 290);
    });
    if (btn)     btn.setAttribute('aria-expanded', 'false');
    if (chevron) chevron.style.transform = '';
  } else {
    // Openen - exact psToggle patroon
    body.style.display   = 'block';
    body.style.overflow  = 'hidden';
    body.style.maxHeight = '0';
    body.style.opacity   = '0';
    if (btn)     btn.setAttribute('aria-expanded', 'true');
    if (chevron) chevron.style.transform = 'rotate(180deg)';

    requestAnimationFrame(function() {
      body.style.transition = 'max-height 0.32s ease, opacity 0.2s ease';
      body.style.maxHeight  = '1400px';
      body.style.opacity    = '1';
      setTimeout(function() { if (body) body.style.overflow = 'visible'; }, 340);
    });

    // Bind tab knoppen (eenmalig na eerste open, gebruik data-col attribuut)
    if (!body._tabsBound) {
      body._tabsBound = true;
      var tabsEl = document.getElementById('dy-opg-tabs');
      if (tabsEl) {
        tabsEl.addEventListener('click', function(e) {
          e.stopPropagation();
          var tab = e.target.closest('.dy-opg-tab');
          if (!tab) return;
          tabsEl.querySelectorAll('.dy-opg-tab').forEach(function(t) { t.classList.remove('active'); });
          tab.classList.add('active');
          DY._laadOpgeslagenGrid(tab.dataset.col || 'alle');
        });
      }
    }

    // Lazy load: alleen bij eerste open
    if (body.dataset.geladen !== '1') {
      body.dataset.geladen = '1';
      DY._laadOpgeslagenGrid('alle');
    }
  }
};

DY._injecteerOpgeslagenTab = function(containerEl) {
  if (!containerEl || !DY.user) return;
  if (containerEl.querySelector('#dy-opg-toggle-btn')) return; // guard op ID

  var profielWrap = containerEl.querySelector('.dy-profiel-wrap');
  if (!profielWrap) return;

  // Invoegpunt: vóór .dy-fit-card zodat het in de accordion-reeks staat
  // (na Volgend/Volgers, vóór Pasvorm & Voorkeuren)
  var fitCard = profielWrap.querySelector('.dy-fit-card');

  var sectie = document.createElement('div');
  sectie.className = 'dy-ps-dd-wrap dy-opgeslagen-sectie';

  // Gebruik inline onclick (DY._opgeslaanToggle) zodat dit event
  // OVERLEEFT bij main.innerHTML tab-cache restore
  sectie.innerHTML =
    '<button class="dy-ps-dd-header" id="dy-opg-toggle-btn" type="button" ' +
      'aria-expanded="false" aria-controls="dy-opg-body" ' +
      'onclick="DY._opgeslaanToggle()">' +
      '<div class="dy-ps-dd-links">' +
        '<span class="dy-ps-dd-lbl">📌 Opgeslagen outfits</span>' +
      '</div>' +
      '<svg id="dy-opg-chevron" class="dy-ps-dd-chevron" viewBox="0 0 20 20" ' +
        'width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" ' +
        'style="pointer-events:none">' +
        '<polyline points="5 8 10 13 15 8"/>' +
      '</svg>' +
    '</button>' +
    '<div id="dy-opg-body" class="dy-opg-body" ' +
      'style="display:none;max-height:0;overflow:hidden;opacity:0">' +
      '<div class="dy-opg-inner">' +
        '<div class="dy-opg-tabs" id="dy-opg-tabs">' +
          '<button class="dy-opg-tab active" data-col="alle" ' +
          '<button class="dy-opg-tab active" data-col="alle">Alle</button>' +
          DY._BOOKMARK_COLLECTIONS.map(function(col) {
            return '<button class="dy-opg-tab" data-col="' + col.id + '">' + col.label + '</button>';
          }).join('') +
        '</div>' +
        '<div class="dy-opg-grid" id="dy-opg-grid"></div>' +
      '</div>' +
    '</div>';

  // Invoegen NA .dy-fit-card (Pasvorm & Voorkeuren), voor de DSP-sectie
  if (fitCard && fitCard.nextSibling) {
    profielWrap.insertBefore(sectie, fitCard.nextSibling);
  } else if (fitCard) {
    profielWrap.appendChild(sectie);
  } else {
    profielWrap.appendChild(sectie);
  }
};

// Tab filter - ook globale functie zodat inline onclick werkt na tab-cache restore
DY._opgeslaanFilterTab = function(btn, collectie) {
  document.querySelectorAll('#dy-opg-tabs .dy-opg-tab').forEach(function(t) {
    t.classList.remove('active');
  });
  btn.classList.add('active');
  DY._laadOpgeslagenGrid(collectie);
};


DY._laadOpgeslagenGrid = async function(collectie) {
  var grid = document.getElementById('dy-opg-grid');
  if (!grid || !DY.user) return;

  grid.innerHTML = '<div class="dy-opg-loading"><div class="dy-spinner"></div></div>';

  try {
    // Gebruik profiel cache als beschikbaar - voorkom onnodige Firestore read
    var savedPosts;
    if (DY.profile && DY.profile.savedPosts !== undefined) {
      savedPosts = DY.profile.savedPosts;
    } else {
      var userSnap = await DY.db.collection('users').doc(DY.user.uid).get();
      savedPosts = (userSnap.exists && userSnap.data().savedPosts) || {};
      if (DY.profile) DY.profile.savedPosts = savedPosts;
    }

    var alleSaved = Object.values(savedPosts || {});
    alleSaved.sort(function(a, b) { return (b.ts || 0) - (a.ts || 0); });

    if (alleSaved.length === 0) {
      grid.innerHTML =
        '<div class="dy-opg-leeg">Nog geen opgeslagen outfits.' +
        '<span>Klik op 📌 Opslaan bij een outfit.</span></div>';
      return;
    }

    var items = alleSaved.filter(function(d) {
      return collectie === 'alle' ||
        (d.collections && d.collections.indexOf(collectie) !== -1);
    }).slice(0, 40);

    if (items.length === 0) {
      grid.innerHTML = '<div class="dy-opg-leeg">Geen outfits in deze categorie.</div>';
      return;
    }

    // Batch-haal story data op voor items zonder foto in de bookmark
    var itemsZonderFoto = items.filter(function(i) { return !i.foto; });
    var batchIds = itemsZonderFoto.map(function(i) { return i.docId; }).filter(Boolean);
    var allStories = {};

    if (batchIds.length > 0) {
      var chunks = [];
      for (var i = 0; i < batchIds.length; i += 10) chunks.push(batchIds.slice(i, i + 10));
      await Promise.all(chunks.map(async function(chunk) {
        try {
          var ss = await DY.db.collection('stories')
            .where(firebase.firestore.FieldPath.documentId(), 'in', chunk).get();
          ss.docs.forEach(function(d) {
            allStories[d.id] = Object.assign({ _docId: d.id }, d.data());
          });
        } catch(e) {}
      }));
    }

    grid.innerHTML = '';

    items.forEach(function(item) {
      var story = allStories[item.docId];
      // Foto: gebruik opgeslagen meta, anders uit story document
      var foto  = item.foto ||
        (story ? (story.photo || story.foto || null) : null);
      var titel = item.titel ||
        (story ? (story.title || story.titel || (story.body || '').slice(0, 60)) : '') ||
        'Outfit';
      var colLabels = (item.collections || []).map(function(id) {
        var c = DY._BOOKMARK_COLLECTIONS.find(function(x) { return x.id === id; });
        return c ? c.label : id;
      }).join(', ');

      var el = document.createElement('div');
      el.className = 'dy-opg-kaart';
      el.setAttribute('role', 'button');
      el.setAttribute('tabindex', '0');
      el.setAttribute('aria-label', DY.escapeHtml(titel));

      el.innerHTML =
        '<div class="dy-opg-foto-wrap' + (foto ? '' : ' dy-opg-foto-placeholder') + '">' +
          (foto
            ? '<img class="dy-opg-foto" src="' + DY.escapeHtml(foto) + '" alt="" loading="lazy" decoding="async">'
            : '<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.5">' +
                '<rect x="3" y="3" width="18" height="18" rx="2"/>' +
                '<circle cx="8.5" cy="8.5" r="1.5"/>' +
                '<polyline points="21 15 16 10 5 21"/>' +
              '</svg>') +
        '</div>' +
        '<div class="dy-opg-info">' +
          '<span class="dy-opg-naam">' + DY.escapeHtml(titel) + '</span>' +
          (colLabels ? '<span class="dy-opg-col">' + DY.escapeHtml(colLabels) + '</span>' : '') +
        '</div>';

      // Klik navigatie - gebruik openDetail voor correcte overlay-routing
      // openDetail behoudt feed context en gebruikt de juiste stacking order
      el.addEventListener('click', function(e) {
        e.stopPropagation();
        if (!item.docId) return;
        // Bewaar profielpagina als terugkeer-context
        DY._profielScrollY = document.getElementById('dy-main')
          ? document.getElementById('dy-main').scrollTop : 0;
        DY.huidigVerhaalId = item.docId;
        // openDetail handelt z-index stacking correct af (vs navigeer('detail') die de feed reset)
        DY.navigeer('detail');
      });

      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          el.click();
        }
      });

      grid.appendChild(el);
    });

  } catch(e) {
    var grid2 = document.getElementById('dy-opg-grid');
    if (grid2) grid2.innerHTML = '<div class="dy-opg-leeg">Kon opgeslagen items niet laden.</div>';
  }
};


// ── Fix bookmark write: sla ook foto+titel op voor weergave in grid
var _origToonBookmarkSheet = DY._toonBookmarkSheet;
DY._toonBookmarkSheet = function(docId, triggerBtn) {
  // Haal foto en titel op uit huidige postState of DOM voordat sheet opent
  var state = DY._getPostState(docId);
  if (!state._storyMeta) {
    // Probeer meta uit het huidige open popup of detail pagina te halen
    var heroImg = document.querySelector('.dy-sd-hero-media, .dy-reel-bg-img-main');
    var titelEl = document.querySelector('.dy-sd-titel, .dy-reel-titel');
    state._storyMeta = {
      foto:  heroImg ? (heroImg.src || heroImg.getAttribute('src') || null) : null,
      titel: titelEl ? (titelEl.textContent || '').trim().slice(0, 80) : ''
    };
  }
  return _origToonBookmarkSheet.call(DY, docId, triggerBtn);
};

// Patch opslaanBtn in _toonBookmarkSheet om meta ook op te slaan in Firestore
// Override de ref.set call door een uitgebreide versie
var _origBookmarkQueueDrain = DY._bookmarkQueueDrain;
DY._enrichBookmarkData = function(docId, collections) {
  // Haal foto/titel op voor de bookmark record
  var state = DY._getPostState(docId);
  var meta = state._storyMeta || {};

  // Zoek ook in DOM (fallback)
  if (!meta.foto) {
    var heroImg = document.querySelector('[data-doc="' + docId + '"] .dy-reel-bg-img-main, .dy-sd-hero-media');
    if (heroImg) meta.foto = heroImg.src || heroImg.getAttribute('src') || null;
  }
  return {
    docId:      docId,
    collections: collections,
    foto:       meta.foto || null,
    titel:      meta.titel || '',
    ts:         firebase.firestore.FieldValue.serverTimestamp()
  };
};

// Monkey-patch de opslaanBtn click handler - we doen dit door _bookmarkQueueDrain
// uit te breiden zodat queued items ook foto/titel meesturen.
// De echte write zit in de sheet's opslaanBtn listener die niet eenvoudig te patchen is
// zonder de hele sheet te herschrijven. Eenvoudigste fix: override laadBookmarkStatus
// zodat bij een write ook meta wordt meegestuurd.
// 
// ECHTER: de bestaande _toonBookmarkSheet opslaanBtn doet:
// ref.set({ docId, collections, ts }, { merge: true })
// We voegen foto+titel toe door de bookmark save op een andere manier te hooken:
// Override DY.db.collection('user_bookmarks') - niet mogelijk.
// 
// Eenvoudigste werkende aanpak: patch de bookmark Firestore write in _toonBookmarkSheet
// door de functie te herschrijven met de extra velden.

// Complete herschrijving van _toonBookmarkSheet met extra metadata en correcte tab refresh
DY._toonBookmarkSheet = function(docId, triggerBtn) {
  // Auth guard - zelfde patroon als alle andere beveiligde acties
  if (!DY.user) {
    DY.toonLoginPrompt('Maak een gratis account aan om outfits op te slaan in je collectie.');
    return;
  }

  var bestaand = document.getElementById('dy-bookmark-sheet-wrap');
  if (bestaand) bestaand.parentNode.removeChild(bestaand);

  // Haal foto+titel op voor opslaan in Firestore
  var metaFoto = null;
  var metaTitel = '';
  var heroImg = document.querySelector('.dy-sd-hero-media');
  if (!heroImg) heroImg = document.querySelector('.dy-reel-bg-img-main');
  if (heroImg) metaFoto = heroImg.src || heroImg.getAttribute('src') || null;
  var titelEl = document.querySelector('.dy-sd-titel');
  if (!titelEl) titelEl = document.querySelector('.dy-reel-titel');
  if (titelEl) metaTitel = (titelEl.textContent || '').trim().slice(0, 80);

  DY.laadBookmarkStatus(docId).catch(function(){ return {}; }).then(function(state) {
    var wrap = document.createElement('div');
    wrap.id = 'dy-bookmark-sheet-wrap';
    wrap.className = 'dy-bs-backdrop';

    var colsHTML = DY._BOOKMARK_COLLECTIONS.map(function(col) {
      var active = state.collections.indexOf(col.id) !== -1;
      return '<button class="dy-bs-col-btn' + (active ? ' active' : '') + '" data-col="' + col.id + '">' +
        '<span class="dy-bs-col-check">' +
          (active ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>' : '') +
        '</span>' +
        col.label +
      '</button>';
    }).join('');

    wrap.innerHTML =
      '<div class="dy-bs-sheet" id="dy-bs-sheet">' +
        '<div class="dy-bs-drag"></div>' +
        '<div class="dy-bs-header">' +
          '<span class="dy-bs-titel">📌 Opslaan in collectie</span>' +
          '<span class="dy-bs-sub">Kies één of meerdere categorieën</span>' +
        '</div>' +
        '<div class="dy-bs-cols">' + colsHTML + '</div>' +
        '<div class="dy-bs-acties">' +
          '<button class="dy-bs-opslaan-btn" id="dy-bs-opslaan">Opslaan</button>' +
          (state.bookmarked ? '<button class="dy-bs-verwijder-btn" id="dy-bs-verwijder">Verwijderen</button>' : '') +
        '</div>' +
      '</div>';

    document.body.appendChild(wrap);
    requestAnimationFrame(function() { requestAnimationFrame(function() { wrap.classList.add('dy-bs-in'); }); });

    // Toggle collectie
    wrap.querySelectorAll('.dy-bs-col-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        btn.classList.toggle('active');
        var check = btn.querySelector('.dy-bs-col-check');
        if (check) {
          check.innerHTML = btn.classList.contains('active')
            ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>'
            : '';
        }
      });
    });

    function sluitSheet(cb) {
      wrap.classList.remove('dy-bs-in');
      wrap.classList.add('dy-bs-out');
      setTimeout(function() {
        if (wrap.parentNode) wrap.parentNode.removeChild(wrap);
        if (cb) cb();
      }, 280);
    }

    var opslaanBtn = document.getElementById('dy-bs-opslaan');
    if (opslaanBtn) {
      opslaanBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        var activeCols = [];
        wrap.querySelectorAll('.dy-bs-col-btn.active').forEach(function(b) { activeCols.push(b.dataset.col); });
        if (activeCols.length === 0) activeCols = ['favorieten'];

        // Update state
        state.bookmarked = true;
        state.collections = activeCols;
        state.bookmarkLoaded = true;
        DY._updateBookmarkBtns(docId);

        // Micro-animatie
        if (triggerBtn) {
          triggerBtn.style.transform = 'scale(1.35)';
          setTimeout(function() { triggerBtn.style.transform = ''; }, 220);
        }

        DY._toonToastBericht('📌 Opgeslagen in ' + activeCols.map(function(id) {
          var c = DY._BOOKMARK_COLLECTIONS.find(function(x) { return x.id === id; });
          return c ? c.label : id;
        }).join(', '));

        if (DY.user) {
          // Schrijf naar users/{uid} document - gegarandeerd toegestaan (zelfde als profielupdate)
          // savedPosts.{docId} als geneste map op het user document
          var saveUpdate = {};
          saveUpdate['savedPosts.' + docId] = {
            docId:       docId,
            collections: activeCols,
            foto:        metaFoto || null,
            titel:       metaTitel || '',
            ts:          Date.now()
          };
          DY.db.collection('users').doc(DY.user.uid).update(saveUpdate)
            .then(function() {
              // Sync naar lokaal profiel object
              if (!DY.profile.savedPosts) DY.profile.savedPosts = {};
              DY.profile.savedPosts[docId] = saveUpdate['savedPosts.' + docId];
            })
            .catch(function() {
              DY._addToBookmarkQueue({ action: 'add', docId: docId, collections: activeCols, foto: metaFoto, titel: metaTitel });
            });
        }
        sluitSheet();
      });
    }

    var verwijderBtn = document.getElementById('dy-bs-verwijder');
    if (verwijderBtn) {
      verwijderBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        state.bookmarked = false;
        state.collections = [];
        DY._updateBookmarkBtns(docId);
        DY._toonToastBericht('Verwijderd uit opgeslagen posts');
        if (DY.user) {
          var delUpdate = {};
          delUpdate['savedPosts.' + docId] = firebase.firestore.FieldValue.delete();
          DY.db.collection('users').doc(DY.user.uid).update(delUpdate)
            .then(function() {
              if (DY.profile && DY.profile.savedPosts) delete DY.profile.savedPosts[docId];
            })
            .catch(function() {
              DY._addToBookmarkQueue({ action: 'remove', docId: docId });
            });
        }
        sluitSheet();
      });
    }

    wrap.addEventListener('click', function(e) { if (e.target === wrap) sluitSheet(); });
  });
};

